    "invoice_error" "text",
    "order_change_used" boolean DEFAULT false NOT NULL,
    "order_change_status" "text",
    "order_change_extra_amount" numeric(12,2),
    "cancelled_at" timestamp with time zone,
    "financial_status" "text" DEFAULT 'pending_payment'::"text" NOT NULL,
    "payment_confirmed_by" "uuid",
    "payment_confirmed_at" timestamp with time zone,
    "payment_confirmed_amount" numeric(12,2),
    "payment_confirmation_observation" "text",
    "cancellation_requested_by" "uuid",
    "cancellation_requested_at" timestamp with time zone,
