    "credit_note_required" boolean DEFAULT false NOT NULL,
    "credit_note_issued" boolean DEFAULT false NOT NULL,
    "credit_note_number" "text",
    "credit_note_issued_at" timestamp with time zone,
    "credit_note_status" "text",
    "credit_note_point" integer,
    "credit_note_cae" "text",
    "credit_note_cae_due" "date",
    "credit_note_created_at" timestamp with time zone,
    "credit_note_amount" numeric(12,2),
    "credit_note_error" "text",
    "store_benefit_id" "uuid",
    "store_benefit_code" "text",
    "store_benefit_type" "text",
    "store_benefit_percent" integer,
    "store_benefit_discount_amount" numeric(12,2),
    "cliente_dni" "text",
    "original_total" numeric(12,2),
    "credit_balance_used" numeric(12,2) DEFAULT 0 NOT NULL,
    "external_amount_due" numeric(12,2),
    "payment_composition" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "credit_balance_movement_id" "uuid",
    "checkout_idempotency_key" "text",
    "mercadopago_checkout_fingerprint" "text",
    "mercadopago_request_fingerprint" "text",
    "mercadopago_preference_id" "text",
    "mercadopago_init_point" "text",
    "mercadopago_preference_expires_at" timestamp with time zone,
    "mercadopago_preference_claim_token" "uuid",
    "mercadopago_preference_claimed_at" timestamp with time zone,
    "mercadopago_preference_generation" integer DEFAULT 0 NOT NULL,
    "cp_destino" "text",
    "shipping_provider" "text",
    "shipping_type" "text",
    "shipping_cost_real" numeric(12,2),
    "shipping_cost_charged" numeric(12,2),
    "free_shipping_applied" boolean DEFAULT false NOT NULL,
    "admin_visible_at" timestamp with time zone DEFAULT "now"(),
    "andreani_creation_status" "text",
    "andreani_creation_claim_token" "uuid",
    "andreani_creation_claimed_at" timestamp with time zone,
    "andreani_creation_attempts" integer DEFAULT 0 NOT NULL,
    "andreani_created_at" timestamp with time zone,
