    "andreani_creation_environment" "text",
    "andreani_tracking_checked_at" timestamp with time zone,
    "andreani_tracking_event_at" timestamp with time zone,
    "andreani_sucursal_id" "text",
    "andreani_sucursal_codigo" "text",
    "andreani_sucursal_nombre" "text",
    "andreani_sucursal_direccion" "text",
    "andreani_sucursal_localidad" "text",
    "andreani_sucursal_provincia" "text",
    "andreani_sucursal_cp" "text",
    "installments_count" smallint,
    "installments_percent" numeric(5,2),
    "installments_products_base_amount" numeric(12,2),
    "installments_surcharge_amount" numeric(12,2),
    "mercadopago_payment_snapshot" "jsonb",
    "transfer_verification_status" "text" DEFAULT 'pending'::"text",
    "transfer_payer_first_name" "text",
    "transfer_payer_last_name" "text",
    "transfer_payer_dni" "text",
    "transfer_amount_declared" numeric,
    "transfer_verification_attempts" integer DEFAULT 0 NOT NULL,
    "transfer_last_verification_at" timestamp with time zone,
    "transfer_verification_failure_reason" "text",
