    "transfer_match_snapshot" "jsonb",
    "transfer_verification_lease_id" "uuid",
    "customer_checkout_fingerprint" "text",
    CONSTRAINT "ordenes_admin_visibility_payment_check" CHECK ((("payment_method_id" IS DISTINCT FROM 'mercadopago'::"text") OR ("admin_visible_at" IS NULL) OR (("payment_status" = 'approved'::"text") AND ("financial_status" = ANY (ARRAY['payment_confirmed'::"text", 'cancellation_requested'::"text", 'refund_pending'::"text", 'refunded'::"text"])) AND ("payment_confirmed_at" IS NOT NULL) AND ("payment_id" IS NOT NULL)) OR (("payment_status" = ANY (ARRAY['approved_amount_mismatch'::"text", 'approved_currency_mismatch'::"text", 'approved_stock_conflict'::"text"])) AND ("payment_id" IS NOT NULL)))),
    CONSTRAINT "ordenes_andreani_creation_attempts_check" CHECK (("andreani_creation_attempts" >= 0)),
    CONSTRAINT "ordenes_andreani_creation_environment_check" CHECK ((("andreani_creation_environment" IS NULL) OR ("andreani_creation_environment" = ANY (ARRAY['QA'::"text", 'PROD'::"text"])))),
    CONSTRAINT "ordenes_andreani_creation_status_check" CHECK ((("andreani_creation_status" IS NULL) OR ("andreani_creation_status" = ANY (ARRAY['claimed'::"text", 'created'::"text", 'failed'::"text", 'rejected'::"text", 'reconciliation_required'::"text"])))),
    CONSTRAINT "ordenes_credit_balance_non_negative_check" CHECK (((COALESCE("original_total", (0)::numeric) >= (0)::numeric) AND (COALESCE("credit_balance_used", (0)::numeric) >= (0)::numeric) AND (COALESCE("external_amount_due", (0)::numeric) >= (0)::numeric))),
    CONSTRAINT "ordenes_credit_note_status_check" CHECK ((("credit_note_status" IS NULL) OR ("credit_note_status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'authorized'::"text", 'error'::"text"])))),
    CONSTRAINT "ordenes_estado_check" CHECK (("estado" = ANY (ARRAY['pendiente'::"text", 'pagado'::"text", 'enviado'::"text", 'en_camino'::"text", 'visita_fallida'::"text", 'en_sucursal'::"text", 'retiro_pendiente'::"text", 'retiro_vencido'::"text", 'en_devolucion'::"text", 'devuelto_beyonix'::"text", 'entregado'::"text", 'cancelado'::"text"]))),
    CONSTRAINT "ordenes_financial_status_check" CHECK (("financial_status" = ANY (ARRAY['pending_payment'::"text", 'payment_submitted'::"text", 'payment_confirmed'::"text", 'cancellation_requested'::"text", 'refund_pending'::"text", 'refunded'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "ordenes_installments_count_check" CHECK ((("installments_count" IS NULL) OR ("installments_count" = ANY (ARRAY[2, 3, 6])))),
    CONSTRAINT "ordenes_invoice_status_check" CHECK ((("invoice_status" IS NULL) OR ("invoice_status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'authorized'::"text", 'error'::"text"])))),
    CONSTRAINT "ordenes_mercadopago_preference_generation_check" CHECK (("mercadopago_preference_generation" >= 0)),
    CONSTRAINT "ordenes_order_change_status_check" CHECK ((("order_change_status" IS NULL) OR ("order_change_status" = ANY (ARRAY['change_requested'::"text", 'change_approved'::"text", 'extra_payment_pending'::"text", 'rejected'::"text"])))),
    CONSTRAINT "ordenes_return_status_check" CHECK ((("return_status" IS NULL) OR ("return_status" = ANY (ARRAY['solicitada'::"text", 'en_revision'::"text", 'aprobada'::"text", 'rechazada'::"text", 'resuelta'::"text"])))),
    CONSTRAINT "ordenes_transfer_verification_status_check" CHECK (("transfer_verification_status" = ANY (ARRAY['pending'::"text", 'checking'::"text", 'auto_verified'::"text", 'manual_review'::"text"])))
);


ALTER TABLE "public"."ordenes" OWNER TO "postgres";

--
-- Name: COLUMN "ordenes"."mercadopago_checkout_fingerprint"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."mercadopago_checkout_fingerprint" IS 'Huella server-side del checkout validado; permite reutilizar de forma segura una orden pendiente.';


--
-- Name: COLUMN "ordenes"."mercadopago_init_point"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."mercadopago_init_point" IS 'URL de Checkout Pro persistida para reintentos idempotentes.';


--
-- Name: COLUMN "ordenes"."cp_destino"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."cp_destino" IS 'Código postal de destino validado durante el checkout.';


--
-- Name: COLUMN "ordenes"."shipping_provider"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."shipping_provider" IS 'Proveedor de la cotización de envío validada por el servidor.';


--
-- Name: COLUMN "ordenes"."shipping_type"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."shipping_type" IS 'Modalidad de entrega de la cotización validada.';


--
-- Name: COLUMN "ordenes"."shipping_cost_real"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."shipping_cost_real" IS 'Costo real de envío validado por el servidor.';


--
-- Name: COLUMN "ordenes"."shipping_cost_charged"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."shipping_cost_charged" IS 'Costo de envío efectivamente cobrado al cliente.';


--
-- Name: COLUMN "ordenes"."free_shipping_applied"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."free_shipping_applied" IS 'Indica si el checkout aplicó el beneficio de envío gratis.';


--
-- Name: COLUMN "ordenes"."admin_visible_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."admin_visible_at" IS 'Momento en que una orden deja de ser un intento técnico y entra al flujo operativo del administrador.';


--
-- Name: COLUMN "ordenes"."andreani_creation_status"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_creation_status" IS 'Estado de creación B2C: claimed, created, failed recuperable, rejected permanente o reconciliation_required ante resultado externo ambiguo.';


--
-- Name: COLUMN "ordenes"."andreani_creation_claim_token"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_creation_claim_token" IS 'Token del intento en curso; permite liberar o reconciliar un reclamo atómico.';


--
-- Name: COLUMN "ordenes"."andreani_creation_claimed_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_creation_claimed_at" IS 'Momento en que se reclamó el intento de creación; permite recuperar reclamos vencidos.';


--
-- Name: COLUMN "ordenes"."andreani_creation_attempts"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_creation_attempts" IS 'Cantidad de intentos de creación del envío realizados para esta orden.';


--
-- Name: COLUMN "ordenes"."andreani_created_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_created_at" IS 'Momento en que Andreani confirmó la creación del envío B2C.';


--
-- Name: COLUMN "ordenes"."andreani_contrato"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_contrato" IS 'Contrato Andreani utilizado para crear el envío (modalidad domicilio).';


--
-- Name: COLUMN "ordenes"."andreani_creation_environment"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_creation_environment" IS 'Ambiente Andreani (QA/PROD) del último intento de creación registrado en andreani_creation_status.';


--
-- Name: COLUMN "ordenes"."andreani_tracking_checked_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_tracking_checked_at" IS 'Última consulta exitosa del tracking Andreani.';


--
-- Name: COLUMN "ordenes"."andreani_tracking_event_at"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_tracking_event_at" IS 'Fecha del último evento externo Andreani persistido.';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_id" IS 'idgla numérico (como texto) de la sucursal Andreani elegida por el cliente para entrega. Es lo que POST /v2/ordenes-de-envio espera en destino.sucursal.id -- nunca el código (ej. "RAC").';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_codigo"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_codigo" IS 'Código/nomenclatura de la sucursal (ej. "RAC"), sólo de referencia/soporte -- no es el identificador que usa la creación del envío.';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_nombre"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_nombre" IS 'Nombre (descripcion) de la sucursal Andreani elegida, para mostrar al cliente/admin.';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_direccion"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_direccion" IS 'Calle y número de la sucursal Andreani elegida, tal como los devolvió Andreani al momento de la selección.';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_localidad"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_localidad" IS 'Localidad de la sucursal Andreani elegida.';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_provincia"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_provincia" IS 'Provincia de la sucursal Andreani elegida.';


--
-- Name: COLUMN "ordenes"."andreani_sucursal_cp"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."andreani_sucursal_cp" IS 'Código postal de la sucursal Andreani elegida.';


--
-- Name: COLUMN "ordenes"."installments_count"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."installments_count" IS 'Cantidad de cuotas elegida por el cliente (2/3/6), null si pagó de otra forma. Snapshot histórico: no se recalcula si cambia la configuración global. Desde la corrección de precio público único, elegir cuotas nunca cambia el total del pedido.';


--
-- Name: COLUMN "ordenes"."installments_percent"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."installments_percent" IS 'Costo interno EFECTIVO de Mercado Pago (comisión + IVA) para esa modalidad al momento de la venta -- puramente informativo/auditoría, NUNCA se usa para aumentar el total cobrado al cliente.';


--
-- Name: COLUMN "ordenes"."installments_products_base_amount"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."installments_products_base_amount" IS 'Base de productos netos + envío efectivamente cobrado. Desde la corrección de precio público único, coincide con el total del pedido (antes del descuento de transferencia, que no aplica a Mercado Pago).';


--
-- Name: COLUMN "ordenes"."installments_surcharge_amount"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."installments_surcharge_amount" IS 'Recargo cobrado al cliente por elegir cuotas. Desde la corrección de precio público único, siempre 0 en órdenes nuevas -- el precio público no cambia según la cantidad de cuotas. Órdenes históricas anteriores a esta corrección pueden tener un valor > 0 (modelo viejo, no se reescribe retroactivamente).';


--
-- Name: COLUMN "ordenes"."mercadopago_payment_snapshot"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."mercadopago_payment_snapshot" IS 'Snapshot acotado del payment real de Mercado Pago al aprobarse (installments, transaction_amount, fee_details, transaction_details), para poder mostrar a futuro costos/neto reales.';


--
-- Name: COLUMN "ordenes"."transfer_verification_status"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."transfer_verification_status" IS 'Estado de la conciliación automática de transferencia: pending (sin intentos), checking (intento en curso, lease corto), auto_verified (conciliado automáticamente contra Mercado Pago), manual_review (requiere revisión de un admin). Independiente de payment_status: no reemplaza pendiente_comprobante/en_revision/confirmado/rechazado, sólo documenta el origen de la conciliación.';


--
-- Name: COLUMN "ordenes"."transfer_matched_payment_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."transfer_matched_payment_id" IS 'payment.id de Mercado Pago usado para conciliar esta transferencia. Único en toda la tabla (ver índice ordenes_transfer_matched_payment_id_key): un mismo pago de Mercado Pago no puede acreditar dos pedidos.';


--
-- Name: COLUMN "ordenes"."transfer_match_snapshot"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."transfer_match_snapshot" IS 'Metadata adicional de la transferencia conciliada (operation_type, payment_method_id, identification type/number original, DNI derivado, bank_transfer_id si existe, fechas). Nunca reemplaza transfer_matched_payment_id como identificador único.';


--
-- Name: COLUMN "ordenes"."transfer_verification_lease_id"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."ordenes"."transfer_verification_lease_id" IS 'Identificador único (fencing token) del intento de verificación automática vigente. Se genera en cada claim_transfer_verification_attempt exitoso. confirm_transfer_auto_verification sólo puede confirmar/reclamar si coincide EXACTAMENTE con el vigente en la fila, la fila sigue en transfer_verification_status=checking y el lease no venció por tiempo -- un intento viejo (sin lease, con lease NULL, con lease reemplazado o vencido) nunca puede completar una confirmación.';


--
-- Name: CONSTRAINT "ordenes_admin_visibility_payment_check" ON "ordenes"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON CONSTRAINT "ordenes_admin_visibility_payment_check" ON "public"."ordenes" IS 'admin_visible_at para una orden mercadopago exige payment_status=approved (con financial_status/payment_confirmed_at/payment_id completos) o uno de los tres estados de conflicto post-aprobación (approved_amount_mismatch/approved_currency_mismatch/approved_stock_conflict) con payment_id -- mismas condiciones que set_order_admin_visibility().';


--
-- Name: admin_cancel_order(bigint, "uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."admin_cancel_order"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_action" "text", "p_reason_code" "text", "p_reason_text" "text") RETURNS "public"."ordenes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_payment_confirmed boolean;
  v_now timestamptz := now();
  v_previous_financial_status text;
  v_next_financial_status text;
  v_previous_estado text;
  v_reason_code text;
  v_reason_text text;
  v_action text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para cancelar este pedido.';
  end if;

  if p_admin_id is null
     or coalesce(p_admin_role, '') not in ('operador', 'admin', 'super_admin') then
    raise exception 'Operador inválido.';
  end if;

  v_action := lower(coalesce(p_action, ''));
  if v_action not in ('reject', 'cancel') then
    raise exception 'INVALID_ACTION';
  end if;

  v_reason_code := nullif(trim(coalesce(p_reason_code, '')), '');
  v_reason_text := nullif(trim(coalesce(p_reason_text, '')), '');
  if v_reason_code is null
     -- Misma lista real que ADMIN_ORDER_CANCELLATION_REASONS en
     -- lib/orders/admin-order-cancellation-reasons.ts -- defensa en
     -- profundidad, la ruta ya la valida antes de llegar acá.
     or v_reason_code not in (
       'solicitud_cliente',
       'pago_no_recibido',
       'pago_invalido',
       'falta_stock',
       'error_administrativo',
       'otro'
     )
     or length(coalesce(v_reason_text, v_reason_code)) < 3
     or length(coalesce(v_reason_text, '')) > 600 then
    raise exception 'INVALID_REASON';
  end if;

  select *
  into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if lower(coalesce(v_order.estado, '')) = 'cancelado' then
    raise exception 'ORDER_ALREADY_CANCELLED';
  end if;

  -- NUEVO: mismo guard que las otras 2 RPCs de cancelación -- ver el
  -- comentario de cabecera de esta migración.
  if v_order.andreani_creation_status = 'claimed' then
    raise exception 'ANDREANI_CREATION_IN_PROGRESS';
  end if;
  if v_order.andreani_creation_status = 'reconciliation_required' then
    raise exception 'ANDREANI_RECONCILIATION_REQUIRED';
  end if;

  if v_order.invoice_status in ('authorized', 'processing')
     or v_order.invoice_cae is not null
     or (v_order.invoice_number is not null and v_order.invoice_point is not null) then
    raise exception 'ORDER_ALREADY_INVOICED';
  end if;

  if lower(coalesce(v_order.estado, '')) in (
       'enviado',
       'en_camino',
       'visita_fallida',
       'en_sucursal',
       'retiro_pendiente',
       'retiro_vencido',
       'en_devolucion',
       'devuelto_beyonix',
       'entregado'
     )
     or nullif(trim(v_order.tracking_number), '') is not null
     or nullif(trim(v_order.andreani_tracking), '') is not null
     or nullif(trim(v_order.andreani_envio_id), '') is not null
     or exists (
       select 1
       from unnest(array[
         'camino',
         'tránsito',
         'transito',
         'distribución',
         'distribucion',
         'reparto',
         'visita',
         'entregado'
       ]) as dispatched_status(fragment)
       where lower(coalesce(v_order.andreani_estado, '')) like '%' || fragment || '%'
     ) then
    raise exception 'ORDER_ALREADY_DISPATCHED';
  end if;

  -- Misma fórmula EXACTA que lib/orders/order-payment-status.ts
  -- isOrderPaymentConfirmed() -- sin cambios respecto a la versión anterior.
  v_payment_confirmed :=
    v_order.paid_at is not null
    or coalesce(v_order.payment_confirmed_amount, 0) > 0
    or coalesce(v_order.payment_status, '') in ('confirmado', 'approved', 'confirmed')
    or coalesce(v_order.financial_status, '') in ('payment_confirmed', 'refund_pending', 'refunded');

  if v_action = 'reject' and v_payment_confirmed then
    raise exception 'ORDER_ALREADY_PAID_USE_CANCEL';
  end if;

  if v_action = 'cancel' and not v_payment_confirmed then
    raise exception 'ORDER_NOT_PAID_USE_REJECT';
  end if;

  -- Capturado ANTES del UPDATE ... RETURNING de más abajo -- v_order se
  -- reasigna ahí, así que sin esta variable propia quedaría con el valor
  -- YA cancelado (ese era exactamente el bug de 20260915130000).
  v_previous_estado := v_order.estado;
  v_previous_financial_status := coalesce(
    v_order.financial_status,
    v_order.payment_status,
    v_order.estado,
    'pending_payment'
  );
  v_next_financial_status := case
    when v_action = 'cancel' then 'refund_pending'
    else 'cancelled'
  end;

  update public.ordenes
  set
    estado = 'cancelado',
    cancelled_at = v_now,
    financial_status = v_next_financial_status,
    cancellation_requested_at = v_now,
    cancellation_requested_by = p_admin_id,
    refund_pending_at = case when v_action = 'cancel' then v_now else null end,
    credit_note_required = false
  where id = v_order.id
  returning * into v_order;

  if coalesce(v_order.credit_balance_used, 0) > 0 then
    perform *
    from public.reverse_customer_credit_for_order(
      v_order.id,
      case
        when v_action = 'reject' then 'Reintegro de saldo a favor por rechazo de pedido'
        else 'Reintegro de saldo a favor por cancelación de pedido'
      end,
      p_admin_id
    );
  end if;

  insert into public.order_audit_events (
    order_id,
    actor_type,
    actor_id,
    action,
    previous_status,
    new_status,
    metadata
  )
  values (
    v_order.id,
    'admin',
    p_admin_id,
    case
      when v_action = 'reject' then 'order_rejected_by_admin'
      else 'order_cancelled_refund_pending'
    end,
    v_previous_financial_status,
    v_next_financial_status,
    jsonb_build_object(
      'previousEstado', v_previous_estado,
      'newEstado', 'cancelado',
      'source', case
        when v_action = 'reject' then 'admin_direct_rejection'
        else 'admin_direct_cancellation'
      end,
      'reasonCode', v_reason_code,
      'reasonText', coalesce(v_reason_text, v_reason_code)
    )
  );

  return v_order;
end;
$$;


ALTER FUNCTION "public"."admin_cancel_order"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_action" "text", "p_reason_code" "text", "p_reason_text" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "admin_cancel_order"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_action" "text", "p_reason_code" "text", "p_reason_text" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."admin_cancel_order"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_action" "text", "p_reason_code" "text", "p_reason_text" "text") IS 'Rechaza (pago no confirmado) o cancela (pago confirmado) un pedido directamente desde Admin, sin depender de un order_claims previo. Misma transacción atómica/guardas que approve_order_claim_cancellation. Bloquea si hay una creación Andreani en curso (claimed) o con resultado externo incierto (reconciliation_required) -- fix 20260916100000.';


--
-- Name: admin_confirm_force_delete("text", "text", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."admin_confirm_force_delete"("p_kind" "text", "p_id" "text", "p_actor_id" "uuid", "p_confirmation" "text", "p_fingerprint" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_impact jsonb;
  v_previous public.admin_destructive_operations%rowtype;
  v_product_id bigint;
begin
  if auth.role() is distinct from 'service_role' or not exists(select 1 from public.profiles where id = p_actor_id and rol = 'super_admin') then
    raise exception 'ADMIN_DELETE_FORBIDDEN';
  end if;
  if p_idempotency_key is null or length(p_idempotency_key) not between 8 and 240 then raise exception 'ADMIN_DELETE_INVALID'; end if;
  perform pg_advisory_xact_lock(hashtextextended('admin-delete:' || p_idempotency_key, 0));
  select * into v_previous from public.admin_destructive_operations where idempotency_key = p_idempotency_key;
  if found then
    if v_previous.actor_id <> p_actor_id or v_previous.kind <> p_kind or v_previous.target_id <> p_id then raise exception 'ADMIN_DELETE_CONFLICT'; end if;
    return jsonb_build_object('deleted', true, 'replayed', true);
  end if;
  if p_kind = 'purchase' then
    select product_id into v_product_id from public.product_cost_entries where id = p_id::uuid for update;
  elsif p_kind = 'variant' then
    select producto_id into v_product_id from public.producto_variantes where id = p_id::bigint for update;
  elsif p_kind = 'product' then
    v_product_id := p_id::bigint;
  else raise exception 'ADMIN_DELETE_INVALID'; end if;
  if v_product_id is not null then perform pg_advisory_xact_lock(93000, v_product_id::integer); end if;
  perform 1 from public.productos where id = v_product_id for update;
  v_impact := public.admin_force_delete_impact(p_kind, p_id);
  if p_confirmation is distinct from v_impact->>'confirmation' then raise exception 'ADMIN_DELETE_CONFIRMATION'; end if;
  if p_fingerprint is distinct from v_impact->>'fingerprint' then raise exception 'ADMIN_DELETE_CONFLICT'; end if;
  if p_kind = 'purchase' then perform public.force_delete_purchase_super_admin(p_id::uuid, p_actor_id);
  elsif p_kind = 'product' then perform public.force_delete_product_super_admin(p_id::bigint, p_actor_id);
  else perform public.force_delete_product_variant_super_admin(p_id::bigint, p_actor_id); end if;
  insert into public.admin_destructive_operations(idempotency_key, actor_id, kind, target_id, impact)
    values(p_idempotency_key, p_actor_id, p_kind, p_id, v_impact);
  return jsonb_build_object('deleted', true, 'replayed', false);
end;
$$;


ALTER FUNCTION "public"."admin_confirm_force_delete"("p_kind" "text", "p_id" "text", "p_actor_id" "uuid", "p_confirmation" "text", "p_fingerprint" "text", "p_idempotency_key" "text") OWNER TO "postgres";

--
-- Name: admin_force_delete_impact("text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."admin_force_delete_impact"("p_kind" "text", "p_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_target jsonb;
  v_product_id bigint;
  v_variant_id bigint;
  v_product jsonb;
  v_variant jsonb;
  v_refs jsonb := '[]'::jsonb;
  v_ref record;
  v_count bigint;
  v_hash text;
  v_stock numeric := 0;
  v_received numeric := 0;
  v_affected jsonb := '{}'::jsonb;
  v_label text;
  v_confirmation text;
  v_target_table regclass;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'ADMIN_DELETE_FORBIDDEN'; end if;
  if p_kind = 'purchase' then
    select to_jsonb(t) into v_target from public.product_cost_entries t where id = p_id::uuid;
    v_product_id := (v_target->>'product_id')::bigint;
    v_variant_id := (v_target->>'variant_id')::bigint;
    v_received := case when v_target->>'reception_status' = 'anulada' then 0 else coalesce((v_target->>'received_quantity')::numeric, 0) end;
    v_affected := public.get_purchase_force_delete_impact(p_id::uuid);
    v_confirmation := 'ELIMINAR COMPRA ' || p_id;
    v_target_table := 'public.product_cost_entries'::regclass;
  elsif p_kind = 'product' then
    select to_jsonb(t) into v_target from public.productos t where id = p_id::bigint;
    v_product_id := p_id::bigint;
    v_target_table := 'public.productos'::regclass;
  elsif p_kind = 'variant' then
    select to_jsonb(t) into v_target from public.producto_variantes t where id = p_id::bigint;
    v_product_id := (v_target->>'producto_id')::bigint;
    v_variant_id := p_id::bigint;
    v_target_table := 'public.producto_variantes'::regclass;
  else raise exception 'ADMIN_DELETE_INVALID'; end if;
  if v_target is null then raise exception 'ADMIN_DELETE_NOT_FOUND'; end if;
  select to_jsonb(t) into v_product from public.productos t where id = v_product_id;
  select to_jsonb(t) into v_variant from public.producto_variantes t where id = v_variant_id;
  v_stock := coalesce((case when v_variant_id is not null then v_variant else v_product end ->>'stock')::numeric, 0);
  v_label := coalesce(v_product->>'nombre', v_target->>'article_name', 'Artículo histórico');
  if p_kind <> 'purchase' then
    v_confirmation := 'ELIMINAR ' || case when p_kind = 'product' then 'PRODUCTO ' else 'VARIANTE ' end ||
      coalesce(nullif(v_target->>'sku', ''), v_target->>'nombre');
  end if;

  -- Inventario real de referencias: incluye nuevas tablas con FK sin mantener
  -- una lista manual de relaciones. También incluye variantes al borrar padre.
  for v_ref in
    select c.conrelid::regclass as relation, a.attname as column_name,
      c.confrelid as parent, c.confdeltype as on_delete
    from pg_constraint c join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
    where c.contype = 'f' and array_length(c.conkey, 1) = 1
      and (c.confrelid = v_target_table or (p_kind = 'product' and c.confrelid = 'public.producto_variantes'::regclass))
    order by c.conrelid, a.attname
  loop
    if p_kind = 'product' and v_ref.parent = 'public.producto_variantes'::regclass then
      execute format('select count(*), md5(coalesce(string_agg(to_jsonb(t)::text, ''|'' order by to_jsonb(t)::text), '''')) from %s t where %I in (select id from public.producto_variantes where producto_id = $1)', v_ref.relation, v_ref.column_name)
        into v_count, v_hash using v_product_id;
    else
      execute format('select count(*), md5(coalesce(string_agg(to_jsonb(t)::text, ''|'' order by to_jsonb(t)::text), '''')) from %s t where %I::text = $1', v_ref.relation, v_ref.column_name)
        into v_count, v_hash using p_id;
    end if;
    v_refs := v_refs || jsonb_build_array(jsonb_build_object('table', v_ref.relation::text, 'column', v_ref.column_name, 'count', v_count, 'fingerprint', v_hash, 'onDelete', v_ref.on_delete));
  end loop;
  -- These historical links intentionally have no FK and must also be disclosed.
  select count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text), '' order by t.id), ''))
    into v_count, v_hash from public.audit_logs t
    where t.table_name = case p_kind when 'purchase' then 'product_cost_entries' when 'product' then 'productos' else 'producto_variantes' end
      and t.record_id = p_id;
  v_refs := v_refs || jsonb_build_array(jsonb_build_object('table','audit_logs','column','record_id','count',v_count,'fingerprint',v_hash,'onDelete','preserve'));
  if p_kind = 'variant' then
    select count(*), md5(coalesce(string_agg(md5(to_jsonb(t)::text), '' order by t.id), ''))
      into v_count, v_hash from public.mercadolibre_sales t
      where to_jsonb(t)->'raw_data'->'beyonix_cost_mapping'->>'variant_id' = p_id;
    v_refs := v_refs || jsonb_build_array(jsonb_build_object('table','mercadolibre_sales','column','raw_data','count',v_count,'fingerprint',v_hash,'onDelete','unlink'));
  end if;
  return jsonb_build_object(
    'kind', p_kind, 'id', p_id, 'product', v_label,
    'variant', v_variant->>'nombre', 'sku', coalesce(v_variant->>'sku', v_product->>'sku', v_target->>'sku'),
    'receivedQuantity', v_received, 'totalCost', coalesce((v_target->>'total_cost')::numeric, 0),
    'currentStock', v_stock, 'projectedStock', case when p_kind = 'purchase' and v_product_id is not null then v_stock - v_received else 0 end,
    'affectedSales', coalesce((v_affected->>'affected_sales_count')::bigint, 0),
    'variants', (select count(*) from public.producto_variantes where producto_id = v_product_id),
    'references', v_refs, 'confirmation', v_confirmation,
    'fingerprint', md5(v_target::text || coalesce(v_product::text, '') || coalesce(v_variant::text, '') || v_refs::text || v_affected::text)
  );
end;
$_$;


ALTER FUNCTION "public"."admin_force_delete_impact"("p_kind" "text", "p_id" "text") OWNER TO "postgres";

