-- Name: blocked_client_identifiers; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."blocked_client_identifiers" (
    "id" bigint NOT NULL,
    "identifier_type" "text" NOT NULL,
    "identifier_value" "text" NOT NULL,
    "reason" "text",
    "source_profile_id" "uuid",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "blocked_client_identifiers_type_check" CHECK (("identifier_type" = ANY (ARRAY['email'::"text", 'username'::"text", 'phone'::"text"])))
);


ALTER TABLE "public"."blocked_client_identifiers" OWNER TO "postgres";

--
-- Name: admin_get_blocked_client_identifiers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."admin_get_blocked_client_identifiers"() RETURNS SETOF "public"."blocked_client_identifiers"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select blocked.*
  from public.blocked_client_identifiers blocked
  where exists (
    select 1
    from public.profiles
    where id = auth.uid()
      and rol in ('admin', 'super_admin')
  )
  order by blocked.created_at desc
$$;


