--
-- Name: admin_get_client_order_summaries(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."admin_get_client_order_summaries"() RETURNS TABLE("profile_id" "uuid", "order_count" bigint, "total_spent" numeric, "last_order" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
  with authorized_profiles as (
    select
      p.id,
      u.email
    from public.profiles p
    left join auth.users u on u.id = p.id
    where p.rol in ('cliente', 'admin', 'super_admin')
      and public.is_current_user_admin()
  ),
  matched_orders as (
    select
      p.id as profile_id,
      o.id,
      o.usuario_id,
      o.cliente_email,
      o.total,
      o.estado,
      o.payment_status,
      o.created_at
    from authorized_profiles p
    join public.ordenes o on o.usuario_id = p.id

    union

    select
      p.id as profile_id,
      o.id,
      o.usuario_id,
      o.cliente_email,
      o.total,
      o.estado,
      o.payment_status,
      o.created_at
    from authorized_profiles p
    join public.ordenes o
      on p.email is not null
      and o.cliente_email is not null
      and lower(btrim(o.cliente_email)) = lower(btrim(p.email))
  )
  select
    o.profile_id,
    count(*)::bigint as order_count,
    coalesce(sum(o.total) filter (
      where o.estado in ('pagado', 'enviado', 'entregado')
        or o.payment_status = 'approved'
    ), 0) as total_spent,
    (array_agg(
      jsonb_build_object(
        'id', o.id,
        'usuario_id', o.usuario_id,
        'cliente_email', o.cliente_email,
        'total', o.total,
        'estado', o.estado,
        'payment_status', o.payment_status,
        'created_at', o.created_at
      )
      order by o.created_at desc, o.id desc
    ))[1] as last_order
  from matched_orders o
  group by o.profile_id;
$$;


ALTER FUNCTION "public"."admin_get_client_order_summaries"() OWNER TO "postgres";

