-- Name: FUNCTION "admin_get_client_profiles"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."admin_get_client_profiles"() IS 'Devuelve al panel administrativo clientes, administradores y superadministradores con sus datos completos. Sólo admin/super_admin obtienen filas (public.is_current_user_admin()); cualquier otro llamante recibe un resultado vacío.';


--
-- Name: apply_customer_credit_to_order("uuid", bigint, numeric, "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."apply_customer_credit_to_order"("p_user_id" "uuid", "p_order_id" bigint, "p_amount" numeric, "p_description" "text" DEFAULT 'Saldo a favor aplicado a compra'::"text", "p_source_key" "text" DEFAULT NULL::"text") RETURNS TABLE("movement_id" "uuid", "remaining_balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_balance numeric(12, 2);
  v_amount numeric(12, 2);
  v_source_key text;
  v_existing public.customer_credit_movements%rowtype;
  v_movement public.customer_credit_movements%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'No tenés permisos para aplicar saldo.';
  end if;

  v_amount := round(coalesce(p_amount, 0)::numeric, 2);

  if p_user_id is null or p_order_id is null or v_amount <= 0 then
    raise exception 'INVALID_CREDIT_APPLICATION';
  end if;

  perform pg_advisory_xact_lock(hashtext('customer-credit:' || p_user_id::text));

  select *
  into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if v_order.usuario_id is distinct from p_user_id then
    raise exception 'ORDER_USER_MISMATCH';
  end if;

  if coalesce(v_order.credit_balance_used, 0) > 0
     or v_order.credit_balance_movement_id is not null then
    raise exception 'ORDER_CREDIT_ALREADY_APPLIED';
  end if;

  v_source_key := coalesce(
    nullif(trim(p_source_key), ''),
    'order:' || p_order_id || ':customer-credit:debit'
  );

  select *
  into v_existing
  from public.customer_credit_movements
  where source_key = v_source_key
  limit 1;

  if found then
    raise exception 'CUSTOMER_CREDIT_DEBIT_ALREADY_EXISTS';
  end if;

  select public.get_customer_credit_balance(p_user_id)
  into v_balance;

  if v_amount > v_balance then
    raise exception 'INSUFFICIENT_CUSTOMER_CREDIT';
  end if;

  if v_amount > coalesce(v_order.original_total, v_order.total, 0) then
    raise exception 'CUSTOMER_CREDIT_EXCEEDS_ORDER_TOTAL';
  end if;

  insert into public.customer_credit_movements (
    user_id,
    movement_type,
    amount,
    description,
    source_type,
    source_id,
    order_id,
    created_by,
    source_key,
    resulting_balance,
    metadata
  ) values (
    p_user_id,
    'debit',
    v_amount,
    coalesce(nullif(trim(p_description), ''), 'Saldo a favor aplicado a compra'),
    'order',
    p_order_id::text,
    p_order_id,
    auth.uid(),
    v_source_key,
    v_balance - v_amount,
    jsonb_build_object(
      'order_id', p_order_id,
      'original_total', coalesce(v_order.original_total, v_order.total, 0)
    )
  )
  returning *
  into v_movement;

  update public.ordenes
  set
    credit_balance_used = v_amount,
    external_amount_due = greatest(
      coalesce(original_total, total, 0) - v_amount,
      0
    ),
    credit_balance_movement_id = v_movement.id,
    payment_composition = coalesce(payment_composition, '{}'::jsonb) ||
      jsonb_build_object(
        'credit_balance_used', v_amount,
        'external_amount_due', greatest(coalesce(original_total, total, 0) - v_amount, 0),
        'credit_movement_id', v_movement.id
      )
  where id = p_order_id;

  movement_id := v_movement.id;
  remaining_balance := v_balance - v_amount;
  return next;
end;
$$;


ALTER FUNCTION "public"."apply_customer_credit_to_order"("p_user_id" "uuid", "p_order_id" bigint, "p_amount" numeric, "p_description" "text", "p_source_key" "text") OWNER TO "postgres";

--
-- Name: order_claims; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."order_claims" (
    "id" bigint NOT NULL,
    "order_id" bigint NOT NULL,
    "user_id" "uuid" NOT NULL,
    "claim_type" "text" NOT NULL,
    "status" "text" DEFAULT 'recibido'::"text" NOT NULL,
    "failure_type" "text",
    "description" "text" NOT NULL,
    "started_at" "text",
    "admin_response" "text",
    "rejection_reason" "text",
    "resolution" "text",
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "offered_resolutions" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "customer_selected_resolution" "text",
    "last_customer_message_at" timestamp with time zone,
    "last_admin_response_at" timestamp with time zone,
    "admin_needs_action" boolean DEFAULT false NOT NULL,
    "first_reviewed_at" timestamp with time zone,
    "first_reviewed_by" "uuid",
    "replacement_product" "text",
    "replacement_extra_cost" numeric(12,2),
    "replacement_payment_link" "text",
    "replacement_shipping_company" "text",
    "replacement_tracking" "text",
    "replacement_sent_at" timestamp with time zone,
    "coupon_code" "text",
    "coupon_created_at" timestamp with time zone,
    "replacement_original_product" "text",
    "replacement_original_order_item_id" bigint,
    "replacement_original_variant" "text",
    "replacement_original_price" numeric(12,2),
    "replacement_requested_product_id" bigint,
    "replacement_requested_product" "text",
    "replacement_requested_variant_id" bigint,
    "replacement_requested_variant" "text",
    "replacement_requested_quantity" integer,
    "replacement_requested_stock" integer,
    "replacement_requested_price" numeric(12,2),
    "replacement_price_difference" numeric(12,2),
    "replacement_change_reason" "text",
    "replacement_customer_selected_at" timestamp with time zone,
    "affected_items" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "affected_items_updated_at" timestamp with time zone,
    "affected_items_updated_by" "uuid",
    "refund_account_holder" "text",
    "refund_account_identifier" "text",
    "refund_bank" "text",
    "refund_amount_confirmed" "text",
    "refund_details_submitted_at" timestamp with time zone,
    "refund_completed_at" timestamp with time zone,
    "refund_completed_by" "uuid",
    CONSTRAINT "order_claims_affected_items_is_array" CHECK (("jsonb_typeof"("affected_items") = 'array'::"text")),
    CONSTRAINT "order_claims_claim_type_check" CHECK (("claim_type" = ANY (ARRAY['transporte_48hs'::"text", 'garantia_beyonix'::"text"]))),
    CONSTRAINT "order_claims_customer_selected_resolution_check" CHECK ((("customer_selected_resolution" IS NULL) OR ("customer_selected_resolution" = ANY (ARRAY['cambio_producto'::"text", 'envio_unidad_faltante'::"text", 'reintegro_total'::"text", 'reintegro_parcial'::"text", 'saldo_a_favor'::"text", 'cupon_descuento'::"text", 'otro'::"text"])))),
    CONSTRAINT "order_claims_offered_resolutions_check" CHECK (("offered_resolutions" <@ ARRAY['cambio_producto'::"text", 'envio_unidad_faltante'::"text", 'reintegro_total'::"text", 'reintegro_parcial'::"text", 'saldo_a_favor'::"text", 'cupon_descuento'::"text", 'otro'::"text"])),
    CONSTRAINT "order_claims_resolution_check" CHECK ((("resolution" IS NULL) OR ("resolution" = ANY (ARRAY['cambio_producto'::"text", 'envio_unidad_faltante'::"text", 'reintegro_total'::"text", 'reintegro_parcial'::"text", 'saldo_a_favor'::"text", 'cupon_descuento'::"text", 'rechazado'::"text", 'otro'::"text"])))),
    CONSTRAINT "order_claims_status_check" CHECK (("status" = ANY (ARRAY['recibido'::"text", 'en_revision'::"text", 'falta_informacion'::"text", 'aprobado'::"text", 'reintegro_pendiente'::"text", 'cambio_pendiente'::"text", 'cupon_pendiente'::"text", 'reemplazo_enviado'::"text", 'rechazado'::"text", 'cerrado'::"text"])))
);


