--
-- Name: audit_business_cost_movement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."audit_business_cost_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_configured_actor text := nullif(
    current_setting('beyonix.actor_id', true),
    ''
  );
  v_actor_id uuid := coalesce(v_configured_actor::uuid, auth.uid());
  v_actor_email text;
  v_record_id text;
begin
  select coalesce(profiles.email, users.email::text)
  into v_actor_email
  from auth.users users
  left join public.profiles on profiles.id = users.id
  where users.id = v_actor_id;

  v_record_id := case
    when tg_op = 'DELETE' then old.id::text
    else new.id::text
  end;

  insert into public.audit_logs (
    table_name,
    action,
    record_id,
    actor_user_id,
    actor_email,
    before_data,
    after_data
  ) values (
    tg_table_name,
    tg_op,
    v_record_id,
    v_actor_id,
    v_actor_email,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."audit_business_cost_movement"() OWNER TO "postgres";

--
-- Name: audit_log_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."audit_log_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid;
  v_actor_email text;
  v_record_id text;
begin
  if current_setting('app.audit_skip', true) = 'true' then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  v_actor_user_id := auth.uid();

  select profiles.email
    into v_actor_email
  from public.profiles
  where profiles.id = v_actor_user_id;

  v_actor_email := coalesce(v_actor_email, auth.jwt() ->> 'email');

  if tg_op = 'DELETE' then
    v_record_id := old.id::text;
  else
    v_record_id := new.id::text;
  end if;

  insert into public.audit_logs (
    table_name,
    action,
    record_id,
    actor_user_id,
    actor_email,
    before_data,
    after_data
  )
  values (
    tg_table_name,
    tg_op,
    v_record_id,
    v_actor_user_id,
    v_actor_email,
    case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) else null end
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."audit_log_change"() OWNER TO "postgres";

--
-- Name: audit_order_replacement_created(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."audit_order_replacement_created"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  insert into public.audit_logs (
    table_name, action, record_id, actor_user_id, actor_email, before_data, after_data
  ) values (
    'order_replacements', 'INSERT', new.id::text, new.created_by,
    (select email from public.profiles where id = new.created_by), null,
    to_jsonb(new) - 'idempotency_key'
  );
  return new;
end;
$$;


