--
-- Name: available_stock_for_session(bigint, bigint, "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."available_stock_for_session"("p_product_id" bigint, "p_variant_id" bigint, "p_conditioned_stock_id" "uuid", "p_session_id" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_stock integer;
  v_reserved_other integer;
begin
  if p_conditioned_stock_id is not null then
    select offers.available_quantity into v_stock
    from public.conditioned_inventory_offers offers
    where offers.id = p_conditioned_stock_id
      and offers.product_id = p_product_id;
  elsif p_variant_id is not null then
    select coalesce(variants.stock, 0) into v_stock
    from public.producto_variantes variants
    where variants.id = p_variant_id
      and variants.producto_id = p_product_id
      and variants.activo;
  else
    select coalesce(products.stock, 0) into v_stock
    from public.productos products
    where products.id = p_product_id and products.activo;
  end if;

  if not found then return null; end if;

  select coalesce(sum(reservations.quantity), 0)::integer
  into v_reserved_other
  from public.stock_reservations reservations
  where reservations.product_id = p_product_id
    and reservations.variant_id is not distinct from p_variant_id
    and reservations.conditioned_stock_id is not distinct from p_conditioned_stock_id
    and reservations.expires_at > now()
    and (p_session_id is null or reservations.session_id is distinct from p_session_id);

  return coalesce(v_stock, 0) - coalesce(v_reserved_other, 0);
end;
$$;


ALTER FUNCTION "public"."available_stock_for_session"("p_product_id" bigint, "p_variant_id" bigint, "p_conditioned_stock_id" "uuid", "p_session_id" "text") OWNER TO "postgres";

--
-- Name: begin_arca_credit_note_processing(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."begin_arca_credit_note_processing"("p_order_id" bigint) RETURNS TABLE("id" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  current_order public.ordenes%rowtype;
  processing_order_id bigint;
begin
  perform pg_advisory_xact_lock(hashtext('beyonix-arca-credit-note-processing'));

  select *
    into current_order
  from public.ordenes
  where ordenes.id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if current_order.credit_note_status = 'authorized' and current_order.credit_note_cae is not null then
    raise exception 'CREDIT_NOTE_ALREADY_AUTHORIZED';
  end if;

  if current_order.credit_note_status = 'processing' then
    raise exception 'CREDIT_NOTE_ALREADY_PROCESSING';
  end if;

  select ordenes.id
    into processing_order_id
  from public.ordenes
  where ordenes.credit_note_status = 'processing'
    and ordenes.id <> p_order_id
  limit 1;

  if processing_order_id is not null then
    raise exception 'CREDIT_NOTE_PROCESSING_IN_PROGRESS';
  end if;

  update public.ordenes
  set credit_note_status = 'processing',
      credit_note_error = null,
      credit_note_required = true
  where ordenes.id = p_order_id
    and (
      ordenes.credit_note_status is null
      or ordenes.credit_note_status = 'pending'
      or ordenes.credit_note_status = 'error'
    )
  returning *
    into current_order;

  if not found then
    raise exception 'CREDIT_NOTE_ALREADY_PROCESSING';
  end if;

  return query
  select current_order.id;
end;
$$;


ALTER FUNCTION "public"."begin_arca_credit_note_processing"("p_order_id" bigint) OWNER TO "postgres";

--
-- Name: begin_arca_invoice_processing(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."begin_arca_invoice_processing"("p_order_id" bigint) RETURNS TABLE("id" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  current_order public.ordenes%rowtype;
  processing_order_id bigint;
begin
  perform pg_advisory_xact_lock(hashtext('beyonix-arca-invoice-processing'));

  select *
    into current_order
  from public.ordenes
  where ordenes.id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if current_order.invoice_status = 'authorized' and current_order.invoice_cae is not null then
    raise exception 'INVOICE_ALREADY_AUTHORIZED';
  end if;

  if current_order.invoice_status = 'processing' then
    raise exception 'INVOICE_ALREADY_PROCESSING';
  end if;

  select ordenes.id
    into processing_order_id
  from public.ordenes
  where ordenes.invoice_status = 'processing'
    and ordenes.id <> p_order_id
  limit 1;

  if processing_order_id is not null then
    raise exception 'INVOICE_PROCESSING_IN_PROGRESS';
  end if;

  update public.ordenes
  set invoice_status = 'processing'
  where ordenes.id = p_order_id
    and (
      ordenes.invoice_status is null
      or ordenes.invoice_status = 'error'
    )
  returning *
    into current_order;

  if not found then
    raise exception 'INVOICE_ALREADY_PROCESSING';
  end if;

  return query
  select current_order.id;
end;
$$;


