--
-- Name: begin_mercadopago_order_refund(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."begin_mercadopago_order_refund"("p_order_id" bigint, "p_admin_id" "uuid") RETURNS TABLE("refund_id" "uuid", "payment_id" "text", "amount" numeric, "idempotency_key" "text", "status" "text", "should_call_mp" boolean, "mp_refund_id" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_existing public.mercadopago_order_refunds%rowtype;
  v_row public.mercadopago_order_refunds%rowtype;
  v_role text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  if p_order_id is null or p_admin_id is null then
    raise exception 'INVALID_REFUND_REQUEST';
  end if;

  select rol into v_role from public.profiles where id = p_admin_id;
  if coalesce(v_role, '') not in ('admin', 'super_admin') then
    raise exception 'REFUND_FORBIDDEN';
  end if;

  select *
  into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  -- Se busca cualquier intento existente ANTES de exigir las precondiciones
  -- de "orden elegible para un refund nuevo" -- un refund ya confirmado (o
  -- en curso) es siempre un no-op idempotente, incluso si para entonces
  -- ordenes.financial_status ya cambió a 'refunded' y por lo tanto ya NO
  -- pasaría el chequeo de 'refund_pending' de más abajo.
  select *
  into v_existing
  from public.mercadopago_order_refunds
  where order_id = p_order_id
  order by created_at desc
  limit 1
  for update;

  if found and v_existing.status = 'confirmed' then
    refund_id := v_existing.id;
    payment_id := v_existing.payment_id;
    amount := v_existing.amount;
    idempotency_key := v_existing.idempotency_key;
    status := v_existing.status;
    should_call_mp := false;
    mp_refund_id := v_existing.mp_refund_id;
    return next;
    return;
  end if;

  if found and v_existing.status in ('processing', 'needs_reconciliation') then
    -- Ya hay un intento en curso o ambiguo: nunca se dispara un segundo
    -- POST. El llamador debe reconciliar, no reintentar a ciegas.
    refund_id := v_existing.id;
    payment_id := v_existing.payment_id;
    amount := v_existing.amount;
    idempotency_key := v_existing.idempotency_key;
    status := v_existing.status;
    should_call_mp := false;
    mp_refund_id := v_existing.mp_refund_id;
    return next;
    return;
  end if;

  -- A partir de acá se va a crear o reclamar un intento NUEVO (no existe
  -- ninguno confirmado/en curso): recién ahora se exigen las precondiciones
  -- completas de "orden elegible para un refund".
  if v_order.payment_method_id is distinct from 'mercadopago' then
    raise exception 'ORDER_NOT_PAID_BY_MERCADOPAGO';
  end if;

  if nullif(trim(coalesce(v_order.payment_id, '')), '') is null then
    raise exception 'ORDER_MISSING_MERCADOPAGO_PAYMENT_ID';
  end if;

  if coalesce(v_order.payment_confirmed_amount, 0) <= 0 then
    raise exception 'ORDER_MISSING_CONFIRMED_AMOUNT';
  end if;

  if v_order.financial_status is distinct from 'refund_pending' then
    raise exception 'ORDER_NOT_REFUND_PENDING';
  end if;

  -- NUEVO (punto 3): un pedido facturado necesita NC antes de reintegrar,
  -- sin importar el medio de pago -- misma exigencia que ya aplica a
  -- transferencia (commit_order_refund_proof). credit_note_required ya es
  -- false para pedidos que nunca se facturaron, así que esto nunca bloquea
  -- ese caso.
  if v_order.credit_note_required then
    raise exception 'CREDIT_NOTE_REQUIRED';
  end if;

  -- Defensa en profundidad: approve_order_claim_cancellation ya bloquea
  -- aprobar una cancelación sobre un pedido despachado, pero un refund
  -- puede ejecutarse en un momento posterior a esa aprobación -- se
  -- vuelve a chequear acá con las mismas reglas.
  if lower(coalesce(v_order.estado, '')) in (
       'enviado', 'en_camino', 'visita_fallida', 'en_sucursal',
       'retiro_pendiente', 'retiro_vencido', 'en_devolucion',
       'devuelto_beyonix', 'entregado'
     )
     or nullif(trim(v_order.tracking_number), '') is not null
     or nullif(trim(v_order.andreani_tracking), '') is not null
     or nullif(trim(v_order.andreani_envio_id), '') is not null then
    raise exception 'ORDER_ALREADY_DISPATCHED';
  end if;

  if found and v_existing.status = 'requested' then
    -- Fila creada pero el POST nunca se confirmó como enviado (crash entre
    -- el commit de esta función y la llamada HTTP): se reclama la MISMA
    -- fila, con la MISMA idempotency_key -- nunca una nueva.
    update public.mercadopago_order_refunds
    set status = 'processing', attempt_count = attempt_count + 1
    where id = v_existing.id
    returning * into v_row;
  else
    -- Ninguna fila activa (nunca hubo intento, o el último terminó en
    -- 'failed' -- un rechazo definitivo previo SÍ admite un intento nuevo,
    -- con una idempotency_key propia).
    insert into public.mercadopago_order_refunds (
      order_id, payment_id, amount, status, idempotency_key, requested_by
    ) values (
      p_order_id, v_order.payment_id, v_order.payment_confirmed_amount,
      'processing', 'mercadopago-order-refund:' || gen_random_uuid()::text, p_admin_id
    )
    returning * into v_row;
  end if;

  refund_id := v_row.id;
  payment_id := v_row.payment_id;
  amount := v_row.amount;
  idempotency_key := v_row.idempotency_key;
  status := v_row.status;
  should_call_mp := true;
  mp_refund_id := v_row.mp_refund_id;
  return next;
end;
$$;


ALTER FUNCTION "public"."begin_mercadopago_order_refund"("p_order_id" bigint, "p_admin_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "begin_mercadopago_order_refund"("p_order_id" bigint, "p_admin_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."begin_mercadopago_order_refund"("p_order_id" bigint, "p_admin_id" "uuid") IS 'Reclama atómicamente un intento de refund real contra Mercado Pago, idempotente por pedido (nunca dos intentos activos, nunca dos POST). Fix 20260917130000: exige credit_note_required=false (misma política fiscal que ya aplica a transferencia) antes de permitir el refund -- defensa en profundidad, la UI ya secuencia NC antes que esto.';


--
-- Name: begin_order_claim_operation("uuid", "uuid", bigint, "text", "text"[], "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."begin_order_claim_operation"("p_id" "uuid", "p_actor_id" "uuid", "p_order_id" bigint, "p_request_key" "text", "p_file_paths" "text"[], "p_bucket_id" "text" DEFAULT 'order-claim-evidence'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_op public.order_claim_operations%rowtype;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'CLAIM_FORBIDDEN'; end if;
  if cardinality(p_file_paths)>6 or exists(select 1 from unnest(p_file_paths) path where path not like p_actor_id::text||'/'||p_id::text||'/%' or path like '%..%') then raise exception 'CLAIM_INVALID'; end if;
  insert into public.order_claim_operations(id,actor_id,order_id,request_key,file_paths,bucket_id)
  values(p_id,p_actor_id,p_order_id,p_request_key,p_file_paths,p_bucket_id) on conflict(actor_id,request_key) do nothing;
  select * into v_op from public.order_claim_operations where actor_id=p_actor_id and request_key=p_request_key for update;
  if v_op.order_id<>p_order_id or v_op.bucket_id<>p_bucket_id then raise exception 'CLAIM_INVALID'; end if;
  if v_op.status='cleaned' then
    update public.order_claim_operations set status='uploading', file_paths=p_file_paths, expires_at=now()+interval '10 minutes' where id=v_op.id returning * into v_op;
    return to_jsonb(v_op)||jsonb_build_object('acquired',true);
  end if;
  return to_jsonb(v_op)||jsonb_build_object('acquired',v_op.id=p_id);
end $$;


ALTER FUNCTION "public"."begin_order_claim_operation"("p_id" "uuid", "p_actor_id" "uuid", "p_order_id" bigint, "p_request_key" "text", "p_file_paths" "text"[], "p_bucket_id" "text") OWNER TO "postgres";

--
-- Name: order_credit_notes; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."order_credit_notes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "order_id" bigint NOT NULL,
    "claim_id" bigint,
    "status" "text" DEFAULT 'processing'::"text" NOT NULL,
    "destination" "text" DEFAULT 'external_refund'::"text" NOT NULL,
    "reason" "text" NOT NULL,
    "items_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "manual_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "total_amount" numeric(12,2) NOT NULL,
    "invoice_point" integer NOT NULL,
    "invoice_number" bigint NOT NULL,
    "voucher_point" integer,
    "voucher_number" bigint,
    "cae" "text",
    "cae_due" "date",
    "error" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "authorized_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "operation_type" "text" DEFAULT 'devolucion_parcial'::"text" NOT NULL,
    "reason_code" "text" DEFAULT 'otro'::"text" NOT NULL,
    "reason_detail" "text",
    "resolution_type" "text" DEFAULT 'saldo_favor'::"text" NOT NULL,
    "management_status" "text" DEFAULT 'nota_credito_pendiente'::"text" NOT NULL,
    "reception_status" "text" DEFAULT 'pendiente_despacho'::"text" NOT NULL,
    "reception_exception" boolean DEFAULT false NOT NULL,
    "reception_date" "date",
    "reception_notes" "text",
    "physical_condition" "text",
    "accessories_complete" boolean,
    "original_packaging" "text",
    "original_shipping_paid" numeric(12,2) DEFAULT 0 NOT NULL,
    "original_shipping_discounted" numeric(12,2) DEFAULT 0 NOT NULL,
    "original_shipping_refunded" numeric(12,2) DEFAULT 0 NOT NULL,
    "return_shipping_party" "text" DEFAULT 'cliente'::"text" NOT NULL,
    "return_shipping_provider" "text",
    "return_shipping_tracking" "text",
    "return_shipping_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "return_shipping_dispatched_at" "date",
    "return_shipping_received_at" "date",
    "new_shipping_party" "text" DEFAULT 'no_corresponde'::"text" NOT NULL,
    "new_shipping_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "other_adjustment_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "stock_destination" "text" DEFAULT 'pendiente_revision'::"text" NOT NULL,
    "stock_reviewed_by" "uuid",
    "stock_reviewed_at" timestamp with time zone,
    "settlement_status" "text" DEFAULT 'pendiente'::"text" NOT NULL,
    "settlement_reference" "text",
    "settlement_date" "date",
    "reception_exception_reason" "text",
    CONSTRAINT "order_credit_notes_amount_breakdown" CHECK (("total_amount" = ("items_amount" + "manual_amount"))),
    CONSTRAINT "order_credit_notes_authorization_complete" CHECK ((("status" <> 'authorized'::"text") OR (("voucher_point" IS NOT NULL) AND ("voucher_number" IS NOT NULL) AND ("cae" IS NOT NULL) AND ("cae_due" IS NOT NULL) AND ("authorized_at" IS NOT NULL)))),
    CONSTRAINT "order_credit_notes_destination_check" CHECK (("destination" = ANY (ARRAY['external_refund'::"text", 'customer_balance'::"text", 'none'::"text"]))),
    CONSTRAINT "order_credit_notes_invoice_number_check" CHECK (("invoice_number" > 0)),
    CONSTRAINT "order_credit_notes_invoice_point_check" CHECK (("invoice_point" > 0)),
    CONSTRAINT "order_credit_notes_items_amount_check" CHECK (("items_amount" >= (0)::numeric)),
    CONSTRAINT "order_credit_notes_management_status_check" CHECK (("management_status" = ANY (ARRAY['borrador'::"text", 'esperando_devolucion'::"text", 'producto_transito'::"text", 'pendiente_revision'::"text", 'aprobada'::"text", 'nota_credito_pendiente'::"text", 'nota_credito_emitida'::"text", 'acreditacion_pendiente'::"text", 'reembolso_pendiente'::"text", 'cambio_pendiente'::"text", 'finalizada'::"text", 'rechazada'::"text", 'cancelada'::"text"]))),
    CONSTRAINT "order_credit_notes_manual_amount_check" CHECK (("manual_amount" >= (0)::numeric)),
    CONSTRAINT "order_credit_notes_new_shipping_party_check" CHECK (("new_shipping_party" = ANY (ARRAY['cliente'::"text", 'beyonix'::"text", 'no_corresponde'::"text"]))),
    CONSTRAINT "order_credit_notes_operation_type_check" CHECK (("operation_type" = ANY (ARRAY['devolucion_parcial'::"text", 'devolucion_total'::"text", 'cambio_producto'::"text", 'cancelacion_antes_despacho'::"text", 'reembolso_excepcional'::"text", 'ajuste_manual'::"text"]))),
    CONSTRAINT "order_credit_notes_reason_code_check" CHECK (("reason_code" = ANY (ARRAY['arrepentimiento'::"text", 'producto_defectuoso'::"text", 'producto_incorrecto'::"text", 'producto_faltante'::"text", 'producto_danado_envio'::"text", 'garantia_aprobada'::"text", 'cancelacion_antes_despacho'::"text", 'error_administrativo'::"text", 'otro'::"text"]))),
    CONSTRAINT "order_credit_notes_reception_status_check" CHECK (("reception_status" = ANY (ARRAY['no_requiere'::"text", 'pendiente_despacho'::"text", 'en_transito'::"text", 'recibido_revision'::"text", 'producto_aprobado'::"text", 'producto_rechazado'::"text", 'aprobado_parcial'::"text"]))),
    CONSTRAINT "order_credit_notes_resolution_type_check" CHECK (("resolution_type" = ANY (ARRAY['saldo_favor'::"text", 'medio_pago'::"text", 'transferencia'::"text", 'cambio_producto'::"text", 'reposicion_sin_costo'::"text", 'ajuste_administrativo'::"text"]))),
    CONSTRAINT "order_credit_notes_return_shipping_party_check" CHECK (("return_shipping_party" = ANY (ARRAY['cliente'::"text", 'beyonix'::"text", 'no_corresponde'::"text"]))),
    CONSTRAINT "order_credit_notes_settlement_status_check" CHECK (("settlement_status" = ANY (ARRAY['pendiente'::"text", 'procesando'::"text", 'completado'::"text", 'rechazado'::"text"]))),
    CONSTRAINT "order_credit_notes_shipping_amounts_check" CHECK ((("original_shipping_paid" >= (0)::numeric) AND ("original_shipping_discounted" >= (0)::numeric) AND ("original_shipping_refunded" >= (0)::numeric) AND ("original_shipping_refunded" <= "original_shipping_paid") AND ("return_shipping_cost" >= (0)::numeric) AND ("new_shipping_cost" >= (0)::numeric) AND ("other_adjustment_amount" >= (0)::numeric))),
    CONSTRAINT "order_credit_notes_status_check" CHECK (("status" = ANY (ARRAY['processing'::"text", 'authorized'::"text", 'error'::"text"]))),
    CONSTRAINT "order_credit_notes_stock_destination_check" CHECK (("stock_destination" = ANY (ARRAY['stock_vendible'::"text", 'stock_observaciones'::"text", 'fallado'::"text", 'garantia_proveedor'::"text", 'no_reingresar'::"text", 'pendiente_revision'::"text"]))),
    CONSTRAINT "order_credit_notes_total_amount_check" CHECK (("total_amount" > (0)::numeric))
);


