--
-- Name: begin_partial_credit_note(bigint, bigint, "text", "text", numeric, numeric, numeric, integer, bigint, "uuid", "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."begin_partial_credit_note"("p_order_id" bigint, "p_claim_id" bigint, "p_destination" "text", "p_reason" "text", "p_items_amount" numeric, "p_manual_amount" numeric, "p_total_amount" numeric, "p_invoice_point" integer, "p_invoice_number" bigint, "p_created_by" "uuid", "p_items" "jsonb", "p_operation_type" "text") RETURNS "public"."order_credit_notes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_note public.order_credit_notes;
  v_invoice_total numeric(12, 2);
  v_order_user_id uuid;
  v_order_financial_status text;
  v_order_payment_confirmed_amount numeric(12, 2);
  v_order_external_amount_due numeric(12, 2);
  v_order_credit_balance_used numeric(12, 2);
  v_committed_total numeric(12, 2);
  v_external_paid numeric(12, 2);
  v_external_committed numeric(12, 2);
  v_refundable_remaining numeric(12, 2);
  v_item jsonb;
  v_order_item public.orden_items;
  v_committed_quantity integer;
  v_actor_role text;
  v_claim public.order_claims%rowtype;
  v_affected_item jsonb;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'No tenés permisos para emitir esta nota de crédito.';
  end if;

  select rol into v_actor_role
  from public.profiles
  where id = p_created_by;

  if coalesce(v_actor_role,'') not in ('admin', 'super_admin') then
    raise exception 'CREDIT_NOTE_ACTOR_FORBIDDEN';
  end if;

  if p_operation_type not in (
    'devolucion_parcial',
    'devolucion_total',
    'cambio_producto',
    'cancelacion_antes_despacho',
    'reembolso_excepcional',
    'ajuste_manual'
  ) then
    raise exception 'INVALID_CREDIT_NOTE_OPERATION_TYPE';
  end if;

  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'INVALID_CREDIT_NOTE_ITEM';
  end if;

  perform pg_advisory_xact_lock(91091, p_order_id::integer);

  -- Expiry cannot prove ARCA did not authorize the previous request.
  if exists(select 1 from public.order_credit_notes where order_id=p_order_id and status='processing') then
    raise exception 'CREDIT_NOTE_PROCESSING_IN_PROGRESS';
  end if;

  if p_destination not in ('external_refund', 'customer_balance', 'none') then
    raise exception 'INVALID_CREDIT_NOTE_DESTINATION';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'CREDIT_NOTE_REASON_REQUIRED';
  end if;

  if round(coalesce(p_total_amount, 0), 2) <= 0
     or round(coalesce(p_total_amount, 0), 2)
        <> round(coalesce(p_items_amount, 0) + coalesce(p_manual_amount, 0), 2) then
    raise exception 'INVALID_CREDIT_NOTE_AMOUNT';
  end if;

  if p_operation_type in ('ajuste_manual', 'reembolso_excepcional') then
    if v_actor_role <> 'super_admin' then
      raise exception 'CREDIT_NOTE_ADMIN_OPERATION_FORBIDDEN';
    end if;
    if p_claim_id is not null then
      raise exception 'INVALID_CREDIT_NOTE_CLAIM';
    end if;
    if jsonb_array_length(coalesce(p_items, '[]'::jsonb)) <> 0
       or round(coalesce(p_items_amount, 0), 2) <> 0 then
      raise exception 'CREDIT_NOTE_ADMIN_ITEMS_FORBIDDEN';
    end if;
  elsif p_claim_id is null then
    raise exception 'CLAIM_REQUIRED';
  end if;

  select
    round(total::numeric, 2),
    usuario_id,
    financial_status,
    payment_confirmed_amount,
    external_amount_due,
    credit_balance_used
  into
    v_invoice_total,
    v_order_user_id,
    v_order_financial_status,
    v_order_payment_confirmed_amount,
    v_order_external_amount_due,
    v_order_credit_balance_used
  from public.ordenes
  where id = p_order_id
    and invoice_status = 'authorized'
    and invoice_cae is not null
    and invoice_point = p_invoice_point
    and invoice_number = p_invoice_number
  for update;

  if v_invoice_total is null then
    raise exception 'AUTHORIZED_INVOICE_REQUIRED';
  end if;

  -- NUEVO (P0-3): un pedido ya liquidado por CUALQUIER canal (NC previa a
  -- customer_balance, refund de Mercado Pago confirmado, comprobante de
  -- transferencia commiteado) nunca puede recibir una segunda NC que mueva
  -- dinero. Simétrico al guard que ya tiene begin_mercadopago_order_refund
  -- (exige financial_status='refund_pending').
  if p_destination in ('external_refund', 'customer_balance')
     and v_order_financial_status = 'refunded' then
    raise exception 'ORDER_ALREADY_REFUNDED';
  end if;

  if p_claim_id is not null then
    select * into v_claim
    from public.order_claims
    where id = p_claim_id
      and order_id = p_order_id
    for update;

    if not found or v_claim.user_id is distinct from v_order_user_id then
      raise exception 'INVALID_CREDIT_NOTE_CLAIM';
    end if;
    if v_claim.status not in (
         'aprobado',
         'reintegro_pendiente',
         'cambio_pendiente',
         'cupon_pendiente',
         'reemplazo_enviado'
       )
       or v_claim.resolution = 'rechazado'
       or v_claim.failure_type = 'consulta_pedido' then
      raise exception 'INVALID_CREDIT_NOTE_CLAIM_STATUS';
    end if;
    if p_operation_type = 'cancelacion_antes_despacho'
       and v_claim.failure_type is distinct from 'cancelar_compra' then
      raise exception 'INVALID_CREDIT_NOTE_CLAIM_STATUS';
    end if;
    if p_operation_type <> 'cancelacion_antes_despacho'
       and v_claim.failure_type = 'cancelar_compra' then
      raise exception 'INVALID_CREDIT_NOTE_CLAIM_STATUS';
    end if;
  end if;

  select coalesce(sum(total_amount), 0)
  into v_committed_total
  from public.order_credit_notes
  where order_id = p_order_id
    and status in ('processing', 'authorized');

  if round(v_committed_total + p_total_amount, 2) > v_invoice_total then
    raise exception 'CREDIT_NOTE_EXCEEDS_INVOICE';
  end if;

  -- NUEVO (P0-1): tope FINANCIERO independiente del fiscal de arriba.
  -- Sólo aplica cuando la NC mueve dinero de verdad. No reemplaza el check
  -- fiscal (que sigue intacto, contra el total facturado): una NC puede
  -- seguir representando fiscalmente el valor facturado completo, pero el
  -- importe que efectivamente se acredita/reintegra por este destino nunca
  -- puede superar lo que todavía queda pendiente de devolver en dinero
  -- externo.
  if p_destination in ('external_refund', 'customer_balance') then
    v_external_paid := coalesce(
      nullif(v_order_payment_confirmed_amount, 0),
      v_order_external_amount_due,
      greatest(v_invoice_total - coalesce(v_order_credit_balance_used, 0), 0),
      0
    );

    select coalesce(sum(total_amount), 0)
    into v_external_committed
    from public.order_credit_notes
    where order_id = p_order_id
      and destination in ('external_refund', 'customer_balance')
      and status in ('processing', 'authorized');

    v_refundable_remaining := greatest(round(v_external_paid, 2) - v_external_committed, 0);

    if round(p_total_amount, 2) > v_refundable_remaining then
      raise exception 'CREDIT_NOTE_EXCEEDS_REFUNDABLE_AMOUNT';
    end if;
  end if;

  for v_item in select value from jsonb_array_elements(coalesce(p_items, '[]'::jsonb))
  loop
    select *
    into v_order_item
    from public.orden_items
    where id = (v_item->>'order_item_id')::bigint
      and orden_id = p_order_id;

    if not found then
      raise exception 'INVALID_CREDIT_NOTE_ITEM';
    end if;

    if p_claim_id is not null then
      v_affected_item := null;
      select affected.value into v_affected_item
      from jsonb_array_elements(coalesce(v_claim.affected_items, '[]'::jsonb)) affected
      where (affected.value->>'order_item_id')::bigint = v_order_item.id
      limit 1;

      if v_affected_item is null
         or (v_item->>'quantity')::integer > (v_affected_item->>'quantity')::integer then
        raise exception 'INVALID_CREDIT_NOTE_CLAIM_ITEM';
      end if;
    end if;

    select coalesce(sum(cni.quantity), 0)
    into v_committed_quantity
    from public.order_credit_note_items cni
    join public.order_credit_notes cn on cn.id = cni.credit_note_id
    where cni.order_item_id = v_order_item.id
      and cn.status in ('processing', 'authorized');

    if (v_item->>'quantity')::integer <= 0
       or v_committed_quantity + (v_item->>'quantity')::integer > v_order_item.cantidad then
      raise exception 'CREDIT_NOTE_ITEM_QUANTITY_EXCEEDED';
    end if;
  end loop;

  insert into public.order_credit_notes (
    order_id,
    claim_id,
    destination,
    reason,
    items_amount,
    manual_amount,
    total_amount,
    invoice_point,
    invoice_number,
    created_by,
    operation_type
  )
  values (
    p_order_id,
    p_claim_id,
    p_destination,
    trim(p_reason),
    round(p_items_amount, 2),
    round(p_manual_amount, 2),
    round(p_total_amount, 2),
    p_invoice_point,
    p_invoice_number,
    p_created_by,
    p_operation_type
  )
  returning * into v_note;

  insert into public.order_credit_note_items (
    credit_note_id,
    order_item_id,
    quantity,
    unit_amount,
    total_amount,
    product_name,
    variant_name
  )
  select
    v_note.id,
    (value->>'order_item_id')::bigint,
    (value->>'quantity')::integer,
    round((value->>'unit_amount')::numeric, 4),
    round((value->>'total_amount')::numeric, 2),
    left(value->>'product_name', 240),
    nullif(left(value->>'variant_name', 240), '')
  from jsonb_array_elements(coalesce(p_items, '[]'::jsonb));

  return v_note;
exception
  when unique_violation then
    raise exception 'CREDIT_NOTE_PROCESSING_IN_PROGRESS';
end;
$$;


ALTER FUNCTION "public"."begin_partial_credit_note"("p_order_id" bigint, "p_claim_id" bigint, "p_destination" "text", "p_reason" "text", "p_items_amount" numeric, "p_manual_amount" numeric, "p_total_amount" numeric, "p_invoice_point" integer, "p_invoice_number" bigint, "p_created_by" "uuid", "p_items" "jsonb", "p_operation_type" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "begin_partial_credit_note"("p_order_id" bigint, "p_claim_id" bigint, "p_destination" "text", "p_reason" "text", "p_items_amount" numeric, "p_manual_amount" numeric, "p_total_amount" numeric, "p_invoice_point" integer, "p_invoice_number" bigint, "p_created_by" "uuid", "p_items" "jsonb", "p_operation_type" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."begin_partial_credit_note"("p_order_id" bigint, "p_claim_id" bigint, "p_destination" "text", "p_reason" "text", "p_items_amount" numeric, "p_manual_amount" numeric, "p_total_amount" numeric, "p_invoice_point" integer, "p_invoice_number" bigint, "p_created_by" "uuid", "p_items" "jsonb", "p_operation_type" "text") IS 'Reserva una NC serializada: devoluciones con claim válido y productos afectados, o ajustes sin claim exclusivos de super_admin y sin items. Fix 20260917120000: cuando el destino mueve dinero (external_refund/customer_balance), exige además que el pedido no esté ya refunded y que el importe no supere lo que todavía falta devolver en dinero externo (payment_confirmed_amount menos lo ya comprometido por NC previas) -- independiente del tope fiscal contra el total facturado, que sigue sin cambios.';


--
-- Name: begin_partial_credit_note(bigint, bigint, "text", "text", numeric, numeric, numeric, integer, bigint, "uuid", "jsonb", "text", "uuid"[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."begin_partial_credit_note"("p_order_id" bigint, "p_claim_id" bigint, "p_destination" "text", "p_reason" "text", "p_items_amount" numeric, "p_manual_amount" numeric, "p_total_amount" numeric, "p_invoice_point" integer, "p_invoice_number" bigint, "p_created_by" "uuid", "p_items" "jsonb", "p_operation_type" "text", "p_expected_note_ids" "uuid"[]) RETURNS "public"."order_credit_notes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_ids uuid[]; v_note public.order_credit_notes%rowtype;
begin
  if auth.role() is distinct from 'service_role' or not exists(select 1 from public.profiles where id=p_created_by and rol in ('admin','super_admin')) then raise exception 'CREDIT_NOTE_ACTOR_FORBIDDEN'; end if;
  perform pg_advisory_xact_lock(91091,p_order_id::integer);
  perform id from public.ordenes where id=p_order_id for update;
  select coalesce(array_agg(id order by id),'{}'::uuid[]) into v_ids from public.order_credit_notes where order_id=p_order_id and status in ('processing','authorized');
  if p_expected_note_ids is null or v_ids is distinct from (select coalesce(array_agg(x order by x),'{}'::uuid[]) from unnest(p_expected_note_ids) x) then raise exception 'CREDIT_NOTE_SNAPSHOT_CONFLICT'; end if;
  -- El motor canónico conserva importes, elegibilidad, cantidades y permisos.
  select * into v_note from public.begin_partial_credit_note(p_order_id,p_claim_id,p_destination,p_reason,p_items_amount,p_manual_amount,p_total_amount,p_invoice_point,p_invoice_number,p_created_by,p_items,p_operation_type);
  return v_note;
end $$;


ALTER FUNCTION "public"."begin_partial_credit_note"("p_order_id" bigint, "p_claim_id" bigint, "p_destination" "text", "p_reason" "text", "p_items_amount" numeric, "p_manual_amount" numeric, "p_total_amount" numeric, "p_invoice_point" integer, "p_invoice_number" bigint, "p_created_by" "uuid", "p_items" "jsonb", "p_operation_type" "text", "p_expected_note_ids" "uuid"[]) OWNER TO "postgres";

--
-- Name: checkout_reservation_ttl(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."checkout_reservation_ttl"() RETURNS interval
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  select interval '30 minutes';
$$;


ALTER FUNCTION "public"."checkout_reservation_ttl"() OWNER TO "postgres";

--
-- Name: FUNCTION "checkout_reservation_ttl"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."checkout_reservation_ttl"() IS 'Duración de una reserva de checkout. Debe coincidir con MERCADOPAGO_PREFERENCE_LIFETIME_MINUTES: una reserva nunca puede vencer antes que la preferencia que todavía se puede pagar.';


--
-- Name: claim_andreani_shipment_creation(bigint, "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_andreani_shipment_creation"("p_order_id" bigint, "p_claim_token" "uuid", "p_environment" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_attempts integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'No tenés permisos para generar este envío.';
  end if;

  if p_order_id is null or p_claim_token is null then
    raise exception 'ANDREANI_SHIPMENT_CLAIM_INVALID';
  end if;

  if p_environment is null or p_environment not in ('QA', 'PROD') then
    raise exception 'ANDREANI_SHIPMENT_CLAIM_INVALID_ENVIRONMENT';
  end if;

  -- La ausencia, un JSON inválido o enabled=false bloquean todo claim nuevo.
  perform 1 from public.site_settings
  where key = 'andreani_commercial' and value -> 'enabled' = 'true'::jsonb
  for share;
  if not found then
    return null;
  end if;

  -- Un claim vencido es ambiguo aunque haya sido tomado en otro ambiente:
  -- no puede abrirse otro POST hasta conciliar el resultado externo. Misma
  -- semántica que antes, ahora factorizada en sweep_stale_andreani_claims()
  -- para que resolve_andreani_reconciliation() pueda reutilizarla sin
  -- duplicar el predicado.
  perform public.sweep_stale_andreani_claims();

  update public.ordenes
  set
    andreani_creation_status = 'claimed',
    andreani_creation_claim_token = p_claim_token,
    andreani_creation_claimed_at = now(),
    andreani_creation_environment = p_environment,
    andreani_creation_attempts = coalesce(andreani_creation_attempts, 0) + 1
  where id = p_order_id
    and nullif(btrim(coalesce(andreani_envio_id, '')), '') is null
    and (
      andreani_creation_status is null
      or andreani_creation_status = 'failed'
      -- Rechazo determinístico (400/422): Andreani no creó nada, así que
      -- es reclamable en cualquier ambiente, incluido el mismo que lo
      -- rechazó, sin esperar a que cambie QA<->PROD.
      or andreani_creation_status = 'rejected'
    )
    and lower(coalesce(estado, '')) in ('pendiente', 'pagado')
    and lower(coalesce(shipping_provider, envio_proveedor, '')) = 'andreani'
    and lower(coalesce(financial_status, '')) not in (
      'cancellation_requested',
      'cancelled',
      'refund_pending',
      'refunded'
    )
    and shipping_type in ('domicilio', 'sucursal')
    and (
      paid_at is not null
      or coalesce(payment_confirmed_amount, 0) > 0
      or lower(coalesce(payment_status, '')) in (
        'confirmado',
        'approved',
        'confirmed'
      )
      or lower(coalesce(financial_status, '')) = 'payment_confirmed'
    )
    and invoice_status = 'authorized'
    and nullif(btrim(coalesce(invoice_cae, '')), '') is not null
    and invoice_number is not null
    and invoice_point is not null
  returning andreani_creation_attempts into v_attempts;

  return v_attempts;
end;
$$;


ALTER FUNCTION "public"."claim_andreani_shipment_creation"("p_order_id" bigint, "p_claim_token" "uuid", "p_environment" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "claim_andreani_shipment_creation"("p_order_id" bigint, "p_claim_token" "uuid", "p_environment" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."claim_andreani_shipment_creation"("p_order_id" bigint, "p_claim_token" "uuid", "p_environment" "text") IS 'Reclama atómicamente una creación Andreani para un pedido pagado, facturado y sin resultado externo ambiguo pendiente, en modalidad domicilio o sucursal; un rechazo determinístico previo (400/422) no bloquea el reclamo. El barrido de claims vencidos vive en sweep_stale_andreani_claims().';


--
-- Name: claim_mercadopago_order_preference(bigint, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_mercadopago_order_preference"("p_order_id" bigint, "p_checkout_fingerprint" "text", "p_claim_token" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_generation integer;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para renovar la preferencia.';
  end if;

  if p_order_id is null
     or nullif(btrim(coalesce(p_checkout_fingerprint, '')), '') is null
     or p_claim_token is null then
    raise exception 'MERCADOPAGO_PREFERENCE_CLAIM_INVALID';
  end if;

  update public.ordenes
  set
    mercadopago_preference_claim_token = p_claim_token,
    mercadopago_preference_claimed_at = now(),
    mercadopago_preference_generation =
      coalesce(mercadopago_preference_generation, 0) + 1,
    mercadopago_preference_id = null,
    mercadopago_init_point = null,
    mercadopago_preference_expires_at = null,
    payment_status = 'pending_checkout'
  where id = p_order_id
    and mercadopago_checkout_fingerprint = p_checkout_fingerprint
    and payment_method_id = 'mercadopago'
    and estado = 'pendiente'
    and coalesce(financial_status, 'pending_payment') = 'pending_payment'
    and coalesce(payment_status, 'pending_checkout') in (
      'pending_checkout',
      'preference_created',
      'preference_error'
    )
    and (
      mercadopago_preference_claimed_at is null
      or mercadopago_preference_claimed_at < now() - interval '5 minutes'
    )
    and (
      mercadopago_init_point is null
      or mercadopago_preference_expires_at is null
      or mercadopago_preference_expires_at <= now()
    )
  returning mercadopago_preference_generation into v_generation;

  return v_generation;
end;
$$;


ALTER FUNCTION "public"."claim_mercadopago_order_preference"("p_order_id" bigint, "p_checkout_fingerprint" "text", "p_claim_token" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "claim_mercadopago_order_preference"("p_order_id" bigint, "p_checkout_fingerprint" "text", "p_claim_token" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."claim_mercadopago_order_preference"("p_order_id" bigint, "p_checkout_fingerprint" "text", "p_claim_token" "uuid") IS 'Adquiere de forma atómica el derecho a crear o renovar una preferencia para una orden pendiente.';


--
-- Name: mercadopago_order_refunds; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."mercadopago_order_refunds" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "order_id" bigint NOT NULL,
    "payment_id" "text" NOT NULL,
    "amount" numeric(12,2) NOT NULL,
    "is_partial" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'processing'::"text" NOT NULL,
    "mp_refund_id" "text",
    "idempotency_key" "text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "error_code" "text",
    "error_message" "text",
    "attempt_count" integer DEFAULT 1 NOT NULL,
    "reconciliation_locked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "mercadopago_order_refunds_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "mercadopago_order_refunds_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'processing'::"text", 'confirmed'::"text", 'failed'::"text", 'needs_reconciliation'::"text"])))
);


ALTER TABLE "public"."mercadopago_order_refunds" OWNER TO "postgres";

--
-- Name: TABLE "mercadopago_order_refunds"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."mercadopago_order_refunds" IS 'Ciclo de vida de cada intento de refund real contra Mercado Pago para un pedido. Fuente de verdad del refund de MP -- ordenes.financial_status sólo refleja el resultado ya confirmado acá. Ver justificación de tabla dedicada en el comentario de la migración 20260911170000.';


--
-- Name: COLUMN "mercadopago_order_refunds"."is_partial"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."mercadopago_order_refunds"."is_partial" IS 'Siempre false en Fase 1 (sólo refund total). Reservado para Fase 2: un refund parcial futuro no debe competir con el índice único de "un solo refund total confirmado por pedido" de abajo.';


--
-- Name: COLUMN "mercadopago_order_refunds"."status"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."mercadopago_order_refunds"."status" IS 'requested: fila creada, todavía no se intentó el POST contra MP. processing: el POST está/estuvo en curso -- resultado real desconocido hasta confirmar. confirmed/failed: terminales. needs_reconciliation: timeout o respuesta ambigua tras el POST -- requiere reconsultar a MP antes de cualquier otro intento.';


--
-- Name: claim_mercadopago_refunds_for_reconciliation(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_mercadopago_refunds_for_reconciliation"("p_batch_size" integer DEFAULT 10, "p_lock_timeout_seconds" integer DEFAULT 300) RETURNS SETOF "public"."mercadopago_order_refunds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  return query
  update public.mercadopago_order_refunds
  set reconciliation_locked_at = now()
  where id in (
    select id
    from public.mercadopago_order_refunds
    where status = 'needs_reconciliation'
      and (
        reconciliation_locked_at is null
        or reconciliation_locked_at < now() - make_interval(secs => greatest(p_lock_timeout_seconds, 1))
      )
    order by updated_at asc
    limit greatest(least(coalesce(p_batch_size, 10), 50), 1)
    for update skip locked
  )
  returning *;
end;
$$;


ALTER FUNCTION "public"."claim_mercadopago_refunds_for_reconciliation"("p_batch_size" integer, "p_lock_timeout_seconds" integer) OWNER TO "postgres";

--
-- Name: claim_transfer_verification_attempt(bigint, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."claim_transfer_verification_attempt"("p_order_id" bigint, "p_max_attempts" integer DEFAULT 20, "p_min_interval_seconds" integer DEFAULT 5, "p_stale_checking_seconds" integer DEFAULT 60) RETURNS "public"."ordenes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_now timestamptz := now();
  v_lease_id uuid := gen_random_uuid();
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para esta operación.';
  end if;

  select *
  into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND: no encontramos el pedido.';
  end if;

  if v_order.payment_method_id is distinct from 'transferencia' then
    raise exception 'NOT_TRANSFER_ORDER: este pedido no corresponde a transferencia bancaria.';
  end if;

  if lower(coalesce(v_order.estado, '')) = 'cancelado' then
    raise exception 'ORDER_CANCELLED: el pedido está cancelado.';
  end if;

  if coalesce(v_order.payment_status, '') not in ('pendiente_comprobante', 'en_revision') then
    raise exception 'ALREADY_RESOLVED: el pago de este pedido ya no admite verificación automática.';
  end if;

  if v_order.transfer_verification_attempts >= p_max_attempts then
    raise exception 'MAX_ATTEMPTS_EXCEEDED: se alcanzó el máximo de intentos automáticos para este pedido.';
  end if;

  if v_order.transfer_verification_status = 'checking'
     and v_order.transfer_last_verification_at is not null
     and v_order.transfer_last_verification_at > v_now - make_interval(secs => p_stale_checking_seconds) then
    raise exception 'ALREADY_CHECKING: ya hay una verificación en curso para este pedido.';
  end if;

  if v_order.transfer_last_verification_at is not null
     and v_order.transfer_last_verification_at > v_now - make_interval(secs => p_min_interval_seconds) then
    raise exception 'RATE_LIMITED: esperá unos segundos antes de volver a intentar.';
  end if;

  update public.ordenes
  set
    transfer_verification_status = 'checking',
    transfer_verification_attempts = transfer_verification_attempts + 1,
    transfer_last_verification_at = v_now,
    transfer_verification_lease_id = v_lease_id
  where id = v_order.id
  returning *
  into v_order;

  return v_order;
end;
$$;


ALTER FUNCTION "public"."claim_transfer_verification_attempt"("p_order_id" bigint, "p_max_attempts" integer, "p_min_interval_seconds" integer, "p_stale_checking_seconds" integer) OWNER TO "postgres";

--
-- Name: FUNCTION "claim_transfer_verification_attempt"("p_order_id" bigint, "p_max_attempts" integer, "p_min_interval_seconds" integer, "p_stale_checking_seconds" integer); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."claim_transfer_verification_attempt"("p_order_id" bigint, "p_max_attempts" integer, "p_min_interval_seconds" integer, "p_stale_checking_seconds" integer) IS 'Reclama de forma atómica un intento de verificación automática de transferencia. Genera y persiste un lease id nuevo (transfer_verification_lease_id) en cada claim exitoso -- ese lease es el que confirm_transfer_auto_verification exige para poder confirmar. Sirve como rate limit, lock anti doble-click/concurrencia y tope de intentos. No confirma nada por sí sola.';


--
-- Name: clear_resolved_order_claim_attention(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."clear_resolved_order_claim_attention"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.status in ('cerrado','rechazado') then new.admin_needs_action:=false; end if;
  return new;
end $$;


ALTER FUNCTION "public"."clear_resolved_order_claim_attention"() OWNER TO "postgres";

--
-- Name: close_mercadopago_order_refund_claim(bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."close_mercadopago_order_refund_claim"("p_order_id" bigint, "p_refund_id" "uuid") RETURNS "public"."order_claims"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_refund public.mercadopago_order_refunds%rowtype;
  v_claim public.order_claims%rowtype;
  v_now timestamptz := now();
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  select *
  into v_refund
  from public.mercadopago_order_refunds
  where id = p_refund_id
  for update;

  if not found then
    raise exception 'REFUND_ATTEMPT_NOT_FOUND';
  end if;

  -- El refund tiene que pertenecer EXACTAMENTE al pedido indicado -- nunca
  -- se cierra el claim de un pedido usando el refund de otro.
  if v_refund.order_id is distinct from p_order_id then
    raise exception 'REFUND_ORDER_MISMATCH';
  end if;

  if v_refund.status is distinct from 'confirmed' then
    raise exception 'REFUND_NOT_CONFIRMED';
  end if;

  -- Único claim de cancelación elegible para este pedido (el mismo
  -- discriminante que usa approve_order_claim_cancellation:
  -- failure_type='cancelar_compra'). Si no hay ninguno, no hay nada que
  -- cerrar por esta vía -- no es un error financiero, el refund ya quedó
  -- confirmado igual.
  select *
  into v_claim
  from public.order_claims
  where order_id = p_order_id
    and failure_type = 'cancelar_compra'
  order by created_at desc
  limit 1
  for update;

  if not found then
    return null;
  end if;

  -- Idempotente: ya cerrado (por esta misma función en un intento previo,
  -- p.ej. una reconciliación posterior que vuelve a confirmar) -- no-op,
  -- nunca un error financiero.
  if v_claim.status = 'cerrado' then
    return v_claim;
  end if;

  if v_claim.status = 'rechazado' then
    raise exception 'CLAIM_ALREADY_REJECTED';
  end if;

  update public.order_claims
  set
    status = 'cerrado',
    resolution = 'reintegro_total',
    admin_response = 'El reintegro fue procesado por Mercado Pago al medio de pago original.',
    closed_at = v_now,
    admin_needs_action = false,
    updated_at = v_now
  where id = v_claim.id
  returning * into v_claim;

  insert into public.order_claim_messages (claim_id, author_user_id, author_role, message)
  values (v_claim.id, null, 'admin', 'El reintegro fue procesado por Mercado Pago al medio de pago original.');

  insert into public.order_audit_events (
    order_id, actor_type, actor_id, action, previous_status, new_status, metadata
  ) values (
    p_order_id, 'system', null, 'mp_refund_claim_closed', 'reintegro_pendiente', 'cerrado',
    jsonb_build_object('claimId', v_claim.id, 'refundAttemptId', v_refund.id, 'mpRefundId', v_refund.mp_refund_id)
  );

  return v_claim;
end;
$$;


ALTER FUNCTION "public"."close_mercadopago_order_refund_claim"("p_order_id" bigint, "p_refund_id" "uuid") OWNER TO "postgres";

--
-- Name: commit_customer_order_claim("uuid", "uuid", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_customer_order_claim"("p_operation_id" "uuid", "p_actor_id" "uuid", "p_payload" "jsonb", "p_files" "jsonb") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    SET "TimeZone" TO 'UTC'
    AS $$
declare
  v_op public.order_claim_operations%rowtype;
  v_order public.ordenes%rowtype;
  v_claim public.order_claims%rowtype;
  v_reason text:=p_payload->>'problemType';
  v_type text;
  v_message text:=btrim(coalesce(p_payload->>'message',''));
  v_items jsonb;
  v_item jsonb;
  v_file jsonb;
  v_message_id bigint;
  v_previous text;
  v_email text;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'CLAIM_FORBIDDEN'; end if;
  select * into v_op from public.order_claim_operations where id=p_operation_id and actor_id=p_actor_id for update;
  if not found then raise exception 'CLAIM_FORBIDDEN'; end if;
  if v_op.status='committed' then return v_op.claim_id; end if;
  if v_op.status<>'uploading' or v_op.expires_at<=now() or v_op.bucket_id<>'order-claim-evidence' then raise exception 'CLAIM_CONFLICT'; end if;
  select * into v_order from public.ordenes where id=v_op.order_id for update;
  select lower(email) into v_email from auth.users where id=p_actor_id and email_confirmed_at is not null;
  if not found or (v_order.usuario_id is not null and v_order.usuario_id<>p_actor_id) or
     (v_order.usuario_id is null and (v_email is null or lower(btrim(v_order.cliente_email)) is distinct from v_email)) then raise exception 'CLAIM_FORBIDDEN'; end if;
  if length(v_message)>2000 or jsonb_array_length(p_files)>6 then raise exception 'CLAIM_INVALID'; end if;
  if p_payload->>'claimId' is not null then
    select * into v_claim from public.order_claims where id=(p_payload->>'claimId')::bigint and order_id=v_order.id and user_id=p_actor_id for update;
    if not found then raise exception 'CLAIM_FORBIDDEN'; end if;
    if v_claim.status in ('cerrado','rechazado') then raise exception 'CLAIM_TERMINAL'; end if;
    if v_claim.updated_at is distinct from (p_payload->>'expectedUpdatedAt')::timestamptz then raise exception 'CLAIM_CONFLICT'; end if;
    v_previous:=v_claim.status;
    if p_payload ? 'refundDetails' then
      if v_claim.status<>'reintegro_pendiente' or jsonb_array_length(p_files)>0 then raise exception 'CLAIM_INVALID'; end if;
      if exists(select 1 from unnest(array['holder','identifier','bank','amount']) k where length(btrim(coalesce(p_payload->'refundDetails'->>k,''))) not between 1 and 180) then raise exception 'CLAIM_INVALID'; end if;
      update public.order_claims set refund_account_holder=p_payload->'refundDetails'->>'holder',refund_account_identifier=p_payload->'refundDetails'->>'identifier',refund_bank=p_payload->'refundDetails'->>'bank',refund_amount_confirmed=p_payload->'refundDetails'->>'amount',refund_details_submitted_at=now() where id=v_claim.id;
      v_message:='Datos de reintegro enviados para revisión de BEYONIX.';
    else
      if length(v_message)<5 and jsonb_array_length(p_files)=0 then raise exception 'CLAIM_INVALID'; end if;
      if jsonb_array_length(p_files)=0 and (select author_role from public.order_claim_messages where claim_id=v_claim.id order by created_at desc,id desc limit 1)='cliente' then raise exception 'CLAIM_WAIT_REPLY'; end if;
      if length(v_message)<5 then v_message:='El cliente adjuntó nueva evidencia.'; end if;
      if v_claim.status='falta_informacion' then update public.order_claims set status='en_revision' where id=v_claim.id; end if;
    end if;
  else
    if length(v_message)<10 then raise exception 'CLAIM_INVALID'; end if;
    if exists(select 1 from public.order_claims where order_id=v_order.id and status not in ('cerrado','rechazado')) then raise exception 'CLAIM_EXISTS'; end if;
    if v_reason='consulta_pedido' then
      if v_order.estado in ('cancelado','entregado') or v_order.delivered_at is not null then raise exception 'CLAIM_INELIGIBLE'; end if;
      v_type:='transporte_48hs'; v_items:='[]';
    else
      if v_reason not in ('danado','incorrecto','faltante','cantidad_menor','falla','otro') or v_reason is null then raise exception 'CLAIM_INVALID'; end if;
      if exists(select 1 from public.order_claims where order_id=v_order.id and coalesce(failure_type,'') not in ('cancelar_compra','consulta_pedido')) then raise exception 'CLAIM_EXISTS'; end if;
      v_type:=case when v_reason in ('falla','otro') then 'garantia_beyonix' else 'transporte_48hs' end;
      if v_order.estado='cancelado' or v_order.delivered_at is null or v_order.delivered_at>now() then raise exception 'CLAIM_DELIVERY_DATE'; end if;
      if now()>v_order.delivered_at+(case when v_type='transporte_48hs' then interval '48 hours' else interval '6 months' end) then raise exception 'CLAIM_EXPIRED'; end if;
      v_items:=p_payload->'items';
      if jsonb_typeof(v_items) is distinct from 'array' or jsonb_array_length(v_items)=0 then raise exception 'CLAIM_INVALID'; end if;
      if (select count(distinct x->>'order_item_id') from jsonb_array_elements(v_items) x)<>jsonb_array_length(v_items) then raise exception 'CLAIM_INVALID'; end if;
      for v_item in select * from jsonb_array_elements(v_items) loop
        if not exists(select 1 from public.orden_items where id=(v_item->>'order_item_id')::bigint and orden_id=v_order.id and (v_item->>'quantity')::integer between 1 and cantidad) then raise exception 'CLAIM_INVALID_ITEMS'; end if;
      end loop;
    end if;
    insert into public.order_claims(order_id,user_id,claim_type,failure_type,description,affected_items,admin_needs_action)
    values(v_order.id,p_actor_id,v_type,v_reason,v_message,v_items,true) returning * into v_claim;
  end if;
  insert into public.order_claim_messages(claim_id,author_user_id,author_role,message)
  values(v_claim.id,p_actor_id,'cliente',v_message) returning id into v_message_id;
  if jsonb_array_length(p_files)<>cardinality(v_op.file_paths) then raise exception 'CLAIM_INVALID_FILES'; end if;
  for v_file in select * from jsonb_array_elements(p_files) loop
    if not (v_file->>'path'=any(v_op.file_paths)) or not exists(select 1 from storage.objects where bucket_id='order-claim-evidence' and name=v_file->>'path') then raise exception 'CLAIM_INVALID_FILES'; end if;
    insert into public.order_claim_files(claim_id,uploaded_by,file_role,file_name,file_path,mime_type,file_size)
    values(v_claim.id,p_actor_id,case when v_previous is null then 'evidencia_inicial' else 'evidencia_adicional' end,v_file->>'name','order-claim-evidence/'||(v_file->>'path'),v_file->>'type',(v_file->>'size')::bigint);
  end loop;
  insert into public.order_audit_events(order_id,actor_type,actor_id,action,previous_status,new_status,metadata)
  select v_order.id,'customer',p_actor_id,case when v_previous is null then 'claim_created' else 'claim_customer_response' end,v_previous,status,jsonb_build_object('claimId',id,'messageId',v_message_id,'fileCount',jsonb_array_length(p_files)) from public.order_claims where id=v_claim.id;
  if v_previous is null then
    insert into public.customer_notifications(user_id,type,title,body,action_url,order_id,source_key) values(p_actor_id,'claim_started','Solicitud recibida','Recibimos tu solicitud de ayuda.','/cuenta/compras/'||v_order.id||'/ayuda',v_order.id,'claim:'||v_claim.id||':created') on conflict(source_key) do nothing;
  end if;
  update public.order_claim_operations set status='committed',claim_id=v_claim.id where id=v_op.id;
  return v_claim.id;
end $$;


ALTER FUNCTION "public"."commit_customer_order_claim"("p_operation_id" "uuid", "p_actor_id" "uuid", "p_payload" "jsonb", "p_files" "jsonb") OWNER TO "postgres";

--
-- Name: commit_order_refund_proof("uuid", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."commit_order_refund_proof"("p_operation_id" "uuid", "p_actor_id" "uuid", "p_file" "jsonb") RETURNS "public"."ordenes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_op public.order_claim_operations%rowtype;
  v_order public.ordenes%rowtype;
  v_amount numeric;
  v_notes uuid[];
  v_proof_id bigint;
  v_role text;
  v_path text := p_file->>'path';
  v_reference text := nullif(trim(coalesce(p_file->>'reference', '')), '');
  v_refund_date date := nullif(p_file->>'refund_date', '')::date;
  v_observation text := nullif(trim(coalesce(p_file->>'notes', '')), '');
  v_no_credit_note_path boolean := false;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'CLAIM_FORBIDDEN'; end if;
  select rol into v_role from public.profiles where id=p_actor_id;
  if coalesce(v_role,'') not in ('admin','super_admin') then raise exception 'CLAIM_FORBIDDEN'; end if;
  if length(coalesce(v_reference, '')) > 120 or length(coalesce(v_observation, '')) > 600 then
    raise exception 'INVALID_REFUND_DETAILS';
  end if;
  select * into v_op from public.order_claim_operations where id=p_operation_id and actor_id=p_actor_id for update;
  if not found then raise exception 'CLAIM_FORBIDDEN'; end if;
  select * into v_order from public.ordenes where id=v_op.order_id for update;
  if v_order.payment_method_id = 'mercadopago' then
    raise exception 'MERCADOPAGO_REQUIRES_REAL_REFUND';
  end if;
  if v_op.status='committed' then return v_order; end if;
  if v_op.status<>'uploading' or v_op.expires_at<=now() or v_op.bucket_id<>'payment-proofs' then raise exception 'CLAIM_CONFLICT'; end if;
  if v_order.financial_status='cancelled' then raise exception 'CLAIM_CONFLICT'; end if;

  -- NUEVO (Fase 4, punto 1): sin NC requerida y sin ninguna NC que mueva
  -- dinero ya emitida para este pedido -- reintegro directo contra el
  -- dinero externo confirmado. Nunca se activa para un pedido que sí
  -- necesita NC (credit_note_required=true cae siempre a la rama de abajo,
  -- sin cambios).
  if not coalesce(v_order.credit_note_required, false)
     and not exists(
       select 1 from public.order_credit_notes
       where order_id = v_order.id and destination <> 'none'
     ) then
    v_no_credit_note_path := true;

    -- Idempotencia: sólo puede completarse una vez por pedido -- tras la
    -- primera ejecución financial_status pasa a 'refunded' y cualquier
    -- reintento cae acá (mismo código de error que ya usa la rama con NC
    -- cuando no queda nada pendiente de liquidar).
    if v_order.financial_status <> 'refund_pending' then
      raise exception 'CLAIM_REFUND_PENDING';
    end if;

    -- Misma fórmula REFUNDABLE_EXTERNAL_AMOUNT que
    -- 20260917120000_credit_note_refundable_external_cap.sql: dinero
    -- externo confirmado, nunca el total (que podría incluir saldo ya
    -- restaurado aparte por reverse_customer_credit_for_order).
    v_amount := greatest(
      coalesce(
        nullif(v_order.payment_confirmed_amount, 0),
        v_order.external_amount_due,
        greatest(coalesce(v_order.original_total, v_order.total, 0) - coalesce(v_order.credit_balance_used, 0), 0),
        0
      ),
      0
    );
    if coalesce(v_amount, 0) <= 0 then raise exception 'CLAIM_REFUND_PENDING'; end if;
  else
    perform id from public.order_credit_notes where order_id=v_order.id order by id for update;
    select sum(total_amount),array_agg(id order by id) into v_amount,v_notes from public.order_credit_notes
      where order_id=v_order.id and status='authorized' and destination='external_refund' and settlement_status is distinct from 'completado' and cae is not null;
    if coalesce(v_amount,0)<=0 then raise exception 'CLAIM_REFUND_PENDING'; end if;
    if jsonb_typeof(p_file->'expected_note_ids') is distinct from 'array' or
      v_notes is distinct from (select array_agg(value::uuid order by value::uuid) from jsonb_array_elements_text(p_file->'expected_note_ids')) then raise exception 'CLAIM_CONFLICT'; end if;
    if exists(select 1 from public.order_credit_notes where order_id=v_order.id and status='processing') then raise exception 'CLAIM_CONFLICT'; end if;
  end if;

  if not(v_path=any(v_op.file_paths)) or not exists(select 1 from storage.objects where bucket_id='payment-proofs' and name=v_path) then raise exception 'CLAIM_INVALID_FILES'; end if;
  insert into public.order_refund_proofs(order_id,uploaded_by,file_name,file_path,mime_type,file_size,amount,method,observation,bank_reference,refund_date)
    values(v_order.id,p_actor_id,p_file->>'name','payment-proofs/'||v_path,p_file->>'type',(p_file->>'size')::bigint,v_amount,'Devolución de dinero',v_observation,v_reference,coalesce(v_refund_date, current_date))
    returning id into v_proof_id;
  if not v_no_credit_note_path then
    update public.order_credit_notes set management_status='finalizada',settlement_status='completado',settlement_date=current_date,settlement_reference=v_proof_id::text,updated_at=now() where id=any(v_notes);
  end if;
  insert into public.order_audit_events(order_id,actor_type,actor_id,action,previous_status,new_status,metadata)
    values(v_order.id,'admin',p_actor_id,'order_refunded',v_order.financial_status,'refunded',jsonb_build_object('proofId',v_proof_id,'amount',v_amount,'creditNoteIds',v_notes,'reference',v_reference,'refundDate',v_refund_date,'requiredCreditNote', not v_no_credit_note_path));
  update public.ordenes set financial_status='refunded',refund_proof_url='payment-proofs/'||v_path,refund_proof_file_name=p_file->>'name',refund_proof_mime_type=p_file->>'type',refund_proof_file_size=(p_file->>'size')::bigint,
    refund_amount=(select sum(amount) from public.order_refund_proofs where order_id=v_order.id),refund_method='Devolución de dinero',refund_uploaded_by=p_actor_id,refund_uploaded_at=now(),refunded_at=now(),refunded_by=p_actor_id,credit_note_required=false where id=v_order.id returning * into v_order;
  if v_order.usuario_id is not null then
    insert into public.customer_notifications(user_id,type,title,body,action_url,order_id,source_key)
      values(v_order.usuario_id,'order_refunded','Dinero reintegrado','Registramos el reintegro de tu pedido.','/cuenta/compras/'||v_order.id,v_order.id,'order:'||v_order.id||':refunded') on conflict(source_key) do nothing;
  end if;
  update public.order_claim_operations set status='committed' where id=v_op.id;
  return v_order;
end $$;


ALTER FUNCTION "public"."commit_order_refund_proof"("p_operation_id" "uuid", "p_actor_id" "uuid", "p_file" "jsonb") OWNER TO "postgres";

--
-- Name: FUNCTION "commit_order_refund_proof"("p_operation_id" "uuid", "p_actor_id" "uuid", "p_file" "jsonb"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."commit_order_refund_proof"("p_operation_id" "uuid", "p_actor_id" "uuid", "p_file" "jsonb") IS 'Registra el comprobante y cierra el reintegro externo (transferencia). Si el pedido nunca requirió NC (nunca se facturó), calcula el importe con la fórmula REFUNDABLE_EXTERNAL_AMOUNT (payment_confirmed_amount) en vez de sumar notas de crédito. Persiste referencia bancaria, fecha y observación. Fix 20260917130000.';


--
-- Name: complete_cart_stock_reservation("text", bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."complete_cart_stock_reservation"("p_session_id" "text", "p_order_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.stock_reservations reservations
  set order_id = p_order_id,
      expires_at = greatest(expires_at, now() + interval '30 minutes'),
      updated_at = now()
  where reservations.session_id = p_session_id
    and (reservations.user_id is null or reservations.user_id = auth.uid());
end;
$$;


