--
-- Name: compute_historical_unit_cost(bigint, bigint, "date"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."compute_historical_unit_cost"("p_product_id" bigint, "p_variant_id" bigint, "p_as_of" "date") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_quantity numeric := 0;
  v_cost numeric := 0;
begin
  if p_product_id is null then
    return null;
  end if;

  if p_variant_id is not null then
    select
      coalesce(sum(
        case
          when entries.reception_status in ('pendiente', 'anulada') then 0
          when entries.reception_status = 'recibida' then entries.quantity
          else least(greatest(coalesce(entries.received_quantity, 0), 0), entries.quantity)
        end
      ), 0),
      coalesce(sum(
        case
          when entries.reception_status in ('pendiente', 'anulada') then 0
          when entries.reception_status = 'recibida' then entries.total_cost
          else entries.total_cost
            * least(greatest(coalesce(entries.received_quantity, 0), 0), entries.quantity)
            / nullif(entries.quantity, 0)
        end
      ), 0)
    into v_quantity, v_cost
    from public.product_cost_entries entries
    where entries.variant_id = p_variant_id
      and entries.purchase_date <= p_as_of;

    if v_quantity > 0 then
      return round(v_cost / v_quantity, 2);
    end if;
  end if;

  select
    coalesce(sum(
      case
        when entries.reception_status in ('pendiente', 'anulada') then 0
        when entries.reception_status = 'recibida' then entries.quantity
        else least(greatest(coalesce(entries.received_quantity, 0), 0), entries.quantity)
      end
    ), 0),
    coalesce(sum(
      case
        when entries.reception_status in ('pendiente', 'anulada') then 0
        when entries.reception_status = 'recibida' then entries.total_cost
        else entries.total_cost
          * least(greatest(coalesce(entries.received_quantity, 0), 0), entries.quantity)
          / nullif(entries.quantity, 0)
      end
    ), 0)
  into v_quantity, v_cost
  from public.product_cost_entries entries
  where entries.product_id = p_product_id
    and entries.variant_id is null
    and entries.purchase_date <= p_as_of;

  if v_quantity > 0 then
    return round(v_cost / v_quantity, 2);
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."compute_historical_unit_cost"("p_product_id" bigint, "p_variant_id" bigint, "p_as_of" "date") OWNER TO "postgres";

--
-- Name: confirm_transfer_auto_verification(bigint, "text", "text", "text", numeric, "text", "text", "text", "text", timestamp with time zone, timestamp with time zone, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."confirm_transfer_auto_verification"("p_order_id" bigint, "p_matched_payment_id" "text", "p_matched_operation_type" "text", "p_matched_payment_method_id" "text", "p_matched_amount" numeric, "p_matched_identification_type" "text", "p_matched_identification_number" "text", "p_matched_dni_derived" "text", "p_matched_bank_transfer_id" "text", "p_matched_date_created" timestamp with time zone, "p_matched_date_approved" timestamp with time zone, "p_lease_id" "uuid") RETURNS "public"."ordenes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_now timestamptz := now();
  -- P0 (quinta auditoría): now() devuelve el timestamp de INICIO de la
  -- transacción -- queda congelado durante toda la ejecución, incluida
  -- cualquier espera real para adquirir el "for update" de abajo. Codex
  -- reprodujo: lease con 59s de antigüedad al arrancar la transacción, la
  -- transacción tarda/espera 2s más antes de evaluar la vigencia, la
  -- antigüedad REAL ya es 61s (vencida), pero now() seguía viendo 59s y la
  -- RPC confirmaba igual. v_lease_checked_at se asigna DESPUÉS del "for
  -- update" (más abajo) con clock_timestamp() -- tiempo de PARED real en el
  -- momento exacto de evaluar, nunca el de inicio de transacción -- y se usa
  -- ÚNICAMENTE para la comprobación de vigencia del lease. v_now se sigue
  -- usando para todo lo demás (timestamps de escritura: payment_confirmed_at,
  -- paid_at, transfer_last_verification_at, etc.) donde congelar el momento
  -- de inicio de transacción es el criterio correcto y no está relacionado
  -- con este bug.
  v_lease_checked_at timestamptz;
  v_previous_financial_status text;
  v_snapshot jsonb;
  v_expected_amount numeric;
  v_expected_cents bigint;
  v_matched_cents bigint;
  v_declared_cents bigint;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para esta operación.';
  end if;

  if coalesce(trim(p_matched_payment_id), '') = '' then
    raise exception 'INVALID_PAYMENT_ID: falta el identificador de Mercado Pago.';
  end if;

  select *
  into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  -- Tiempo real de PARED, tomado recién acá -- inmediatamente DESPUÉS de
  -- que el "for update" de arriba ya terminó de esperar (si tuvo que
  -- esperar). Nunca reutilizar v_now (congelado al inicio de la
  -- transacción) para la comprobación de vigencia del lease de más abajo.
  v_lease_checked_at := clock_timestamp();

  if not found then
    raise exception 'ORDER_NOT_FOUND: no encontramos el pedido.';
  end if;

  if v_order.payment_method_id is distinct from 'transferencia' then
    raise exception 'NOT_TRANSFER_ORDER: este pedido no corresponde a transferencia bancaria.';
  end if;

  if lower(coalesce(v_order.estado, '')) = 'cancelado' then
    raise exception 'ORDER_CANCELLED: el pedido está cancelado.';
  end if;

  if coalesce(v_order.payment_status, '') not in ('pendiente_comprobante', 'en_revision') then
    raise exception 'ALREADY_RESOLVED: el pago de este pedido ya no admite verificación automática.';
  end if;

  -- P0 (tercera auditoría): validación de lease COMPLETA, bajo el mismo
  -- FOR UPDATE de arriba -- las cinco condiciones exigidas, en el orden que
  -- da el diagnóstico más específico posible:
  --
  --  1) transfer_verification_status debe seguir siendo 'checking' (hubo un
  --     claim y nadie lo resolvió/liberó todavía) -> si no,
  --     INVALID_VERIFICATION_STATE. Cubre tanto "nunca se hizo claim"
  --     (status por defecto, nunca 'checking') como "ya se resolvió en
  --     manual_review/pending mientras tanto".
  --  2) p_lease_id y el lease vigente en la fila deben ser AMBOS no nulos
  --     -> si cualquiera es NULL, LEASE_MISSING. Esto es lo que la versión
  --     anterior de este chequeo (IS DISTINCT FROM) dejaba pasar: NULL IS
  --     NOT DISTINCT FROM NULL en Postgres.
  --  3) deben coincidir EXACTAMENTE -> si no, LEASE_MISMATCH (un intento
  --     más nuevo ya reclamó este pedido).
  --  4) transfer_last_verification_at (fijado por el claim que otorgó este
  --     lease) debe seguir dentro de una ventana de vigencia FIJA de 60
  --     segundos -- hardcodeada acá, nunca un parámetro que el caller pueda
  --     manipular (ver comentario más arriba, antes de los DROP) -> si no,
  --     LEASE_EXPIRED. Comparado contra v_lease_checked_at (clock_timestamp(),
  --     tiempo real tomado DESPUÉS del "for update" de arriba), nunca contra
  --     v_now (congelado al inicio de la transacción -- ver comentario en la
  --     declaración de v_lease_checked_at más arriba).
  --
  -- Si cualquiera de las cuatro falla: NO se toca ningún campo de la orden.
  if coalesce(v_order.transfer_verification_status, '') <> 'checking' then
    raise exception 'INVALID_VERIFICATION_STATE: el pedido no tiene una verificación automática en curso.';
  end if;

  if p_lease_id is null or v_order.transfer_verification_lease_id is null then
    raise exception 'LEASE_MISSING: falta el identificador del intento de verificación vigente.';
  end if;

  if p_lease_id <> v_order.transfer_verification_lease_id then
    raise exception 'LEASE_MISMATCH: el intento de verificación ya no es el vigente (fue reemplazado por uno nuevo).';
  end if;

  if v_order.transfer_last_verification_at is null
     or v_order.transfer_last_verification_at <= v_lease_checked_at - interval '60 seconds' then
    raise exception 'LEASE_EXPIRED: el intento de verificación vigente venció.';
  end if;

  if exists (
    select 1 from public.ordenes
    where transfer_matched_payment_id = p_matched_payment_id
      and id <> p_order_id
  ) then
    raise exception 'TRANSFER_PAYMENT_ID_ALREADY_USED: esa transferencia ya fue utilizada para acreditar otro pedido.';
  end if;

  -- P0 (segunda auditoría): claim histórico e insert-only, independiente del
  -- valor actual de ordenes.transfer_matched_payment_id (que esta misma
  -- orden podría sobrescribir más adelante con otro payment.id). Una vez
  -- reclamado acá, este payment.id queda atado a esta orden para siempre.
  insert into public.transfer_verification_payment_claims (payment_id, order_id)
  values (p_matched_payment_id, p_order_id)
  on conflict (payment_id) do nothing;

  if not exists (
    select 1 from public.transfer_verification_payment_claims
    where payment_id = p_matched_payment_id
      and order_id = p_order_id
  ) then
    raise exception 'TRANSFER_PAYMENT_ID_ALREADY_USED: esa transferencia ya fue utilizada para acreditar otro pedido.';
  end if;

  -- P0: monto esperado BAJO EL LOCK ya tomado arriba -- nunca el monto que
  -- el caller haya leído antes de invocar esta RPC (puede quedar
  -- desactualizado durante el tiempo que tarda la consulta a Mercado Pago).
  -- Mismo criterio de columnas que usa el resto del proyecto:
  -- external_amount_due si existe, si no total.
  v_expected_amount := coalesce(v_order.external_amount_due, v_order.total);
  v_expected_cents := round(coalesce(v_expected_amount, -1) * 100);
  v_matched_cents := round(coalesce(p_matched_amount, -1) * 100);

  if v_expected_cents is null or v_expected_cents <= 0
     or v_matched_cents is null or v_matched_cents <> v_expected_cents then
    raise exception 'AMOUNT_MISMATCH: el monto vigente del pedido no coincide con el importe de la transferencia.';
  end if;

  if v_order.transfer_amount_declared is not null then
    v_declared_cents := round(v_order.transfer_amount_declared * 100);
    if v_declared_cents <> v_matched_cents then
      raise exception 'AMOUNT_MISMATCH: el monto declarado no coincide con el importe vigente del pedido.';
    end if;
  end if;

  v_previous_financial_status := coalesce(
    v_order.financial_status,
    v_order.payment_status,
    'pending_payment'
  );
  v_snapshot := jsonb_build_object(
    'operationType', p_matched_operation_type,
    'paymentMethodId', p_matched_payment_method_id,
    'identificationType', p_matched_identification_type,
    'identificationNumber', p_matched_identification_number,
    'dniDerivado', p_matched_dni_derived,
    'bankTransferId', p_matched_bank_transfer_id,
    'dateCreated', p_matched_date_created,
    'dateApproved', p_matched_date_approved
  );

  begin
    update public.ordenes
    set
      payment_status = 'confirmado',
      estado = 'pagado',
      financial_status = 'payment_confirmed',
      paid_at = coalesce(v_order.paid_at, v_now),
      payment_confirmed_by = null,
      payment_confirmed_at = v_now,
      payment_confirmed_amount = p_matched_amount,
      order_change_status = 'change_approved',
      order_change_extra_amount = 0,
      transfer_verification_status = 'auto_verified',
      transfer_verification_failure_reason = null,
      transfer_last_verification_at = v_now,
      transfer_matched_payment_id = p_matched_payment_id,
      transfer_match_snapshot = v_snapshot
    where id = v_order.id
    returning *
    into v_order;
  exception
    when unique_violation then
      raise exception 'TRANSFER_PAYMENT_ID_ALREADY_USED: esa transferencia ya fue utilizada para acreditar otro pedido.';
    when others then
      if sqlerrm !~* 'CHECKOUT_STOCK_INSUFFICIENT' then
        raise;
      end if;

      -- El dinero YA fue identificado contra Mercado Pago (y ya quedó en el
      -- historial de claims de arriba): aunque el stock ya no alcance para
      -- confirmar la orden, el payment.id tiene que quedar reservado para
      -- ESTE pedido de forma atómica (mismo lock de fila tomado arriba por
      -- el "for update"). A propósito no toca estado/financial_status: eso
      -- evita que este UPDATE angosto dispare de nuevo el guardián de
      -- inventario.
      begin
        update public.ordenes
        set
          payment_status = 'auto_verified_stock_conflict',
          transfer_verification_status = 'manual_review',
          transfer_verification_failure_reason = 'stock_conflict',
          transfer_last_verification_at = v_now,
          transfer_matched_payment_id = p_matched_payment_id,
          transfer_match_snapshot = v_snapshot
        where id = v_order.id
        returning *
        into v_order;
      exception
        when unique_violation then
          raise exception 'TRANSFER_PAYMENT_ID_ALREADY_USED: esa transferencia ya fue utilizada para acreditar otro pedido.';
      end;

      insert into public.order_audit_events (
        order_id, actor_type, actor_id, action, previous_status, new_status, metadata
      )
      values (
        v_order.id, 'system', null, 'transfer_auto_verification_stock_conflict',
        v_previous_financial_status, v_previous_financial_status,
        jsonb_build_object(
          'provider', 'mercadopago',
          'matchedPaymentId', p_matched_payment_id,
          'matchedAmount', p_matched_amount,
          'reason', 'inventory_unavailable_at_confirmation'
        )
      );

      return v_order;
  end;

  insert into public.order_audit_events (
    order_id,
    actor_type,
    actor_id,
    action,
    previous_status,
    new_status,
    metadata
  )
  values (
    v_order.id,
    'system',
    null,
    'transfer_auto_verified',
    v_previous_financial_status,
    'payment_confirmed',
    jsonb_build_object(
      'provider', 'mercadopago',
      'matchedPaymentId', p_matched_payment_id,
      'matchedAmount', p_matched_amount,
      'operationType', p_matched_operation_type,
      'paymentMethodId', p_matched_payment_method_id
    )
  );

  return v_order;
end;
$$;


ALTER FUNCTION "public"."confirm_transfer_auto_verification"("p_order_id" bigint, "p_matched_payment_id" "text", "p_matched_operation_type" "text", "p_matched_payment_method_id" "text", "p_matched_amount" numeric, "p_matched_identification_type" "text", "p_matched_identification_number" "text", "p_matched_dni_derived" "text", "p_matched_bank_transfer_id" "text", "p_matched_date_created" timestamp with time zone, "p_matched_date_approved" timestamp with time zone, "p_lease_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "confirm_transfer_auto_verification"("p_order_id" bigint, "p_matched_payment_id" "text", "p_matched_operation_type" "text", "p_matched_payment_method_id" "text", "p_matched_amount" numeric, "p_matched_identification_type" "text", "p_matched_identification_number" "text", "p_matched_dni_derived" "text", "p_matched_bank_transfer_id" "text", "p_matched_date_created" timestamp with time zone, "p_matched_date_approved" timestamp with time zone, "p_lease_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."confirm_transfer_auto_verification"("p_order_id" bigint, "p_matched_payment_id" "text", "p_matched_operation_type" "text", "p_matched_payment_method_id" "text", "p_matched_amount" numeric, "p_matched_identification_type" "text", "p_matched_identification_number" "text", "p_matched_dni_derived" "text", "p_matched_bank_transfer_id" "text", "p_matched_date_created" timestamp with time zone, "p_matched_date_approved" timestamp with time zone, "p_lease_id" "uuid") IS 'Confirma automáticamente un pedido por transferencia ya conciliado contra Mercado Pago. Exige, bajo el mismo FOR UPDATE: transfer_verification_status=checking (INVALID_VERIFICATION_STATE si no), p_lease_id y el lease de la fila ambos no nulos (LEASE_MISSING si no), coincidencia exacta (LEASE_MISMATCH si no) y vigencia por una ventana FIJA de 60 segundos hardcodeada en el cuerpo -- nunca un parámetro del caller -- comparada contra clock_timestamp() tomado DESPUÉS del FOR UPDATE, nunca contra now() (que queda congelado al inicio de la transacción y no refleja el tiempo real de espera del lock) (LEASE_EXPIRED si no). Revalida el monto esperado vigente BAJO LOCK contra el monto de la transferencia y el declarado. Reclama el payment.id en transfer_verification_payment_claims (insert-only, permanente, con backfill de lo reservado antes de esta migración) antes de confirmar -- ese historial, no la columna transfer_matched_payment_id, es la fuente de verdad de unicidad. Si el guardián de inventario rechaza la confirmación por falta de stock, reclama igual el payment.id de forma atómica (payment_status=auto_verified_stock_conflict). Idempotente ante payment.id repetido.';


--
-- Name: create_customer_credit_movement("uuid", "text", numeric, "text", "text", "text", bigint, bigint, "text", "uuid", "uuid", timestamp with time zone, "jsonb", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_customer_credit_movement"("p_user_id" "uuid", "p_movement_type" "text", "p_amount" numeric, "p_description" "text", "p_source_type" "text" DEFAULT 'admin_adjustment'::"text", "p_source_id" "text" DEFAULT NULL::"text", "p_order_id" bigint DEFAULT NULL::bigint, "p_claim_id" bigint DEFAULT NULL::bigint, "p_credit_note_id" "text" DEFAULT NULL::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid", "p_related_movement_id" "uuid" DEFAULT NULL::"uuid", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_source_key" "text" DEFAULT NULL::"text") RETURNS TABLE("movement_id" "uuid", "resulting_balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_amount numeric(12, 2);
  v_balance numeric(12, 2);
  v_effect integer;
  v_source_key text;
  v_existing public.customer_credit_movements%rowtype;
  v_movement public.customer_credit_movements%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'No tenés permisos para crear movimientos de saldo.';
  end if;

  v_amount := round(coalesce(p_amount, 0)::numeric, 2);
  v_effect := public.customer_credit_movement_effect(p_movement_type);
  v_source_key := nullif(trim(coalesce(p_source_key, '')), '');

  if p_user_id is null or v_amount <= 0 or v_effect = 0 then
    raise exception 'INVALID_CUSTOMER_CREDIT_MOVEMENT';
  end if;

  if p_movement_type not in ('credit', 'debit', 'reversal', 'adjustment', 'expiration') then
    raise exception 'INVALID_CUSTOMER_CREDIT_MOVEMENT_TYPE';
  end if;

  if p_source_type not in (
    'credit_note',
    'claim',
    'return',
    'exchange',
    'order',
    'admin_adjustment',
    'reversal'
  ) then
    raise exception 'INVALID_CUSTOMER_CREDIT_SOURCE_TYPE';
  end if;

  if length(trim(coalesce(p_description, ''))) < 3 then
    raise exception 'CUSTOMER_CREDIT_DESCRIPTION_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtext('customer-credit:' || p_user_id::text));

  if v_source_key is not null then
    select *
    into v_existing
    from public.customer_credit_movements
    where source_key = v_source_key
    limit 1;

    if found then
      movement_id := v_existing.id;
      resulting_balance := coalesce(
        v_existing.resulting_balance,
        public.get_customer_credit_balance(p_user_id)
      );
      return next;
      return;
    end if;
  end if;

  select public.get_customer_credit_balance(p_user_id)
  into v_balance;

  if v_effect < 0 and v_amount > v_balance then
    raise exception 'INSUFFICIENT_CUSTOMER_CREDIT';
  end if;

  insert into public.customer_credit_movements (
    user_id,
    movement_type,
    amount,
    description,
    source_type,
    source_id,
    order_id,
    claim_id,
    credit_note_id,
    created_by,
    related_movement_id,
    expires_at,
    metadata,
    source_key,
    resulting_balance
  ) values (
    p_user_id,
    p_movement_type,
    v_amount,
    trim(p_description),
    p_source_type,
    p_source_id,
    p_order_id,
    p_claim_id,
    p_credit_note_id,
    coalesce(p_created_by, auth.uid()),
    p_related_movement_id,
    p_expires_at,
    coalesce(p_metadata, '{}'::jsonb),
    v_source_key,
    greatest(v_balance + (v_amount * v_effect), 0)
  )
  returning *
  into v_movement;

  movement_id := v_movement.id;
  resulting_balance := coalesce(v_movement.resulting_balance, 0);
  return next;
end;
$$;


ALTER FUNCTION "public"."create_customer_credit_movement"("p_user_id" "uuid", "p_movement_type" "text", "p_amount" numeric, "p_description" "text", "p_source_type" "text", "p_source_id" "text", "p_order_id" bigint, "p_claim_id" bigint, "p_credit_note_id" "text", "p_created_by" "uuid", "p_related_movement_id" "uuid", "p_expires_at" timestamp with time zone, "p_metadata" "jsonb", "p_source_key" "text") OWNER TO "postgres";

--
-- Name: order_replacements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."order_replacements" (
    "id" bigint NOT NULL,
    "original_order_id" bigint NOT NULL,
    "original_order_item_id" bigint NOT NULL,
    "claim_id" bigint,
    "replacement_product_id" bigint NOT NULL,
    "replacement_variant_id" bigint NOT NULL,
    "quantity" integer NOT NULL,
    "reason" "text" NOT NULL,
    "condition_note" "text",
    "notes" "text",
    "unit_cost" numeric(12,2),
    "idempotency_key" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "order_replacements_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "order_replacements_reason_check" CHECK (("reason" = ANY (ARRAY['mismo_producto'::"text", 'otra_variante'::"text", 'otro_producto'::"text", 'garantia'::"text"])))
);


ALTER TABLE "public"."order_replacements" OWNER TO "postgres";

--
-- Name: create_order_replacement(bigint, bigint, bigint, integer, "text", "uuid", "text", "text", "text", bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_order_replacement"("p_original_order_id" bigint, "p_original_order_item_id" bigint, "p_replacement_variant_id" bigint, "p_quantity" integer, "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text", "p_condition_note" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_claim_id" bigint DEFAULT NULL::bigint) RETURNS "public"."order_replacements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare v_existing public.order_replacements; v_item public.orden_items; v_used integer; v_result public.order_replacements;
begin
  if auth.role() is distinct from 'service_role' or not exists (
    select 1 from public.profiles where id = p_actor_id and rol in ('admin','super_admin')
  ) then raise exception 'REPLACEMENT_FORBIDDEN'; end if;
  if p_idempotency_key is null or length(trim(p_idempotency_key)) < 8 then
    raise exception 'REPLACEMENT_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('replacement:' || p_idempotency_key, 0));
  select * into v_existing from public.order_replacements where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.original_order_id <> p_original_order_id or v_existing.original_order_item_id <> p_original_order_item_id
      or v_existing.replacement_variant_id <> p_replacement_variant_id or v_existing.quantity <> p_quantity
      or v_existing.reason <> p_reason or v_existing.created_by <> p_actor_id
      or v_existing.claim_id is distinct from p_claim_id then raise exception 'REPLACEMENT_CONFLICT'; end if;
    return v_existing;
  end if;
  select * into v_item from public.orden_items where id = p_original_order_item_id and orden_id = p_original_order_id for update;
  if not found then raise exception 'REPLACEMENT_INVALID_ITEM'; end if;
  select coalesce(sum(quantity),0) into v_used from public.order_replacements where original_order_item_id = p_original_order_item_id;
  if p_quantity is null or p_quantity <= 0 or p_quantity + v_used > v_item.cantidad then
    raise exception 'REPLACEMENT_QUANTITY_EXCEEDED';
  end if;
  if p_reason <> 'garantia' and p_quantity + v_used > coalesce(v_item.return_restocked_quantity,0) + coalesce(v_item.return_written_off_quantity,0) then
    raise exception 'REPLACEMENT_REQUIRES_RECEIVED_ITEM';
  end if;
  if p_claim_id is not null and not exists (select 1 from public.order_claims where id = p_claim_id and order_id = p_original_order_id) then
    raise exception 'REPLACEMENT_INVALID_CLAIM';
  end if;
  if not exists (select 1 from public.producto_variantes v join public.productos p on p.id = v.producto_id
    where v.id = p_replacement_variant_id and v.activo and p.activo) then raise exception 'REPLACEMENT_UNAVAILABLE'; end if;
  v_result := public.create_order_replacement_internal(p_original_order_id,p_original_order_item_id,p_replacement_variant_id,
    p_quantity,p_reason,p_actor_id,p_idempotency_key,p_condition_note,p_notes,p_claim_id);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_order_replacement"("p_original_order_id" bigint, "p_original_order_item_id" bigint, "p_replacement_variant_id" bigint, "p_quantity" integer, "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text", "p_condition_note" "text", "p_notes" "text", "p_claim_id" bigint) OWNER TO "postgres";

--
-- Name: create_order_replacement_internal(bigint, bigint, bigint, integer, "text", "uuid", "text", "text", "text", bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_order_replacement_internal"("p_original_order_id" bigint, "p_original_order_item_id" bigint, "p_replacement_variant_id" bigint, "p_quantity" integer, "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text", "p_condition_note" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_claim_id" bigint DEFAULT NULL::bigint) RETURNS "public"."order_replacements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_original_item public.orden_items%rowtype;
  v_variant public.producto_variantes%rowtype;
  v_existing public.order_replacements%rowtype;
  v_unit_cost numeric;
  v_target_stock integer;
  v_result public.order_replacements%rowtype;
begin
  if auth.role() is distinct from 'service_role'
     or not exists (select 1 from public.profiles where id = p_actor_id and rol in ('admin', 'super_admin')) then
    raise exception 'REPLACEMENT_FORBIDDEN';
  end if;
  if p_reason not in ('mismo_producto', 'otra_variante', 'otro_producto', 'garantia') then
    raise exception 'REPLACEMENT_INVALID_REASON';
  end if;
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'REPLACEMENT_INVALID_QUANTITY';
  end if;
  if p_idempotency_key is null or length(trim(p_idempotency_key)) < 8 then
    raise exception 'REPLACEMENT_IDEMPOTENCY_KEY_REQUIRED';
  end if;

  select * into v_existing from public.order_replacements where idempotency_key = p_idempotency_key;
  if found then
    return v_existing;
  end if;

  select * into v_original_item
  from public.orden_items
  where id = p_original_order_item_id and orden_id = p_original_order_id;
  if not found then
    raise exception 'No se encontró el producto dentro del pedido original.';
  end if;

  -- Trazabilidad real, no chat: salvo garantía sin devolución física, exige
  -- que el producto original ya haya sido recibido (sano o roto) por el
  -- motor canónico de devoluciones antes de poder generar el reemplazo.
  if p_reason <> 'garantia'
     and coalesce(v_original_item.return_restocked_quantity, 0)
         + coalesce(v_original_item.return_written_off_quantity, 0) < p_quantity then
    raise exception 'REPLACEMENT_REQUIRES_RECEIVED_ITEM';
  end if;

  select * into v_variant
  from public.producto_variantes
  where id = p_replacement_variant_id;
  if not found then
    raise exception 'La variante de reemplazo no existe.';
  end if;

  -- Mismo lock que toda operación de stock (refresh_inventory_stock,
  -- adjust_variant_stock_idempotent, etc.) -- reentrante dentro de esta
  -- misma transacción, así que leer el stock acá y pasarlo como objetivo
  -- absoluto más abajo es seguro: nadie más puede tocar el stock de este
  -- producto hasta que esta transacción termine.
  perform pg_advisory_xact_lock(93000, v_variant.producto_id::integer);

  select stock into v_target_stock from public.producto_variantes where id = p_replacement_variant_id;
  v_target_stock := coalesce(v_target_stock, 0) - p_quantity;
  if v_target_stock < 0 then
    raise exception 'STOCK_INSUFICIENTE: no hay stock suficiente del producto/variante de reemplazo.';
  end if;

  v_unit_cost := public.compute_historical_unit_cost(v_variant.producto_id, p_replacement_variant_id, current_date);

  perform public.adjust_variant_stock_idempotent(
    p_replacement_variant_id,
    v_target_stock,
    'Salida por reemplazo del pedido #' || p_original_order_id,
    p_actor_id,
    'replacement:' || p_idempotency_key
  );

  insert into public.order_replacements (
    original_order_id, original_order_item_id, claim_id,
    replacement_product_id, replacement_variant_id, quantity, reason,
    condition_note, notes, unit_cost, idempotency_key, created_by
  ) values (
    p_original_order_id, p_original_order_item_id, p_claim_id,
    v_variant.producto_id, p_replacement_variant_id, p_quantity, p_reason,
    nullif(left(trim(coalesce(p_condition_note, '')), 500), ''),
    nullif(left(trim(coalesce(p_notes, '')), 1000), ''),
    v_unit_cost, p_idempotency_key, p_actor_id
  )
  returning * into v_result;

  insert into public.order_audit_events (order_id, actor_type, actor_id, action, metadata)
  values (
    p_original_order_id, 'admin', p_actor_id, 'order_replacement_created',
    jsonb_build_object(
      'originalOrderItemId', p_original_order_item_id,
      'replacementProductId', v_variant.producto_id,
      'replacementVariantId', p_replacement_variant_id,
      'quantity', p_quantity,
      'reason', p_reason,
      'unitCost', v_unit_cost,
      'claimId', p_claim_id
    )
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."create_order_replacement_internal"("p_original_order_id" bigint, "p_original_order_item_id" bigint, "p_replacement_variant_id" bigint, "p_quantity" integer, "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text", "p_condition_note" "text", "p_notes" "text", "p_claim_id" bigint) OWNER TO "postgres";

--
-- Name: business_expenses; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."business_expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "expense_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "category" "text" NOT NULL,
    "description" "text",
    "amount" numeric(14,2) NOT NULL,
    "recurrence" "text" DEFAULT 'unico'::"text" NOT NULL,
    "status" "text" DEFAULT 'pagado'::"text" NOT NULL,
    "supplier" "text",
    "payment_method" "text",
    "document_type" "text",
    "document_number" "text",
    "tax_deductible" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "category_detail" "text",
    "recipient" "text",
    "expense_type" "text" DEFAULT 'money'::"text" NOT NULL,
    "product_id" bigint,
    "variant_id" bigint,
    "product_name" "text",
    "product_sku" "text",
    "quantity" integer,
    "idempotency_key" "text",
    CONSTRAINT "business_expenses_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "business_expenses_expense_type_check" CHECK (("expense_type" = ANY (ARRAY['money'::"text", 'product'::"text"]))),
    CONSTRAINT "business_expenses_product_fields_check" CHECK (((("expense_type" = 'money'::"text") AND ("product_id" IS NULL) AND ("variant_id" IS NULL) AND ("quantity" IS NULL)) OR (("expense_type" = 'product'::"text") AND ("product_name" IS NOT NULL) AND ("quantity" IS NOT NULL) AND ("quantity" > 0) AND ("amount" = (0)::numeric) AND ("category" = ANY (ARRAY['Donación/Regalo'::"text", 'Sorteo/Evento'::"text", 'Producto dañado/perdido'::"text"]))))),
    CONSTRAINT "business_expenses_recurrence_check" CHECK (("recurrence" = ANY (ARRAY['unico'::"text", 'mensual'::"text", 'bimestral'::"text", 'trimestral'::"text", 'semestral'::"text", 'anual'::"text"]))),
    CONSTRAINT "business_expenses_status_check" CHECK (("status" = ANY (ARRAY['pendiente'::"text", 'pagado'::"text"])))
);


ALTER TABLE "public"."business_expenses" OWNER TO "postgres";

--
-- Name: TABLE "business_expenses"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."business_expenses" IS 'Gastos operativos, fiscales y administrativos reales de BEYONIX.';


--
-- Name: COLUMN "business_expenses"."category_detail"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."business_expenses"."category_detail" IS 'Detalle opcional cuando la categoría del gasto es Otros.';


--
-- Name: COLUMN "business_expenses"."recipient"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."business_expenses"."recipient" IS 'Destinatario de un gasto categorizado como Donación/Regalo.';


--
-- Name: create_product_business_expense("date", "text", "text", "text", "text", bigint, bigint, "text", "text", integer, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_product_business_expense"("p_expense_date" "date", "p_category" "text", "p_recipient" "text", "p_category_detail" "text", "p_description" "text", "p_product_id" bigint, "p_variant_id" bigint, "p_product_name" "text", "p_product_sku" "text", "p_quantity" integer, "p_notes" "text", "p_created_by" "uuid") RETURNS "public"."business_expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_expense public.business_expenses;
  v_available integer;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para registrar salidas de inventario.';
  end if;
  if p_category not in ('Donación/Regalo', 'Sorteo/Evento')
     or p_product_id is null
     or p_quantity is null
     or p_quantity <= 0
     or trim(coalesce(p_product_name, '')) = '' then
    raise exception 'PRODUCT_EXPENSE_INVALID';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);

  if exists (
    select 1 from public.producto_variantes
    where producto_id = p_product_id
  ) and p_variant_id is null then
    raise exception 'PRODUCT_EXPENSE_VARIANT_REQUIRED';
  end if;

  if p_variant_id is not null then
    select coalesce(stock, 0)
    into v_available
    from public.producto_variantes
    where id = p_variant_id
      and producto_id = p_product_id;
  else
    select coalesce(stock, 0)
    into v_available
    from public.productos
    where id = p_product_id;
  end if;

  if not found or v_available < p_quantity then
    raise exception 'PRODUCT_EXPENSE_STOCK_INSUFFICIENT';
  end if;

  insert into public.business_expenses (
    expense_date,
    category,
    category_detail,
    recipient,
    description,
    amount,
    recurrence,
    status,
    tax_deductible,
    notes,
    expense_type,
    product_id,
    variant_id,
    product_name,
    product_sku,
    quantity,
    created_by
  )
  values (
    p_expense_date,
    p_category,
    nullif(trim(p_category_detail), ''),
    nullif(trim(p_recipient), ''),
    nullif(trim(p_description), ''),
    0,
    'unico',
    'pagado',
    false,
    nullif(trim(p_notes), ''),
    'product',
    p_product_id,
    p_variant_id,
    trim(p_product_name),
    nullif(trim(p_product_sku), ''),
    p_quantity,
    p_created_by
  )
  returning * into v_expense;

  return v_expense;
end;
$$;


ALTER FUNCTION "public"."create_product_business_expense"("p_expense_date" "date", "p_category" "text", "p_recipient" "text", "p_category_detail" "text", "p_description" "text", "p_product_id" bigint, "p_variant_id" bigint, "p_product_name" "text", "p_product_sku" "text", "p_quantity" integer, "p_notes" "text", "p_created_by" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "create_product_business_expense"("p_expense_date" "date", "p_category" "text", "p_recipient" "text", "p_category_detail" "text", "p_description" "text", "p_product_id" bigint, "p_variant_id" bigint, "p_product_name" "text", "p_product_sku" "text", "p_quantity" integer, "p_notes" "text", "p_created_by" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."create_product_business_expense"("p_expense_date" "date", "p_category" "text", "p_recipient" "text", "p_category_detail" "text", "p_description" "text", "p_product_id" bigint, "p_variant_id" bigint, "p_product_name" "text", "p_product_sku" "text", "p_quantity" integer, "p_notes" "text", "p_created_by" "uuid") IS 'Registra una donación, regalo o sorteo de productos y descuenta su stock de forma atómica.';


--
-- Name: create_product_business_expense_idempotent("date", "text", "text", "text", "text", bigint, bigint, "text", "text", integer, "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_product_business_expense_idempotent"("p_expense_date" "date", "p_category" "text", "p_recipient" "text", "p_category_detail" "text", "p_description" "text", "p_product_id" bigint, "p_variant_id" bigint, "p_product_name" "text", "p_product_sku" "text", "p_quantity" integer, "p_notes" "text", "p_created_by" "uuid", "p_idempotency_key" "text") RETURNS "public"."business_expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing public.business_expenses%rowtype;
  v_saved public.business_expenses%rowtype;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
begin
  if v_key is null or length(v_key) < 8 or length(v_key) > 240 then
    raise exception 'IDEMPOTENCY_KEY_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtext('inventory-expense'), hashtext(v_key));

  select * into v_existing
  from public.business_expenses expenses
  where expenses.idempotency_key = v_key
  for update;
  if found then return v_existing; end if;

  v_saved := public.create_product_business_expense(
    p_expense_date, p_category, p_recipient, p_category_detail,
    p_description, p_product_id, p_variant_id, p_product_name,
    p_product_sku, p_quantity, p_notes, p_created_by
  );

  update public.business_expenses
  set idempotency_key = v_key
  where id = v_saved.id
  returning * into v_saved;

  insert into public.inventory_operation_log (
    product_id, variant_id, movement_type, quantity, origin, effective_at,
    actor_user_id, actor_process, idempotency_key, source_table, source_id,
    document_reference, metadata
  ) values (
    p_product_id, p_variant_id, 'write_off', p_quantity,
    'product_business_expense',
    p_expense_date::timestamp at time zone 'America/Argentina/Buenos_Aires',
    p_created_by, 'create_product_business_expense_idempotent', v_key,
    'business_expenses', v_saved.id::text, v_saved.id::text,
    jsonb_build_object('category', p_category)
  ) on conflict (idempotency_key) do nothing;

  return v_saved;
end;
$$;


ALTER FUNCTION "public"."create_product_business_expense_idempotent"("p_expense_date" "date", "p_category" "text", "p_recipient" "text", "p_category_detail" "text", "p_description" "text", "p_product_id" bigint, "p_variant_id" bigint, "p_product_name" "text", "p_product_sku" "text", "p_quantity" integer, "p_notes" "text", "p_created_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";

--
-- Name: create_product_variant_with_allocation(bigint, "text", "text", "text", "jsonb", integer, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_product_variant_with_allocation"("p_product_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid") RETURNS "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_product public.productos%rowtype;
  v_created public.producto_variantes%rowtype;
  v_allocations jsonb;
begin
  if p_product_id is null
     or p_product_id <= 0
     or nullif(btrim(p_name), '') is null
     or p_color_hex !~ '^#[0-9A-Fa-f]{6}$'
     or p_quantity is null
     or p_quantity < 0 then
    raise exception 'Los datos de la variante no son válidos.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);

  select *
  into v_product
  from public.productos
  where id = p_product_id
  for update;

  if not found then
    raise exception 'El producto ya no existe.';
  end if;

  insert into public.producto_variantes (
    producto_id,
    nombre,
    sku,
    color_hex,
    imagenes,
    activo,
    orden
  )
  values (
    p_product_id,
    left(btrim(p_name), 160),
    nullif(left(btrim(coalesce(p_sku, '')), 120), ''),
    upper(p_color_hex),
    coalesce(p_images, '[]'::jsonb),
    v_product.activo,
    (
      select coalesce(max(variants.orden), 0) + 1
      from public.producto_variantes variants
      where variants.producto_id = p_product_id
    )
  )
  returning * into v_created;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'variant_id', allocations.variant_id,
        'quantity', allocations.quantity
      )
      order by allocations.variant_id
    ),
    '[]'::jsonb
  )
  into v_allocations
  from public.inventory_variant_allocations allocations
  where allocations.product_id = p_product_id;

  v_allocations := v_allocations || jsonb_build_array(
    jsonb_build_object(
      'variant_id', v_created.id,
      'quantity', p_quantity
    )
  );

  perform public.set_product_variant_allocations(
    p_product_id,
    v_allocations,
    p_actor_id
  );

  select *
  into v_created
  from public.producto_variantes
  where id = v_created.id;

  return v_created;
end;
$_$;


ALTER FUNCTION "public"."create_product_variant_with_allocation"("p_product_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: create_product_variant_with_allocation_v2(bigint, "text", "text", "text", "jsonb", integer, "uuid", numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_product_variant_with_allocation_v2"("p_product_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid", "p_peso_empaquetado_kg" numeric, "p_alto_paquete_cm" numeric, "p_ancho_paquete_cm" numeric, "p_largo_paquete_cm" numeric) RETURNS "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_variant public.producto_variantes%rowtype;
begin
  v_variant := public.create_product_variant_with_allocation(
    p_product_id, p_name, p_sku, p_color_hex, p_images, p_quantity, p_actor_id
  );
  update public.producto_variantes
  set activo = false,
      peso_empaquetado_kg = p_peso_empaquetado_kg,
      alto_paquete_cm = p_alto_paquete_cm,
      ancho_paquete_cm = p_ancho_paquete_cm,
      largo_paquete_cm = p_largo_paquete_cm
  where id = v_variant.id
  returning * into v_variant;
  perform public.sync_product_primary_variant_image(p_product_id);
  return v_variant;
end;
$$;


ALTER FUNCTION "public"."create_product_variant_with_allocation_v2"("p_product_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid", "p_peso_empaquetado_kg" numeric, "p_alto_paquete_cm" numeric, "p_ancho_paquete_cm" numeric, "p_largo_paquete_cm" numeric) OWNER TO "postgres";

--
-- Name: productos; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."productos" (
    "id" bigint NOT NULL,
    "nombre" "text" NOT NULL,
    "slug" "text" NOT NULL,
    "descripcion" "text",
    "precio" numeric(10,2) NOT NULL,
    "precio_anterior" numeric(10,2),
    "descuento" integer DEFAULT 0,
    "stock" integer DEFAULT 0,
    "destacado" boolean DEFAULT false,
    "activo" boolean DEFAULT true,
    "imagen_principal" "text",
    "categoria_id" bigint,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "video_url" "text",
    "promo_event_id" "uuid",
    "promo_original_precio" numeric,
    "promo_original_precio_anterior" numeric,
    "promo_original_descuento" integer,
    "sku" "text",
    "created_from_costs" boolean DEFAULT false NOT NULL,
    "peso_empaquetado_kg" numeric(10,3),
    "alto_paquete_cm" numeric(10,2),
    "ancho_paquete_cm" numeric(10,2),
    "largo_paquete_cm" numeric(10,2),
    "codigo_barra" "text",
    "cuotas_2_habilitadas" boolean DEFAULT false NOT NULL,
    "cuotas_3_habilitadas" boolean DEFAULT false NOT NULL,
    "cuotas_6_habilitadas" boolean DEFAULT false NOT NULL,
    "promo_original_cuotas_2_habilitadas" boolean,
    "promo_original_cuotas_3_habilitadas" boolean,
    "promo_original_cuotas_6_habilitadas" boolean,
    CONSTRAINT "productos_alto_paquete_cm_check" CHECK ((("alto_paquete_cm" IS NULL) OR (("alto_paquete_cm" <> 'NaN'::numeric) AND ("alto_paquete_cm" > (0)::numeric) AND ("alto_paquete_cm" <= (1000)::numeric)))),
    CONSTRAINT "productos_ancho_paquete_cm_check" CHECK ((("ancho_paquete_cm" IS NULL) OR (("ancho_paquete_cm" <> 'NaN'::numeric) AND ("ancho_paquete_cm" > (0)::numeric) AND ("ancho_paquete_cm" <= (1000)::numeric)))),
    CONSTRAINT "productos_largo_paquete_cm_check" CHECK ((("largo_paquete_cm" IS NULL) OR (("largo_paquete_cm" <> 'NaN'::numeric) AND ("largo_paquete_cm" > (0)::numeric) AND ("largo_paquete_cm" <= (1000)::numeric)))),
    CONSTRAINT "productos_peso_empaquetado_kg_check" CHECK ((("peso_empaquetado_kg" IS NULL) OR (("peso_empaquetado_kg" <> 'NaN'::numeric) AND ("peso_empaquetado_kg" > (0)::numeric) AND ("peso_empaquetado_kg" <= (10000)::numeric)))),
    CONSTRAINT "productos_stock_nonnegative_check" CHECK (("stock" >= 0)),
    CONSTRAINT "productos_video_url_https_chk" CHECK ((("video_url" IS NULL) OR ("video_url" ~ '^https://[^[:space:]]+$'::"text")))
);


ALTER TABLE "public"."productos" OWNER TO "postgres";

