--
-- Name: create_producto_completo("jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_producto_completo"("p_producto" "jsonb", "p_imagenes" "jsonb" DEFAULT '[]'::"jsonb", "p_variantes" "jsonb" DEFAULT '[]'::"jsonb", "p_especificaciones" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."productos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_actor_email text := coalesce(auth.jwt() ->> 'email', current_setting('request.jwt.claim.email', true));
  v_producto public.productos%rowtype;
  v_imagen jsonb;
  v_variante jsonb;
  v_especificacion jsonb;
  v_trigger record;
  v_disabled_trigger text;
  v_disabled_triggers text[] := array[]::text[];
  v_legacy_cuotas_sin_interes boolean := coalesce((p_producto ->> 'cuotas_sin_interes')::boolean, false);
  v_legacy_cuotas_maximas text := p_producto ->> 'cuotas_maximas';
begin
  if v_actor_user_id is null then
    raise exception 'Tenés que iniciar sesión para crear productos.';
  end if;

  if not exists (
    select 1
    from public.profiles
    where id = v_actor_user_id
      and rol in ('admin', 'super_admin')
  ) then
    raise exception 'Solo un administrador puede crear productos.';
  end if;

  p_imagenes := coalesce(p_imagenes, '[]'::jsonb);
  p_variantes := coalesce(p_variantes, '[]'::jsonb);
  p_especificaciones := coalesce(p_especificaciones, '[]'::jsonb);

  for v_trigger in
    select
      c.relname as table_name,
      t.tgname as trigger_name
    from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
    join pg_proc p on p.oid = t.tgfoid
    where n.nspname = 'public'
      and c.relname = any(array[
        'productos',
        'imagenes_producto',
        'producto_variantes',
        'producto_especificaciones'
      ])
      and not t.tgisinternal
      and t.tgenabled <> 'D'
      and (
        p.proname ilike '%audit%'
        or p.prosrc ilike '%audit_logs%'
      )
  loop
    execute format(
      'alter table public.%I disable trigger %I',
      v_trigger.table_name,
      v_trigger.trigger_name
    );

    v_disabled_triggers :=
      array_append(
        v_disabled_triggers,
        v_trigger.table_name || ':' || v_trigger.trigger_name
      );
  end loop;

  insert into public.productos (
    nombre,
    slug,
    descripcion,
    video_url,
    precio,
    precio_anterior,
    descuento,
    cuotas_2_habilitadas,
    cuotas_3_habilitadas,
    cuotas_6_habilitadas,
    stock,
    categoria_id,
    destacado,
    activo,
    imagen_principal
  )
  values (
    trim(p_producto ->> 'nombre'),
    trim(p_producto ->> 'slug'),
    nullif(trim(coalesce(p_producto ->> 'descripcion', '')), ''),
    nullif(trim(coalesce(p_producto ->> 'video_url', '')), ''),
    (p_producto ->> 'precio')::numeric,
    nullif(p_producto ->> 'precio_anterior', '')::numeric,
    nullif(p_producto ->> 'descuento', '')::integer,
    coalesce((p_producto ->> 'cuotas_2_habilitadas')::boolean, false),
    coalesce(
      (p_producto ->> 'cuotas_3_habilitadas')::boolean,
      v_legacy_cuotas_sin_interes and v_legacy_cuotas_maximas = '3'
    ),
    coalesce(
      (p_producto ->> 'cuotas_6_habilitadas')::boolean,
      v_legacy_cuotas_sin_interes and v_legacy_cuotas_maximas = '6'
    ),
    coalesce((p_producto ->> 'stock')::integer, 0),
    nullif(p_producto ->> 'categoria_id', '')::integer,
    coalesce((p_producto ->> 'destacado')::boolean, false),
    coalesce((p_producto ->> 'activo')::boolean, false),
    nullif(trim(coalesce(p_producto ->> 'imagen_principal', '')), '')
  )
  returning *
  into v_producto;

  for v_imagen in
    select value
    from jsonb_array_elements(p_imagenes)
  loop
    if nullif(trim(coalesce(v_imagen ->> 'url', '')), '') is not null then
      insert into public.imagenes_producto (
        producto_id,
        url,
        orden
      )
      values (
        v_producto.id,
        trim(v_imagen ->> 'url'),
        coalesce((v_imagen ->> 'orden')::integer, 1)
      );
    end if;
  end loop;

  for v_variante in
    select value
    from jsonb_array_elements(p_variantes)
  loop
    insert into public.producto_variantes (
      producto_id,
      nombre,
      color_hex,
      stock,
      imagenes,
      activo,
      orden
    )
    values (
      v_producto.id,
      trim(v_variante ->> 'nombre'),
      trim(v_variante ->> 'color_hex'),
      coalesce((v_variante ->> 'stock')::integer, 0),
      coalesce(v_variante -> 'imagenes', '[]'::jsonb),
      coalesce((v_variante ->> 'activo')::boolean, true),
      coalesce((v_variante ->> 'orden')::integer, 1)
    );
  end loop;

  for v_especificacion in
    select value
    from jsonb_array_elements(p_especificaciones)
  loop
    if
      nullif(trim(coalesce(v_especificacion ->> 'icono', '')), '') is not null
      and nullif(trim(coalesce(v_especificacion ->> 'texto', '')), '') is not null
    then
      insert into public.producto_especificaciones (
        producto_id,
        icono,
        texto,
        orden,
        activo
      )
      values (
        v_producto.id,
        trim(v_especificacion ->> 'icono'),
        trim(v_especificacion ->> 'texto'),
        coalesce((v_especificacion ->> 'orden')::integer, 1),
        coalesce((v_especificacion ->> 'activo')::boolean, true)
      );
    end if;
  end loop;

  select *
  into v_producto
  from public.productos
  where id = v_producto.id;

  foreach v_disabled_trigger in array v_disabled_triggers
  loop
    execute format(
      'alter table public.%I enable trigger %I',
      split_part(v_disabled_trigger, ':', 1),
      split_part(v_disabled_trigger, ':', 2)
    );
  end loop;

  insert into public.audit_logs (
    table_name,
    action,
    record_id,
    actor_user_id,
    actor_email,
    before_data,
    after_data
  )
  values (
    'productos',
    'INSERT',
    v_producto.id::text,
    v_actor_user_id,
    v_actor_email,
    null,
    to_jsonb(v_producto) ||
      jsonb_build_object(
        'imagenes_cargadas', jsonb_array_length(p_imagenes),
        'variantes_cargadas', jsonb_array_length(p_variantes),
        'especificaciones_cargadas', jsonb_array_length(p_especificaciones)
      )
  );

  return v_producto;
exception
  when others then
    foreach v_disabled_trigger in array v_disabled_triggers
    loop
      execute format(
        'alter table public.%I enable trigger %I',
        split_part(v_disabled_trigger, ':', 1),
        split_part(v_disabled_trigger, ':', 2)
      );
    end loop;

    raise;
end;
$$;


ALTER FUNCTION "public"."create_producto_completo"("p_producto" "jsonb", "p_imagenes" "jsonb", "p_variantes" "jsonb", "p_especificaciones" "jsonb") OWNER TO "postgres";

--
-- Name: create_producto_completo_v2("jsonb", "jsonb", "jsonb", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."create_producto_completo_v2"("p_producto" "jsonb", "p_imagenes" "jsonb" DEFAULT '[]'::"jsonb", "p_variantes" "jsonb" DEFAULT '[]'::"jsonb", "p_especificaciones" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "public"."productos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product public.productos%rowtype;
  v_variant jsonb;
  v_variant_id bigint;
  v_index integer := 0;
  v_peso numeric;
  v_alto numeric;
  v_ancho numeric;
  v_largo numeric;
begin
  v_peso := nullif(p_producto ->> 'peso_empaquetado_kg', '')::numeric;
  v_alto := nullif(p_producto ->> 'alto_paquete_cm', '')::numeric;
  v_ancho := nullif(p_producto ->> 'ancho_paquete_cm', '')::numeric;
  v_largo := nullif(p_producto ->> 'largo_paquete_cm', '')::numeric;

  if v_peso is null or v_peso <= 0
     or v_alto is null or v_alto <= 0
     or v_ancho is null or v_ancho <= 0
     or v_largo is null or v_largo <= 0 then
    raise exception
      'El peso y las dimensiones del producto (alto, ancho y largo) son obligatorios y deben ser mayores que 0.';
  end if;

  v_product := public.create_producto_completo(
    p_producto,
    p_imagenes,
    p_variantes,
    p_especificaciones
  );

  update public.productos
  set peso_empaquetado_kg = v_peso,
      alto_paquete_cm = v_alto,
      ancho_paquete_cm = v_ancho,
      largo_paquete_cm = v_largo
  where id = v_product.id;

  for v_variant in
    select value
    from jsonb_array_elements(coalesce(p_variantes, '[]'::jsonb))
  loop
    select variants.id
    into v_variant_id
    from public.producto_variantes variants
    where variants.producto_id = v_product.id
    order by variants.id
    offset v_index
    limit 1;

    if v_variant_id is null then
      raise exception 'No se pudo verificar una variante recién creada.';
    end if;

    update public.producto_variantes
    set sku = nullif(left(btrim(coalesce(v_variant ->> 'sku', '')), 120), ''),
        peso_empaquetado_kg = nullif(v_variant ->> 'peso_empaquetado_kg', '')::numeric,
        alto_paquete_cm = nullif(v_variant ->> 'alto_paquete_cm', '')::numeric,
        ancho_paquete_cm = nullif(v_variant ->> 'ancho_paquete_cm', '')::numeric,
        largo_paquete_cm = nullif(v_variant ->> 'largo_paquete_cm', '')::numeric
    where id = v_variant_id;

    v_index := v_index + 1;
  end loop;

  if jsonb_array_length(coalesce(p_variantes, '[]'::jsonb)) = 0 then
    update public.productos
    set sku = nullif(left(btrim(coalesce(p_producto ->> 'sku', '')), 120), '')
    where id = v_product.id;
  end if;

  select * into v_product
  from public.productos
  where id = v_product.id;

  return v_product;
end;
$$;


ALTER FUNCTION "public"."create_producto_completo_v2"("p_producto" "jsonb", "p_imagenes" "jsonb", "p_variantes" "jsonb", "p_especificaciones" "jsonb") OWNER TO "postgres";

--
-- Name: FUNCTION "create_producto_completo_v2"("p_producto" "jsonb", "p_imagenes" "jsonb", "p_variantes" "jsonb", "p_especificaciones" "jsonb"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."create_producto_completo_v2"("p_producto" "jsonb", "p_imagenes" "jsonb", "p_variantes" "jsonb", "p_especificaciones" "jsonb") IS 'Crea el producto completo desde la ficha de Productos; peso y dimensiones son obligatorios en esta vía únicamente.';


--
-- Name: credit_customer_credit_topup_from_mercadopago("uuid", "text", "text", numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."credit_customer_credit_topup_from_mercadopago"("p_topup_id" "uuid", "p_payment_id" "text", "p_payment_status" "text", "p_paid_amount" numeric) RETURNS TABLE("topup_status" "text", "movement_id" "uuid", "resulting_balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_topup public.customer_credit_topups%rowtype;
  v_paid_amount numeric(12, 2);
  v_movement_id uuid;
  v_resulting_balance numeric(12, 2);
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  select *
  into v_topup
  from public.customer_credit_topups
  where id = p_topup_id
  for update;

  if not found then
    raise exception 'TOPUP_NOT_FOUND';
  end if;

  if v_topup.payment_method <> 'mercadopago' then
    raise exception 'INVALID_TOPUP_PAYMENT_METHOD';
  end if;

  if p_payment_status <> 'approved' then
    raise exception 'PAYMENT_NOT_APPROVED';
  end if;

  if nullif(trim(coalesce(p_payment_id, '')), '') is null then
    raise exception 'PAYMENT_ID_REQUIRED';
  end if;

  -- Terminal: una carga ya revertida (refund/chargeback) NUNCA vuelve a
  -- 'acreditado' sola. Queda auditado en admin_notes (una sola vez por
  -- payment_id) y requiere reconciliación administrativa explícita para
  -- reabrirse -- no la hace esta función.
  if v_topup.status = 'revertido' then
    if position(p_payment_id in coalesce(v_topup.admin_notes, '')) = 0 then
      update public.customer_credit_topups
      set
        admin_notes = trim(
          coalesce(admin_notes, '') ||
          E'\n[Alerta] Mercado Pago informó approved (payment ' || p_payment_id ||
          ') DESPUÉS de una reversa ya aplicada -- NO se volvió a acreditar saldo. Requiere revisión manual.'
        ),
        updated_at = now()
      where id = v_topup.id;
    end if;

    topup_status := 'revertido';
    movement_id := v_topup.reversed_movement_id;
    resulting_balance := public.get_customer_credit_balance(v_topup.user_id);
    return next;
    return;
  end if;

  if v_topup.status = 'acreditado' then
    if v_topup.mercadopago_payment_id is distinct from p_payment_id then
      raise exception 'TOPUP_ALREADY_CREDITED_BY_DIFFERENT_PAYMENT';
    end if;

    topup_status := v_topup.status;
    movement_id := v_topup.credited_movement_id;
    resulting_balance := public.get_customer_credit_balance(v_topup.user_id);
    return next;
    return;
  end if;

  v_paid_amount := round(coalesce(p_paid_amount, 0)::numeric, 2);

  if v_topup.amount is null
     or v_topup.gross_amount is null
     or abs(v_paid_amount - v_topup.gross_amount) > 0.01 then
    raise exception 'PAYMENT_AMOUNT_MISMATCH';
  end if;

  select created.movement_id, created.resulting_balance
  into v_movement_id, v_resulting_balance
  from public.create_customer_credit_movement(
    p_user_id => v_topup.user_id,
    p_movement_type => 'credit',
    p_amount => v_topup.amount,
    p_description => 'Carga de saldo acreditada automáticamente por Mercado Pago',
    p_source_type => 'admin_adjustment',
    p_source_id => v_topup.id::text,
    p_created_by => null,
    p_metadata => jsonb_build_object(
      'created_from', 'mercadopago_webhook',
      'source_kind', 'balance_topup',
      'topup_id', v_topup.id,
      'mercadopago_payment_id', p_payment_id,
      'gross_amount', v_topup.gross_amount,
      'surcharge_percent', v_topup.surcharge_percent,
      'surcharge_amount', v_topup.surcharge_amount
    ),
    p_source_key => 'customer-credit-topup-mp:' || v_topup.id::text
  ) as created;

  update public.customer_credit_topups
  set
    status = 'acreditado',
    credited_movement_id = v_movement_id,
    mercadopago_payment_id = p_payment_id,
    mercadopago_status = p_payment_status,
    updated_at = now()
  where id = v_topup.id;

  topup_status := 'acreditado';
  movement_id := v_movement_id;
  resulting_balance := v_resulting_balance;
  return next;
end;
$$;


ALTER FUNCTION "public"."credit_customer_credit_topup_from_mercadopago"("p_topup_id" "uuid", "p_payment_id" "text", "p_payment_status" "text", "p_paid_amount" numeric) OWNER TO "postgres";

--
-- Name: current_user_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."current_user_role"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select rol
  from public.profiles
  where id = auth.uid();
$$;


ALTER FUNCTION "public"."current_user_role"() OWNER TO "postgres";

--
-- Name: customer_credit_movement_effect("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."customer_credit_movement_effect"("p_movement_type" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_movement_type in ('credit', 'reversal', 'adjustment') then 1
    when p_movement_type in ('debit', 'expiration') then -1
    else 0
  end;
$$;


ALTER FUNCTION "public"."customer_credit_movement_effect"("p_movement_type" "text") OWNER TO "postgres";

--
-- Name: deactivate_product_variants(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."deactivate_product_variants"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if old.activo is distinct from new.activo then
    update public.producto_variantes
    set activo = new.activo
    where producto_id = new.id
      and activo is distinct from new.activo;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."deactivate_product_variants"() OWNER TO "postgres";

