--
-- Name: product_cost_entries; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."product_cost_entries" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "product_id" bigint,
    "variant_id" bigint,
    "purchase_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "quantity" integer NOT NULL,
    "unit_cost" numeric(14,2) NOT NULL,
    "freight_cost" numeric(14,2) DEFAULT 0 NOT NULL,
    "tax_cost" numeric(14,2) DEFAULT 0 NOT NULL,
    "commission_cost" numeric(14,2) DEFAULT 0 NOT NULL,
    "other_cost" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_cost" numeric(14,2) GENERATED ALWAYS AS ((((((("quantity")::numeric * "unit_cost") + "freight_cost") + "tax_cost") + "commission_cost") + "other_cost")) STORED,
    "supplier" "text",
    "document_type" "text",
    "document_number" "text",
    "payment_method" "text",
    "notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "article_name" "text",
    "sku" "text",
    "received_quantity" integer DEFAULT 0 NOT NULL,
    "reception_status" "text" DEFAULT 'recibida'::"text" NOT NULL,
    "idempotency_key" "text",
    CONSTRAINT "product_cost_entries_article_required" CHECK ((("product_id" IS NOT NULL) OR (NULLIF("btrim"("article_name"), ''::"text") IS NOT NULL))),
    CONSTRAINT "product_cost_entries_commission_cost_check" CHECK (("commission_cost" >= (0)::numeric)),
    CONSTRAINT "product_cost_entries_freight_cost_check" CHECK (("freight_cost" >= (0)::numeric)),
    CONSTRAINT "product_cost_entries_other_cost_check" CHECK (("other_cost" >= (0)::numeric)),
    CONSTRAINT "product_cost_entries_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "product_cost_entries_received_quantity_check" CHECK ((("received_quantity" >= 0) AND ("received_quantity" <= "quantity"))),
    CONSTRAINT "product_cost_entries_reception_status_check" CHECK (("reception_status" = ANY (ARRAY['pendiente'::"text", 'parcial'::"text", 'recibida'::"text", 'anulada'::"text"]))),
    CONSTRAINT "product_cost_entries_tax_cost_check" CHECK (("tax_cost" >= (0)::numeric)),
    CONSTRAINT "product_cost_entries_unit_cost_check" CHECK (("unit_cost" >= (0)::numeric)),
    CONSTRAINT "product_cost_entries_variant_requires_product" CHECK ((("variant_id" IS NULL) OR ("product_id" IS NOT NULL)))
);


