--
-- Name: FUNCTION "force_delete_product_variant_super_admin"("p_variant_id" bigint, "p_actor_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."force_delete_product_variant_super_admin"("p_variant_id" bigint, "p_actor_id" "uuid") IS 'Elimina una variante ignorando stock/historial, desacoplando (SET NULL) el historial comercial (incluida Mercado Libre) en vez de borrarlo. Exclusivo SUPER_ADMIN.';


--
-- Name: force_delete_purchase_super_admin("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."force_delete_purchase_super_admin"("p_purchase_id" "uuid", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_role text;
  v_entry public.product_cost_entries%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para eliminar compras.';
  end if;

  select rol into v_actor_role
  from public.profiles
  where id = p_actor_id;

  if v_actor_role is distinct from 'super_admin' then
    raise exception 'Solamente un SUPER ADMIN puede forzar la eliminación de una compra.';
  end if;

  select * into v_entry
  from public.product_cost_entries entries
  where entries.id = p_purchase_id
  for update;

  if not found then
    raise exception 'La compra ya no existe.';
  end if;

  if v_entry.product_id is not null then
    perform pg_advisory_xact_lock(93000, v_entry.product_id::integer);
  end if;

  alter table public.product_cost_entries disable trigger audit_product_cost_entries;

  delete from public.product_cost_entries
  where id = p_purchase_id;

  alter table public.product_cost_entries enable trigger audit_product_cost_entries;

  if v_entry.product_id is not null then
    perform public.refresh_inventory_stock(v_entry.product_id);
  end if;

  insert into public.audit_logs (
    table_name, action, record_id, actor_user_id, before_data, after_data
  ) values (
    'product_cost_entries',
    'DELETE',
    p_purchase_id::text,
    p_actor_id,
    to_jsonb(v_entry),
    jsonb_build_object('reason', 'super_admin_force_delete_purchase')
  );
end;
$$;


ALTER FUNCTION "public"."force_delete_purchase_super_admin"("p_purchase_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "force_delete_purchase_super_admin"("p_purchase_id" "uuid", "p_actor_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."force_delete_purchase_super_admin"("p_purchase_id" "uuid", "p_actor_id" "uuid") IS 'Elimina definitivamente una compra (histórica o vigente) ignorando la protección de stock ya consumido, recalculando el stock derivado si seguía vinculada a un producto. Exclusivo SUPER_ADMIN. Audita a mano (desactiva el trigger genérico audit_product_cost_entries para no duplicar la fila de audit_logs).';


--
-- Name: freeze_external_sale_historical_cost(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."freeze_external_sale_historical_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.product_id is not null and new.costo_unitario_historico is null then
    new.costo_unitario_historico := public.compute_historical_unit_cost(
      new.product_id,
      new.variant_id,
      new.sale_date
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."freeze_external_sale_historical_cost"() OWNER TO "postgres";

--
-- Name: freeze_order_item_historical_cost_on_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."freeze_order_item_historical_cost_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.ordenes%rowtype;
begin
  if new.costo_unitario_historico is not null then
    return new;
  end if;

  select * into v_order from public.ordenes where id = new.orden_id;

  if v_order.id is not null
     and public.inventory_order_consumes_stock(v_order.estado, v_order.payment_status) then
    new.costo_unitario_historico := public.compute_historical_unit_cost(
      new.producto_id,
      new.variante_id,
      coalesce(v_order.paid_at, v_order.created_at)::date
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."freeze_order_item_historical_cost_on_insert"() OWNER TO "postgres";

--
-- Name: freeze_order_items_historical_cost(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."freeze_order_items_historical_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.inventory_order_consumes_stock(new.estado, new.payment_status) then
    return new;
  end if;

  update public.orden_items items
  set costo_unitario_historico = public.compute_historical_unit_cost(
    items.producto_id,
    items.variante_id,
    coalesce(new.paid_at, new.created_at)::date
  )
  where items.orden_id = new.id
    and items.costo_unitario_historico is null;

  return new;
end;
$$;


ALTER FUNCTION "public"."freeze_order_items_historical_cost"() OWNER TO "postgres";

--
-- Name: get_admin_category_product_stats(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."get_admin_category_product_stats"() RETURNS TABLE("category_id" bigint, "product_count" bigint, "stock_total" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    productos.categoria_id as category_id,
    count(*)::bigint as product_count,
    coalesce(sum(productos.stock), 0)::bigint as stock_total
  from public.productos
  where productos.categoria_id is not null
    and public.current_user_role() in ('operador', 'admin', 'super_admin')
  group by productos.categoria_id;
$$;


