--
-- Name: get_purchase_force_delete_impact("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."get_purchase_force_delete_impact"("p_purchase_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_entry public.product_cost_entries%rowtype;
  v_web_count bigint := 0;
  v_external_count bigint := 0;
  v_ml_count bigint := 0;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para consultar el impacto de esta compra.';
  end if;

  select * into v_entry
  from public.product_cost_entries entries
  where entries.id = p_purchase_id;

  if not found or v_entry.product_id is null then
    return jsonb_build_object('affected_sales_count', 0);
  end if;

  select count(*) into v_web_count
  from public.orden_items items
  join public.ordenes orders on orders.id = items.orden_id
  where items.producto_id = v_entry.product_id
    and (
      v_entry.variant_id is null
      or items.variante_id is not distinct from v_entry.variant_id
    )
    and orders.estado <> 'cancelado'
    and coalesce(orders.paid_at, orders.created_at) >= v_entry.purchase_date;

  select count(*) into v_external_count
  from public.external_sales sales
  where sales.product_id = v_entry.product_id
    and (
      v_entry.variant_id is null
      or sales.variant_id is not distinct from v_entry.variant_id
    )
    and sales.sale_date >= v_entry.purchase_date;

  select count(*) into v_ml_count
  from public.mercadolibre_sales sales
  where sales.product_id = v_entry.product_id
    and sales.sale_date >= v_entry.purchase_date;

  return jsonb_build_object(
    'affected_sales_count', v_web_count + v_external_count + v_ml_count,
    'web_count', v_web_count,
    'external_count', v_external_count,
    'mercadolibre_count', v_ml_count
  );
end;
$$;


ALTER FUNCTION "public"."get_purchase_force_delete_impact"("p_purchase_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "get_purchase_force_delete_impact"("p_purchase_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."get_purchase_force_delete_impact"("p_purchase_id" "uuid") IS 'Sólo lectura: cuenta ventas (web/externas/ML) del mismo producto/variante con fecha >= la fecha de la compra dada, como proxy de cuántas ventas posteriores pudieron usarla en su costo histórico. Usada para advertir antes de force_delete_purchase_super_admin.';


--
-- Name: guard_derived_inventory_stock(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."guard_derived_inventory_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.stock := 0;
    return new;
  end if;

  if new.stock is distinct from old.stock
     and coalesce(
       current_setting('beyonix.inventory_refresh', true),
       ''
     ) <> 'on' then
    raise exception
      'INVENTORY_STOCK_IS_DERIVED: registrá una compra, venta, devolución o salida.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_derived_inventory_stock"() OWNER TO "postgres";

--
-- Name: guard_inventory_return_variant_link(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."guard_inventory_return_variant_link"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.variant_id is distinct from old.variant_id
     and current_setting('beyonix.inventory_variant_link', true) is distinct from 'on' then
    raise exception 'INVENTORY_VARIANT_LINK_RPC_REQUIRED';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_inventory_return_variant_link"() OWNER TO "postgres";

--
-- Name: guard_product_variant_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."guard_product_variant_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(93000, old.producto_id::integer);

  if coalesce(old.stock, 0) <> 0
     or exists (
       select 1
       from public.inventory_variant_allocations allocations
       where allocations.variant_id = old.id
         and allocations.quantity > 0
     ) then
    raise exception
      'No se puede eliminar la variante % porque tiene unidades vinculadas. Reasigná primero el stock.',
      old.nombre;
  end if;
  if exists (
    select 1
    from public.inventory_movements movements
    where movements.variant_id = old.id
  ) then
    raise exception
      'No se puede eliminar la variante % porque tiene movimientos históricos. Desactivala para conservar la trazabilidad.',
      old.nombre;
  end if;

  return old;
end;
$$;


ALTER FUNCTION "public"."guard_product_variant_delete"() OWNER TO "postgres";

--
-- Name: FUNCTION "guard_product_variant_delete"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."guard_product_variant_delete"() IS 'Impide eliminar variantes con stock o trazabilidad asociada.';


--
-- Name: guard_profile_privilege_assignment(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."guard_profile_privilege_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_role text;
begin
  if auth.role() = 'service_role' or session_user in ('postgres', 'supabase_admin') and auth.uid() is null then return new; end if;
  if tg_op = 'INSERT' then
    if new.rol <> 'cliente' then raise exception 'PROFILE_ROLE_FORBIDDEN'; end if;
  elsif new.rol is distinct from old.rol then
    select rol into v_role from public.profiles where id=auth.uid();
    if coalesce(v_role,'') <> 'super_admin' and not (v_role='admin' and old.rol <> 'super_admin' and new.rol in ('cliente','operador','admin')) then
      raise exception 'PROFILE_ROLE_FORBIDDEN';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_profile_privilege_assignment"() OWNER TO "postgres";

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  insert into public.profiles (
    id,
    nombre,
    email,
    rol
  )
  values (
    new.id,
    coalesce(
      new.raw_user_meta_data->>'nombre',
      'Usuario'
    ),
    new.email,
    'cliente'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";

--
-- Name: handle_new_user_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."handle_new_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (
    id,
    email,
    username,
    nombre,
    telefono,
    direccion,
    calle,
    numero,
    piso,
    departamento,
    localidad,
    codigo_postal,
    provincia,
    referencias,
    rol
  )
  values (
    new.id,
    new.email,
    nullif(trim(new.raw_user_meta_data ->> 'username'), ''),
    coalesce(nullif(trim(new.raw_user_meta_data ->> 'nombre'), ''), 'Usuario'),
    nullif(trim(new.raw_user_meta_data ->> 'telefono'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'direccion'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'calle'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'numero'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'piso'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'departamento'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'localidad'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'codigo_postal'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'provincia'), ''),
    nullif(trim(new.raw_user_meta_data ->> 'referencias'), ''),
    'cliente'
  )
  on conflict (id) do update
  set
    email = excluded.email,
    username = excluded.username,
    nombre = excluded.nombre,
    telefono = excluded.telefono,
    direccion = excluded.direccion,
    calle = excluded.calle,
    numero = excluded.numero,
    piso = excluded.piso,
    departamento = excluded.departamento,
    localidad = excluded.localidad,
    codigo_postal = excluded.codigo_postal,
    provincia = excluded.provincia,
    referencias = excluded.referencias;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_user_profile"() OWNER TO "postgres";

--
-- Name: import_mercadolibre_sales_idempotent("jsonb", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."import_mercadolibre_sales_idempotent"("p_rows" "jsonb", "p_imported_by" "uuid", "p_source_file_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row jsonb;
  v_raw_data jsonb;
  v_final_raw_data jsonb;
  v_source_key text;
  v_fingerprint text;
  v_seen jsonb := '{}'::jsonb;
  v_existing public.mercadolibre_sales%rowtype;
  v_product_id bigint;
  v_variant_id bigint;
  v_unit_cost numeric(12, 2);
  v_sale_date timestamptz;
  v_operation_id text;
  v_order_id text;
  v_product_name text;
  v_sku text;
  v_quantity integer;
  v_gross_amount numeric(12, 2);
  v_fee_amount numeric(12, 2);
  v_shipping_amount numeric(12, 2);
  v_net_amount numeric(12, 2);
  v_file_name text;
  v_received integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_unchanged integer := 0;
  v_duplicate_rows integer := 0;
  v_touched_product_ids bigint[] := '{}'::bigint[];
begin
  if p_rows is null
     or jsonb_typeof(p_rows) <> 'array'
     or jsonb_array_length(p_rows) = 0 then
    raise exception 'No hay ventas válidas para importar.';
  end if;

  if jsonb_array_length(p_rows) > 500 then
    raise exception 'Cada bloque puede contener como máximo 500 ventas.';
  end if;

  -- Serializa importaciones concurrentes. La restricción única sigue siendo la
  -- última defensa, pero este bloqueo permite contar y comparar sin carreras.
  perform pg_advisory_xact_lock(hashtext('beyonix_mercadolibre_import'));

  for v_row in
    select value
    from jsonb_array_elements(p_rows)
  loop
    v_received := v_received + 1;
    v_raw_data := coalesce(v_row -> 'raw_data', '{}'::jsonb);
    if jsonb_typeof(v_raw_data) <> 'object' then
      raise exception 'La fila % contiene datos originales inválidos.', v_received;
    end if;

    v_sale_date := nullif(v_row ->> 'sale_date', '')::timestamptz;
    v_operation_id := nullif(btrim(v_row ->> 'operation_id'), '');
    v_order_id := nullif(btrim(v_row ->> 'order_id'), '');
    v_product_name := coalesce(
      nullif(btrim(v_row ->> 'product_name'), ''),
      'Venta Mercado Libre'
    );
    v_sku := nullif(btrim(v_row ->> 'sku'), '');
    v_quantity := greatest(coalesce((v_row ->> 'quantity')::integer, 1), 1);
    v_unit_cost := greatest(coalesce((v_row ->> 'unit_cost')::numeric, 0), 0);
    v_gross_amount := coalesce((v_row ->> 'gross_amount')::numeric, 0);
    v_fee_amount := nullif(v_row ->> 'fee_amount', '')::numeric;
    v_shipping_amount := nullif(v_row ->> 'shipping_amount', '')::numeric;
    v_net_amount := nullif(v_row ->> 'net_amount', '')::numeric;
    v_file_name := coalesce(
      nullif(btrim(v_row ->> 'source_file_name'), ''),
      nullif(btrim(p_source_file_name), '')
    );
    v_product_id := nullif(v_row ->> 'product_id', '')::bigint;
    v_variant_id := nullif(
      v_raw_data #>> '{beyonix_cost_mapping,variant_id}',
      ''
    )::bigint;

    if v_operation_id is null and v_order_id is null then
      raise exception
        'La fila % no tiene número de venta ni orden de compra.',
        v_received;
    end if;

    v_source_key := public.mercadolibre_sale_source_key(
      v_operation_id,
      v_order_id,
      v_product_name,
      v_sku,
      v_sale_date,
      v_raw_data
    );
    v_fingerprint := md5(
      (
        (v_row - 'source_file_name')
        || jsonb_build_object('raw_data', v_raw_data - 'source')
      )::text
    );

    if v_seen ? v_source_key then
      if v_seen ->> v_source_key is distinct from v_fingerprint then
        raise exception
          'El archivo contiene dos filas contradictorias para la identidad %.',
          v_source_key;
      end if;
      v_duplicate_rows := v_duplicate_rows + 1;
      continue;
    end if;
    v_seen := v_seen || jsonb_build_object(v_source_key, v_fingerprint);

    if v_product_id is not null then
      if not exists (
        select 1
        from public.productos products
        where products.id = v_product_id
      ) then
        raise exception
          'La fila % apunta a un producto inexistente.',
          v_received;
      end if;

      if v_variant_id is not null
         and not exists (
           select 1
           from public.producto_variantes variants
           where variants.id = v_variant_id
             and variants.producto_id = v_product_id
         ) then
        raise exception
          'La variante vinculada en la fila % no pertenece al producto.',
          v_received;
      end if;
    elsif v_variant_id is not null then
      raise exception
        'La fila % tiene una variante sin producto vinculado.',
        v_received;
    end if;

    if v_product_id is not null
       and array_position(v_touched_product_ids, v_product_id) is null then
      v_touched_product_ids := array_append(
        v_touched_product_ids,
        v_product_id
      );
    end if;

    select *
    into v_existing
    from public.mercadolibre_sales sales
    where sales.source_key = v_source_key
    for update;

    if not found then
      insert into public.mercadolibre_sales (
        source_key,
        sale_date,
        operation_id,
        order_id,
        product_id,
        product_name,
        sku,
        quantity,
        unit_cost,
        gross_amount,
        fee_amount,
        shipping_amount,
        net_amount,
        source_file_name,
        imported_by,
        raw_data
      )
      values (
        v_source_key,
        v_sale_date,
        v_operation_id,
        v_order_id,
        v_product_id,
        v_product_name,
        v_sku,
        v_quantity,
        v_unit_cost,
        v_gross_amount,
        v_fee_amount,
        v_shipping_amount,
        v_net_amount,
        v_file_name,
        p_imported_by,
        v_raw_data
      );
      v_inserted := v_inserted + 1;
      continue;
    end if;

    if v_existing.product_id is not null
       and array_position(
         v_touched_product_ids,
         v_existing.product_id
       ) is null then
      v_touched_product_ids := array_append(
        v_touched_product_ids,
        v_existing.product_id
      );
    end if;

    -- Una revisión física depende del UUID de esta fila. Nunca se reemplaza ni
    -- se elimina la venta; sólo se actualiza el mismo registro.
    if exists (
      select 1
      from public.inventory_return_movements movements
      where movements.mercadolibre_sale_id = v_existing.id
        and movements.received_quantity > v_quantity
    ) then
      raise exception
        'La venta % no puede reducirse por debajo de las unidades ya recibidas en devolución.',
        coalesce(v_operation_id, v_existing.operation_id);
    end if;

    if v_existing.raw_data ? 'beyonix_cost_mapping' then
      v_final_raw_data := v_raw_data || jsonb_build_object(
        'beyonix_cost_mapping',
        v_existing.raw_data -> 'beyonix_cost_mapping'
      );
      v_product_id := v_existing.product_id;
      v_unit_cost := v_existing.unit_cost;
    else
      v_final_raw_data := v_raw_data;
      v_product_id := coalesce(v_product_id, v_existing.product_id);
      if v_product_id = v_existing.product_id and v_unit_cost = 0 then
        v_unit_cost := v_existing.unit_cost;
      end if;
    end if;

    -- Un reporte histórico cargado después de uno más completo no puede
    -- retroceder una cancelación, devolución o entrega ya observada.
    if public.mercadolibre_sale_evidence_score(v_final_raw_data)
       < public.mercadolibre_sale_evidence_score(v_existing.raw_data) then
      v_unchanged := v_unchanged + 1;
      continue;
    end if;

    if row(
      v_existing.sale_date,
      v_existing.operation_id,
      v_existing.order_id,
      v_existing.product_id,
      v_existing.product_name,
      v_existing.sku,
      v_existing.quantity,
      v_existing.unit_cost,
      v_existing.gross_amount,
      v_existing.fee_amount,
      v_existing.shipping_amount,
      v_existing.net_amount,
      v_existing.raw_data - 'source'
    ) is not distinct from row(
      v_sale_date,
      v_operation_id,
      v_order_id,
      v_product_id,
      v_product_name,
      v_sku,
      v_quantity,
      v_unit_cost,
      v_gross_amount,
      v_fee_amount,
      v_shipping_amount,
      v_net_amount,
      v_final_raw_data - 'source'
    ) then
      v_unchanged := v_unchanged + 1;
      continue;
    end if;

    update public.mercadolibre_sales
    set
      sale_date = v_sale_date,
      operation_id = v_operation_id,
      order_id = v_order_id,
      product_id = v_product_id,
      product_name = v_product_name,
      sku = v_sku,
      quantity = v_quantity,
      unit_cost = v_unit_cost,
      gross_amount = v_gross_amount,
      fee_amount = v_fee_amount,
      shipping_amount = v_shipping_amount,
      net_amount = v_net_amount,
      source_file_name = v_file_name,
      imported_by = p_imported_by,
      imported_at = now(),
      raw_data = v_final_raw_data
    where id = v_existing.id;

    v_updated := v_updated + 1;
  end loop;

  if exists (
    select 1
    from public.productos products
    where products.id = any(v_touched_product_ids)
      and products.stock < 0
  ) or exists (
    select 1
    from public.producto_variantes variants
    where variants.producto_id = any(v_touched_product_ids)
      and variants.stock < 0
  ) then
    raise exception
      'STOCK_INSUFICIENTE: la importación dejaría stock negativo.';
  end if;

  if v_inserted > 0 or v_updated > 0 then
    insert into public.audit_logs (
      table_name,
      action,
      record_id,
      actor_user_id,
      after_data
    ) values (
      'mercadolibre_sales',
      case when v_inserted > 0 then 'INSERT' else 'UPDATE' end,
      'import:' || txid_current()::text,
      p_imported_by,
      jsonb_build_object(
        'source_file_name', p_source_file_name,
        'received', v_received,
        'inserted', v_inserted,
        'updated', v_updated,
        'unchanged', v_unchanged,
        'duplicate_rows', v_duplicate_rows
      )
    );
  end if;

  return jsonb_build_object(
    'received', v_received,
    'inserted', v_inserted,
    'updated', v_updated,
    'unchanged', v_unchanged,
    'duplicate_rows', v_duplicate_rows
  );
end;
$$;


ALTER FUNCTION "public"."import_mercadolibre_sales_idempotent"("p_rows" "jsonb", "p_imported_by" "uuid", "p_source_file_name" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "import_mercadolibre_sales_idempotent"("p_rows" "jsonb", "p_imported_by" "uuid", "p_source_file_name" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."import_mercadolibre_sales_idempotent"("p_rows" "jsonb", "p_imported_by" "uuid", "p_source_file_name" "text") IS 'Importa ventas ML sin duplicar filas ni reemplazar UUID; conserva vinculaciones y devoluciones.';


--
-- Name: inventory_ml_stock_units(integer, "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."inventory_ml_stock_units"("p_quantity" integer, "p_raw_data" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_quantity integer := greatest(coalesce(p_quantity, 0), 0);
  v_status text := lower(coalesce(
    p_raw_data -> 'parsed' ->> 'status',
    ''
  ));
begin
  if v_status like '%cancel%'
     or v_status like '%anulad%' then
    return 0;
  end if;

  return v_quantity;
end;
$$;


ALTER FUNCTION "public"."inventory_ml_stock_units"("p_quantity" integer, "p_raw_data" "jsonb") OWNER TO "postgres";

--
-- Name: FUNCTION "inventory_ml_stock_units"("p_quantity" integer, "p_raw_data" "jsonb"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."inventory_ml_stock_units"("p_quantity" integer, "p_raw_data" "jsonb") IS 'Calcula unidades vendidas en Mercado Libre excluyendo sólo cancelaciones; las devoluciones requieren reingreso aprobado.';


--
-- Name: inventory_ml_variant_id("jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."inventory_ml_variant_id"("p_raw_data" "jsonb") RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
  select case
    when coalesce(
      p_raw_data #>> '{beyonix_cost_mapping,variant_id}',
      ''
    ) ~ '^[1-9][0-9]*$'
      then (p_raw_data #>> '{beyonix_cost_mapping,variant_id}')::bigint
    else null
  end;
$_$;


ALTER FUNCTION "public"."inventory_ml_variant_id"("p_raw_data" "jsonb") OWNER TO "postgres";

--
-- Name: inventory_order_consumes_stock("text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."inventory_order_consumes_stock"("p_status" "text", "p_payment_status" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  select
    coalesce(p_status, '') in (
      'pagado',
      'preparado',
      'enviado',
      'en_camino',
      'visita_fallida',
      'en_sucursal',
      'retiro_pendiente',
      'retiro_vencido',
      'en_devolucion',
      'devuelto_beyonix',
      'entregado',
      'approved'
    )
    or (
      coalesce(p_status, '') <> 'cancelado'
      and coalesce(p_payment_status, '') in (
        'confirmado',
        'confirmed',
        'approved'
      )
    );
$$;


ALTER FUNCTION "public"."inventory_order_consumes_stock"("p_status" "text", "p_payment_status" "text") OWNER TO "postgres";

--
-- Name: is_client_registration_blocked("text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."is_client_registration_blocked"("email_input" "text" DEFAULT NULL::"text", "username_input" "text" DEFAULT NULL::"text", "phone_input" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.blocked_client_identifiers blocked
    where (
        blocked.identifier_type = 'email'
        and blocked.identifier_value = public.normalize_block_identifier('email', email_input)
      )
      or (
        blocked.identifier_type = 'username'
        and blocked.identifier_value = public.normalize_block_identifier('username', username_input)
      )
      or (
        blocked.identifier_type = 'phone'
        and blocked.identifier_value = public.normalize_block_identifier('phone', phone_input)
      )
  )
$$;


ALTER FUNCTION "public"."is_client_registration_blocked"("email_input" "text", "username_input" "text", "phone_input" "text") OWNER TO "postgres";

