--
-- Name: inventory_return_movements; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."inventory_return_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_key" "text" NOT NULL,
    "order_id" bigint,
    "order_item_id" bigint,
    "product_id" bigint,
    "variant_id" bigint,
    "quantity" integer NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "mercadolibre_sale_id" "uuid",
    "received_quantity" integer DEFAULT 0 NOT NULL,
    "sellable_quantity" integer DEFAULT 0 NOT NULL,
    "discounted_quantity" integer DEFAULT 0 NOT NULL,
    "non_sellable_quantity" integer DEFAULT 0 NOT NULL,
    "discount_percent" numeric(5,2),
    "review_notes" "text",
    "discount_reason" "text",
    "non_sellable_reason" "text",
    "conditioned_active" boolean DEFAULT false NOT NULL,
    "conditioned_name" "text",
    "conditioned_sku" "text",
    "conditioned_color_hex" "text",
    "conditioned_images" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "inventory_return_conditioned_color_check" CHECK ((("conditioned_color_hex" IS NULL) OR ("conditioned_color_hex" ~ '^#[0-9A-Fa-f]{6}$'::"text"))),
    CONSTRAINT "inventory_return_conditioned_identity_check" CHECK ((("discounted_quantity" <= 0) OR (NOT "conditioned_active") OR ((NULLIF("btrim"("conditioned_name"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("conditioned_sku"), ''::"text") IS NOT NULL) AND ("conditioned_color_hex" ~ '^#[0-9A-Fa-f]{6}$'::"text")))),
    CONSTRAINT "inventory_return_conditioned_images_check" CHECK (("jsonb_typeof"("conditioned_images") = 'array'::"text")),
    CONSTRAINT "inventory_return_movements_condition_check" CHECK ((("received_quantity" >= 0) AND ("sellable_quantity" >= 0) AND ("discounted_quantity" >= 0) AND ("non_sellable_quantity" >= 0) AND ((("sellable_quantity" + "discounted_quantity") + "non_sellable_quantity") <= "received_quantity") AND ("quantity" = "sellable_quantity") AND ((("discounted_quantity" = 0) AND ("discount_percent" IS NULL)) OR (("discounted_quantity" > 0) AND ("discount_percent" > (0)::numeric) AND ("discount_percent" < (100)::numeric))))),
    CONSTRAINT "inventory_return_movements_conditioned_active_check" CHECK ((("discounted_quantity" > 0) OR ("conditioned_active" = false))),
    CONSTRAINT "inventory_return_movements_quantity_check" CHECK (("quantity" >= 0)),
    CONSTRAINT "inventory_return_movements_source_check" CHECK (((("order_id" IS NOT NULL) AND ("order_item_id" IS NOT NULL) AND ("mercadolibre_sale_id" IS NULL)) OR (("order_id" IS NULL) AND ("order_item_id" IS NULL) AND ("mercadolibre_sale_id" IS NOT NULL))))
);


