--
-- Name: link_conditioned_stock_variant_idempotent("uuid", bigint, "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."link_conditioned_stock_variant_idempotent"("p_return_id" "uuid", "p_variant_id" bigint, "p_actor_id" "uuid", "p_idempotency_key" "text", "p_document_reference" "text") RETURNS "public"."inventory_return_movements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_return public.inventory_return_movements%rowtype;
  v_allocation public.inventory_variant_allocations%rowtype;
  v_generic_after bigint;
  v_total_allocated bigint;
  v_overflow bigint;
  v_reduction bigint;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_reference text := nullif(btrim(coalesce(p_document_reference, '')), '');
begin
  if p_return_id is null or p_variant_id is null or p_variant_id <= 0
     or v_key is null or length(v_key) < 8 or length(v_key) > 240
     or v_reference is null then
    raise exception 'Los datos de vinculación no son válidos.';
  end if;

  perform pg_advisory_xact_lock(hashtext('inventory-return-link'), hashtext(v_key));

  select * into v_return
  from public.inventory_return_movements movements
  where movements.id = p_return_id
  for update;
  if not found then raise exception 'La devolución ya no existe.'; end if;

  perform pg_advisory_xact_lock(93000, v_return.product_id::integer);

  if not exists (
    select 1 from public.producto_variantes variants
    where variants.id = p_variant_id
      and variants.producto_id = v_return.product_id
  ) then
    raise exception 'La variante no pertenece al producto.';
  end if;

  if exists (
    select 1 from public.inventory_operation_log operations
    where operations.idempotency_key = v_key
  ) then
    if v_return.variant_id is distinct from p_variant_id then
      raise exception 'IDEMPOTENCY_KEY_CONFLICT';
    end if;
    return v_return;
  end if;

  if v_return.variant_id is not null
     and v_return.variant_id is distinct from p_variant_id then
    raise exception 'La devolución ya está vinculada a otra variante.';
  end if;

  if v_return.variant_id is null then
    perform set_config('beyonix.inventory_variant_link', 'on', true);
    update public.inventory_return_movements movements
    set variant_id = p_variant_id
    where movements.id = v_return.id
    returning * into v_return;

    select coalesce(sum(movements.quantity_delta), 0)::bigint
    into v_generic_after
    from public.inventory_movements movements
    where movements.product_id = v_return.product_id
      and movements.variant_id is null
      and movements.movement_date <= current_date;

    select coalesce(sum(allocations.quantity), 0)::bigint
    into v_total_allocated
    from public.inventory_variant_allocations allocations
    where allocations.product_id = v_return.product_id;

    v_overflow := greatest(v_total_allocated - greatest(v_generic_after, 0), 0);

    select * into v_allocation
    from public.inventory_variant_allocations allocations
    where allocations.product_id = v_return.product_id
      and allocations.variant_id = p_variant_id
    for update;

    v_reduction := least(
      v_return.sellable_quantity,
      v_overflow,
      coalesce(v_allocation.quantity, 0)
    );

    if v_reduction > 0 then
      update public.inventory_variant_allocations allocations
      set quantity = quantity - v_reduction,
          updated_by = p_actor_id,
          updated_at = now()
      where allocations.product_id = v_return.product_id
        and allocations.variant_id = p_variant_id;
    end if;
  else
    v_reduction := 0;
  end if;

  perform public.refresh_inventory_stock(v_return.product_id);

  insert into public.inventory_operation_log (
    product_id, variant_id, movement_type, quantity, origin, effective_at,
    actor_user_id, actor_process, idempotency_key, source_table, source_id,
    document_reference, metadata
  ) values (
    v_return.product_id,
    p_variant_id,
    'reclassification',
    greatest(v_return.received_quantity, 1),
    'conditioned_stock_variant_link',
    coalesce(v_return.occurred_at, v_return.approved_at, v_return.created_at),
    p_actor_id,
    'link_conditioned_stock_variant_idempotent',
    v_key,
    'inventory_return_movements',
    v_return.id::text,
    v_reference,
    jsonb_build_object(
      'physicalDelta', 0,
      'sellableQuantity', v_return.sellable_quantity,
      'discountedQuantity', v_return.discounted_quantity,
      'allocationReduction', coalesce(v_reduction, 0)
    )
  ) on conflict (idempotency_key) do nothing;

  insert into public.audit_logs (
    table_name, action, record_id, actor_user_id, before_data, after_data
  ) values (
    'inventory_variant_allocations',
    'UPDATE',
    v_return.product_id::text || ':' || p_variant_id::text,
    p_actor_id,
    jsonb_build_object('quantity', coalesce(v_allocation.quantity, 0)),
    jsonb_build_object(
      'quantity', greatest(coalesce(v_allocation.quantity, 0) - coalesce(v_reduction, 0), 0),
      'reason', 'conditioned_return_variant_link',
      'returnId', v_return.id
    )
  );

  return v_return;
end;
$$;


ALTER FUNCTION "public"."link_conditioned_stock_variant_idempotent"("p_return_id" "uuid", "p_variant_id" bigint, "p_actor_id" "uuid", "p_idempotency_key" "text", "p_document_reference" "text") OWNER TO "postgres";

--
-- Name: link_cost_entry_to_shared_catalog(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."link_cost_entry_to_shared_catalog"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_registry_product_id bigint;
  v_registry_variant_id bigint;
begin
  if new.product_id is null and nullif(btrim(new.article_name), '') is not null then
    if public.normalized_catalog_sku(new.sku) is not null then
      select
        coalesce(registry.product_id, variants.producto_id),
        registry.variant_id
      into v_registry_product_id, v_registry_variant_id
      from public.catalog_sku_registry registry
      left join public.producto_variantes variants
        on variants.id = registry.variant_id
      where registry.normalized_sku = public.normalized_catalog_sku(new.sku);
    end if;

    if v_registry_product_id is not null then
      new.product_id := v_registry_product_id;
      new.variant_id := v_registry_variant_id;
    else
      new.product_id := public.ensure_cost_catalog_product(
        new.article_name,
        new.sku
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."link_cost_entry_to_shared_catalog"() OWNER TO "postgres";

--
-- Name: lock_inventory_sale_targets(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."lock_inventory_sale_targets"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_id bigint;
begin
  for v_product_id in
    select distinct targets.product_id
    from unnest(array[
      case when tg_op <> 'INSERT' then old.product_id else null end,
      case when tg_op <> 'DELETE' then new.product_id else null end
    ]) targets(product_id)
    where targets.product_id is not null
    order by targets.product_id
  loop
    perform pg_advisory_xact_lock(93000, v_product_id::integer);
  end loop;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."lock_inventory_sale_targets"() OWNER TO "postgres";

--
-- Name: mercadolibre_sale_evidence_score("jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."mercadolibre_sale_evidence_score"("p_raw_data" "jsonb") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select
    public.mercadolibre_sale_lifecycle_rank(p_raw_data) * 100
    + case
        when coalesce(
          nullif(p_raw_data #>> '{parsed,return_units}', '')::numeric,
          0
        ) > 0 then 20 else 0
      end
    + case
        when coalesce(p_raw_data #>> '{parsed,return_delivered_date}', '') <> ''
          then 8 else 0
      end
    + case
        when coalesce(p_raw_data #>> '{parsed,return_review_date}', '') <> ''
          then 8 else 0
      end
    + case
        when coalesce(p_raw_data #>> '{parsed,return_result}', '') <> ''
          then 4 else 0
      end
    + case
        when coalesce(p_raw_data #>> '{parsed,return_destination}', '') <> ''
          then 4 else 0
      end
    + case
        when coalesce(p_raw_data #>> '{parsed,return_result_reason}', '') <> ''
          then 4 else 0
      end
    + case
        when coalesce(
          nullif(p_raw_data #>> '{parsed,claim_units}', '')::numeric,
          0
        ) > 0 then 4 else 0
      end;
$$;


ALTER FUNCTION "public"."mercadolibre_sale_evidence_score"("p_raw_data" "jsonb") OWNER TO "postgres";

--
-- Name: mercadolibre_sale_lifecycle_rank("jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."mercadolibre_sale_lifecycle_rank"("p_raw_data" "jsonb") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  with fields as (
    select
      lower(coalesce(p_raw_data #>> '{parsed,status}', '')) as status,
      coalesce(
        nullif(p_raw_data #>> '{parsed,return_units}', '')::numeric,
        0
      ) as return_units,
      coalesce(
        nullif(p_raw_data #>> '{parsed,cancellations_refunds}', '')::numeric,
        0
      ) as cancellations_refunds
  )
  select case
    when status like '%cancel%'
      or status like '%anulad%'
      then 500
    when return_units > 0
      or cancellations_refunds <> 0
      or status like '%devol%'
      or status like '%reembols%'
      then 400
    when status like '%entreg%'
      or status like '%finaliz%'
      or status like '%complet%'
      then 300
    when status like '%tránsito%'
      or status like '%transito%'
      or status like '%enviad%'
      or status like '%despach%'
      then 200
    when status like '%pag%'
      or status like '%confirm%'
      or status like '%aprobad%'
      then 100
    else 0
  end
  from fields;
$$;


ALTER FUNCTION "public"."mercadolibre_sale_lifecycle_rank"("p_raw_data" "jsonb") OWNER TO "postgres";

--
-- Name: mercadolibre_sale_source_key("text", "text", "text", "text", timestamp with time zone, "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."mercadolibre_sale_source_key"("p_operation_id" "text", "p_order_id" "text", "p_product_name" "text", "p_sku" "text", "p_sale_date" timestamp with time zone, "p_raw_data" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  with normalized as (
    select
      lower(btrim(coalesce(p_operation_id, ''))) as operation_id,
      lower(btrim(coalesce(p_order_id, ''))) as order_id,
      lower(btrim(coalesce(p_product_name, ''))) as product_name,
      lower(btrim(coalesce(p_sku, ''))) as sku,
      lower(btrim(coalesce(p_raw_data #>> '{parsed,listing_id}', ''))) as listing_id,
      lower(btrim(coalesce(p_raw_data #>> '{parsed,variant}', ''))) as variant_name
  )
  select
    'ml:v1:' || md5(
      case
        when operation_id <> '' then concat_ws(
          chr(31),
          'operation',
          operation_id,
          case
            when listing_id <> '' then 'listing'
            when sku <> '' then 'sku'
            else 'product'
          end,
          case
            when listing_id <> '' then listing_id
            when sku <> '' then sku
            else product_name
          end,
          'variant',
          variant_name
        )
        else concat_ws(
          chr(31),
          'order',
          order_id,
          'sale_date',
          coalesce(extract(epoch from p_sale_date)::text, ''),
          case
            when listing_id <> '' then 'listing'
            when sku <> '' then 'sku'
            else 'product'
          end,
          case
            when listing_id <> '' then listing_id
            when sku <> '' then sku
            else product_name
          end,
          'variant',
          variant_name
        )
      end
    )
  from normalized;
$$;


ALTER FUNCTION "public"."mercadolibre_sale_source_key"("p_operation_id" "text", "p_order_id" "text", "p_product_name" "text", "p_sku" "text", "p_sale_date" timestamp with time zone, "p_raw_data" "jsonb") OWNER TO "postgres";

--
-- Name: merge_catalog_products(bigint, bigint, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."merge_catalog_products"("p_keep_product_id" bigint, "p_absorb_product_id" bigint, "p_actor_id" "uuid") RETURNS "public"."productos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_keep public.productos%rowtype;
  v_absorb public.productos%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para fusionar productos.';
  end if;
  if p_keep_product_id is null or p_absorb_product_id is null then
    raise exception 'Los productos a fusionar no son válidos.';
  end if;
  if p_keep_product_id = p_absorb_product_id then
    raise exception 'No podés fusionar un producto consigo mismo.';
  end if;

  perform pg_advisory_xact_lock(
    93000, least(p_keep_product_id, p_absorb_product_id)::integer
  );
  perform pg_advisory_xact_lock(
    93000, greatest(p_keep_product_id, p_absorb_product_id)::integer
  );

  select * into v_keep
  from public.productos
  where id = p_keep_product_id
  for update;
  if not found then
    raise exception 'El producto que querés conservar ya no existe.';
  end if;

  select * into v_absorb
  from public.productos
  where id = p_absorb_product_id
  for update;
  if not found then
    raise exception 'El producto que querés fusionar ya no existe.';
  end if;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);

  alter table public.product_cost_entries disable trigger link_cost_entry_to_shared_catalog;
  alter table public.product_cost_entries disable trigger sync_cost_catalog_product_sku;
  alter table public.product_cost_entries disable trigger refresh_inventory_after_purchase;
  alter table public.business_expenses disable trigger refresh_inventory_after_expense;
  alter table public.external_sales disable trigger lock_inventory_external_sale;
  alter table public.external_sales disable trigger refresh_inventory_after_external_sale;
  alter table public.external_sales disable trigger zz_reject_negative_external_sale;
  alter table public.mercadolibre_sales disable trigger lock_inventory_mercadolibre_sale;
  alter table public.mercadolibre_sales disable trigger refresh_inventory_after_mercadolibre_sale;
  alter table public.mercadolibre_sales disable trigger zz_reject_negative_mercadolibre_sale;
  alter table public.inventory_return_movements disable trigger refresh_inventory_after_return_movement;
  alter table public.inventory_return_movements disable trigger validate_inventory_return_condition;
  alter table public.inventory_return_movements disable trigger guard_inventory_return_variant_link;

  -- Mueve las variantes primero: si el producto a conservar ya tiene una
  -- variante con el mismo nombre (color) o color_hex, el guard
  -- prevent_duplicate_product_variant_identity corta acá con un mensaje claro.
  update public.producto_variantes
  set producto_id = p_keep_product_id
  where producto_id = p_absorb_product_id;

  update public.product_cost_entries
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.business_expenses
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.external_sales
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.mercadolibre_sales
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.inventory_return_movements
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.inventory_variant_allocations
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.stock_reservations
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;

  update public.orden_items
  set producto_id = p_keep_product_id
  where producto_id = p_absorb_product_id;

  alter table public.product_cost_entries enable trigger link_cost_entry_to_shared_catalog;
  alter table public.product_cost_entries enable trigger sync_cost_catalog_product_sku;
  alter table public.product_cost_entries enable trigger refresh_inventory_after_purchase;
  alter table public.business_expenses enable trigger refresh_inventory_after_expense;
  alter table public.external_sales enable trigger lock_inventory_external_sale;
  alter table public.external_sales enable trigger refresh_inventory_after_external_sale;
  alter table public.external_sales enable trigger zz_reject_negative_external_sale;
  alter table public.mercadolibre_sales enable trigger lock_inventory_mercadolibre_sale;
  alter table public.mercadolibre_sales enable trigger refresh_inventory_after_mercadolibre_sale;
  alter table public.mercadolibre_sales enable trigger zz_reject_negative_mercadolibre_sale;
  alter table public.inventory_return_movements enable trigger refresh_inventory_after_return_movement;
  alter table public.inventory_return_movements enable trigger guard_inventory_return_variant_link;
  alter table public.inventory_return_movements enable trigger validate_inventory_return_condition;

  alter table public.inventory_operation_log disable trigger prevent_inventory_operation_log_mutation;
  update public.inventory_operation_log
  set product_id = p_keep_product_id
  where product_id = p_absorb_product_id;
  alter table public.inventory_operation_log enable trigger prevent_inventory_operation_log_mutation;

  -- El SKU/código de barra a nivel producto solo tiene sentido cuando el
  -- producto no tiene variantes propias (ver 102_variant_only_skus.sql); si
  -- el que se conserva ahora tiene variantes, esos campos pasan a vivir
  -- únicamente en cada variante.
  if exists (
    select 1 from public.producto_variantes where producto_id = p_keep_product_id
  ) then
    update public.productos
    set sku = null,
        codigo_barra = null
    where id = p_keep_product_id;
  end if;

  perform public.refresh_inventory_stock(p_keep_product_id);

  delete from public.productos where id = p_absorb_product_id;

  insert into public.audit_logs (
    table_name, action, record_id, actor_user_id, before_data, after_data
  ) values (
    'productos',
    'UPDATE',
    p_keep_product_id::text,
    p_actor_id,
    jsonb_build_object(
      'absorbedProductId', p_absorb_product_id,
      'absorbedName', v_absorb.nombre
    ),
    jsonb_build_object('reason', 'merge_catalog_products')
  );

  select * into v_keep from public.productos where id = p_keep_product_id;
  return v_keep;
end;
$$;


ALTER FUNCTION "public"."merge_catalog_products"("p_keep_product_id" bigint, "p_absorb_product_id" bigint, "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "merge_catalog_products"("p_keep_product_id" bigint, "p_absorb_product_id" bigint, "p_actor_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."merge_catalog_products"("p_keep_product_id" bigint, "p_absorb_product_id" bigint, "p_actor_id" "uuid") IS 'Fusiona dos productos: mueve variantes e historial comercial (compras, gastos, ventas externas/ML, devoluciones, reservas, pedidos) del absorbido al conservado, y elimina el absorbido. Rechaza la fusión si hay variantes con el mismo nombre o color en ambos productos.';


--
-- Name: mutate_admin_order_claim(bigint, "uuid", timestamp with time zone, "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."mutate_admin_order_claim"("p_claim_id" bigint, "p_actor_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_patch" "jsonb") RETURNS "public"."order_claims"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.order_claims%rowtype;
  v_order public.ordenes%rowtype;
  v_role text;
  v_status text;
  v_resolution text;
  v_action text:=coalesce(p_patch->>'action','update');
  v_message text:=btrim(coalesce(p_patch->>'admin_response',''));
  v_before text;
  v_items jsonb;
  v_item jsonb;
  v_allowed text[];
begin
  if auth.role() is distinct from 'service_role' then raise exception 'CLAIM_FORBIDDEN'; end if;
  select rol into v_role from public.profiles where id=p_actor_id;
  if coalesce(v_role,'') not in ('operador','admin','super_admin') then raise exception 'CLAIM_FORBIDDEN'; end if;
  select * into v_order from public.ordenes where id=(select order_id from public.order_claims where id=p_claim_id) for update;
  select * into v_claim from public.order_claims where id=p_claim_id for update;
  if not found then raise exception 'CLAIM_NOT_FOUND'; end if;
  if p_expected_updated_at is null or v_claim.updated_at<>p_expected_updated_at then raise exception 'CLAIM_CONFLICT'; end if;
  if v_claim.status in ('cerrado','rechazado') then raise exception 'CLAIM_TERMINAL'; end if;
  if length(v_message)>2000 then raise exception 'CLAIM_INVALID'; end if;
  v_before:=v_claim.status;
  v_status:=coalesce(p_patch->>'status',v_claim.status);
  v_resolution:=coalesce(p_patch->>'resolution',v_claim.resolution);
  if exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and status in ('processing','authorized')) and
    (v_resolution is distinct from v_claim.resolution or v_status='rechazado') then raise exception 'CLAIM_RESOLUTION_LOCKED'; end if;
  if v_status='cerrado' and exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and
    (status='processing' or status='authorized' and settlement_status is distinct from 'completado')) then raise exception 'CLAIM_CREDIT_PENDING'; end if;
  -- Las consultas y cancelaciones conservan su circuito propio.
  if v_claim.failure_type='consulta_pedido' and
    (v_action<>'update' or v_status not in ('recibido','en_revision','falta_informacion','cerrado','rechazado') or coalesce(v_resolution,'otro') not in ('otro','rechazado')) then raise exception 'CLAIM_INVALID'; end if;
  if v_claim.failure_type='cancelar_compra' and v_action='update' and
    (v_status is distinct from v_claim.status and v_status not in ('en_revision','falta_informacion') or v_resolution is distinct from v_claim.resolution) then raise exception 'CLAIM_CANCELLATION_ACTION'; end if;
  if v_action='affected_items' then
    if v_role='operador' then raise exception 'CLAIM_FORBIDDEN'; end if;
    if coalesce(v_claim.failure_type,'') in ('consulta_pedido','cancelar_compra') then raise exception 'CLAIM_INVALID'; end if;
    v_items:=p_patch->'items';
    if jsonb_typeof(v_items) is distinct from 'array' or jsonb_array_length(v_items)=0 or (select count(distinct x->>'order_item_id') from jsonb_array_elements(v_items) x)<>jsonb_array_length(v_items) then raise exception 'CLAIM_INVALID_ITEMS'; end if;
    perform id from public.orden_items where orden_id=v_order.id order by id for update;
    if exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and status in ('processing','authorized')) then raise exception 'CLAIM_ITEMS_LOCKED'; end if;
    for v_item in select * from jsonb_array_elements(v_items) loop
      if not exists(select 1 from public.orden_items where id=(v_item->>'order_item_id')::bigint and orden_id=v_order.id and (v_item->>'quantity')::integer between 1 and cantidad) then raise exception 'CLAIM_INVALID_ITEMS'; end if;
    end loop;
    if exists(select 1 from public.orden_items i where i.orden_id=v_order.id and i.return_inventory_processed_at is not null and
      (select x->>'quantity' from jsonb_array_elements(v_claim.affected_items) x where (x->>'order_item_id')::bigint=i.id) is distinct from
      (select x->>'quantity' from jsonb_array_elements(v_items) x where (x->>'order_item_id')::bigint=i.id)) then raise exception 'CLAIM_ITEMS_LOCKED'; end if;
    update public.order_claims set affected_items=v_items,affected_items_updated_at=now(),affected_items_updated_by=p_actor_id where id=v_claim.id;
  else
    if v_action='approve_cancellation' then
      if v_role='operador' then raise exception 'CLAIM_FORBIDDEN'; end if;
      perform public.approve_order_claim_cancellation(v_claim.id,p_actor_id,v_role,v_message);
      v_status:='cerrado'; v_resolution:='otro'; v_message:='';
    elsif v_action='reject_cancellation' then
      if v_claim.failure_type is distinct from 'cancelar_compra' or length(v_message)<5 then raise exception 'CLAIM_INVALID'; end if;
      v_status:='rechazado'; v_resolution:='rechazado';
    elsif v_action='mark_credit_note_issued' then
      if v_role='operador' then raise exception 'CLAIM_FORBIDDEN'; end if;
      if coalesce(v_claim.resolution,'') not in ('cupon_descuento','saldo_a_favor') or not exists(
        select 1 from public.order_credit_notes n join public.customer_credit_movements m on m.order_id=n.order_id and m.claim_id=n.claim_id
        where n.claim_id=v_claim.id and n.status='authorized' and n.destination='customer_balance' and n.cae is not null and n.settlement_status='completado' and m.source_type='credit_note' and m.movement_type='credit'
      ) or exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and (status='processing' or status='authorized' and settlement_status is distinct from 'completado')) then raise exception 'CLAIM_CREDIT_PENDING'; end if;
      v_status:='cerrado'; v_resolution:=v_claim.resolution;
      v_message:='La nota de crédito fue autorizada y el saldo ya está acreditado en tu cuenta.';
    elsif v_action='mark_refund_done' then
      if v_role='operador' then raise exception 'CLAIM_FORBIDDEN'; end if;
      if coalesce(v_claim.resolution,'') not in ('reintegro_total','reintegro_parcial') or v_order.financial_status is distinct from 'refunded' or not exists(
        select 1 from public.order_credit_notes n join public.order_refund_proofs f on f.order_id=n.order_id and f.id::text=n.settlement_reference where n.claim_id=v_claim.id and n.status='authorized' and n.destination='external_refund' and n.settlement_status='completado' and n.cae is not null
      ) or exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and (status='processing' or status='authorized' and settlement_status is distinct from 'completado')) then raise exception 'CLAIM_REFUND_PENDING'; end if;
      v_status:='cerrado'; v_resolution:=v_claim.resolution;
      v_message:='El reintegro fue registrado. Podés consultar el comprobante desde el detalle de tu compra.';
    elsif v_action<>'update' then raise exception 'CLAIM_INVALID';
    end if;
    v_allowed:=case v_claim.status
      when 'recibido' then array['en_revision','falta_informacion','aprobado','reintegro_pendiente','rechazado','cerrado']
      when 'en_revision' then array['falta_informacion','aprobado','reintegro_pendiente','rechazado','cerrado']
      when 'falta_informacion' then array['en_revision','aprobado','reintegro_pendiente','rechazado','cerrado']
      when 'aprobado' then array['cambio_pendiente','cupon_pendiente','rechazado','cerrado']
      else array['cerrado','rechazado'] end;
    if v_status<>v_claim.status and not v_status=any(v_allowed) then raise exception 'CLAIM_TRANSITION'; end if;
    if v_role='operador' and (p_patch ? 'credit_note_amount' or ((v_resolution in ('reintegro_total','reintegro_parcial','saldo_a_favor','cupon_descuento','cambio_producto','envio_unidad_faltante') or v_claim.resolution in ('reintegro_total','reintegro_parcial','saldo_a_favor','cupon_descuento','cambio_producto','envio_unidad_faltante')) and (v_status<>v_claim.status or v_resolution is distinct from v_claim.resolution))) then raise exception 'CLAIM_FORBIDDEN'; end if;
    if v_claim.resolution in ('reintegro_total','reintegro_parcial','saldo_a_favor','cupon_descuento') and v_resolution is distinct from v_claim.resolution and v_claim.status not in ('recibido','en_revision','falta_informacion') and
      not (v_status='rechazado' and not exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and status in ('processing','authorized'))) then raise exception 'CLAIM_RESOLUTION_LOCKED'; end if;
    if v_status='cerrado' and v_resolution in ('reintegro_total','reintegro_parcial','saldo_a_favor','cupon_descuento') and v_action not in ('mark_refund_done','mark_credit_note_issued') then raise exception 'CLAIM_ECONOMIC_CLOSE'; end if;
    if v_status in ('aprobado','reintegro_pendiente','cambio_pendiente','cupon_pendiente','cerrado') and (v_resolution is null or v_resolution='rechazado') then raise exception 'CLAIM_INVALID'; end if;
    if v_status='cambio_pendiente' and v_resolution not in ('cambio_producto','envio_unidad_faltante','otro') then raise exception 'CLAIM_INVALID'; end if;
    if v_status='reintegro_pendiente' and v_resolution not in ('reintegro_total','reintegro_parcial') then raise exception 'CLAIM_INVALID'; end if;
    if v_status='cupon_pendiente' and v_resolution not in ('cupon_descuento','saldo_a_favor') then raise exception 'CLAIM_INVALID'; end if;
    if v_resolution='rechazado' and v_status<>'rechazado' then raise exception 'CLAIM_INVALID'; end if;
    if v_status='rechazado' and (v_resolution<>'rechazado' or length(coalesce(nullif(p_patch->>'rejection_reason',''),v_message))<5) then raise exception 'CLAIM_INVALID'; end if;
    if p_patch ? 'credit_note_amount' then
      if v_role='operador' then raise exception 'CLAIM_FORBIDDEN'; end if;
      if v_action<>'update' or v_status<>'aprobado' or v_resolution is distinct from 'cupon_descuento' or exists(select 1 from public.order_credit_notes where claim_id=v_claim.id and status in ('processing','authorized')) then raise exception 'CLAIM_INVALID_AMOUNT'; end if;
      if p_patch->>'credit_note_amount' is null or (p_patch->>'credit_note_amount')::numeric<=0 or (p_patch->>'credit_note_amount')::numeric > v_order.total-coalesce((select sum(total_amount) from public.order_credit_notes where order_id=v_order.id and status in ('processing','authorized')),0) then raise exception 'CLAIM_INVALID_AMOUNT'; end if;
      update public.ordenes set credit_note_required=true,credit_note_amount=(p_patch->>'credit_note_amount')::numeric where id=v_order.id;
    end if;
    if v_action<>'approve_cancellation' then
      update public.order_claims set status=v_status,resolution=v_resolution,
        admin_response=case when p_patch ? 'admin_response' or v_action in ('mark_refund_done','mark_credit_note_issued') then nullif(v_message,'') else admin_response end,
        rejection_reason=case when v_status='rechazado' then coalesce(nullif(p_patch->>'rejection_reason',''),v_message) else rejection_reason end,
        closed_at=case when v_status in ('cerrado','rechazado') then now() else null end,
        refund_completed_at=case when v_action='mark_refund_done' then now() else refund_completed_at end,
        refund_completed_by=case when v_action='mark_refund_done' then p_actor_id else refund_completed_by end,
        first_reviewed_at=case when v_claim.status='recibido' and v_status='en_revision' then now() else first_reviewed_at end,
        first_reviewed_by=case when v_claim.status='recibido' and v_status='en_revision' then p_actor_id else first_reviewed_by end,
        admin_needs_action=case when v_status in ('cerrado','rechazado') or v_status='aprobado' and v_status<>v_claim.status or v_claim.status='recibido' and v_status='en_revision' then false else admin_needs_action end
      where id=v_claim.id;
      if length(v_message)>0 and (coalesce((p_patch->>'append_message')::boolean,false) or v_message is distinct from v_claim.admin_response) then
        insert into public.order_claim_messages(claim_id,author_user_id,author_role,message) values(v_claim.id,p_actor_id,v_role,v_message);
      elsif v_status in ('cerrado','rechazado') then
        insert into public.order_claim_messages(claim_id,author_user_id,author_role,message) values(v_claim.id,p_actor_id,v_role,case when v_status='cerrado' then 'BEYONIX finalizó el reclamo.' else 'BEYONIX rechazó el reclamo: '||coalesce(p_patch->>'rejection_reason',v_message) end);
      end if;
    end if;
  end if;
  insert into public.order_audit_events(order_id,actor_type,actor_id,action,previous_status,new_status,metadata)
  values(v_order.id,'admin',p_actor_id,'claim_'||v_action,v_before,v_status,jsonb_build_object('claimId',v_claim.id,'previousResolution',v_claim.resolution,'newResolution',v_resolution,'previousItems',case when v_action='affected_items' then v_claim.affected_items end,'affectedItems',v_items));
  select * into v_claim from public.order_claims where id=v_claim.id;
  return v_claim;
end $$;


ALTER FUNCTION "public"."mutate_admin_order_claim"("p_claim_id" bigint, "p_actor_id" "uuid", "p_expected_updated_at" timestamp with time zone, "p_patch" "jsonb") OWNER TO "postgres";

--
-- Name: normalize_block_identifier("text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."normalize_block_identifier"("identifier_type_input" "text", "identifier_value_input" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when identifier_type_input = 'phone'
      then regexp_replace(lower(trim(coalesce(identifier_value_input, ''))), '\D', '', 'g')
    else lower(trim(coalesce(identifier_value_input, '')))
  end
$$;


ALTER FUNCTION "public"."normalize_block_identifier"("identifier_type_input" "text", "identifier_value_input" "text") OWNER TO "postgres";

--
-- Name: normalize_conditioned_stock_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."normalize_conditioned_stock_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.discounted_quantity <= 0 then
    new.conditioned_active := false;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."normalize_conditioned_stock_state"() OWNER TO "postgres";

--
-- Name: normalized_catalog_barcode("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."normalized_catalog_barcode"("p_barcode" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select nullif(btrim(coalesce(p_barcode, '')), '');
$$;


ALTER FUNCTION "public"."normalized_catalog_barcode"("p_barcode" "text") OWNER TO "postgres";

--
-- Name: normalized_catalog_sku("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."normalized_catalog_sku"("p_sku" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select nullif(upper(btrim(coalesce(p_sku, ''))), '');
$$;


ALTER FUNCTION "public"."normalized_catalog_sku"("p_sku" "text") OWNER TO "postgres";

--
-- Name: notify_customer_claim_message(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."notify_customer_claim_message"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_claim public.order_claims%rowtype;
begin
  if new.author_role='cliente' then return new; end if;
  select * into v_claim from public.order_claims where id=new.claim_id;
  if v_claim.user_id is null then return new; end if;
  insert into public.customer_notifications(user_id,type,title,body,action_url,order_id,source_key)
  values(v_claim.user_id,'claim_response','Mensaje de BEYONIX','Tenés una nueva respuesta sobre tu pedido.',
    '/cuenta/compras/'||v_claim.order_id||'/ayuda',v_claim.order_id,'claim-message:'||new.id)
  on conflict(source_key) do nothing;
  return new;
end $$;


ALTER FUNCTION "public"."notify_customer_claim_message"() OWNER TO "postgres";

--
-- Name: notify_customer_credit_movement(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."notify_customer_credit_movement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_title text;
  v_body text;
  v_amount text;
begin
  if new.user_id is null then
    return new;
  end if;

  v_amount := to_char(new.amount, 'FM$999G999G999G990');

  if new.movement_type = 'debit' then
    v_title := 'Saldo a favor usado';
    v_body := 'Usaste ' || v_amount || ' de tu saldo a favor' ||
      case when new.order_id is not null then ' en el pedido BX-' || (1000 + new.order_id)::text else '' end || '.';
  elsif new.movement_type = 'reversal' then
    v_title := 'Saldo a favor reintegrado';
    v_body := 'Se devolvieron ' || v_amount || ' a tu saldo a favor.';
  else
    v_title := 'Saldo a favor acreditado';
    v_body := 'Se acreditaron ' || v_amount || ' en tu saldo a favor.';
  end if;

  insert into public.customer_notifications (
    user_id,
    type,
    title,
    body,
    action_url,
    order_id,
    source_key
  ) values (
    new.user_id,
    'customer_credit',
    v_title,
    v_body,
    case when new.order_id is null then '/cuenta' else '/cuenta?tab=saldo' end,
    new.order_id,
    'customer-credit:' || new.id::text
  )
  on conflict (source_key) do nothing;

  return new;
end;
$_$;


ALTER FUNCTION "public"."notify_customer_credit_movement"() OWNER TO "postgres";

--
-- Name: notify_customer_order_cancelled(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."notify_customer_order_cancelled"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  order_code text;
  notification_body text;
begin
  if new.usuario_id is null then
    return new;
  end if;

  if not (
    old.estado is distinct from new.estado
    or old.financial_status is distinct from new.financial_status
  ) then
    return new;
  end if;

  if new.estado <> 'cancelado'
     and coalesce(new.financial_status, '') not in ('cancelled', 'cancellation_requested', 'refund_pending') then
    return new;
  end if;

  order_code := 'BX-' || (1000 + new.id);
  notification_body := case
    when coalesce(new.financial_status, '') in ('cancellation_requested', 'refund_pending') then
      'Tu pedido ' || order_code || ' fue cancelado correctamente. Estamos gestionando el reintegro correspondiente.'
    else
      'Tu pedido ' || order_code || ' fue cancelado correctamente.'
  end;

  insert into public.customer_notifications (
    user_id,
    type,
    title,
    body,
    action_url,
    order_id,
    source_key,
    is_read,
    created_at
  ) values (
    new.usuario_id,
    'order_cancelled',
    'Pedido cancelado',
    notification_body,
    '/cuenta/compras/' || new.id,
    new.id,
    'order:' || new.id || ':cancelled',
    false,
    now()
  )
  on conflict (source_key) do update
  set
    type = excluded.type,
    title = excluded.title,
    body = excluded.body,
    action_url = excluded.action_url,
    is_read = false,
    created_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."notify_customer_order_cancelled"() OWNER TO "postgres";

--
-- Name: notify_customer_order_changes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."notify_customer_order_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.usuario_id is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.payment_method_id = 'transferencia'
       and coalesce(new.payment_status, '') = 'pendiente_comprobante'
       and new.payment_proof_url is null
       and new.payment_proof_uploaded_at is null then
      insert into public.customer_notifications (
        user_id,
        type,
        title,
        body,
        action_url,
        order_id,
        source_key
      ) values (
        new.usuario_id,
        'payment_proof_pending',
        'Comprobante pendiente',
        'Subí el comprobante para que podamos confirmar tu pago.',
        '/checkout/success?method=transferencia&order_id=' || new.id,
        new.id,
        'order:' || new.id || ':payment-proof-pending'
      )
      on conflict (source_key) do nothing;
    end if;

    return new;
  end if;

  if new.payment_method_id = 'transferencia'
     and (
       old.payment_proof_url is distinct from new.payment_proof_url
       or old.payment_proof_uploaded_at is distinct from new.payment_proof_uploaded_at
       or old.payment_status is distinct from new.payment_status
     )
     and coalesce(new.payment_status, '') <> 'confirmado'
     and (new.payment_proof_url is not null or new.payment_proof_uploaded_at is not null) then
    update public.customer_notifications
    set
      type = 'payment_proof_received',
      title = 'Comprobante recibido',
      body = 'Recibimos tu comprobante y estamos revisando el pago.',
      action_url = '/cuenta?tab=ordenes',
      is_read = false
    where order_id = new.id
      and type = 'payment_proof_pending';

    if not found then
      insert into public.customer_notifications (
        user_id,
        type,
        title,
        body,
        action_url,
        order_id,
        source_key
      ) values (
        new.usuario_id,
        'payment_proof_received',
        'Comprobante recibido',
        'Recibimos tu comprobante y estamos revisando el pago.',
        '/cuenta?tab=ordenes',
        new.id,
        'order:' || new.id || ':payment-proof-received'
      )
      on conflict (source_key) do update
      set
        type = excluded.type,
        title = excluded.title,
        body = excluded.body,
        action_url = excluded.action_url,
        is_read = false;
    end if;
  end if;

  if old.payment_status is distinct from new.payment_status
     and new.payment_status = 'confirmado' then
    update public.customer_notifications
    set
      type = 'payment_validated',
      title = 'Pago confirmado',
      body = 'Tu pago fue confirmado correctamente.',
      action_url = '/cuenta?tab=ordenes',
      is_read = false
    where order_id = new.id
      and type in ('payment_proof_pending', 'payment_proof_received');

    if not found then
      insert into public.customer_notifications (
        user_id, type, title, body, action_url, order_id, source_key
      ) values (
        new.usuario_id,
        'payment_validated',
        'Pago confirmado',
        'Tu pago fue confirmado correctamente.',
        '/cuenta?tab=ordenes',
        new.id,
        'order:' || new.id || ':payment-validated'
      )
      on conflict (source_key) do nothing;
    end if;
  end if;

  if old.estado is distinct from new.estado then
    if new.estado in ('enviado', 'en_camino') then
      insert into public.customer_notifications (
        user_id, type, title, body, action_url, order_id, source_key
      ) values (
        new.usuario_id,
        'order_shipped',
        'Pedido enviado',
        'Tu pedido ya está en camino.',
        '/cuenta?tab=ordenes',
        new.id,
        'order:' || new.id || ':shipped'
      )
      on conflict (source_key) do nothing;
    elsif new.estado = 'entregado' then
      insert into public.customer_notifications (
        user_id, type, title, body, action_url, order_id, source_key
      ) values (
        new.usuario_id,
        'order_delivered',
        'Pedido entregado',
        'Tu pedido figura como entregado.',
        '/cuenta?tab=ordenes',
        new.id,
        'order:' || new.id || ':delivered'
      )
      on conflict (source_key) do nothing;
    elsif new.estado = 'cancelado' then
      insert into public.customer_notifications (
        user_id, type, title, body, action_url, order_id, source_key
      ) values (
        new.usuario_id,
        'order_status',
        'Actualización de tu pedido',
        'El estado de tu pedido cambió. Revisá el detalle para más información.',
        '/cuenta?tab=ordenes',
        new.id,
        'order:' || new.id || ':cancelled'
      )
      on conflict (source_key) do nothing;
    end if;
  end if;

  return new;
end;
$$;


