--
-- Name: notify_customers_about_offer("text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."notify_customers_about_offer"("offer_title" "text" DEFAULT 'Oferta disponible'::"text", "offer_body" "text" DEFAULT 'Hay una nueva oferta activa en la tienda.'::"text", "offer_action_url" "text" DEFAULT '/productos'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  inserted_count integer;
begin
  if public.current_user_role() not in ('admin', 'super_admin') then
    raise exception 'No tenés permisos para publicar notificaciones de ofertas.';
  end if;

  insert into public.customer_notifications (
    user_id,
    type,
    title,
    body,
    action_url
  )
  select
    profiles.id,
    'offer',
    offer_title,
    offer_body,
    offer_action_url
  from public.profiles
  where profiles.rol = 'cliente';

  get diagnostics inserted_count = row_count;
  return inserted_count;
end;
$$;


