--
-- Name: prepare_manual_mercadolibre_sale_identity(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."prepare_manual_mercadolibre_sale_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if nullif(btrim(coalesce(new.source_key, '')), '') is not null then
    return new;
  end if;

  if nullif(btrim(coalesce(new.operation_id, '')), '') is null
     and nullif(btrim(coalesce(new.order_id, '')), '') is null then
    new.operation_id := 'manual:' || new.id::text;
  end if;

  new.source_key := public.mercadolibre_sale_source_key(
    new.operation_id,
    new.order_id,
    new.product_name,
    new.sku,
    new.sale_date,
    new.raw_data
  );
  return new;
end;
$$;


