-- Name: prevent_active_variant_on_inactive_product(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."prevent_active_variant_on_inactive_product"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.activo = true
    and exists (
      select 1
      from public.productos
      where id = new.producto_id
        and activo = false
    )
  then
    new.activo := false;
  end if;

  return new;
end;
$$;


