--
-- Name: orden_items; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."orden_items" (
    "id" bigint NOT NULL,
    "orden_id" bigint,
    "producto_id" bigint,
    "cantidad" integer DEFAULT 1 NOT NULL,
    "precio" numeric(10,2) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "variante_id" bigint,
    "warranty_started_at" timestamp with time zone,
    "warranty_expires_at" timestamp with time zone,
    "warranty_months" integer DEFAULT 6 NOT NULL,
    "warranty_status" "text" DEFAULT 'pending_delivery'::"text" NOT NULL,
    "return_restocked_quantity" integer DEFAULT 0 NOT NULL,
    "return_written_off_quantity" integer DEFAULT 0 NOT NULL,
    "return_inventory_note" "text",
    "return_inventory_processed_at" timestamp with time zone,
    "return_inventory_processed_by" "uuid",
    "conditioned_stock_id" "uuid",
    "conditioned_name" "text",
    "conditioned_sku" "text",
    "conditioned_color_hex" "text",
    "conditioned_images" "jsonb",
    "conditioned_discount_percent" numeric,
    "conditioned_reason" "text",
    "costo_unitario_historico" numeric(12,2),
    CONSTRAINT "orden_items_return_inventory_quantities_check" CHECK ((("return_restocked_quantity" >= 0) AND ("return_written_off_quantity" >= 0) AND (("return_restocked_quantity" + "return_written_off_quantity") <= "cantidad"))),
    CONSTRAINT "orden_items_warranty_months_check" CHECK ((("warranty_months" >= 0) AND ("warranty_months" <= 120))),
    CONSTRAINT "orden_items_warranty_status_check" CHECK (("warranty_status" = ANY (ARRAY['pending_delivery'::"text", 'active'::"text", 'expired'::"text", 'voided'::"text"]))),
    CONSTRAINT "order_items_conditioned_color_check" CHECK ((("conditioned_color_hex" IS NULL) OR ("conditioned_color_hex" ~ '^#[0-9A-Fa-f]{6}$'::"text"))),
    CONSTRAINT "order_items_conditioned_discount_check" CHECK ((("conditioned_discount_percent" IS NULL) OR (("conditioned_discount_percent" > (0)::numeric) AND ("conditioned_discount_percent" < (100)::numeric)))),
    CONSTRAINT "order_items_conditioned_images_check" CHECK ((("conditioned_images" IS NULL) OR ("jsonb_typeof"("conditioned_images") = 'array'::"text"))),
    CONSTRAINT "order_items_single_stock_source_check" CHECK ((("conditioned_stock_id" IS NULL) OR ("variante_id" IS NULL)))
);


