--
-- Name: process_claim_return_inventory(bigint, bigint, bigint, integer, integer, "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."process_claim_return_inventory"("p_claim_id" bigint, "p_order_id" bigint, "p_order_item_id" bigint, "p_restocked_quantity" integer, "p_written_off_quantity" integer, "p_note" "text", "p_processed_by" "uuid", "p_idempotency_key" "text") RETURNS "public"."orden_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_claim public.order_claims%rowtype;
  v_quantity integer;
  v_result public.orden_items%rowtype;
begin
  if auth.role() is distinct from 'service_role'
     or not exists (select 1 from public.profiles where id = p_processed_by and rol in ('admin', 'super_admin')) then
    raise exception 'CLAIM_FORBIDDEN';
  end if;
  perform id from public.ordenes where id = p_order_id for update;
  select * into v_claim from public.order_claims where id = p_claim_id and order_id = p_order_id for update;
  if not found or coalesce(v_claim.failure_type, '') in ('cancelar_compra', 'consulta_pedido') then
    raise exception 'CLAIM_INVALID';
  end if;

  select (x->>'quantity')::integer into v_quantity
  from jsonb_array_elements(v_claim.affected_items) x
  where (x->>'order_item_id')::bigint = p_order_item_id;
  if v_quantity is null
     or p_restocked_quantity is null or p_written_off_quantity is null
     or p_restocked_quantity < 0 or p_written_off_quantity < 0
     or p_restocked_quantity + p_written_off_quantity > v_quantity then
    raise exception 'CLAIM_INVALID_ITEMS';
  end if;

  -- El tope real de esta llamada es lo reclamado para este ítem, no sólo lo
  -- vendido (record_order_item_return_reception igual vuelve a validar
  -- contra lo vendido como defensa en profundidad).
  perform public.record_order_item_return_reception(
    p_order_id := p_order_id,
    p_order_item_id := p_order_item_id,
    p_sellable_quantity := p_restocked_quantity,
    p_discounted_quantity := 0,
    p_non_sellable_quantity := p_written_off_quantity,
    p_idempotency_key := p_idempotency_key,
    p_processed_by := p_processed_by,
    p_note := p_note,
    p_max_quantity_override := v_quantity
  );

  select * into v_result from public.orden_items where id = p_order_item_id;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."process_claim_return_inventory"("p_claim_id" bigint, "p_order_id" bigint, "p_order_item_id" bigint, "p_restocked_quantity" integer, "p_written_off_quantity" integer, "p_note" "text", "p_processed_by" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";

--
-- Name: process_order_item_return_inventory(bigint, bigint, integer, integer, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."process_order_item_return_inventory"("p_order_id" bigint, "p_order_item_id" bigint, "p_restocked_quantity" integer, "p_written_off_quantity" integer, "p_note" "text", "p_processed_by" "uuid") RETURNS "public"."orden_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.orden_items%rowtype;
begin
  if p_restocked_quantity < 0 or p_written_off_quantity < 0 then
    raise exception
      'Las cantidades de la devolución no pueden ser negativas.';
  end if;
  if p_written_off_quantity > 0
     and length(trim(coalesce(p_note, ''))) < 3 then
    raise exception 'Indicá el motivo de la baja o pérdida.';
  end if;

  select *
  into v_item
  from public.orden_items
  where id = p_order_item_id
    and orden_id = p_order_id
  for update;

  if not found then
    raise exception 'No se encontró el producto dentro del pedido.';
  end if;
  if v_item.return_inventory_processed_at is not null then
    raise exception 'La recepción de este producto ya fue registrada.';
  end if;
  if p_restocked_quantity + p_written_off_quantity > v_item.cantidad then
    raise exception
      'La cantidad recibida no puede superar la cantidad vendida.';
  end if;

  update public.orden_items
  set return_restocked_quantity = p_restocked_quantity,
      return_written_off_quantity = p_written_off_quantity,
      return_inventory_note =
        nullif(left(trim(coalesce(p_note, '')), 1000), ''),
      return_inventory_processed_at = now(),
      return_inventory_processed_by = p_processed_by
  where id = v_item.id
  returning * into v_item;

  -- Las unidades condicionadas vuelven al mismo lote derivado mediante
  -- return_restocked_quantity. No se convierten silenciosamente en stock normal.
  if p_restocked_quantity > 0
     and v_item.conditioned_stock_id is null then
    insert into public.inventory_return_movements (
      source_key,
      order_id,
      order_item_id,
      product_id,
      variant_id,
      quantity,
      approved_by,
      approved_at
    )
    values (
      'order-item:' || v_item.id,
      v_item.orden_id,
      v_item.id,
      v_item.producto_id,
      v_item.variante_id,
      p_restocked_quantity,
      p_processed_by,
      v_item.return_inventory_processed_at
    )
    on conflict (source_key) do nothing;
  end if;

  insert into public.order_audit_events (
    order_id,
    actor_type,
    actor_id,
    action,
    metadata
  )
  values (
    p_order_id,
    'admin',
    p_processed_by,
    'return_inventory_processed',
    jsonb_build_object(
      'orderItemId', v_item.id,
      'productId', v_item.producto_id,
      'variantId', v_item.variante_id,
      'conditionedStockId', v_item.conditioned_stock_id,
      'restockedQuantity', p_restocked_quantity,
      'writtenOffQuantity', p_written_off_quantity,
      'sourceOfTruth', 'derived_inventory'
    )
  );

  return v_item;
end;
$$;


ALTER FUNCTION "public"."process_order_item_return_inventory"("p_order_id" bigint, "p_order_item_id" bigint, "p_restocked_quantity" integer, "p_written_off_quantity" integer, "p_note" "text", "p_processed_by" "uuid") OWNER TO "postgres";

--
-- Name: product_activation_error(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."product_activation_error"("p_product_id" bigint) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_product public.productos%rowtype;
  v_primary_variant_id bigint;
  v_catalog_sku text;
  v_variant_error text;
begin
  select * into v_product
  from public.productos products
  where products.id = p_product_id;

  if not found then
    return 'El producto ya no existe.';
  end if;
  if nullif(btrim(coalesce(v_product.nombre, '')), '') is null then
    return 'Falta completar el título.';
  end if;

  select variants.id, variants.sku
  into v_primary_variant_id, v_catalog_sku
  from public.producto_variantes variants
  where variants.producto_id = p_product_id
  order by variants.orden, variants.id
  limit 1;

  v_catalog_sku := coalesce(v_catalog_sku, v_product.sku);
  if nullif(btrim(coalesce(v_catalog_sku, '')), '') is null then
    return 'El producto necesita un SKU.';
  end if;
  if coalesce(v_product.precio, 0) <= 0 then
    return 'El precio debe ser mayor a $0.';
  end if;
  if v_product.categoria_id is null
     or not exists (
       select 1 from public.categorias categories
       where categories.id = v_product.categoria_id
     ) then
    return 'Seleccioná una categoría.';
  end if;
  if nullif(btrim(coalesce(v_product.descripcion, '')), '') is null then
    return 'Completá la descripción.';
  end if;
  if not exists (
    select 1
    from public.producto_especificaciones specifications
    where specifications.producto_id = p_product_id
      and specifications.activo
      and nullif(btrim(coalesce(specifications.icono, '')), '') is not null
      and nullif(btrim(coalesce(specifications.texto, '')), '') is not null
  ) then
    return 'Agregá al menos una especificación activa.';
  end if;
  if coalesce(v_product.peso_empaquetado_kg, 0) <= 0
     or coalesce(v_product.alto_paquete_cm, 0) <= 0
     or coalesce(v_product.ancho_paquete_cm, 0) <= 0
     or coalesce(v_product.largo_paquete_cm, 0) <= 0 then
    return 'Completá peso, profundidad, ancho y largo.';
  end if;
  if v_primary_variant_id is null then
    return 'Creá al menos una variante.';
  end if;

  v_variant_error := public.product_variant_activation_error(
    p_product_id,
    v_primary_variant_id,
    true
  );
  return v_variant_error;
end;
$_$;


ALTER FUNCTION "public"."product_activation_error"("p_product_id" bigint) OWNER TO "postgres";

--
-- Name: FUNCTION "product_activation_error"("p_product_id" bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."product_activation_error"("p_product_id" bigint) IS 'Centraliza el primer requisito faltante para publicar un producto.';


--
-- Name: product_variant_activation_error(bigint, bigint, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."product_variant_activation_error"("p_product_id" bigint, "p_variant_id" bigint, "p_primary" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_variant public.producto_variantes%rowtype;
  v_subject text := case
    when p_primary then 'La variante principal'
    else 'La variante'
  end;
begin
  select * into v_variant
  from public.producto_variantes variants
  where variants.id = p_variant_id
    and variants.producto_id = p_product_id;

  if not found then
    return case
      when p_primary then 'Creá al menos una variante.'
      else 'La variante ya no existe.'
    end;
  end if;
  if nullif(btrim(coalesce(v_variant.nombre, '')), '') is null then
    return v_subject || ' necesita un nombre.';
  end if;
  if nullif(btrim(coalesce(v_variant.sku, '')), '') is null then
    return v_subject || ' necesita un SKU.';
  end if;
  if v_variant.color_hex is null
     or v_variant.color_hex !~ '^#[0-9A-Fa-f]{6}$' then
    return v_subject || ' necesita un color.';
  end if;
  if jsonb_typeof(coalesce(v_variant.imagenes, '[]'::jsonb)) <> 'array' then
    return v_subject || ' necesita al menos una imagen.';
  end if;
  if not exists (
    select 1
    from jsonb_array_elements_text(v_variant.imagenes) images(url)
    where nullif(btrim(images.url), '') is not null
  ) then
    return v_subject || ' necesita al menos una imagen.';
  end if;

  if coalesce(v_variant.stock, 0) <= 0 then
    return v_subject || ' necesita stock asignado.';
  end if;

  return null;
end;
$_$;


ALTER FUNCTION "public"."product_variant_activation_error"("p_product_id" bigint, "p_variant_id" bigint, "p_primary" boolean) OWNER TO "postgres";

--
-- Name: FUNCTION "product_variant_activation_error"("p_product_id" bigint, "p_variant_id" bigint, "p_primary" boolean); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."product_variant_activation_error"("p_product_id" bigint, "p_variant_id" bigint, "p_primary" boolean) IS 'Centraliza el primer requisito faltante para activar una variante.';


--
-- Name: protect_primary_super_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."protect_primary_super_admin"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE'
     and lower(old.email) = 'espinosatrabajo@gmail.com'
     and (
       new.rol is distinct from 'super_admin'
       or lower(coalesce(new.email, '')) is distinct from
          'espinosatrabajo@gmail.com'
     ) then
    raise exception 'El super administrador principal está protegido.';
  end if;

  if lower(coalesce(new.email, '')) = 'espinosatrabajo@gmail.com' then
    new.rol := 'super_admin';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."protect_primary_super_admin"() OWNER TO "postgres";

--
-- Name: protect_profile_role_changes(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."protect_profile_role_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  actor_role text;
begin
  if new.rol is not distinct from old.rol then
    return new;
  end if;

  if auth.role() = 'service_role' then
    return new;
  end if;

  select rol into actor_role
  from public.profiles
  where id = auth.uid();

  if actor_role = 'super_admin' then
    return new;
  end if;

  if actor_role = 'admin'
     and old.rol <> 'super_admin'
     and new.rol in ('cliente', 'operador', 'admin') then
    return new;
  end if;

  raise exception 'No tenés permisos para cambiar este rol.';
end;
$$;


ALTER FUNCTION "public"."protect_profile_role_changes"() OWNER TO "postgres";

--
-- Name: purge_expired_stock_reservations(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."purge_expired_stock_reservations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_deleted integer;
begin
  delete from public.stock_reservations reservations
  where reservations.expires_at <= now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;


