--
-- Name: reconcile_mercadopago_order_refund("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reconcile_mercadopago_order_refund"("p_refund_id" "uuid", "p_outcome" "text", "p_mp_refund_id" "text" DEFAULT NULL::"text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "public"."mercadopago_order_refunds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_row public.mercadopago_order_refunds%rowtype;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_row from public.mercadopago_order_refunds where id = p_refund_id for update;
  if not found then
    raise exception 'REFUND_ATTEMPT_NOT_FOUND';
  end if;

  -- Sólo se rechaza reconciliar una fila 'requested' recién creada (nunca
  -- se intentó, no hay nada que reconciliar contra Mercado Pago todavía).
  -- 'confirmed'/'failed' se dejan pasar a (3), que ya es idempotente para
  -- esos dos casos (reentregas de la reconciliación no fallan).
  if v_row.status = 'requested' then
    raise exception 'REFUND_ATTEMPT_NOT_STARTED';
  end if;

  return public.record_mercadopago_order_refund_result(
    p_refund_id, p_outcome, p_mp_refund_id, p_error_code, p_error_message
  );
end;
$$;


ALTER FUNCTION "public"."reconcile_mercadopago_order_refund"("p_refund_id" "uuid", "p_outcome" "text", "p_mp_refund_id" "text", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";

--
-- Name: record_mercadopago_order_refund_result("uuid", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."record_mercadopago_order_refund_result"("p_refund_id" "uuid", "p_outcome" "text", "p_mp_refund_id" "text" DEFAULT NULL::"text", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "public"."mercadopago_order_refunds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_row public.mercadopago_order_refunds%rowtype;
  v_order public.ordenes%rowtype;
  v_previous_status text;
  v_audit_action text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  if p_outcome not in ('confirmed', 'failed', 'needs_reconciliation', 'requested') then
    raise exception 'INVALID_REFUND_OUTCOME';
  end if;

  select *
  into v_row
  from public.mercadopago_order_refunds
  where id = p_refund_id
  for update;

  if not found then
    raise exception 'REFUND_ATTEMPT_NOT_FOUND';
  end if;

  if v_row.status in ('confirmed', 'failed') then
    return v_row;
  end if;

  if v_row.status not in ('processing', 'needs_reconciliation') then
    raise exception 'REFUND_ATTEMPT_NOT_IN_PROGRESS';
  end if;

  v_previous_status := v_row.status;

  update public.mercadopago_order_refunds
  set
    status = p_outcome,
    mp_refund_id = coalesce(p_mp_refund_id, mp_refund_id),
    error_code = case when p_outcome in ('failed', 'needs_reconciliation') then p_error_code else null end,
    error_message = case when p_outcome in ('failed', 'needs_reconciliation') then p_error_message else null end,
    reconciliation_locked_at = case when p_outcome = 'needs_reconciliation' then reconciliation_locked_at else null end,
    completed_at = case when p_outcome in ('confirmed', 'failed') then now() else completed_at end
  where id = p_refund_id
  returning * into v_row;

  -- Auditoría explícita de la transición -- sólo si realmente cambió, para
  -- no spamear ante reconciliaciones repetidas que concluyen lo mismo
  -- (needs_reconciliation -> needs_reconciliation no es una transición real).
  if v_previous_status is distinct from p_outcome then
    v_audit_action := case p_outcome
      when 'confirmed' then 'mp_refund_confirmed'
      when 'failed' then 'mp_refund_failed'
      when 'needs_reconciliation' then 'mp_refund_needs_reconciliation'
      when 'requested' then 'mp_refund_requested'
    end;

    insert into public.order_audit_events (
      order_id, actor_type, actor_id, action, previous_status, new_status, metadata
    ) values (
      v_row.order_id, 'system', null, v_audit_action, v_previous_status, p_outcome,
      jsonb_build_object(
        'refundAttemptId', v_row.id,
        'paymentId', v_row.payment_id,
        'mpRefundId', v_row.mp_refund_id,
        'amount', v_row.amount,
        'errorCode', p_error_code
      )
    );
  end if;

  if p_outcome = 'confirmed' then
    select * into v_order from public.ordenes where id = v_row.order_id for update;

    update public.ordenes
    set
      financial_status = 'refunded',
      refund_method = 'mercadopago',
      refund_amount = v_row.amount,
      refunded_at = now(),
      refunded_by = v_row.requested_by
    where id = v_row.order_id;

    perform public.close_mercadopago_order_refund_claim(v_row.order_id, v_row.id);
  end if;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."record_mercadopago_order_refund_result"("p_refund_id" "uuid", "p_outcome" "text", "p_mp_refund_id" "text", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";

--
-- Name: record_order_item_return_reception(bigint, bigint, integer, integer, integer, "text", "uuid", "text", numeric, "text", "text", "text", "text", "text", "jsonb", timestamp with time zone, integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."record_order_item_return_reception"("p_order_id" bigint, "p_order_item_id" bigint, "p_sellable_quantity" integer, "p_discounted_quantity" integer, "p_non_sellable_quantity" integer, "p_idempotency_key" "text", "p_processed_by" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_discount_percent" numeric DEFAULT NULL::numeric, "p_discount_reason" "text" DEFAULT NULL::"text", "p_non_sellable_reason" "text" DEFAULT NULL::"text", "p_conditioned_name" "text" DEFAULT NULL::"text", "p_conditioned_sku" "text" DEFAULT NULL::"text", "p_conditioned_color_hex" "text" DEFAULT NULL::"text", "p_conditioned_images" "jsonb" DEFAULT '[]'::"jsonb", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_max_quantity_override" integer DEFAULT NULL::integer, "p_variant_id_override" bigint DEFAULT NULL::bigint) RETURNS "public"."inventory_return_movements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item public.orden_items%rowtype;
  v_existing public.inventory_return_movements%rowtype;
  v_movement public.inventory_return_movements%rowtype;
  v_already integer;
  v_requested integer;
  v_cap integer;
  v_source_key text;
  v_non_sellable_reason text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'RETURN_FORBIDDEN';
  end if;
  if p_idempotency_key is null or length(trim(p_idempotency_key)) = 0 then
    raise exception 'RETURN_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  if p_sellable_quantity < 0 or p_discounted_quantity < 0 or p_non_sellable_quantity < 0 then
    raise exception 'Las cantidades de la devolución no pueden ser negativas.';
  end if;

  v_requested := p_sellable_quantity + p_discounted_quantity + p_non_sellable_quantity;
  if v_requested <= 0 then
    raise exception 'Indicá al menos una unidad recibida para registrar la devolución.';
  end if;
  -- validate_inventory_return_condition (trigger) exige non_sellable_reason
  -- en la FILA -- no alcanza con validar acá y seguir insertando el
  -- p_non_sellable_reason original: si vino vacío, el motivo pasado en
  -- p_note (ya validado abajo) es el que efectivamente se persiste.
  v_non_sellable_reason := nullif(trim(coalesce(p_non_sellable_reason, '')), '');
  if v_non_sellable_reason is null then
    v_non_sellable_reason := nullif(trim(coalesce(p_note, '')), '');
  end if;
  if p_non_sellable_quantity > 0
     and (v_non_sellable_reason is null or length(v_non_sellable_reason) < 3) then
    raise exception 'Indicá el motivo de la baja o pérdida.';
  end if;

  v_source_key := 'order-item:' || p_order_item_id || ':' || p_idempotency_key;

  -- Idempotencia: reintento (doble click, retry, dos pestañas) con la misma
  -- key devuelve el resultado ya aplicado, sin volver a tocar stock/auditoría.
  select * into v_existing
  from public.inventory_return_movements
  where source_key = v_source_key;
  if found then
    return v_existing;
  end if;

  select * into v_item
  from public.orden_items
  where id = p_order_item_id and orden_id = p_order_id
  for update;
  if not found then
    raise exception 'No se encontró el producto dentro del pedido.';
  end if;

  select coalesce(sum(received_quantity), 0) into v_already
  from public.inventory_return_movements
  where order_item_id = p_order_item_id;

  v_cap := coalesce(p_max_quantity_override, v_item.cantidad);
  if v_already + v_requested > v_cap then
    raise exception
      'RETURN_EXCEEDS_REMAINING: quedan % unidad(es) disponibles para devolver de este producto (ya se registraron % de %).',
      greatest(v_cap - v_already, 0), v_already, v_cap;
  end if;

  -- El trigger genérico inventory_return_movements_audit_log_trigger (ver
  -- 20260920100000) audita este INSERT automáticamente; esto sólo le da el
  -- actor correcto vía auth.uid().
  perform set_config('beyonix.actor_id', p_processed_by::text, true);

  insert into public.inventory_return_movements (
    source_key, order_id, order_item_id, product_id, variant_id,
    quantity, received_quantity, sellable_quantity, discounted_quantity, non_sellable_quantity,
    discount_percent, discount_reason, non_sellable_reason, review_notes,
    conditioned_active, conditioned_name, conditioned_sku, conditioned_color_hex, conditioned_images,
    occurred_at, approved_by, approved_at
  ) values (
    v_source_key, p_order_id, p_order_item_id, v_item.producto_id, coalesce(p_variant_id_override, v_item.variante_id),
    p_sellable_quantity, v_requested, p_sellable_quantity, p_discounted_quantity, p_non_sellable_quantity,
    p_discount_percent, p_discount_reason, v_non_sellable_reason, nullif(left(trim(coalesce(p_note, '')), 1000), ''),
    p_discounted_quantity > 0, p_conditioned_name, p_conditioned_sku, p_conditioned_color_hex,
    coalesce(p_conditioned_images, '[]'::jsonb),
    p_occurred_at, p_processed_by, now()
  )
  returning * into v_movement;

  perform set_config('beyonix.return_reception_rpc', 'on', true);
  update public.orden_items
  set return_restocked_quantity = (
        select coalesce(sum(sellable_quantity + discounted_quantity), 0)
        from public.inventory_return_movements
        where order_item_id = p_order_item_id
      ),
      return_written_off_quantity = (
        select coalesce(sum(non_sellable_quantity), 0)
        from public.inventory_return_movements
        where order_item_id = p_order_item_id
      ),
      return_inventory_note = case
        when nullif(trim(coalesce(p_note, '')), '') is null then return_inventory_note
        when return_inventory_note is null then left(trim(p_note), 1000)
        else left(return_inventory_note || E'\n---\n' || trim(p_note), 1000)
      end,
      return_inventory_processed_at = now(),
      return_inventory_processed_by = p_processed_by
  where id = p_order_item_id;

  insert into public.order_audit_events (
    order_id, actor_type, actor_id, action, metadata
  ) values (
    p_order_id, 'admin', p_processed_by, 'return_inventory_processed',
    jsonb_build_object(
      'orderItemId', p_order_item_id,
      'productId', v_item.producto_id,
      'variantId', v_item.variante_id,
      'sellableQuantity', p_sellable_quantity,
      'discountedQuantity', p_discounted_quantity,
      'nonSellableQuantity', p_non_sellable_quantity,
      'sourceKey', v_source_key,
      'cumulativeReturned', v_already + v_requested,
      'soldQuantity', v_item.cantidad,
      'remaining', v_item.cantidad - (v_already + v_requested)
    )
  );

  return v_movement;
end;
$$;


ALTER FUNCTION "public"."record_order_item_return_reception"("p_order_id" bigint, "p_order_item_id" bigint, "p_sellable_quantity" integer, "p_discounted_quantity" integer, "p_non_sellable_quantity" integer, "p_idempotency_key" "text", "p_processed_by" "uuid", "p_note" "text", "p_discount_percent" numeric, "p_discount_reason" "text", "p_non_sellable_reason" "text", "p_conditioned_name" "text", "p_conditioned_sku" "text", "p_conditioned_color_hex" "text", "p_conditioned_images" "jsonb", "p_occurred_at" timestamp with time zone, "p_max_quantity_override" integer, "p_variant_id_override" bigint) OWNER TO "postgres";

--
-- Name: refresh_inventory_from_order(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."refresh_inventory_from_order"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_id bigint;
begin
  if public.inventory_order_consumes_stock(old.estado, old.payment_status)
     is not distinct from
     public.inventory_order_consumes_stock(new.estado, new.payment_status) then
    return new;
  end if;

  for v_product_id in
    select distinct items.producto_id
    from public.orden_items items
    where items.orden_id = new.id
  loop
    perform public.refresh_inventory_stock(v_product_id);
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."refresh_inventory_from_order"() OWNER TO "postgres";

--
-- Name: refresh_inventory_from_order_item(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."refresh_inventory_from_order_item"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_old_product_id bigint;
  v_new_product_id bigint;
begin
  v_old_product_id := case when tg_op <> 'INSERT' then old.producto_id else null end;
  v_new_product_id := case when tg_op <> 'DELETE' then new.producto_id else null end;

  if v_old_product_id is not null then
    perform public.refresh_inventory_stock(v_old_product_id);
  end if;
  if v_new_product_id is not null
     and v_new_product_id is distinct from v_old_product_id then
    perform public.refresh_inventory_stock(v_new_product_id);
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


