--
-- Name: refresh_inventory_stock(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."refresh_inventory_stock"("p_product_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_previous_refresh_setting text := coalesce(
    current_setting('beyonix.inventory_refresh', true),
    ''
  );
  v_negative_variant_id bigint;
  v_negative_variant_stock numeric;
  v_negative_product_stock numeric;
begin
  if p_product_id is null then
    return;
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);
  perform set_config('beyonix.inventory_refresh', 'on', true);

  update public.producto_variantes variants
  set stock =
    coalesce((
      select sum(movements.quantity_delta)
      from public.inventory_movements movements
      where movements.product_id = variants.producto_id
        and movements.variant_id = variants.id
        and movements.movement_date <= current_date
    ), 0)
    + coalesce((
      select allocations.quantity
      from public.inventory_variant_allocations allocations
      where allocations.variant_id = variants.id
    ), 0)
  where variants.producto_id = p_product_id;

  select variants.id, variants.stock
  into v_negative_variant_id, v_negative_variant_stock
  from public.producto_variantes variants
  where variants.producto_id = p_product_id
    and variants.stock < 0
  order by variants.id
  limit 1;

  if found then
    perform set_config(
      'beyonix.inventory_refresh',
      v_previous_refresh_setting,
      true
    );
    raise exception
      'INVENTORY_CORRUPTION_NEGATIVE_STOCK: producto_variantes.id=%, producto_id=%, stock_calculado=% -- revisar inventory_movements/inventory_variant_allocations antes de reintentar',
      v_negative_variant_id, p_product_id, v_negative_variant_stock;
  end if;

  update public.productos products
  set stock = coalesce((
    select sum(movements.quantity_delta)
    from public.inventory_movements movements
    where movements.product_id = products.id
      and movements.movement_date <= current_date
  ), 0)
  where products.id = p_product_id;

  select products.stock
  into v_negative_product_stock
  from public.productos products
  where products.id = p_product_id
    and products.stock < 0;

  if found then
    perform set_config(
      'beyonix.inventory_refresh',
      v_previous_refresh_setting,
      true
    );
    raise exception
      'INVENTORY_CORRUPTION_NEGATIVE_STOCK: productos.id=%, stock_calculado=% -- revisar inventory_movements antes de reintentar',
      p_product_id, v_negative_product_stock;
  end if;

  perform set_config(
    'beyonix.inventory_refresh',
    v_previous_refresh_setting,
    true
  );
exception
  when others then
    perform set_config(
      'beyonix.inventory_refresh',
      v_previous_refresh_setting,
      true
    );
    raise;
end;
$$;


ALTER FUNCTION "public"."refresh_inventory_stock"("p_product_id" bigint) OWNER TO "postgres";

--
-- Name: FUNCTION "refresh_inventory_stock"("p_product_id" bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."refresh_inventory_stock"("p_product_id" bigint) IS 'Recalcula stock derivado (productos/producto_variantes) desde inventory_movements + inventory_variant_allocations. FAIL CLOSED: si el recompute da negativo, aborta con excepción en vez de pisar con 0 -- nunca esconde una corrupción del ledger. Fix 20260918100000.';


--
-- Name: reject_negative_inventory_sale(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reject_negative_inventory_sale"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_ids bigint[] := array[
    case when tg_op <> 'INSERT' then old.product_id else null end,
    case when tg_op <> 'DELETE' then new.product_id else null end
  ];
begin
  if exists (
    select 1
    from public.productos products
    where products.id = any(v_product_ids)
      and products.stock < 0
  ) or exists (
    select 1
    from public.producto_variantes variants
    where variants.producto_id = any(v_product_ids)
      and variants.stock < 0
  ) then
    raise exception 'STOCK_INSUFICIENTE: la venta supera el stock disponible.';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."reject_negative_inventory_sale"() OWNER TO "postgres";

