-- Name: release_cart_stock_reservation("text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."release_cart_stock_reservation"("p_session_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  delete from public.stock_reservations reservations
  where reservations.session_id = p_session_id
    and (reservations.user_id is null or reservations.user_id = auth.uid());
end;
$$;


