--
-- Name: reorder_product_variants_atomic(bigint, "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reorder_product_variants_atomic"("p_product_id" bigint, "p_variant_ids" "jsonb", "p_actor_id" "uuid") RETURNS SETOF "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_requested_count integer;
  v_catalog_count integer;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para reordenar variantes.';
  end if;
  if jsonb_typeof(coalesce(p_variant_ids, 'null'::jsonb)) <> 'array' then
    raise exception 'El orden de variantes no es válido.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);
  select count(*) into v_catalog_count
  from public.producto_variantes variants
  where variants.producto_id = p_product_id;
  select count(*) into v_requested_count
  from jsonb_array_elements_text(p_variant_ids);

  if v_requested_count <> v_catalog_count
     or (
       select count(distinct value::bigint)
       from jsonb_array_elements_text(p_variant_ids)
     ) <> v_requested_count
     or exists (
       select 1
       from jsonb_array_elements_text(p_variant_ids) requested(value)
       left join public.producto_variantes variants
         on variants.id = requested.value::bigint
        and variants.producto_id = p_product_id
       where variants.id is null
     ) then
    raise exception 'El orden debe incluir exactamente todas las variantes del producto.';
  end if;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);
  update public.producto_variantes variants
  set orden = requested.position::integer
  from jsonb_array_elements_text(p_variant_ids)
    with ordinality as requested(value, position)
  where variants.id = requested.value::bigint
    and variants.producto_id = p_product_id;

  if exists (
    select 1 from public.productos products
    where products.id = p_product_id and products.activo
  ) then
    perform public.assert_product_can_activate(p_product_id);
    update public.producto_variantes variants
    set activo = true
    where variants.id = (
      select primary_variant.id
      from public.producto_variantes primary_variant
      where primary_variant.producto_id = p_product_id
      order by primary_variant.orden, primary_variant.id
      limit 1
    );
  end if;

  perform public.sync_product_primary_variant_image(p_product_id);
  return query
  select variants.*
  from public.producto_variantes variants
  where variants.producto_id = p_product_id
  order by variants.orden, variants.id;
end;
$$;


ALTER FUNCTION "public"."reorder_product_variants_atomic"("p_product_id" bigint, "p_variant_ids" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: conditioned_inventory_offers; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."conditioned_inventory_offers" WITH ("security_invoker"='true') AS
 SELECT "movements"."id",
    "movements"."product_id",
    "movements"."variant_id" AS "source_variant_id",
    "movements"."conditioned_name" AS "name",
    "movements"."conditioned_sku" AS "sku",
    "movements"."conditioned_color_hex" AS "color_hex",
    "movements"."conditioned_images" AS "images",
    "movements"."discounted_quantity" AS "original_quantity",
    (COALESCE("sales"."quantity", (0)::bigint))::integer AS "sold_quantity",
    (GREATEST(("movements"."discounted_quantity" - COALESCE("sales"."quantity", (0)::bigint)), (0)::bigint))::integer AS "available_quantity",
    "movements"."discount_percent",
    "movements"."discount_reason" AS "reason",
    "movements"."conditioned_active" AS "active",
    "movements"."approved_at"
   FROM ("public"."inventory_return_movements" "movements"
     LEFT JOIN LATERAL ( SELECT "sum"(GREATEST(("items"."cantidad" - COALESCE("items"."return_restocked_quantity", 0)), 0)) AS "quantity"
           FROM ("public"."orden_items" "items"
             JOIN "public"."ordenes" "orders" ON (("orders"."id" = "items"."orden_id")))
          WHERE (("items"."conditioned_stock_id" = "movements"."id") AND "public"."inventory_order_consumes_stock"("orders"."estado", "orders"."payment_status"))) "sales" ON (true))
  WHERE ("movements"."discounted_quantity" > 0);


ALTER VIEW "public"."conditioned_inventory_offers" OWNER TO "postgres";

--
-- Name: VIEW "conditioned_inventory_offers"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW "public"."conditioned_inventory_offers" IS 'Existencia inicial, ventas netas y disponibilidad de cada variante con descuento.';


--
-- Name: external_sales; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE "public"."external_sales" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "sale_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "product_id" bigint,
    "product_name" "text" NOT NULL,
    "sku" "text",
    "quantity" integer DEFAULT 1 NOT NULL,
    "unit_price" numeric(12,2) DEFAULT 0 NOT NULL,
    "unit_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "gross_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "fee_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "shipping_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "other_expense_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "net_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "payment_method" "text",
    "reference" "text",
    "notes" "text",
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fee_type" "text" DEFAULT 'amount'::"text" NOT NULL,
    "fee_value" numeric(12,2) DEFAULT 0 NOT NULL,
    "customer_name" "text",
    "variant_id" bigint,
    "costo_unitario_historico" numeric(12,2),
    "status" "text" DEFAULT 'completed'::"text" NOT NULL,
    "reversed_at" timestamp with time zone,
    "reversed_by" "uuid",
    "reversal_reason" "text",
    "reversal_amount" numeric(12,2),
    "reversal_idempotency_key" "text",
    CONSTRAINT "external_sales_fee_amount_check" CHECK (("fee_amount" >= (0)::numeric)),
    CONSTRAINT "external_sales_fee_type_check" CHECK (("fee_type" = ANY (ARRAY['amount'::"text", 'percent'::"text"]))),
    CONSTRAINT "external_sales_fee_value_check" CHECK (("fee_value" >= (0)::numeric)),
    CONSTRAINT "external_sales_gross_amount_check" CHECK (("gross_amount" >= (0)::numeric)),
    CONSTRAINT "external_sales_other_expense_amount_check" CHECK (("other_expense_amount" >= (0)::numeric)),
    CONSTRAINT "external_sales_quantity_check" CHECK (("quantity" > 0)),
    CONSTRAINT "external_sales_reversal_reason_check" CHECK (((("status" = 'completed'::"text") AND ("reversed_at" IS NULL) AND ("reversed_by" IS NULL) AND ("reversal_reason" IS NULL) AND ("reversal_amount" IS NULL) AND ("reversal_idempotency_key" IS NULL)) OR (("status" = 'reversed'::"text") AND ("reversed_at" IS NOT NULL) AND ("reversal_reason" IS NOT NULL) AND ("length"("btrim"("reversal_reason")) >= 10) AND ("reversal_amount" IS NOT NULL) AND ("reversal_amount" >= (0)::numeric) AND ("reversal_idempotency_key" IS NOT NULL)))),
    CONSTRAINT "external_sales_shipping_amount_check" CHECK (("shipping_amount" >= (0)::numeric)),
    CONSTRAINT "external_sales_status_check" CHECK (("status" = ANY (ARRAY['completed'::"text", 'reversed'::"text"]))),
    CONSTRAINT "external_sales_unit_cost_check" CHECK (("unit_cost" >= (0)::numeric)),
    CONSTRAINT "external_sales_unit_price_check" CHECK (("unit_price" >= (0)::numeric))
);


ALTER TABLE "public"."external_sales" OWNER TO "postgres";

--
-- Name: TABLE "external_sales"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON TABLE "public"."external_sales" IS 'Ventas manuales realizadas fuera de la tienda web y Mercado Libre.';


--
-- Name: COLUMN "external_sales"."costo_unitario_historico"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN "public"."external_sales"."costo_unitario_historico" IS 'Igual semántica que orden_items.costo_unitario_historico, congelado al crear la fila (trigger freeze_external_sale_historical_cost_before_insert). No confundir con unit_cost, que es un valor manual tipeado por el admin al cargar la venta (usado sólo como fallback para artículos no catalogados).';


