    "product_id" bigint NOT NULL,
    "variant_id" bigint NOT NULL,
    "adjustment_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "quantity_delta" integer NOT NULL,
    "reason" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "idempotency_key" "text",
    CONSTRAINT "inventory_stock_adjustments_quantity_delta_check" CHECK (("quantity_delta" <> 0)),
    CONSTRAINT "inventory_stock_adjustments_reason_check" CHECK ((("length"("btrim"("reason")) >= 3) AND ("length"("btrim"("reason")) <= 300)))
);


