    "product_name" "text" NOT NULL,
    "sku" "text",
    "quantity" integer DEFAULT 1 NOT NULL,
    "gross_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "fee_amount" numeric(12,2),
    "shipping_amount" numeric(12,2),
    "net_amount" numeric(12,2),
    "source_file_name" "text",
    "imported_by" "uuid",
    "imported_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "raw_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "product_id" bigint,
    "unit_price" numeric(12,2),
    "unit_cost" numeric(12,2) DEFAULT 0 NOT NULL,
    "other_expense_amount" numeric(12,2) DEFAULT 0 NOT NULL,
    "payment_method" "text",
    "reference" "text",
    "notes" "text",
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "fee_type" "text" DEFAULT 'amount'::"text" NOT NULL,
    "fee_value" numeric(12,2) DEFAULT 0 NOT NULL,
    "customer_name" "text",
    "source_key" "text" NOT NULL,
    "costo_unitario_historico" numeric(12,2),
