--
-- Name: inventory_movements; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_movements" WITH ("security_invoker"='true') AS
 SELECT "entries"."product_id",
    "entries"."variant_id",
    "entries"."purchase_date" AS "movement_date",
    "entries"."created_at" AS "recorded_at",
    'purchase'::"text" AS "source",
    ("entries"."id")::"text" AS "source_id",
    ("entries"."received_quantity")::bigint AS "quantity_delta",
    ('purchase:'::"text" || ("entries"."id")::"text") AS "movement_id",
    'purchase'::"text" AS "movement_type",
    'product_cost_entries'::"text" AS "origin",
    (("entries"."purchase_date")::timestamp without time zone AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text") AS "effective_at",
    "entries"."created_by" AS "responsible_user_id",
    'admin_purchase'::"text" AS "responsible_process",
    COALESCE("entries"."idempotency_key", ('purchase:'::"text" || ("entries"."id")::"text")) AS "idempotency_key",
    COALESCE(NULLIF("btrim"("entries"."document_number"), ''::"text"), ("entries"."id")::"text") AS "document_reference"
   FROM "public"."product_cost_entries" "entries"
  WHERE (("entries"."product_id" IS NOT NULL) AND ("entries"."received_quantity" <> 0))
UNION ALL
 SELECT "items"."producto_id" AS "product_id",
    "items"."variante_id" AS "variant_id",
    (("orders"."created_at" AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text"))::"date" AS "movement_date",
    "orders"."created_at" AS "recorded_at",
    'web_sale'::"text" AS "source",
    ("items"."id")::"text" AS "source_id",
    (- ("items"."cantidad")::bigint) AS "quantity_delta",
    ('web_sale:'::"text" || ("items"."id")::"text") AS "movement_id",
    'web_sale'::"text" AS "movement_type",
    'orden_items'::"text" AS "origin",
    "orders"."created_at" AS "effective_at",
    "orders"."usuario_id" AS "responsible_user_id",
    'checkout'::"text" AS "responsible_process",
    COALESCE("orders"."checkout_idempotency_key", ('order-item:'::"text" || ("items"."id")::"text")) AS "idempotency_key",
    ('order:'::"text" || ("orders"."id")::"text") AS "document_reference"
   FROM ("public"."orden_items" "items"
     JOIN "public"."ordenes" "orders" ON (("orders"."id" = "items"."orden_id")))
  WHERE (("items"."conditioned_stock_id" IS NULL) AND "public"."inventory_order_consumes_stock"("orders"."estado", "orders"."payment_status"))
UNION ALL
 SELECT "sales"."product_id",
    "sales"."variant_id",
    "sales"."sale_date" AS "movement_date",
    "sales"."created_at" AS "recorded_at",
    'external_sale'::"text" AS "source",
    ("sales"."id")::"text" AS "source_id",
    (- ("sales"."quantity")::bigint) AS "quantity_delta",
    ('external_sale:'::"text" || ("sales"."id")::"text") AS "movement_id",
    'external_sale'::"text" AS "movement_type",
    'external_sales'::"text" AS "origin",
    (("sales"."sale_date")::timestamp without time zone AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text") AS "effective_at",
    "sales"."created_by" AS "responsible_user_id",
    'admin_external_sale'::"text" AS "responsible_process",
    ('external-sale:'::"text" || ("sales"."id")::"text") AS "idempotency_key",
    COALESCE(NULLIF("btrim"("sales"."reference"), ''::"text"), ("sales"."id")::"text") AS "document_reference"
   FROM "public"."external_sales" "sales"
  WHERE (("sales"."product_id" IS NOT NULL) AND ("sales"."status" <> 'reversed'::"text"))
UNION ALL
 SELECT "sales"."product_id",
    "public"."inventory_ml_variant_id"("sales"."raw_data") AS "variant_id",
    COALESCE((("sales"."sale_date" AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text"))::"date", (("sales"."imported_at" AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text"))::"date") AS "movement_date",
    "sales"."imported_at" AS "recorded_at",
    'mercadolibre_sale'::"text" AS "source",
    ("sales"."id")::"text" AS "source_id",
    (- ("public"."inventory_ml_stock_units"("sales"."quantity", "sales"."raw_data"))::bigint) AS "quantity_delta",
    ('mercadolibre_sale:'::"text" || ("sales"."id")::"text") AS "movement_id",
    'mercadolibre_sale'::"text" AS "movement_type",
    'mercadolibre_sales'::"text" AS "origin",
    COALESCE("sales"."sale_date", "sales"."imported_at") AS "effective_at",
    "sales"."imported_by" AS "responsible_user_id",
    'mercadolibre_import'::"text" AS "responsible_process",
    COALESCE("sales"."source_key", ('mercadolibre-sale:'::"text" || ("sales"."id")::"text")) AS "idempotency_key",
    COALESCE(NULLIF("btrim"("sales"."operation_id"), ''::"text"), NULLIF("btrim"("sales"."order_id"), ''::"text"), ("sales"."id")::"text") AS "document_reference"
   FROM "public"."mercadolibre_sales" "sales"
  WHERE (("sales"."product_id" IS NOT NULL) AND ("public"."inventory_ml_stock_units"("sales"."quantity", "sales"."raw_data") > 0))
UNION ALL
 SELECT "movements"."product_id",
    "movements"."variant_id",
    (("movements"."occurred_at" AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text"))::"date" AS "movement_date",
    "movements"."created_at" AS "recorded_at",
    'approved_return'::"text" AS "source",
    ("movements"."id")::"text" AS "source_id",
    ("movements"."sellable_quantity")::bigint AS "quantity_delta",
    ('approved_return:'::"text" || ("movements"."id")::"text") AS "movement_id",
    'return'::"text" AS "movement_type",
    'inventory_return_movements'::"text" AS "origin",
    COALESCE("movements"."occurred_at", "movements"."approved_at", "movements"."created_at") AS "effective_at",
    "movements"."approved_by" AS "responsible_user_id",
    'return_review'::"text" AS "responsible_process",
    "movements"."source_key" AS "idempotency_key",
    COALESCE(
        CASE
            WHEN ("movements"."mercadolibre_sale_id" IS NOT NULL) THEN ('mercadolibre-sale:'::"text" || ("movements"."mercadolibre_sale_id")::"text")
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("movements"."order_item_id" IS NOT NULL) THEN ('order-item:'::"text" || ("movements"."order_item_id")::"text")
            ELSE NULL::"text"
        END, ("movements"."id")::"text") AS "document_reference"
   FROM "public"."inventory_return_movements" "movements"
  WHERE ("movements"."sellable_quantity" <> 0)
UNION ALL
 SELECT "expenses"."product_id",
    "expenses"."variant_id",
    "expenses"."expense_date" AS "movement_date",
    "expenses"."created_at" AS "recorded_at",
    'product_expense'::"text" AS "source",
    ("expenses"."id")::"text" AS "source_id",
    (- ("expenses"."quantity")::bigint) AS "quantity_delta",
    ('product_expense:'::"text" || ("expenses"."id")::"text") AS "movement_id",
    'write_off'::"text" AS "movement_type",
    'business_expenses'::"text" AS "origin",
    (("expenses"."expense_date")::timestamp without time zone AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text") AS "effective_at",
    "expenses"."created_by" AS "responsible_user_id",
    'admin_product_expense'::"text" AS "responsible_process",
    COALESCE("expenses"."idempotency_key", ('product-expense:'::"text" || ("expenses"."id")::"text")) AS "idempotency_key",
    COALESCE(NULLIF("btrim"("expenses"."document_number"), ''::"text"), ("expenses"."id")::"text") AS "document_reference"
   FROM "public"."business_expenses" "expenses"
  WHERE (("expenses"."expense_type" = 'product'::"text") AND ("expenses"."product_id" IS NOT NULL) AND ("expenses"."quantity" IS NOT NULL))
UNION ALL
 SELECT "adjustments"."product_id",
    "adjustments"."variant_id",
    "adjustments"."adjustment_date" AS "movement_date",
    "adjustments"."created_at" AS "recorded_at",
    'stock_adjustment'::"text" AS "source",
    ("adjustments"."id")::"text" AS "source_id",
    ("adjustments"."quantity_delta")::bigint AS "quantity_delta",
    ('stock_adjustment:'::"text" || ("adjustments"."id")::"text") AS "movement_id",
    'adjustment'::"text" AS "movement_type",
    'inventory_stock_adjustments'::"text" AS "origin",
    "adjustments"."created_at" AS "effective_at",
    "adjustments"."created_by" AS "responsible_user_id",
    'admin_stock_adjustment'::"text" AS "responsible_process",
    COALESCE("adjustments"."idempotency_key", ('stock-adjustment:'::"text" || ("adjustments"."id")::"text")) AS "idempotency_key",
    "adjustments"."reason" AS "document_reference"
   FROM "public"."inventory_stock_adjustments" "adjustments"
  WHERE ("adjustments"."quantity_delta" <> 0);


ALTER VIEW "public"."inventory_movements" OWNER TO "postgres";

