--
-- Name: inventory_stock_integrity; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_stock_integrity" WITH ("security_invoker"='true') AS
 SELECT "products"."id" AS "product_id",
    "products"."nombre" AS "product_name",
    ("products"."stock")::bigint AS "stored_normal_stock",
    (COALESCE("ledger"."normal_stock", (0)::numeric))::bigint AS "calculated_normal_stock",
    COALESCE("variants"."stored_stock", (0)::bigint) AS "stored_variant_stock",
    (COALESCE("variants"."expected_stock", (0)::numeric))::bigint AS "calculated_variant_stock",
    (COALESCE("generic"."balance", (0)::numeric))::bigint AS "generic_balance",
    COALESCE("allocations"."quantity", (0)::bigint) AS "allocated_quantity",
    (GREATEST(((COALESCE("allocations"."quantity", (0)::bigint))::numeric - GREATEST(COALESCE("generic"."balance", (0)::numeric), (0)::numeric)), (0)::numeric))::bigint AS "allocation_overflow",
    (GREATEST((GREATEST(COALESCE("generic"."balance", (0)::numeric), (0)::numeric) - (COALESCE("allocations"."quantity", (0)::bigint))::numeric), (0)::numeric))::bigint AS "unassigned_quantity",
    COALESCE("conditioned"."available", (0)::bigint) AS "discounted_stock",
    COALESCE("returns"."non_sellable", (0)::bigint) AS "non_sellable_stock",
    COALESCE("returns"."pending_review", (0)::bigint) AS "pending_review_stock",
    ((((COALESCE("ledger"."normal_stock", (0)::numeric) + (COALESCE("conditioned"."available", (0)::bigint))::numeric) + (COALESCE("returns"."non_sellable", (0)::bigint))::numeric) + (COALESCE("returns"."pending_review", (0)::bigint))::numeric))::bigint AS "physical_stock",
    "array_remove"(ARRAY[
        CASE
            WHEN (("products"."stock")::numeric IS DISTINCT FROM COALESCE("ledger"."normal_stock", (0)::numeric)) THEN 'PRODUCT_STOCK_MISMATCH'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ((COALESCE("variants"."stored_stock", (0)::bigint))::numeric IS DISTINCT FROM COALESCE("variants"."expected_stock", (0)::numeric)) THEN 'VARIANT_STOCK_MISMATCH'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ((COALESCE("allocations"."quantity", (0)::bigint))::numeric > GREATEST(COALESCE("generic"."balance", (0)::numeric), (0)::numeric)) THEN 'ALLOCATION_OVERFLOW'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("products"."sku" IS NOT NULL) AND (COALESCE("variants"."count", (0)::bigint) > 0)) THEN 'PRODUCT_AND_VARIANT_SKU'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "issues"
   FROM (((((("public"."productos" "products"
     LEFT JOIN LATERAL ( SELECT "sum"("movements"."quantity_delta") AS "normal_stock"
           FROM "public"."inventory_movements" "movements"
          WHERE (("movements"."product_id" = "products"."id") AND ("movements"."movement_date" <= CURRENT_DATE))) "ledger" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("movements"."quantity_delta") AS "balance"
           FROM "public"."inventory_movements" "movements"
          WHERE (("movements"."product_id" = "products"."id") AND ("movements"."variant_id" IS NULL) AND ("movements"."movement_date" <= CURRENT_DATE))) "generic" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("items"."quantity") AS "quantity"
           FROM "public"."inventory_variant_allocations" "items"
          WHERE ("items"."product_id" = "products"."id")) "allocations" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "count",
            "sum"("variant"."stock") AS "stored_stock",
            "sum"((COALESCE(( SELECT "sum"("movements"."quantity_delta") AS "sum"
                   FROM "public"."inventory_movements" "movements"
                  WHERE (("movements"."product_id" = "products"."id") AND ("movements"."variant_id" = "variant"."id") AND ("movements"."movement_date" <= CURRENT_DATE))), (0)::numeric) + (COALESCE(( SELECT "allocation"."quantity"
                   FROM "public"."inventory_variant_allocations" "allocation"
                  WHERE ("allocation"."variant_id" = "variant"."id")), 0))::numeric)) AS "expected_stock"
           FROM "public"."producto_variantes" "variant"
          WHERE ("variant"."producto_id" = "products"."id")) "variants" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("offers"."available_quantity") AS "available"
           FROM "public"."conditioned_inventory_offers" "offers"
          WHERE ("offers"."product_id" = "products"."id")) "conditioned" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("movements"."non_sellable_quantity") AS "non_sellable",
            "sum"(GREATEST(((("movements"."received_quantity" - "movements"."sellable_quantity") - "movements"."discounted_quantity") - "movements"."non_sellable_quantity"), 0)) AS "pending_review"
           FROM "public"."inventory_return_movements" "movements"
          WHERE ("movements"."product_id" = "products"."id")) "returns" ON (true));


ALTER VIEW "public"."inventory_stock_integrity" OWNER TO "postgres";

--
-- Name: VIEW "inventory_stock_integrity"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW "public"."inventory_stock_integrity" IS 'Conciliación derivada entre libro, stock almacenado, variantes, devoluciones y distribución.';


--
-- Name: inventory_variant_diagnostics; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_variant_diagnostics" WITH ("security_invoker"='true') AS
 SELECT "products"."id" AS "product_id",
    "products"."nombre" AS "product_name",
    "variants"."id" AS "variant_id",
    "variants"."nombre" AS "variant_name",
    "variants"."sku" AS "variant_sku",
    ("variants"."stock")::bigint AS "actual_stock",
    (COALESCE("allocations"."quantity", 0) + COALESCE("variant_movements"."balance", (0)::bigint)) AS "calculated_stock",
    GREATEST(LEAST((COALESCE("allocations"."quantity", 0))::bigint, COALESCE("historical_returns"."quantity", (0)::bigint), COALESCE("integrity"."allocation_overflow", (0)::bigint)), (0)::bigint) AS "duplicated_allocation",
    ((COALESCE("allocations"."quantity", 0) + COALESCE("variant_movements"."balance", (0)::bigint)) - GREATEST(LEAST((COALESCE("allocations"."quantity", 0))::bigint, COALESCE("historical_returns"."quantity", (0)::bigint), COALESCE("integrity"."allocation_overflow", (0)::bigint)), (0)::bigint)) AS "expected_stock",
    ("variants"."stock" - ((COALESCE("allocations"."quantity", 0) + COALESCE("variant_movements"."balance", (0)::bigint)) - GREATEST(LEAST((COALESCE("allocations"."quantity", 0))::bigint, COALESCE("historical_returns"."quantity", (0)::bigint), COALESCE("integrity"."allocation_overflow", (0)::bigint)), (0)::bigint))) AS "difference",
    (COALESCE("allocations"."quantity", 0))::bigint AS "allocation_quantity",
    COALESCE("integrity"."generic_balance", (0)::bigint) AS "generic_balance",
    COALESCE("integrity"."allocation_overflow", (0)::bigint) AS "allocation_overflow",
    "historical_returns"."movement_id" AS "possible_cause_movement_id",
    "historical_returns"."occurred_at" AS "possible_cause_at",
        CASE
            WHEN ((COALESCE("integrity"."allocation_overflow", (0)::bigint) > 0) AND (COALESCE("historical_returns"."quantity", (0)::bigint) > 0)) THEN 'Devolución normal vinculada después de quedar incluida en la asignación inicial.'::"text"
            WHEN (COALESCE("integrity"."allocation_overflow", (0)::bigint) > 0) THEN 'La asignación por variante supera el saldo genérico disponible.'::"text"
            WHEN ("variants"."stock" IS DISTINCT FROM (COALESCE("allocations"."quantity", 0) + COALESCE("variant_movements"."balance", (0)::bigint))) THEN 'El stock almacenado no coincide con el libro derivado.'::"text"
            ELSE NULL::"text"
        END AS "possible_cause",
    "integrity"."issues"
   FROM ((((("public"."productos" "products"
     JOIN "public"."producto_variantes" "variants" ON (("variants"."producto_id" = "products"."id")))
     LEFT JOIN "public"."inventory_stock_integrity" "integrity" ON (("integrity"."product_id" = "products"."id")))
     LEFT JOIN "public"."inventory_variant_allocations" "allocations" ON ((("allocations"."product_id" = "products"."id") AND ("allocations"."variant_id" = "variants"."id"))))
     LEFT JOIN LATERAL ( SELECT (COALESCE("sum"("movements"."quantity_delta"), (0)::numeric))::bigint AS "balance"
           FROM "public"."inventory_movements" "movements"
          WHERE (("movements"."product_id" = "products"."id") AND ("movements"."variant_id" = "variants"."id") AND ("movements"."movement_date" <= CURRENT_DATE))) "variant_movements" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("returns"."sellable_quantity") AS "quantity",
            ("array_agg"("returns"."id" ORDER BY COALESCE("returns"."occurred_at", "returns"."approved_at", "returns"."created_at") DESC))[1] AS "movement_id",
            "max"(COALESCE("returns"."occurred_at", "returns"."approved_at", "returns"."created_at")) AS "occurred_at"
           FROM "public"."inventory_return_movements" "returns"
          WHERE (("returns"."product_id" = "products"."id") AND ("returns"."variant_id" = "variants"."id") AND ("returns"."sellable_quantity" > 0) AND (COALESCE("returns"."approved_at", "returns"."created_at") <= COALESCE("allocations"."updated_at", "variants"."created_at")))) "historical_returns" ON (true));


ALTER VIEW "public"."inventory_variant_diagnostics" OWNER TO "postgres";

--
-- Name: VIEW "inventory_variant_diagnostics"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW "public"."inventory_variant_diagnostics" IS 'Compara stock esperado y actual e identifica devoluciones incluidas dos veces en asignaciones.';


--
-- Name: repair_inventory_allocation_overflow(bigint, bigint, boolean, "uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."repair_inventory_allocation_overflow"("p_product_id" bigint, "p_variant_id" bigint, "p_confirm" boolean, "p_actor_id" "uuid", "p_idempotency_key" "text", "p_document_reference" "text") RETURNS SETOF "public"."inventory_variant_diagnostics"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_diagnostic public.inventory_variant_diagnostics%rowtype;
  v_before public.inventory_variant_allocations%rowtype;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_reference text := nullif(btrim(coalesce(p_document_reference, '')), '');
begin
  if not coalesce(p_confirm, false) then
    raise exception 'REPAIR_CONFIRMATION_REQUIRED';
  end if;
  if v_key is null or length(v_key) < 8 or length(v_key) > 240
     or v_reference is null then
    raise exception 'Los datos de reparación no son válidos.';
  end if;

  perform pg_advisory_xact_lock(hashtext('inventory-repair'), hashtext(v_key));
  perform pg_advisory_xact_lock(93000, p_product_id::integer);

  select * into v_diagnostic
  from public.inventory_variant_diagnostics diagnostics
  where diagnostics.product_id = p_product_id
    and diagnostics.variant_id = p_variant_id;
  if not found then raise exception 'No existe el diagnóstico solicitado.'; end if;

  if exists (
    select 1 from public.inventory_operation_log operations
    where operations.idempotency_key = v_key
  ) then
    return query
    select * from public.inventory_variant_diagnostics diagnostics
    where diagnostics.product_id = p_product_id
      and diagnostics.variant_id = p_variant_id;
    return;
  end if;

  if v_diagnostic.duplicated_allocation <= 0
     or v_diagnostic.possible_cause_movement_id is null then
    raise exception 'La diferencia no tiene un movimiento duplicado demostrable.';
  end if;

  select * into v_before
  from public.inventory_variant_allocations allocations
  where allocations.product_id = p_product_id
    and allocations.variant_id = p_variant_id
  for update;
  if not found or v_before.quantity < v_diagnostic.duplicated_allocation then
    raise exception 'La asignación cambió; volvé a ejecutar el diagnóstico.';
  end if;

  update public.inventory_variant_allocations allocations
  set quantity = quantity - v_diagnostic.duplicated_allocation,
      updated_by = p_actor_id,
      updated_at = now()
  where allocations.product_id = p_product_id
    and allocations.variant_id = p_variant_id;

  perform public.refresh_inventory_stock(p_product_id);

  insert into public.inventory_operation_log (
    product_id, variant_id, movement_type, quantity, origin, effective_at,
    actor_user_id, actor_process, idempotency_key, source_table, source_id,
    document_reference, metadata
  ) values (
    p_product_id,
    p_variant_id,
    'repair',
    v_diagnostic.duplicated_allocation,
    'inventory_integrity_diagnostic',
    now(),
    p_actor_id,
    'repair_inventory_allocation_overflow',
    v_key,
    'inventory_return_movements',
    v_diagnostic.possible_cause_movement_id::text,
    v_reference,
    jsonb_build_object(
      'physicalDelta', 0,
      'allocationBefore', v_before.quantity,
      'allocationAfter', v_before.quantity - v_diagnostic.duplicated_allocation,
      'expectedStock', v_diagnostic.expected_stock,
      'actualStockBefore', v_diagnostic.actual_stock,
      'cause', v_diagnostic.possible_cause
    )
  );

  insert into public.audit_logs (
    table_name, action, record_id, actor_user_id, before_data, after_data
  ) values (
    'inventory_variant_allocations',
    'UPDATE',
    p_product_id::text || ':' || p_variant_id::text,
    p_actor_id,
    to_jsonb(v_before),
    jsonb_build_object(
      'product_id', p_product_id,
      'variant_id', p_variant_id,
      'quantity', v_before.quantity - v_diagnostic.duplicated_allocation,
      'repairKey', v_key,
      'causeMovementId', v_diagnostic.possible_cause_movement_id
    )
  );

  return query
  select * from public.inventory_variant_diagnostics diagnostics
  where diagnostics.product_id = p_product_id
    and diagnostics.variant_id = p_variant_id;
end;
$$;


ALTER FUNCTION "public"."repair_inventory_allocation_overflow"("p_product_id" bigint, "p_variant_id" bigint, "p_confirm" boolean, "p_actor_id" "uuid", "p_idempotency_key" "text", "p_document_reference" "text") OWNER TO "postgres";

--
-- Name: request_customer_order_cancellation_with_claim(bigint, "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."request_customer_order_cancellation_with_claim"("p_order_id" bigint, "p_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_claim public.order_claims%rowtype;
  v_now timestamptz := now();
  v_payment_confirmed boolean;
  v_proof_pending boolean;
  v_invoiced boolean;
  v_next_financial_status text;
  v_previous_financial_status text;
  v_affected_items jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para cancelar esta compra.';
  end if;

  if p_order_id is null or p_user_id is null
     or length(trim(coalesce(p_reason, ''))) not between 5 and 600 then
    raise exception 'INVALID_CANCELLATION_REQUEST';
  end if;

  select * into v_order
  from public.ordenes
  where id = p_order_id
    and usuario_id = p_user_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if lower(coalesce(v_order.estado, '')) = 'cancelado'
     or lower(coalesce(v_order.financial_status, '')) in (
       'cancelled', 'refund_pending', 'refunded'
     ) then
    raise exception 'ORDER_ALREADY_CANCELLED';
  end if;

  -- Guard de creación Andreani en curso / conciliación pendiente -- sin
  -- cambios respecto a 20260916100000.
  if v_order.andreani_creation_status = 'claimed' then
    raise exception 'ANDREANI_CREATION_IN_PROGRESS';
  end if;
  if v_order.andreani_creation_status = 'reconciliation_required' then
    raise exception 'ANDREANI_RECONCILIATION_REQUIRED';
  end if;

  if lower(coalesce(v_order.estado, '')) in (
       'enviado', 'en_camino', 'visita_fallida', 'en_sucursal',
       'retiro_pendiente', 'retiro_vencido', 'en_devolucion',
       'devuelto_beyonix', 'entregado'
     )
     or nullif(btrim(coalesce(v_order.tracking_number, '')), '') is not null
     or nullif(btrim(coalesce(v_order.andreani_tracking, '')), '') is not null
     or nullif(btrim(coalesce(v_order.andreani_envio_id, '')), '') is not null then
    raise exception 'ORDER_ALREADY_DISPATCHED';
  end if;

  v_payment_confirmed :=
    v_order.paid_at is not null
    or coalesce(v_order.payment_confirmed_amount, 0) > 0
    or lower(coalesce(v_order.payment_status, '')) in (
      'confirmado', 'approved', 'confirmed'
    )
    or lower(coalesce(v_order.financial_status, '')) = 'payment_confirmed';
  v_proof_pending :=
    nullif(btrim(coalesce(v_order.payment_proof_url, '')), '') is not null
    and lower(coalesce(v_order.payment_status, '')) in (
      'en_revision', 'pendiente_comprobante', 'pending'
    );
  -- FIX 2/2: `invoice_status in (...)` con invoice_status NULL (pedido
  -- pagado, todavía no facturado) evaluaba a NULL y propagaba NULL hasta
  -- credit_note_required (NOT NULL) -- ver el comentario de cabecera.
  v_invoiced :=
    coalesce(v_order.invoice_status, '') in ('authorized', 'processing')
    or v_order.invoice_cae is not null
    or (v_order.invoice_number is not null and v_order.invoice_point is not null);
  v_next_financial_status := case
    when v_payment_confirmed then 'refund_pending'
    when v_proof_pending then 'cancellation_requested'
    else 'cancelled'
  end;
  v_previous_financial_status := coalesce(
    v_order.financial_status,
    v_order.payment_status,
    'pending_payment'
  );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'order_item_id', oi.id,
        'quantity', oi.cantidad
      ) order by oi.id
    ),
    '[]'::jsonb
  ) into v_affected_items
  from public.orden_items oi
  where oi.orden_id = v_order.id;

  insert into public.order_claims (
    order_id,
    user_id,
    claim_type,
    status,
    failure_type,
    started_at,
    description,
    resolution,
    offered_resolutions,
    admin_needs_action,
    last_customer_message_at,
    affected_items,
    closed_at
  ) values (
    v_order.id,
    p_user_id,
    'transporte_48hs',
    case
      when v_payment_confirmed then 'reintegro_pendiente'
      when v_proof_pending then 'en_revision'
      else 'cerrado'
    end,
    'cancelar_compra',
    v_now,
    trim(p_reason),
    case when v_payment_confirmed then 'reintegro_total' else 'otro' end,
    -- FIX 1/2: offered_resolutions es text[] en la base real, no jsonb.
    '{}'::text[],
    v_payment_confirmed or v_proof_pending,
    v_now,
    v_affected_items,
    case when not v_payment_confirmed and not v_proof_pending then v_now else null end
  )
  returning * into v_claim;

  update public.ordenes
  set
    estado = 'cancelado',
    cancelled_at = v_now,
    financial_status = v_next_financial_status,
    cancellation_requested_at = v_now,
    cancellation_requested_by = p_user_id,
    refund_pending_at = case when v_payment_confirmed then v_now else null end,
    credit_note_required = v_payment_confirmed and v_invoiced
  where id = v_order.id
  returning * into v_order;

  if coalesce(v_order.credit_balance_used, 0) > 0 then
    perform *
    from public.reverse_customer_credit_for_order(
      v_order.id,
      'Reintegro de saldo por cancelación de compra',
      p_user_id
    );
  end if;

  insert into public.order_audit_events (
    order_id,
    actor_type,
    actor_id,
    action,
    previous_status,
    new_status,
    metadata
  ) values (
    v_order.id,
    'customer',
    p_user_id,
    case
      when v_payment_confirmed then 'cancellation_requested_refund_pending'
      else 'cancellation_requested'
    end,
    v_previous_financial_status,
    v_next_financial_status,
    jsonb_build_object(
      'claimId', v_claim.id,
      'cancellationReason', trim(p_reason),
      'invoiceIssued', v_invoiced,
      'creditNoteRequired', v_payment_confirmed and v_invoiced,
      'source', 'customer_cancellation'
    )
  );

  insert into public.order_claim_messages (
    claim_id,
    author_user_id,
    author_role,
    message
  ) values (
    v_claim.id,
    p_user_id,
    'cliente',
    trim(p_reason)
  );

  return to_jsonb(v_order) || jsonb_build_object('claim_id', v_claim.id);
end;
$$;


ALTER FUNCTION "public"."request_customer_order_cancellation_with_claim"("p_order_id" bigint, "p_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "request_customer_order_cancellation_with_claim"("p_order_id" bigint, "p_user_id" "uuid", "p_reason" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."request_customer_order_cancellation_with_claim"("p_order_id" bigint, "p_user_id" "uuid", "p_reason" "text") IS 'Cancela una orden no despachada y crea atómicamente el claim comercial del cliente. Bloquea si hay una creación Andreani en curso (claimed) o con resultado externo incierto (reconciliation_required). Fix 20260917110000: offered_resolutions es text[] (no jsonb) y v_invoiced ya no propaga NULL cuando invoice_status es NULL.';


--
-- Name: require_formal_claim_for_return_inventory(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."require_formal_claim_for_return_inventory"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if (
    new.return_restocked_quantity is distinct from old.return_restocked_quantity
    or new.return_written_off_quantity is distinct from old.return_written_off_quantity
    or new.return_inventory_note is distinct from old.return_inventory_note
    or new.return_inventory_processed_at is distinct from old.return_inventory_processed_at
    or new.return_inventory_processed_by is distinct from old.return_inventory_processed_by
  ) and not exists (
    select 1
    from public.order_claims
    where order_claims.order_id = new.orden_id
      and order_claims.failure_type is not null
      and order_claims.failure_type not in ('cancelar_compra', 'consulta_pedido')
  ) then
    raise exception 'No se puede modificar el inventario sin un reclamo formal asociado al pedido.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."require_formal_claim_for_return_inventory"() OWNER TO "postgres";

--
-- Name: FUNCTION "require_formal_claim_for_return_inventory"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."require_formal_claim_for_return_inventory"() IS 'Impide registrar devoluciones o bajas de inventario en pedidos sin reclamo formal.';


--
-- Name: reserve_cart_stock("text", "jsonb"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reserve_cart_stock"("p_session_id" "text", "p_items" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item record;
  v_product_id bigint;
  v_available integer;
  v_expiry timestamptz := now() + public.checkout_reservation_ttl();
begin
  if length(btrim(coalesce(p_session_id, ''))) < 8
     or length(p_session_id) > 160
     or p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     -- Tope defensivo: esta función la llama directo anon/authenticated: sin
     -- límite, un payload con miles de elementos es un vector de DoS barato
     -- contra la base (cada elemento dispara un advisory lock y una fila).
     or jsonb_array_length(p_items) > 50 then
    raise exception 'RESERVATION_INVALID';
  end if;

  -- Cada línea cruda tiene que ser una cantidad positiva ANTES de agrupar:
  -- agrupar por producto/variante suma cantidades, así que una línea
  -- negativa podría compensarse con otra positiva y esconderse detrás de un
  -- total agregado que parece válido (ej. -999999 + 1000000 = 1).
  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    where coalesce(nullif(item ->> 'quantity', '')::integer, 0) <= 0
  ) then
    raise exception 'RESERVATION_INVALID';
  end if;

  -- Secuestro de sesión: si esta sesión ya tiene una reserva activa atada a
  -- OTRO usuario autenticado, no se pisa. La sesión anónima -> mismo usuario
  -- (login a mitad de compra) sigue permitida porque el user_id previo es
  -- null. Sólo se puede llegar acá si el session_id de otra persona se
  -- adivinó/filtró -- con crypto.randomUUID() del lado del cliente es
  -- computacionalmente inviable, pero la guarda no cuesta nada tenerla.
  if exists (
    select 1 from public.stock_reservations reservations
    where reservations.session_id = p_session_id
      and reservations.expires_at > now()
      and reservations.user_id is not null
      and reservations.user_id is distinct from auth.uid()
  ) then
    raise exception 'RESERVATION_SESSION_MISMATCH';
  end if;

  perform public.purge_expired_stock_reservations();

  -- Se bloquean también los productos que esta sesión ya tenía reservados
  -- aunque hayan salido del carrito: liberarlos es parte de la misma
  -- operación atómica.
  for v_product_id in
    select distinct product_id from (
      select coalesce(
        nullif(item ->> 'productId', '')::bigint,
        nullif(item ->> 'product_id', '')::bigint
      ) as product_id
      from jsonb_array_elements(p_items) item
      union
      select reservations.product_id
      from public.stock_reservations reservations
      where reservations.session_id = p_session_id
    ) targets
    order by 1
  loop
    if v_product_id is null then raise exception 'RESERVATION_INVALID'; end if;
    perform pg_advisory_xact_lock(93000, v_product_id::integer);
  end loop;

  delete from public.stock_reservations reservations
  where reservations.session_id = p_session_id;

  for v_item in
    select
      coalesce(
        nullif(item ->> 'productId', '')::bigint,
        nullif(item ->> 'product_id', '')::bigint
      ) as product_id,
      coalesce(
        nullif(item ->> 'variantId', '')::bigint,
        nullif(item ->> 'variant_id', '')::bigint
      ) as variant_id,
      coalesce(
        nullif(item ->> 'conditionedStockId', '')::uuid,
        nullif(item ->> 'conditioned_stock_id', '')::uuid
      ) as conditioned_stock_id,
      sum(coalesce(nullif(item ->> 'quantity', '')::integer, 0))::integer
        as quantity
    from jsonb_array_elements(p_items) item
    group by 1, 2, 3
    order by 1, 2 nulls first, 3 nulls first
  loop
    if v_item.product_id is null or v_item.quantity <= 0
       or (v_item.variant_id is not null and v_item.conditioned_stock_id is not null) then
      raise exception 'RESERVATION_INVALID';
    end if;

    if v_item.variant_id is null and v_item.conditioned_stock_id is null
       and exists (
         select 1 from public.producto_variantes variants
         where variants.producto_id = v_item.product_id and variants.activo
       ) then
      raise exception 'CHECKOUT_VARIANT_REQUIRED';
    end if;

    v_available := public.available_stock_for_session(
      v_item.product_id,
      v_item.variant_id,
      v_item.conditioned_stock_id,
      p_session_id
    );

    if v_available is null or v_available < v_item.quantity then
      raise exception 'CHECKOUT_STOCK_INSUFFICIENT';
    end if;

    insert into public.stock_reservations (
      session_id, user_id, product_id, variant_id,
      conditioned_stock_id, quantity, expires_at
    ) values (
      p_session_id, auth.uid(), v_item.product_id, v_item.variant_id,
      v_item.conditioned_stock_id, v_item.quantity, v_expiry
    );
  end loop;

  return jsonb_build_object('reserved', true, 'expires_at', v_expiry);
end;
$$;


ALTER FUNCTION "public"."reserve_cart_stock"("p_session_id" "text", "p_items" "jsonb") OWNER TO "postgres";

--
-- Name: resolve_andreani_reconciliation(bigint, "uuid", "text", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."resolve_andreani_reconciliation"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_resolution" "text", "p_envio_id" "text", "p_tracking" "text", "p_etiqueta_url" "text", "p_notes" "text") RETURNS "public"."ordenes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_resolution text;
  v_envio_id text;
  v_tracking text;
  v_etiqueta_url text;
  v_notes text;
  v_previous_status text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para conciliar este pedido.';
  end if;

  -- Deliberadamente más angosto que admin_cancel_order (que sí admite
  -- 'operador'): pedido explícito de la auditoría -- "sólo admin/super_admin
  -- según roles reales" para esta operación específica.
  if p_admin_id is null or coalesce(p_admin_role, '') not in ('admin', 'super_admin') then
    raise exception 'ANDREANI_RECONCILIATION_FORBIDDEN';
  end if;

  v_resolution := lower(coalesce(p_resolution, ''));
  if v_resolution not in ('created', 'not_created') then
    raise exception 'ANDREANI_RECONCILIATION_INVALID_RESOLUTION';
  end if;

  v_notes := nullif(trim(coalesce(p_notes, '')), '');
  if v_notes is null or length(v_notes) < 5 or length(v_notes) > 1000 then
    raise exception 'ANDREANI_RECONCILIATION_INVALID_NOTES';
  end if;

  select * into v_order from public.ordenes where id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  -- Self-heal de un claim vencido de ESTE pedido específico, misma
  -- semántica y misma función que ya usa claim_andreani_shipment_creation --
  -- nunca toca un claim todavía fresco (sweep_stale_andreani_claims() sólo
  -- mueve claims con más de 5 minutos). Se re-lee la fila porque el sweep
  -- pudo haberla cambiado.
  perform public.sweep_stale_andreani_claims();
  select * into v_order from public.ordenes where id = p_order_id for update;

  v_previous_status := v_order.andreani_creation_status;

  if v_order.andreani_creation_status is distinct from 'reconciliation_required' then
    raise exception 'ANDREANI_RECONCILIATION_NOT_PENDING';
  end if;

  if v_resolution = 'created' then
    v_envio_id := nullif(trim(coalesce(p_envio_id, '')), '');
    if v_envio_id is null or length(v_envio_id) > 100 then
      raise exception 'ANDREANI_RECONCILIATION_INVALID_ENVIO_ID';
    end if;
    v_tracking := nullif(trim(coalesce(p_tracking, '')), '');
    if v_tracking is not null and length(v_tracking) > 100 then
      raise exception 'ANDREANI_RECONCILIATION_INVALID_TRACKING';
    end if;
    v_etiqueta_url := nullif(trim(coalesce(p_etiqueta_url, '')), '');
    if v_etiqueta_url is not null and (
      length(v_etiqueta_url) > 2000 or v_etiqueta_url !~ '^https?://'
    ) then
      raise exception 'ANDREANI_RECONCILIATION_INVALID_LABEL_URL';
    end if;

    -- Nunca pisa un envío ya persistido por otra vía mientras tanto.
    if nullif(btrim(coalesce(v_order.andreani_envio_id, '')), '') is not null then
      raise exception 'ANDREANI_SHIPMENT_ALREADY_PERSISTED';
    end if;

    update public.ordenes
    set
      andreani_envio_id = v_envio_id,
      andreani_tracking = coalesce(v_tracking, andreani_tracking),
      andreani_etiqueta_url = coalesce(v_etiqueta_url, andreani_etiqueta_url),
      andreani_creation_status = 'created',
      andreani_creation_claim_token = null,
      andreani_error = null
    where id = v_order.id
      and andreani_creation_status = 'reconciliation_required'
      and nullif(btrim(coalesce(andreani_envio_id, '')), '') is null
    returning * into v_order;

    if not found then
      raise exception 'ANDREANI_RECONCILIATION_CONFLICT';
    end if;
  else
    -- 'failed' es el mismo estado reintentable que ya acepta el WHERE de
    -- claim_andreani_shipment_creation -- no se inventa un estado nuevo.
    update public.ordenes
    set
      andreani_creation_status = 'failed',
      andreani_creation_claim_token = null,
      andreani_error = 'Conciliado manualmente: Andreani no llegó a crear el envío.'
    where id = v_order.id
      and andreani_creation_status = 'reconciliation_required'
    returning * into v_order;

    if not found then
      raise exception 'ANDREANI_RECONCILIATION_CONFLICT';
    end if;
  end if;

  insert into public.order_audit_events (
    order_id, actor_type, actor_id, action, previous_status, new_status, metadata
  ) values (
    v_order.id,
    'admin',
    p_admin_id,
    'andreani_reconciliation_resolved',
    v_previous_status,
    v_order.andreani_creation_status,
    jsonb_build_object(
      'resolution', v_resolution,
      'notes', v_notes,
      'envioId', case when v_resolution = 'created' then v_envio_id else null end,
      'tracking', case when v_resolution = 'created' then v_tracking else null end
    )
  );

  return v_order;
end;
$$;


ALTER FUNCTION "public"."resolve_andreani_reconciliation"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_resolution" "text", "p_envio_id" "text", "p_tracking" "text", "p_etiqueta_url" "text", "p_notes" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "resolve_andreani_reconciliation"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_resolution" "text", "p_envio_id" "text", "p_tracking" "text", "p_etiqueta_url" "text", "p_notes" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."resolve_andreani_reconciliation"("p_order_id" bigint, "p_admin_id" "uuid", "p_admin_role" "text", "p_resolution" "text", "p_envio_id" "text", "p_tracking" "text", "p_etiqueta_url" "text", "p_notes" "text") IS 'Único camino para resolver andreani_creation_status=reconciliation_required (o un claimed vencido de ese pedido): admin/super_admin confirma si Andreani creó el envío (created, con referencia real) o no (not_created, vuelve a failed/reintentable). Atómico, auditado, nunca pisa un envío ya persistido ni libera un claim fresco.';


--
-- Name: resolve_customer_credit_topup("uuid", "text", numeric, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."resolve_customer_credit_topup"("p_topup_id" "uuid", "p_action" "text", "p_amount" numeric DEFAULT NULL::numeric, "p_admin_notes" "text" DEFAULT NULL::"text", "p_resolved_by" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("topup_status" "text", "movement_id" "uuid", "resulting_balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_topup public.customer_credit_topups%rowtype;
  v_amount numeric(12, 2);
  v_movement_id uuid;
  v_resulting_balance numeric(12, 2);
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'No tenés permisos para resolver cargas de saldo.';
  end if;

  if p_action not in ('approve', 'reject') then
    raise exception 'INVALID_TOPUP_ACTION';
  end if;

  select *
  into v_topup
  from public.customer_credit_topups
  where id = p_topup_id
  for update;

  if not found then
    raise exception 'TOPUP_NOT_FOUND';
  end if;

  if v_topup.status <> 'en_revision' then
    raise exception 'TOPUP_ALREADY_RESOLVED';
  end if;

  if p_action = 'reject' then
    update public.customer_credit_topups
    set
      status = 'rechazado',
      admin_notes = coalesce(
        nullif(trim(coalesce(p_admin_notes, '')), ''),
        'Transferencia no recibida o comprobante inválido.'
      ),
      updated_at = now()
    where id = v_topup.id;

    topup_status := 'rechazado';
    movement_id := null;
    resulting_balance := public.get_customer_credit_balance(v_topup.user_id);
    return next;
    return;
  end if;

  v_amount := round(coalesce(p_amount, 0)::numeric, 2);

  if v_amount <= 0 then
    raise exception 'INVALID_TOPUP_AMOUNT';
  end if;

  select created.movement_id, created.resulting_balance
  into v_movement_id, v_resulting_balance
  from public.create_customer_credit_movement(
    p_user_id => v_topup.user_id,
    p_movement_type => 'credit',
    p_amount => v_amount,
    p_description => 'Carga de saldo por transferencia acreditada',
    p_source_type => 'admin_adjustment',
    p_source_id => v_topup.id::text,
    p_created_by => coalesce(p_resolved_by, auth.uid()),
    p_metadata => jsonb_build_object(
      'created_from', 'customer_credit_topup',
      'source_kind', 'balance_topup',
      'topup_id', v_topup.id
    ),
    p_source_key => 'customer-credit-topup:' || v_topup.id::text
  ) as created;

  update public.customer_credit_topups
  set
    amount = v_amount,
    status = 'acreditado',
    credited_movement_id = v_movement_id,
    admin_notes = nullif(trim(coalesce(p_admin_notes, '')), ''),
    updated_at = now()
  where id = v_topup.id;

  topup_status := 'acreditado';
  movement_id := v_movement_id;
  resulting_balance := v_resulting_balance;
  return next;
end;
$$;


ALTER FUNCTION "public"."resolve_customer_credit_topup"("p_topup_id" "uuid", "p_action" "text", "p_amount" numeric, "p_admin_notes" "text", "p_resolved_by" "uuid") OWNER TO "postgres";

--
-- Name: reverse_customer_credit_for_order(bigint, "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reverse_customer_credit_for_order"("p_order_id" bigint, "p_description" "text" DEFAULT 'Reintegro de saldo a favor por cancelación'::"text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("movement_id" "uuid", "restored_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_order public.ordenes%rowtype;
  v_amount numeric(12, 2);
  v_balance numeric(12, 2);
  v_source_key text;
  v_existing public.customer_credit_movements%rowtype;
  v_movement public.customer_credit_movements%rowtype;
  v_full_amount_due numeric(12, 2);
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'No tenés permisos para revertir saldo.';
  end if;

  if p_order_id is null then
    raise exception 'ORDER_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtext('order-credit-reversal:' || p_order_id::text));

  select *
  into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  v_amount := round(coalesce(v_order.credit_balance_used, 0)::numeric, 2);

  if v_order.usuario_id is null or v_amount <= 0 then
    movement_id := null;
    restored_amount := 0;
    return next;
    return;
  end if;

  v_source_key := 'order:' || p_order_id || ':customer-credit:reversal';

  select *
  into v_existing
  from public.customer_credit_movements
  where source_key = v_source_key
  limit 1;

  if found then
    movement_id := v_existing.id;
    restored_amount := v_existing.amount;
    return next;
    return;
  end if;

  select public.get_customer_credit_balance(v_order.usuario_id)
  into v_balance;

  insert into public.customer_credit_movements (
    user_id,
    movement_type,
    amount,
    description,
    source_type,
    source_id,
    order_id,
    created_by,
    related_movement_id,
    source_key,
    resulting_balance,
    metadata
  ) values (
    v_order.usuario_id,
    'reversal',
    v_amount,
    coalesce(nullif(trim(p_description), ''), 'Reintegro de saldo a favor por cancelación'),
    'reversal',
    p_order_id::text,
    p_order_id,
    p_created_by,
    v_order.credit_balance_movement_id,
    v_source_key,
    v_balance + v_amount,
    jsonb_build_object(
      'order_id', p_order_id,
      'reversed_movement_id', v_order.credit_balance_movement_id
    )
  )
  returning *
  into v_movement;

  -- El saldo ya volvió a la billetera: la orden deja de tener crédito
  -- aplicado y su pendiente vuelve a ser el total completo. Sin esto, un
  -- pago posterior por el monto reducido (external_amount_due viejo)
  -- confirmaría la orden sin haber cobrado la diferencia ya reintegrada.
  --
  -- payment_composition.parts también se resetea a '[]': lo arma
  -- getPaymentComposition() (lib/customer-credit.ts) sólo al crear la orden,
  -- con el label del medio de pago externo -- reproducir ese mapeo acá
  -- duplicaría esa lógica en SQL. Dejarlo con el desglose viejo ($30.000
  -- saldo + $70.000 MP) sería peor: quedaría contradiciendo a los campos de
  -- nivel superior de ese mismo JSON, que si se resetean a 0 / total
  -- completo. Ningún consumidor actual lee payment_composition.parts
  -- (verificado: sin matches en app/, components/, hooks/), así que vaciarlo
  -- no rompe ninguna pantalla existente.
  v_full_amount_due := greatest(coalesce(v_order.original_total, v_order.total, 0), 0);

  update public.ordenes
  set
    credit_balance_used = 0,
    external_amount_due = v_full_amount_due,
    credit_balance_movement_id = null,
    payment_composition = coalesce(payment_composition, '{}'::jsonb) ||
      jsonb_build_object(
        'credit_balance_used', 0,
        'external_amount_due', v_full_amount_due,
        'parts', '[]'::jsonb,
        'credit_movement_id', null,
        'credit_reversal_movement_id', v_movement.id
      )
  where id = p_order_id;

  movement_id := v_movement.id;
  restored_amount := v_movement.amount;
  return next;
end;
$_$;


ALTER FUNCTION "public"."reverse_customer_credit_for_order"("p_order_id" bigint, "p_description" "text", "p_created_by" "uuid") OWNER TO "postgres";

--
-- Name: reverse_customer_credit_topup("uuid", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reverse_customer_credit_topup"("p_topup_id" "uuid", "p_payment_id" "text", "p_payment_status" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS TABLE("topup_status" "text", "movement_id" "uuid", "resulting_balance" numeric, "shortfall_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_topup public.customer_credit_topups%rowtype;
  v_amount numeric(12, 2);
  v_balance numeric(12, 2);
  v_debit numeric(12, 2);
  v_shortfall numeric(12, 2);
  v_source_key text;
  v_existing public.customer_credit_movements%rowtype;
  v_movement public.customer_credit_movements%rowtype;
  v_movement_id uuid;
  v_notes text;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  if p_topup_id is null
     or nullif(trim(coalesce(p_payment_id, '')), '') is null
     or nullif(trim(coalesce(p_payment_status, '')), '') is null then
    raise exception 'INVALID_TOPUP_REVERSAL_REQUEST';
  end if;

  perform pg_advisory_xact_lock(hashtext('customer-credit-topup-reversal:' || p_topup_id::text));

  select *
  into v_topup
  from public.customer_credit_topups
  where id = p_topup_id
  for update;

  if not found then
    raise exception 'TOPUP_NOT_FOUND';
  end if;

  if v_topup.payment_method <> 'mercadopago' then
    raise exception 'INVALID_TOPUP_PAYMENT_METHOD';
  end if;

  -- Nunca llegó a acreditarse (rechazada/cancelada antes de aprobarse):
  -- no-op explícito, nada que revertir.
  if v_topup.status <> 'acreditado' and v_topup.status <> 'revertido' then
    topup_status := v_topup.status;
    movement_id := null;
    resulting_balance := public.get_customer_credit_balance(v_topup.user_id);
    shortfall_amount := 0;
    return next;
    return;
  end if;

  -- Ya revertida: idempotente ante reentregas del mismo webhook o varios
  -- eventos de reversa (refunded + charged_back) sobre el mismo topup.
  if v_topup.status = 'revertido' then
    topup_status := 'revertido';
    movement_id := v_topup.reversed_movement_id;
    resulting_balance := public.get_customer_credit_balance(v_topup.user_id);
    shortfall_amount := coalesce(v_topup.reversal_shortfall_amount, 0);
    return next;
    return;
  end if;

  v_amount := round(coalesce(v_topup.amount, 0)::numeric, 2);
  v_source_key := 'customer-credit-topup-mp-reversal:' || p_topup_id::text;

  select *
  into v_existing
  from public.customer_credit_movements
  where source_key = v_source_key
  limit 1;

  if found then
    update public.customer_credit_topups
    set
      status = 'revertido',
      mercadopago_payment_id = p_payment_id,
      mercadopago_status = p_payment_status,
      reversed_movement_id = v_existing.id,
      updated_at = now()
    where id = p_topup_id;

    topup_status := 'revertido';
    movement_id := v_existing.id;
    resulting_balance := public.get_customer_credit_balance(v_topup.user_id);
    shortfall_amount := coalesce(v_topup.reversal_shortfall_amount, 0);
    return next;
    return;
  end if;

  select public.get_customer_credit_balance(v_topup.user_id)
  into v_balance;

  -- Si el cliente ya gastó parte/todo el saldo, sólo se puede debitar lo
  -- disponible -- el resto queda como deuda/conflicto explícito, nunca
  -- oculto ni forzado a un saldo negativo.
  v_debit := least(v_amount, v_balance);
  v_shortfall := greatest(v_amount - v_balance, 0);

  if v_debit > 0 then
    insert into public.customer_credit_movements (
      user_id,
      movement_type,
      amount,
      description,
      source_type,
      source_id,
      created_by,
      related_movement_id,
      source_key,
      resulting_balance,
      metadata
    ) values (
      v_topup.user_id,
      'debit',
      v_debit,
      coalesce(
        nullif(trim(p_description), ''),
        'Reintegro/contracargo de Mercado Pago sobre carga de saldo (' || p_payment_status || ')'
      ),
      'reversal',
      p_topup_id::text,
      null,
      v_topup.credited_movement_id,
      v_source_key,
      greatest(v_balance - v_debit, 0),
      jsonb_build_object(
        'topup_id', p_topup_id,
        'mercadopago_payment_id', p_payment_id,
        'mercadopago_status', p_payment_status,
        'shortfall_amount', v_shortfall
      )
    )
    returning *
    into v_movement;

    v_movement_id := v_movement.id;
  else
    v_movement_id := null;
  end if;

  v_notes := trim(
    coalesce(v_topup.admin_notes, '') ||
    case
      when v_shortfall > 0 then
        E'\n[Reversa MP] El cliente ya había gastado el saldo: quedan $' ||
        v_shortfall::text ||
        ' sin recuperar (payment ' || p_payment_id || ', estado ' || p_payment_status || '). Requiere gestión de cobro/ajuste manual.'
      else ''
    end
  );

  update public.customer_credit_topups
  set
    status = 'revertido',
    mercadopago_payment_id = p_payment_id,
    mercadopago_status = p_payment_status,
    reversed_movement_id = v_movement_id,
    reversal_shortfall_amount = v_shortfall,
    admin_notes = nullif(v_notes, ''),
    updated_at = now()
  where id = p_topup_id;

  topup_status := 'revertido';
  movement_id := v_movement_id;
  resulting_balance := greatest(v_balance - v_debit, 0);
  shortfall_amount := v_shortfall;
  return next;
end;
$_$;


ALTER FUNCTION "public"."reverse_customer_credit_topup"("p_topup_id" "uuid", "p_payment_id" "text", "p_payment_status" "text", "p_description" "text") OWNER TO "postgres";

--
-- Name: reverse_external_sale("uuid", "text", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."reverse_external_sale"("p_id" "uuid", "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text") RETURNS "public"."external_sales"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sale public.external_sales%rowtype;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para reversar esta venta.';
  end if;

  if p_actor_id is null then
    raise exception 'EXTERNAL_SALE_REVERSAL_ACTOR_REQUIRED';
  end if;

  if v_key is null or length(v_key) < 8 or length(v_key) > 240 then
    raise exception 'IDEMPOTENCY_KEY_INVALID';
  end if;

  if v_reason is null or length(v_reason) < 10 then
    raise exception 'Indicá el motivo de la reversión (mínimo 10 caracteres).';
  end if;

  perform pg_advisory_xact_lock(hashtext('external-sale-reversal'), hashtext(p_id::text));

  select * into v_sale from public.external_sales where id = p_id for update;
  if not found then
    raise exception 'La venta externa ya no existe.';
  end if;

  if v_sale.status = 'reversed' then
    if v_sale.reversal_idempotency_key = v_key then
      return v_sale;
    end if;
    raise exception 'EXTERNAL_SALE_ALREADY_REVERSED';
  end if;

  if v_sale.product_id is not null then
    perform pg_advisory_xact_lock(93000, v_sale.product_id::integer);
  end if;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);

  update public.external_sales
  set status = 'reversed',
      reversed_at = now(),
      reversed_by = p_actor_id,
      reversal_reason = v_reason,
      reversal_amount = greatest(coalesce(v_sale.gross_amount, 0), 0),
      reversal_idempotency_key = v_key
  where id = p_id
  returning * into v_sale;

  return v_sale;
end;
$$;


ALTER FUNCTION "public"."reverse_external_sale"("p_id" "uuid", "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";

--
-- Name: FUNCTION "reverse_external_sale"("p_id" "uuid", "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."reverse_external_sale"("p_id" "uuid", "p_reason" "text", "p_actor_id" "uuid", "p_idempotency_key" "text") IS 'Reversión formal de una venta externa (cancelación/devolución real, no un error de tipeo): exige motivo, queda auditada, es idempotente y reintegra stock automáticamente vía el trigger refresh_inventory_after_external_sale + la exclusión de status=reversed en inventory_movements. Auditoría 5/7.';


--
-- Name: review_mercadolibre_return("uuid", integer, integer, integer, integer, numeric, "text", "text", "text", timestamp with time zone, "uuid", timestamp with time zone, "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."review_mercadolibre_return"("p_sale_id" "uuid", "p_received_quantity" integer, "p_sellable_quantity" integer, "p_discounted_quantity" integer, "p_non_sellable_quantity" integer, "p_discount_percent" numeric, "p_discount_reason" "text", "p_non_sellable_reason" "text", "p_notes" "text", "p_occurred_at" timestamp with time zone, "p_reviewed_by" "uuid", "p_expected_approved_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_correction_reason" "text" DEFAULT NULL::"text") RETURNS "public"."inventory_return_movements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sale public.mercadolibre_sales%rowtype;
  v_review public.inventory_return_movements%rowtype;
  v_previous jsonb;
  v_previous_approved_at timestamptz;
  v_notes text;
begin
  if p_received_quantity < 0
     or p_sellable_quantity < 0
     or p_discounted_quantity < 0
     or p_non_sellable_quantity < 0 then
    raise exception 'Las cantidades de la devolución no pueden ser negativas.';
  end if;

  if p_sellable_quantity
       + p_discounted_quantity
       + p_non_sellable_quantity
       > p_received_quantity then
    raise exception 'La clasificación supera las unidades recibidas.';
  end if;

  if p_discounted_quantity > 0 and (
    p_discount_percent is null
    or p_discount_percent <= 0
    or p_discount_percent >= 100
    or length(btrim(coalesce(p_discount_reason, ''))) < 3
  ) then
    raise exception 'Indicá el porcentaje y el motivo del descuento.';
  end if;

  if p_non_sellable_quantity > 0
     and length(btrim(coalesce(p_non_sellable_reason, ''))) < 3 then
    raise exception 'Indicá por qué las unidades no son vendibles.';
  end if;

  perform pg_advisory_xact_lock(hashtext('beyonix_ml_return'), hashtext(p_sale_id::text));

  select *
  into v_sale
  from public.mercadolibre_sales sales
  where sales.id = p_sale_id
  for update;

  if not found then
    raise exception 'La venta de Mercado Libre ya no existe.';
  end if;
  if v_sale.product_id is null then
    raise exception 'Primero vinculá la venta con un producto.';
  end if;
  perform pg_advisory_xact_lock(93000, v_sale.product_id::integer);
  if p_received_quantity > v_sale.quantity then
    raise exception 'No podés recibir más unidades que las vendidas.';
  end if;

  select to_jsonb(movements), movements.approved_at
  into v_previous, v_previous_approved_at
  from public.inventory_return_movements movements
  where movements.mercadolibre_sale_id = p_sale_id
  for update;

  -- Control optimista: nunca pisar en silencio un estado que el admin no
  -- vio. Primera revisión: no debe existir nada todavía. Corrección: el
  -- approved_at que el admin mandó tiene que coincidir con el vigente.
  if v_previous is null then
    if p_expected_approved_at is not null then
      raise exception 'ML_RETURN_CONFLICT';
    end if;
  else
    if p_expected_approved_at is null
       or p_expected_approved_at is distinct from v_previous_approved_at then
      raise exception 'ML_RETURN_CONFLICT';
    end if;
    if length(btrim(coalesce(p_correction_reason, ''))) < 3 then
      raise exception 'ML_RETURN_CORRECTION_REASON_REQUIRED';
    end if;
  end if;

  v_notes := nullif(left(trim(coalesce(p_notes, '')), 1000), '');
  if v_previous is not null and p_correction_reason is not null then
    v_notes := left(
      'Corrección: ' || btrim(p_correction_reason)
        || case when v_notes is not null then E'\n' || v_notes else '' end,
      1000
    );
  end if;

  -- El trigger genérico inventory_return_movements_audit_log_trigger (ver
  -- 20260920100000) ya audita este INSERT/UPDATE con before/after reales
  -- -- evita el insert manual duplicado que tenía esta función antes (mismo
  -- tipo de bug que se corrigió para force_delete_purchase_super_admin en
  -- la Auditoría 3/7). set_config le da el actor correcto vía auth.uid().
  perform set_config('beyonix.actor_id', p_reviewed_by::text, true);

  insert into public.inventory_return_movements (
    source_key,
    order_id,
    order_item_id,
    mercadolibre_sale_id,
    product_id,
    variant_id,
    quantity,
    received_quantity,
    sellable_quantity,
    discounted_quantity,
    non_sellable_quantity,
    discount_percent,
    discount_reason,
    non_sellable_reason,
    review_notes,
    occurred_at,
    approved_by,
    approved_at
  ) values (
    'mercadolibre-sale:' || v_sale.id::text,
    null,
    null,
    v_sale.id,
    v_sale.product_id,
    public.inventory_ml_variant_id(v_sale.raw_data),
    p_sellable_quantity,
    p_received_quantity,
    p_sellable_quantity,
    p_discounted_quantity,
    p_non_sellable_quantity,
    case when p_discounted_quantity > 0 then p_discount_percent else null end,
    case
      when p_discounted_quantity > 0
      then nullif(left(btrim(p_discount_reason), 300), '')
      else null
    end,
    case
      when p_non_sellable_quantity > 0
      then nullif(left(btrim(p_non_sellable_reason), 300), '')
      else null
    end,
    v_notes,
    coalesce(p_occurred_at, now()),
    p_reviewed_by,
    now()
  )
  on conflict (source_key) do update set
    quantity = excluded.quantity,
    received_quantity = excluded.received_quantity,
    sellable_quantity = excluded.sellable_quantity,
    discounted_quantity = excluded.discounted_quantity,
    non_sellable_quantity = excluded.non_sellable_quantity,
    discount_percent = excluded.discount_percent,
    discount_reason = excluded.discount_reason,
    non_sellable_reason = excluded.non_sellable_reason,
    review_notes = excluded.review_notes,
    occurred_at = excluded.occurred_at,
    approved_by = excluded.approved_by,
    approved_at = excluded.approved_at
  returning * into v_review;

  if exists (
    select 1 from public.productos products
    where products.id = v_sale.product_id and products.stock < 0
  ) or exists (
    select 1 from public.producto_variantes variants
    where variants.producto_id = v_sale.product_id and variants.stock < 0
  ) then
    raise exception
      'STOCK_INSUFICIENTE: la reclasificación consumiría stock ya vendido.';
  end if;

  return v_review;
end;
$$;


ALTER FUNCTION "public"."review_mercadolibre_return"("p_sale_id" "uuid", "p_received_quantity" integer, "p_sellable_quantity" integer, "p_discounted_quantity" integer, "p_non_sellable_quantity" integer, "p_discount_percent" numeric, "p_discount_reason" "text", "p_non_sellable_reason" "text", "p_notes" "text", "p_occurred_at" timestamp with time zone, "p_reviewed_by" "uuid", "p_expected_approved_at" timestamp with time zone, "p_correction_reason" "text") OWNER TO "postgres";

--
-- Name: save_product_purchase_atomic("jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."save_product_purchase_atomic"("p_purchase" "jsonb", "p_actor_id" "uuid") RETURNS "public"."product_cost_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid := nullif(p_purchase->>'id', '')::uuid;
  v_product_id bigint := nullif(p_purchase->>'product_id', '')::bigint;
  v_variant_id bigint := nullif(p_purchase->>'variant_id', '')::bigint;
  v_quantity integer := nullif(p_purchase->>'quantity', '')::integer;
  v_received integer := nullif(p_purchase->>'received_quantity', '')::integer;
  v_status text := coalesce(
    nullif(p_purchase->>'reception_status', ''),
    'recibida'
  );
  v_previous public.product_cost_entries%rowtype;
  v_saved public.product_cost_entries%rowtype;
  v_lock_product_id bigint;
begin
  if p_purchase is null or jsonb_typeof(p_purchase) <> 'object' then
    raise exception 'Los datos de la compra no son válidos.';
  end if;
  if v_quantity is null or v_quantity <= 0 then
    raise exception 'La cantidad comprada debe ser mayor que cero.';
  end if;
  if v_status not in ('pendiente', 'parcial', 'recibida', 'anulada') then
    raise exception 'El estado de recepción no es válido.';
  end if;

  v_received := case
    when v_status in ('pendiente', 'anulada') then 0
    when v_status = 'recibida' then v_quantity
    else coalesce(v_received, 0)
  end;
  if v_received < 0 or v_received > v_quantity then
    raise exception 'La cantidad recibida no puede superar la compra.';
  end if;
  if v_status = 'parcial'
     and (v_received <= 0 or v_received >= v_quantity) then
    raise exception 'La recepción parcial debe ser mayor que cero y menor que la compra.';
  end if;

  if v_id is not null then
    select * into v_previous
    from public.product_cost_entries entries
    where entries.id = v_id
    for update;
    if not found then
      raise exception 'La compra que querés editar ya no existe.';
    end if;
  end if;

  for v_lock_product_id in
    select distinct ids.product_id
    from unnest(array[v_previous.product_id, v_product_id]) ids(product_id)
    where ids.product_id is not null
    order by ids.product_id
  loop
    perform pg_advisory_xact_lock(93000, v_lock_product_id::integer);
  end loop;

  if v_variant_id is not null and not exists (
    select 1
    from public.producto_variantes variants
    where variants.id = v_variant_id
      and variants.producto_id = v_product_id
  ) then
    raise exception 'La variante no pertenece al producto seleccionado.';
  end if;

  if v_id is null
     and v_variant_id is null
     and v_product_id is not null
     and exists (
       select 1
       from public.producto_variantes variants
       where variants.producto_id = v_product_id
     ) then
    raise exception
      'Este producto tiene variantes: elegí el color/SKU específico que compraste.';
  end if;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);

  if v_id is null then
    insert into public.product_cost_entries (
      product_id, variant_id, article_name, sku, purchase_date,
      quantity, received_quantity, reception_status, unit_cost,
      freight_cost, tax_cost, commission_cost, other_cost, supplier,
      document_type, document_number, payment_method, notes, created_by
    ) values (
      v_product_id,
      v_variant_id,
      nullif(left(btrim(coalesce(p_purchase->>'article_name', '')), 180), ''),
      nullif(left(btrim(coalesce(p_purchase->>'sku', '')), 120), ''),
      (p_purchase->>'purchase_date')::date,
      v_quantity,
      v_received,
      v_status,
      coalesce((p_purchase->>'unit_cost')::numeric, 0),
      coalesce((p_purchase->>'freight_cost')::numeric, 0),
      coalesce((p_purchase->>'tax_cost')::numeric, 0),
      coalesce((p_purchase->>'commission_cost')::numeric, 0),
      coalesce((p_purchase->>'other_cost')::numeric, 0),
      nullif(left(btrim(coalesce(p_purchase->>'supplier', '')), 180), ''),
      nullif(left(btrim(coalesce(p_purchase->>'document_type', '')), 80), ''),
      nullif(left(btrim(coalesce(p_purchase->>'document_number', '')), 120), ''),
      nullif(left(btrim(coalesce(p_purchase->>'payment_method', '')), 100), ''),
      nullif(left(btrim(coalesce(p_purchase->>'notes', '')), 1000), ''),
      p_actor_id
    ) returning * into v_saved;
  else
    update public.product_cost_entries entries
    set
      product_id = v_product_id,
      variant_id = v_variant_id,
      article_name = nullif(left(btrim(coalesce(p_purchase->>'article_name', '')), 180), ''),
      sku = nullif(left(btrim(coalesce(p_purchase->>'sku', '')), 120), ''),
      purchase_date = (p_purchase->>'purchase_date')::date,
      quantity = v_quantity,
      received_quantity = v_received,
      reception_status = v_status,
      unit_cost = coalesce((p_purchase->>'unit_cost')::numeric, 0),
      freight_cost = coalesce((p_purchase->>'freight_cost')::numeric, 0),
      tax_cost = coalesce((p_purchase->>'tax_cost')::numeric, 0),
      commission_cost = coalesce((p_purchase->>'commission_cost')::numeric, 0),
      other_cost = coalesce((p_purchase->>'other_cost')::numeric, 0),
      supplier = nullif(left(btrim(coalesce(p_purchase->>'supplier', '')), 180), ''),
      document_type = nullif(left(btrim(coalesce(p_purchase->>'document_type', '')), 80), ''),
      document_number = nullif(left(btrim(coalesce(p_purchase->>'document_number', '')), 120), ''),
      payment_method = nullif(left(btrim(coalesce(p_purchase->>'payment_method', '')), 100), ''),
      notes = nullif(left(btrim(coalesce(p_purchase->>'notes', '')), 1000), '')
    where entries.id = v_id
    returning * into v_saved;
  end if;

  if exists (
    select 1 from public.productos products
    where products.id in (v_previous.product_id, v_saved.product_id)
      and products.stock < 0
  ) or exists (
    select 1 from public.producto_variantes variants
    where variants.producto_id in (v_previous.product_id, v_saved.product_id)
      and variants.stock < 0
  ) then
    raise exception 'STOCK_INSUFICIENTE: el cambio dejaría stock negativo.';
  end if;

  return v_saved;
end;
$$;


ALTER FUNCTION "public"."save_product_purchase_atomic"("p_purchase" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: save_product_purchase_idempotent("jsonb", "uuid", "text"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."save_product_purchase_idempotent"("p_purchase" "jsonb", "p_actor_id" "uuid", "p_idempotency_key" "text") RETURNS "public"."product_cost_entries"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing public.product_cost_entries%rowtype;
  v_saved public.product_cost_entries%rowtype;
  v_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
begin
  if v_key is null or length(v_key) < 8 or length(v_key) > 240 then
    raise exception 'IDEMPOTENCY_KEY_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtext('inventory-purchase'), hashtext(v_key));

  select * into v_existing
  from public.product_cost_entries entries
  where entries.idempotency_key = v_key
  for update;
  if found then
    return v_existing;
  end if;

  v_saved := public.save_product_purchase_atomic(p_purchase, p_actor_id);
  update public.product_cost_entries
  set idempotency_key = v_key
  where id = v_saved.id
  returning * into v_saved;

  insert into public.inventory_operation_log (
    product_id, variant_id, movement_type, quantity, origin, effective_at,
    actor_user_id, actor_process, idempotency_key, source_table, source_id,
    document_reference, metadata
  )
  select
    v_saved.product_id,
    v_saved.variant_id,
    'purchase',
    v_saved.received_quantity,
    'admin_purchase',
    v_saved.purchase_date::timestamp at time zone 'America/Argentina/Buenos_Aires',
    p_actor_id,
    'save_product_purchase_idempotent',
    v_key,
    'product_cost_entries',
    v_saved.id::text,
    coalesce(nullif(btrim(v_saved.document_number), ''), v_saved.id::text),
    jsonb_build_object('receptionStatus', v_saved.reception_status)
  where v_saved.product_id is not null
    and v_saved.received_quantity > 0
  on conflict (idempotency_key) do nothing;

  return v_saved;
end;
$$;


ALTER FUNCTION "public"."save_product_purchase_idempotent"("p_purchase" "jsonb", "p_actor_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";

--
-- Name: search_admin_orders("text", integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."search_admin_orders"("p_search" "text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare v_result jsonb; v_term text;
begin
  if auth.role() is distinct from 'service_role' then raise exception 'Acceso denegado'; end if;
  if p_search is null or length(btrim(p_search)) < 1 or length(p_search) > 160 then raise exception 'Búsqueda inválida'; end if;
  v_term := '%' || replace(replace(replace(lower(btrim(p_search)), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  with matching as materialized (
    select o.id, o.admin_visible_at from public.ordenes o
    where o.admin_visible_at is not null and (
      concat_ws(' ', o.id::text, 'BX-' || (o.id + 1000)::text, 'BX' || (o.id + 1000)::text,
        to_jsonb(o)->>'cliente_nombre', to_jsonb(o)->>'cliente_email', to_jsonb(o)->>'cliente_telefono',
        to_jsonb(o)->>'cliente_username', to_jsonb(o)->>'tracking_number', to_jsonb(o)->>'andreani_tracking',
        to_jsonb(o)->>'invoice_cae', to_jsonb(o)->>'invoice_number', to_jsonb(o)->>'invoice_point',
        to_jsonb(o)->>'payment_id', to_jsonb(o)->>'mercadopago_payment_id', to_jsonb(o)->>'transfer_matched_payment_id',
        to_jsonb(o)->>'external_reference', to_jsonb(o)->>'mercadopago_preference_id',
        concat_ws('-', lpad(to_jsonb(o)->>'invoice_point',4,'0'),lpad(to_jsonb(o)->>'invoice_number',8,'0'))) ilike v_term escape '\'
      or exists (
        select 1 from public.orden_items i
        left join public.productos p on p.id = i.producto_id
        left join public.producto_variantes v on v.id = i.variante_id
        where i.orden_id = o.id and concat_ws(' ', to_jsonb(p)->>'nombre', to_jsonb(p)->>'sku',
          to_jsonb(v)->>'nombre', to_jsonb(v)->>'sku', to_jsonb(i)->>'conditioned_sku',
          to_jsonb(i)->>'conditioned_name', to_jsonb(i)->>'product_name', to_jsonb(i)->>'sku') ilike v_term escape '\'
      )
    )
  ), page as (
    select id from matching order by admin_visible_at desc, id desc
    limit least(100, greatest(1, p_limit)) offset greatest(0, p_offset)
  ) select jsonb_build_object('ids', coalesce((select jsonb_agg(id) from page), '[]'::jsonb), 'total', (select count(*) from matching)) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."search_admin_orders"("p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";

