-- Name: FUNCTION "set_order_admin_visibility"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."set_order_admin_visibility"() IS 'Impide que intentos MP pendientes entren al flujo admin, fija una única fecha al confirmarse el pago y expone los pagos aprobados que quedaron trabados (monto, moneda o inventario) para resolución manual.';


--
-- Name: set_pending_credit_note_amount(bigint, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_pending_credit_note_amount"("p_order_id" bigint, "p_credit_note_amount" numeric) RETURNS TABLE("order_id" bigint, "credit_note_amount" numeric, "remaining_creditable_amount" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.ordenes%rowtype;
  v_committed numeric(12, 2);
  v_remaining numeric(12, 2);
  v_amount numeric(12, 2) := round(coalesce(p_credit_note_amount, 0), 2);
begin
  perform pg_advisory_xact_lock(91091, p_order_id::integer);

  select *
    into v_order
  from public.ordenes
  where id = p_order_id
  for update;

  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;

  if v_amount <= 0 then
    raise exception 'INVALID_CREDIT_NOTE_AMOUNT';
  end if;

  select coalesce(sum(total_amount), 0)
    into v_committed
  from public.order_credit_notes
  where order_id = p_order_id
    and status in ('processing', 'authorized');

  v_remaining := greatest(0, round(coalesce(v_order.total, 0) - v_committed, 2));

  if v_amount > v_remaining + 0.005 then
    raise exception 'CREDIT_NOTE_EXCEEDS_REMAINING';
  end if;

  -- Mismo comportamiento que el UPDATE original (.is("credit_note_cae",
  -- null)): si la orden ya tiene una nota de crédito facturada, no se pisa
  -- el importe; se devuelve sin error para no romper el flujo del wizard.
  if v_order.credit_note_cae is not null then
    return query select v_order.id, v_order.credit_note_amount, v_remaining;
    return;
  end if;

  update public.ordenes
  set credit_note_required = true,
      credit_note_status = 'pending',
      credit_note_amount = v_amount
  where id = p_order_id;

  return query select p_order_id, v_amount, v_remaining;
end;
$$;


ALTER FUNCTION "public"."set_pending_credit_note_amount"("p_order_id" bigint, "p_credit_note_amount" numeric) OWNER TO "postgres";

--
-- Name: set_product_commercial_state_atomic(bigint, boolean, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_product_commercial_state_atomic"("p_product_id" bigint, "p_active" boolean, "p_actor_id" "uuid") RETURNS "public"."productos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product public.productos%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para cambiar el estado comercial.';
  end if;
  if p_product_id is null or p_active is null then
    raise exception 'El estado comercial no es válido.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);
  select * into v_product
  from public.productos products
  where products.id = p_product_id
  for update;
  if not found then
    raise exception 'El producto ya no existe.';
  end if;
  if p_active then
    perform public.assert_product_can_activate(p_product_id);
  end if;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);
  update public.productos
  set activo = p_active
  where id = p_product_id
  returning * into v_product;

  return v_product;
end;
$$;


ALTER FUNCTION "public"."set_product_commercial_state_atomic"("p_product_id" bigint, "p_active" boolean, "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "set_product_commercial_state_atomic"("p_product_id" bigint, "p_active" boolean, "p_actor_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."set_product_commercial_state_atomic"("p_product_id" bigint, "p_active" boolean, "p_actor_id" "uuid") IS 'Cambia el estado del producto; al desactivarlo apaga todas sus variantes sin borrar configuración.';


--
-- Name: set_product_variant_allocations(bigint, "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_product_variant_allocations"("p_product_id" bigint, "p_allocations" "jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("variant_id" bigint, "allocated_quantity" integer, "available_quantity" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_assignable_quantity bigint;
  v_current_quantity bigint;
  v_requested_quantity bigint;
  v_requested_increase bigint;
  v_unassigned_quantity bigint;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para distribuir inventario.';
  end if;
  if p_product_id is null
     or jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then
    raise exception 'La distribución indicada no es válida.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);
  if not exists (select 1 from public.productos where id = p_product_id) then
    raise exception 'El producto ya no existe.';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
      as requested(variant_id bigint, quantity integer)
    where requested.variant_id is null
       or requested.quantity is null
       or requested.quantity < 0
  ) then
    raise exception 'Las cantidades deben ser números enteros iguales o mayores que cero.';
  end if;
  if (
    select count(*)
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
      as requested(variant_id bigint, quantity integer)
  ) <> (
    select count(distinct requested.variant_id)
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
      as requested(variant_id bigint, quantity integer)
  ) then
    raise exception 'Hay variantes repetidas en la distribución.';
  end if;
  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
      as requested(variant_id bigint, quantity integer)
    left join public.producto_variantes variants
      on variants.id = requested.variant_id
     and variants.producto_id = p_product_id
    where variants.id is null
  ) then
    raise exception 'Una de las variantes no pertenece al producto.';
  end if;

  select coalesce(sum(movements.quantity_delta), 0)
  into v_assignable_quantity
  from public.inventory_movements movements
  where movements.product_id = p_product_id
    and movements.variant_id is null
    and movements.movement_date <= current_date;

  select coalesce(sum(allocations.quantity), 0)
  into v_current_quantity
  from public.inventory_variant_allocations allocations
  where allocations.product_id = p_product_id;

  select coalesce(sum(requested.quantity), 0)
  into v_requested_quantity
  from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
    as requested(variant_id bigint, quantity integer);

  if v_requested_quantity > greatest(v_assignable_quantity, 0) then
    v_requested_increase := greatest(v_requested_quantity - v_current_quantity, 0);
    v_unassigned_quantity := greatest(
      greatest(v_assignable_quantity, 0) - v_current_quantity,
      0
    );
    raise exception
      'No podés asignar % unidades nuevas. Solo quedan % unidades sin asignar.',
      v_requested_increase,
      v_unassigned_quantity;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
      as requested(variant_id bigint, quantity integer)
    left join lateral (
      select coalesce(sum(movements.quantity_delta), 0) as physical_quantity
      from public.inventory_movements movements
      where movements.product_id = p_product_id
        and movements.variant_id = requested.variant_id
        and movements.movement_date <= current_date
    ) physical on true
    where physical.physical_quantity + requested.quantity < 0
  ) then
    raise exception 'No podés asignar menos unidades que las ya vendidas en una variante.';
  end if;

  delete from public.inventory_variant_allocations allocations
  where allocations.product_id = p_product_id;
  insert into public.inventory_variant_allocations (
    product_id, variant_id, quantity, updated_by, updated_at
  )
  select
    p_product_id,
    requested.variant_id,
    requested.quantity,
    p_actor_id,
    now()
  from jsonb_to_recordset(coalesce(p_allocations, '[]'::jsonb))
    as requested(variant_id bigint, quantity integer)
  where requested.quantity > 0;

  perform public.refresh_inventory_stock(p_product_id);
  return query
  select
    variants.id,
    coalesce(allocations.quantity, 0),
    coalesce(variants.stock, 0)
  from public.producto_variantes variants
  left join public.inventory_variant_allocations allocations
    on allocations.variant_id = variants.id
  where variants.producto_id = p_product_id
  order by variants.orden, variants.id;
end;
$$;


ALTER FUNCTION "public"."set_product_variant_allocations"("p_product_id" bigint, "p_allocations" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: set_product_variant_state_atomic(bigint, bigint, boolean, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."set_product_variant_state_atomic"("p_product_id" bigint, "p_variant_id" bigint, "p_active" boolean, "p_actor_id" "uuid") RETURNS "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_active boolean;
  v_variant public.producto_variantes%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para cambiar el estado de la variante.';
  end if;
  perform pg_advisory_xact_lock(93000, p_product_id::integer);

  select products.activo into v_product_active
  from public.productos products
  where products.id = p_product_id
  for update;
  if not found then
    raise exception 'El producto ya no existe.';
  end if;

  select * into v_variant
  from public.producto_variantes variants
  where variants.id = p_variant_id
    and variants.producto_id = p_product_id
  for update;
  if not found then
    raise exception 'La variante ya no existe.';
  end if;
  if p_active and not v_product_active then
    raise exception 'No podés activar esta variante porque el producto está inactivo.';
  end if;
  if p_active then
    perform public.assert_product_variant_can_activate(
      p_product_id,
      p_variant_id,
      false
    );
  end if;
  if not p_active
     and v_product_active
     and not exists (
       select 1
       from public.producto_variantes variants
       where variants.producto_id = p_product_id
         and variants.id <> p_variant_id
         and variants.activo
     ) then
    raise exception 'No podés desactivar la única variante activa. Desactivá primero el producto.';
  end if;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);
  update public.producto_variantes
  set activo = p_active
  where id = p_variant_id
  returning * into v_variant;

  return v_variant;
end;
$$;


ALTER FUNCTION "public"."set_product_variant_state_atomic"("p_product_id" bigint, "p_variant_id" bigint, "p_active" boolean, "p_actor_id" "uuid") OWNER TO "postgres";

