-- Name: FUNCTION "sweep_stale_andreani_claims"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."sweep_stale_andreani_claims"() IS 'Mueve a reconciliation_required cualquier claim Andreani vencido (>5 min, sin envío persistido) -- 100% local, sin llamar a Andreani. Nunca toca un claim fresco.';


--
-- Name: sync_auth_user_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_auth_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  begin
    insert into public.profiles (
      id,
      email,
      username,
      nombre,
      telefono,
      dni,
      calle,
      numero,
      piso,
      departamento,
      localidad,
      codigo_postal,
      provincia,
      referencias,
      rol
    )
    values (
      new.id,
      new.email,
      nullif(new.raw_user_meta_data ->> 'username', ''),
      coalesce(new.raw_user_meta_data ->> 'nombre', ''),
      nullif(new.raw_user_meta_data ->> 'telefono', ''),
      nullif(new.raw_user_meta_data ->> 'dni', ''),
      nullif(new.raw_user_meta_data ->> 'calle', ''),
      nullif(new.raw_user_meta_data ->> 'numero', ''),
      nullif(new.raw_user_meta_data ->> 'piso', ''),
      nullif(new.raw_user_meta_data ->> 'departamento', ''),
      nullif(new.raw_user_meta_data ->> 'localidad', ''),
      nullif(new.raw_user_meta_data ->> 'codigo_postal', ''),
      nullif(new.raw_user_meta_data ->> 'provincia', ''),
      nullif(new.raw_user_meta_data ->> 'referencias', ''),
      'cliente'
    )
    on conflict (id) do update
    set
      email = excluded.email,
      username = coalesce(excluded.username, profiles.username),
      nombre = coalesce(nullif(excluded.nombre, ''), profiles.nombre),
      telefono = coalesce(excluded.telefono, profiles.telefono),
      dni = coalesce(excluded.dni, profiles.dni),
      calle = coalesce(excluded.calle, profiles.calle),
      numero = coalesce(excluded.numero, profiles.numero),
      piso = coalesce(excluded.piso, profiles.piso),
      departamento = coalesce(excluded.departamento, profiles.departamento),
      localidad = coalesce(excluded.localidad, profiles.localidad),
      codigo_postal = coalesce(excluded.codigo_postal, profiles.codigo_postal),
      provincia = coalesce(excluded.provincia, profiles.provincia),
      referencias = coalesce(excluded.referencias, profiles.referencias),
      rol = coalesce(profiles.rol, 'cliente');
  exception
    when unique_violation then
      insert into public.profiles (
        id,
        email,
        nombre,
        dni,
        rol
      )
      values (
        new.id,
        new.email,
        coalesce(new.raw_user_meta_data ->> 'nombre', ''),
        nullif(new.raw_user_meta_data ->> 'dni', ''),
        'cliente'
      )
      on conflict (id) do update
      set
        email = excluded.email,
        nombre = coalesce(nullif(excluded.nombre, ''), profiles.nombre),
        dni = coalesce(excluded.dni, profiles.dni),
        rol = coalesce(profiles.rol, 'cliente');
  end;

  return new;
exception
  when others then
    raise warning 'sync_auth_user_profile failed for user %: %', new.id, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION "public"."sync_auth_user_profile"() OWNER TO "postgres";

--
-- Name: sync_conditioned_catalog_sku_registry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_conditioned_catalog_sku_registry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sku text;
begin
  if tg_op in ('UPDATE', 'DELETE') and old.conditioned_sku is not null then
    delete from public.catalog_sku_registry registry
    where registry.conditioned_stock_id = old.id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  v_sku := public.normalized_catalog_sku(new.conditioned_sku);
  if v_sku is null or new.discounted_quantity <= 0 then
    return new;
  end if;

  insert into public.catalog_sku_registry (
    normalized_sku,
    product_id,
    variant_id,
    conditioned_stock_id
  )
  values (v_sku, null, null, new.id);

  return new;
exception
  when unique_violation then
    raise exception
      'El SKU % ya está asignado a otro artículo.',
      new.conditioned_sku;
end;
$$;


ALTER FUNCTION "public"."sync_conditioned_catalog_sku_registry"() OWNER TO "postgres";

