--
-- Name: sync_product_primary_variant_image(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_product_primary_variant_image"("p_product_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_primary_image text;
begin
  select images.value
  into v_primary_image
  from public.producto_variantes variants
  cross join lateral jsonb_array_elements_text(
    coalesce(variants.imagenes, '[]'::jsonb)
  ) with ordinality as images(value, position)
  where variants.producto_id = p_product_id
    and nullif(btrim(images.value), '') is not null
  order by variants.orden, variants.id, images.position
  limit 1;

  update public.productos
  set imagen_principal = v_primary_image
  where id = p_product_id
    and imagen_principal is distinct from v_primary_image;
end;
$$;


ALTER FUNCTION "public"."sync_product_primary_variant_image"("p_product_id" bigint) OWNER TO "postgres";

--
-- Name: sync_product_variant_commercial_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_product_variant_commercial_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not new.activo then
    update public.producto_variantes variants
    set activo = false
    where variants.producto_id = new.id
      and variants.activo;
  elsif tg_op = 'UPDATE' and not coalesce(old.activo, false) then
    update public.producto_variantes variants
    set activo = true
    where variants.id = (
      select primary_variant.id
      from public.producto_variantes primary_variant
      where primary_variant.producto_id = new.id
      order by primary_variant.orden, primary_variant.id
      limit 1
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_product_variant_commercial_state"() OWNER TO "postgres";

--
-- Name: sync_signup_profile("uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_signup_profile"("user_id_input" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (
    id,
    email,
    username,
    nombre,
    telefono,
    dni,
    calle,
    numero,
    piso,
    departamento,
    localidad,
    codigo_postal,
    provincia,
    referencias,
    rol
  )
  select
    users.id,
    users.email,
    nullif(users.raw_user_meta_data ->> 'username', ''),
    coalesce(users.raw_user_meta_data ->> 'nombre', ''),
    nullif(users.raw_user_meta_data ->> 'telefono', ''),
    nullif(users.raw_user_meta_data ->> 'dni', ''),
    nullif(users.raw_user_meta_data ->> 'calle', ''),
    nullif(users.raw_user_meta_data ->> 'numero', ''),
    nullif(users.raw_user_meta_data ->> 'piso', ''),
    nullif(users.raw_user_meta_data ->> 'departamento', ''),
    nullif(users.raw_user_meta_data ->> 'localidad', ''),
    nullif(users.raw_user_meta_data ->> 'codigo_postal', ''),
    nullif(users.raw_user_meta_data ->> 'provincia', ''),
    nullif(users.raw_user_meta_data ->> 'referencias', ''),
    'cliente'
  from auth.users
  where users.id = user_id_input
    and (
      auth.uid() = users.id
      or (
        auth.uid() is null
        and users.email_confirmed_at is null
        and users.created_at >= now() - interval '10 minutes'
      )
    )
  on conflict (id) do update
  set
    email = excluded.email,
    username = coalesce(excluded.username, profiles.username),
    nombre = coalesce(nullif(excluded.nombre, ''), profiles.nombre),
    telefono = coalesce(excluded.telefono, profiles.telefono),
    dni = coalesce(excluded.dni, profiles.dni),
    calle = coalesce(excluded.calle, profiles.calle),
    numero = coalesce(excluded.numero, profiles.numero),
    piso = coalesce(excluded.piso, profiles.piso),
    departamento = coalesce(excluded.departamento, profiles.departamento),
    localidad = coalesce(excluded.localidad, profiles.localidad),
    codigo_postal = coalesce(excluded.codigo_postal, profiles.codigo_postal),
    provincia = coalesce(excluded.provincia, profiles.provincia),
    referencias = coalesce(excluded.referencias, profiles.referencias),
    rol = coalesce(profiles.rol, 'cliente');
end;
$$;


ALTER FUNCTION "public"."sync_signup_profile"("user_id_input" "uuid") OWNER TO "postgres";

--
-- Name: sync_variant_catalog_barcode_registry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_variant_catalog_barcode_registry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_barcode text;
  v_registered_product_id bigint;
begin
  if tg_op in ('UPDATE', 'DELETE') and old.codigo_barra is not null then
    delete from public.catalog_barcode_registry registry
    where registry.variant_id = old.id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  v_barcode := public.normalized_catalog_barcode(new.codigo_barra);
  if v_barcode is null then
    return new;
  end if;

  select registry.product_id
  into v_registered_product_id
  from public.catalog_barcode_registry registry
  where registry.normalized_barcode = v_barcode
  for update;

  if found and v_registered_product_id = new.producto_id then
    update public.catalog_barcode_registry
    set product_id = null,
        variant_id = new.id
    where normalized_barcode = v_barcode;
  else
    insert into public.catalog_barcode_registry (
      normalized_barcode,
      product_id,
      variant_id
    )
    values (v_barcode, null, new.id);
  end if;

  return new;
exception
  when unique_violation then
    raise exception 'El código de barra % ya está asignado a otro artículo.', new.codigo_barra;
end;
$$;


ALTER FUNCTION "public"."sync_variant_catalog_barcode_registry"() OWNER TO "postgres";

--
-- Name: sync_variant_catalog_sku_registry(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."sync_variant_catalog_sku_registry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sku text;
  v_registered_product_id bigint;
begin
  if tg_op in ('UPDATE', 'DELETE') and old.sku is not null then
    delete from public.catalog_sku_registry registry
    where registry.variant_id = old.id;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  v_sku := public.normalized_catalog_sku(new.sku);
  if v_sku is null then
    return new;
  end if;

  select registry.product_id
  into v_registered_product_id
  from public.catalog_sku_registry registry
  where registry.normalized_sku = v_sku
  for update;

  if found and v_registered_product_id = new.producto_id then
    update public.catalog_sku_registry
    set product_id = null,
        variant_id = new.id
    where normalized_sku = v_sku;
  else
    insert into public.catalog_sku_registry (
      normalized_sku,
      product_id,
      variant_id
    )
    values (v_sku, null, new.id);
  end if;

  return new;
exception
  when unique_violation then
    raise exception 'El SKU % ya está asignado a otro artículo.', new.sku;
end;
$$;


ALTER FUNCTION "public"."sync_variant_catalog_sku_registry"() OWNER TO "postgres";

