--
-- Name: undo_audit_log(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."undo_audit_log"("p_log_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_log public.audit_logs%rowtype;
  v_table_oid oid;
  v_table_schema text := 'public';
  v_table_name text;
  v_pk_column text;
  v_set_clause text;
  v_conflict_clause text;
  v_conflict_ok boolean;
  v_insert_columns text;
  v_insert_values text;
  v_actor_email text;
  v_actor_id uuid := auth.uid();
  v_child_log public.audit_logs%rowtype;
  v_child_table_oid oid;
  v_child_insert_columns text;
  v_child_insert_values text;
  v_variant public.producto_variantes%rowtype;
  v_original_delta integer;
  v_new_quantity integer;
  v_echo_log_id bigint;
begin
  if not exists (
    select 1
    from public.profiles
    where id = v_actor_id
      and rol = 'super_admin'
  ) then
    raise exception 'Solo un super admin puede deshacer movimientos de auditoria.';
  end if;

  select *
  into v_log
  from public.audit_logs
  where id = p_log_id
  for update;

  if not found then
    raise exception 'No se encontro el movimiento de auditoria %.', p_log_id;
  end if;

  if v_log.undone_at is not null then
    raise exception 'Este movimiento ya fue deshecho.';
  end if;

  if v_log.table_name = 'admin_events' then
    raise exception 'Este evento no representa un cambio de datos y no se puede deshacer.';
  end if;

  -- Lista blanca server-side: espejo de reversibleTables en audit-helpers.ts.
  -- Nunca confiar solamente en el frontend para esta decisión.
  if v_log.table_name not in (
    'banners', 'categorias', 'configuracion_visual', 'hero_banners',
    'imagenes_producto', 'metodos_envio', 'metodos_pago', 'payment_methods',
    'producto_especificaciones', 'producto_variantes', 'productos',
    'shipping_methods', 'site_settings', 'store_settings'
  ) then
    raise exception 'Esta accion no tiene una reversion automatica segura.';
  end if;

  -- Ningun campo de pago, tracking o MercadoPago se revierte
  -- automaticamente, sin importar en que tabla haya quedado registrado.
  if exists (
    select 1
    from jsonb_object_keys(coalesce(v_log.after_data, '{}'::jsonb) || coalesce(v_log.before_data, '{}'::jsonb)) as k
    where k ilike '%payment%' or k ilike '%tracking%' or k ilike '%mercadopago%'
  ) then
    raise exception 'Este cambio incluye datos de pago o envio y no se revierte automaticamente.';
  end if;

  v_table_name := v_log.table_name;
  v_table_oid := to_regclass(format('%I.%I', v_table_schema, v_table_name));

  if v_table_oid is null then
    raise exception 'No se encontro la tabla %.%.', v_table_schema, v_table_name;
  end if;

  select a.attname
  into v_pk_column
  from pg_index i
  join pg_attribute a
    on a.attrelid = i.indrelid
   and a.attnum = any(i.indkey)
  where i.indrelid = v_table_oid
    and i.indisprimary
  order by array_position(i.indkey, a.attnum)
  limit 1;

  if v_pk_column is null then
    select a.attname
    into v_pk_column
    from pg_attribute a
    where a.attrelid = v_table_oid
      and a.attname = 'id'
      and not a.attisdropped
    limit 1;
  end if;

  if v_pk_column is null or v_log.record_id is null then
    raise exception 'No se pudo identificar el registro a deshacer.';
  end if;

  select email
  into v_actor_email
  from auth.users
  where id = v_actor_id;

  -- Ajuste manual de stock: nunca se reescribe producto_variantes.stock
  -- directamente (columna derivada). Se aplica el delta inverso sobre el
  -- stock actual con la misma función idempotente que un ajuste manual
  -- normal, lo que preserva ventas/compras/devoluciones ocurridas después.
  if v_table_name = 'producto_variantes'
     and v_log.action = 'UPDATE'
     and v_log.after_data ? 'stock_adjustment_delta' then

    select *
    into v_variant
    from public.producto_variantes
    where id = (v_log.record_id)::bigint
    for update;

    if not found then
      raise exception 'La variante ya no existe.';
    end if;

    v_original_delta := (v_log.after_data->>'stock_adjustment_delta')::integer;
    v_new_quantity := coalesce(v_variant.stock, 0) - v_original_delta;

    if v_new_quantity < 0 then
      raise exception 'No se puede deshacer: el stock actual ya no alcanza para revertir este ajuste (se movieron unidades después).';
    end if;

    perform public.adjust_variant_stock_idempotent(
      v_variant.id,
      v_new_quantity,
      left('Revertido: ' || coalesce(nullif(btrim(v_log.after_data->>'stock_adjustment_reason'), ''), 'ajuste de stock'), 300),
      v_actor_id,
      'undo:' || p_log_id::text
    );

    -- El "eco" de recalculo agregado (productos.stock) de este mismo ajuste
    -- ya se regenero solo dentro de la llamada anterior; sólo se marca el
    -- registro viejo como deshecho para que no vuelva a ofrecerse.
    select id
    into v_echo_log_id
    from public.audit_logs
    where table_name = 'productos'
      and action = 'UPDATE'
      and record_id = v_variant.producto_id::text
      and actor_email is not distinct from v_log.actor_email
      and undone_at is null
      and created_at >= v_log.created_at
      and created_at <= v_log.created_at + interval '5 seconds'
    order by created_at asc
    limit 1;

    if v_echo_log_id is not null then
      update public.audit_logs
      set undone_at = now(), undone_by = v_actor_id
      where id = v_echo_log_id;
    end if;

  elsif v_log.action = 'UPDATE' then
    if v_log.before_data is null then
      raise exception 'El movimiento no tiene datos anteriores para restaurar.';
    end if;

    -- before_data/after_data son la foto COMPLETA de la fila en cada evento
    -- (no un diff), así que sólo se restauran y verifican las columnas que
    -- realmente cambiaron en ESTE evento (before <> after). Restaurar toda
    -- la fila a ciegas pisaría columnas que un evento posterior modificó
    -- sin que este evento las haya tocado nunca.
    --
    -- Ningún ajuste de stock "crudo" (sin stock_adjustment_delta, es decir
    -- un recalculo automático por venta/compra/devolución) es reversible:
    -- no hay un "motivo" que invertir y guard_derived_inventory_stock
    -- rechazaría de todos modos una escritura directa sobre la columna.
    if v_table_name in ('productos', 'producto_variantes')
       and (v_log.before_data->>'stock') is distinct from (v_log.after_data->>'stock') then
      raise exception 'Este cambio de stock fue generado automáticamente (venta, compra o devolución) y no se puede deshacer desde acá.';
    end if;

    select string_agg(format('%1$I = source.%1$I', a.attname), ', ')
    into v_set_clause
    from pg_attribute a
    where a.attrelid = v_table_oid
      and a.attnum > 0
      and not a.attisdropped
      and a.attname <> v_pk_column
      and a.attgenerated = ''
      and a.attidentity = ''
      and v_log.before_data ? a.attname
      and (v_log.before_data->>a.attname) is distinct from (v_log.after_data->>a.attname);

    if v_set_clause is null then
      raise exception 'No hay columnas que hayan cambiado para restaurar en %.%.', v_table_schema, v_table_name;
    end if;

    -- Detección de conflicto: si alguna de las columnas que cambiaron en
    -- este evento ya no coincide con lo que quedó registrado como su valor
    -- "después", algo la modificó de nuevo más tarde. Se aborta en vez de
    -- pisar ese cambio posterior con una foto vieja.
    select string_agg(format('target.%1$I is not distinct from expected.%1$I', a.attname), ' and ')
    into v_conflict_clause
    from pg_attribute a
    where a.attrelid = v_table_oid
      and a.attnum > 0
      and not a.attisdropped
      and a.attname <> v_pk_column
      and a.attgenerated = ''
      and a.attidentity = ''
      and v_log.before_data ? a.attname
      and (v_log.before_data->>a.attname) is distinct from (v_log.after_data->>a.attname);

    execute format(
      'select exists (
         select 1
         from %I.%I as target
         join jsonb_populate_record(null::%I.%I, $2) as expected on true
         where target.%I::text = $1
           and (%s)
       )',
      v_table_schema,
      v_table_name,
      v_table_schema,
      v_table_name,
      v_pk_column,
      v_conflict_clause
    )
    using v_log.record_id, coalesce(v_log.after_data, '{}'::jsonb)
    into v_conflict_ok;

    if not coalesce(v_conflict_ok, false) then
      raise exception 'No se puede deshacer: este registro fue modificado de nuevo después de este cambio.';
    end if;

    execute format(
      'update %I.%I as target
       set %s
       from jsonb_populate_record(null::%I.%I, $1) as source
       where target.%I::text = $2',
      v_table_schema,
      v_table_name,
      v_set_clause,
      v_table_schema,
      v_table_name,
      v_pk_column
    )
    using v_log.before_data, v_log.record_id;

  elsif v_log.action = 'INSERT' then
    execute format(
      'delete from %I.%I where %I::text = $1',
      v_table_schema,
      v_table_name,
      v_pk_column
    )
    using v_log.record_id;

  elsif v_log.action = 'DELETE' then
    if v_log.before_data is null then
      raise exception 'El movimiento no tiene datos eliminados para recuperar.';
    end if;

    select
      string_agg(format('%I', a.attname), ', '),
      string_agg(format('source.%I', a.attname), ', ')
    into v_insert_columns, v_insert_values
    from pg_attribute a
    where a.attrelid = v_table_oid
      and a.attnum > 0
      and not a.attisdropped
      and a.attgenerated = ''
      and v_log.before_data ? a.attname;

    if v_insert_columns is null then
      raise exception 'No hay columnas para recuperar en %.%.', v_table_schema, v_table_name;
    end if;

    execute format(
      'insert into %I.%I (%s)
       overriding system value
       select %s
       from jsonb_populate_record(null::%I.%I, $1) as source',
      v_table_schema,
      v_table_name,
      v_insert_columns,
      v_insert_values,
      v_table_schema,
      v_table_name
    )
    using v_log.before_data;

    if v_table_name = 'productos' then
      for v_child_log in
        select *
        from public.audit_logs
        where action = 'DELETE'
          and table_name in (
            'imagenes_producto',
            'producto_especificaciones',
            'producto_variantes'
          )
          and before_data ->> 'producto_id' = v_log.record_id
          and undone_at is null
          and created_at <= v_log.created_at
          and created_at >= v_log.created_at - interval '10 minutes'
        order by
          case table_name
            when 'producto_variantes' then 1
            when 'imagenes_producto' then 2
            when 'producto_especificaciones' then 3
            else 4
          end,
          id
      loop
        v_child_table_oid := to_regclass(format('%I.%I', v_table_schema, v_child_log.table_name));

        if v_child_table_oid is null then
          continue;
        end if;

        select
          string_agg(format('%I', a.attname), ', '),
          string_agg(format('source.%I', a.attname), ', ')
        into v_child_insert_columns, v_child_insert_values
        from pg_attribute a
        where a.attrelid = v_child_table_oid
          and a.attnum > 0
          and not a.attisdropped
          and a.attgenerated = ''
          and v_child_log.before_data ? a.attname;

        if v_child_insert_columns is null then
          continue;
        end if;

        execute format(
          'insert into %I.%I (%s)
           overriding system value
           select %s
           from jsonb_populate_record(null::%I.%I, $1) as source
           on conflict do nothing',
          v_table_schema,
          v_child_log.table_name,
          v_child_insert_columns,
          v_child_insert_values,
          v_table_schema,
          v_child_log.table_name
        )
        using v_child_log.before_data;

        update public.audit_logs
        set undone_at = now(),
            undone_by = v_actor_id
        where id = v_child_log.id;
      end loop;
    end if;

  else
    raise exception 'Accion de auditoria no soportada: %.', v_log.action;
  end if;

  update public.audit_logs
  set undone_at = now(),
      undone_by = v_actor_id
  where id = p_log_id;

  insert into public.audit_logs (
    table_name,
    action,
    record_id,
    actor_user_id,
    actor_email,
    before_data,
    after_data
  )
  values (
    'admin_events',
    'INSERT',
    p_log_id::text,
    v_actor_id,
    coalesce(v_actor_email, v_actor_id::text),
    null,
    jsonb_build_object(
      'event_type', 'undo_audit_log',
      'undone_log_id', v_log.id,
      'original_actor_email', v_log.actor_email,
      'original_action', v_log.action,
      'original_table_name', v_log.table_name,
      'original_record_id', v_log.record_id,
      'original_before_data', v_log.before_data,
      'original_after_data', v_log.after_data
    )
  );
exception
  when foreign_key_violation then
    raise exception 'No se puede deshacer: otros registros dependen de este dato ahora.';
  when unique_violation then
    raise exception 'No se puede deshacer: el valor anterior ya está en uso por otro registro.';
end;
$_$;


ALTER FUNCTION "public"."undo_audit_log"("p_log_id" bigint) OWNER TO "postgres";

--
-- Name: update_product_catalog_atomic(bigint, "jsonb", "text", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."update_product_catalog_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_actor_id" "uuid") RETURNS "public"."productos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_product public.productos%rowtype;
  v_primary_variant_id bigint;
  v_name text := nullif(btrim(coalesce(p_catalog ->> 'nombre', '')), '');
  v_slug text := nullif(btrim(coalesce(p_catalog ->> 'slug', '')), '');
  v_price numeric := nullif(p_catalog ->> 'precio', '')::numeric;
  v_active boolean := coalesce((p_catalog ->> 'activo')::boolean, false);
  v_category_id bigint := nullif(p_catalog ->> 'categoria_id', '')::bigint;
  v_legacy_cuotas_sin_interes boolean := coalesce((p_catalog ->> 'cuotas_sin_interes')::boolean, false);
  v_legacy_cuotas_maximas text := p_catalog ->> 'cuotas_maximas';
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para actualizar el catálogo.';
  end if;
  if p_product_id is null
     or jsonb_typeof(coalesce(p_catalog, 'null'::jsonb)) <> 'object'
     or v_slug is null then
    raise exception 'Los datos comerciales del producto no son válidos.';
  end if;
  if v_active and v_name is null then
    raise exception 'Falta completar el título.';
  end if;
  if v_name is null then
    raise exception 'Los datos comerciales del producto no son válidos.';
  end if;
  if v_active and coalesce(v_price, 0) <= 0 then
    raise exception 'El precio debe ser mayor a $0.';
  end if;
  if v_price is null or v_price < 0 then
    raise exception 'Los datos comerciales del producto no son válidos.';
  end if;
  if v_active and (
    v_category_id is null
    or not exists (
      select 1 from public.categorias categories
      where categories.id = v_category_id
    )
  ) then
    raise exception 'Seleccioná una categoría.';
  end if;
  if v_active and (
    coalesce(nullif(p_catalog ->> 'peso_empaquetado_kg', '')::numeric, 0) <= 0
    or coalesce(nullif(p_catalog ->> 'alto_paquete_cm', '')::numeric, 0) <= 0
    or coalesce(nullif(p_catalog ->> 'ancho_paquete_cm', '')::numeric, 0) <= 0
    or coalesce(nullif(p_catalog ->> 'largo_paquete_cm', '')::numeric, 0) <= 0
  ) then
    raise exception 'Completá peso, profundidad, ancho y largo.';
  end if;
  perform pg_advisory_xact_lock(93000, p_product_id::integer);
  select * into v_product
  from public.productos products
  where products.id = p_product_id
  for update;
  if not found then
    raise exception 'El producto ya no existe.';
  end if;

  select variants.id
  into v_primary_variant_id
  from public.producto_variantes variants
  where variants.producto_id = p_product_id
  order by variants.orden, variants.id
  limit 1
  for update;

  perform set_config('beyonix.actor_id', p_actor_id::text, true);

  if v_primary_variant_id is not null then
    update public.producto_variantes
    set sku = nullif(left(btrim(coalesce(p_primary_sku, '')), 120), '')
    where id = v_primary_variant_id;
  end if;

  update public.productos products
  set nombre = left(v_name, 240),
      sku = case
        when v_primary_variant_id is null
          then nullif(left(btrim(coalesce(p_primary_sku, '')), 120), '')
        else null
      end,
      slug = left(v_slug, 240),
      descripcion = nullif(p_catalog ->> 'descripcion', ''),
      video_url = nullif(p_catalog ->> 'video_url', ''),
      precio = v_price,
      precio_anterior = nullif(p_catalog ->> 'precio_anterior', '')::numeric,
      descuento = nullif(p_catalog ->> 'descuento', '')::numeric,
      cuotas_2_habilitadas = coalesce(
        (p_catalog ->> 'cuotas_2_habilitadas')::boolean,
        false
      ),
      cuotas_3_habilitadas = coalesce(
        (p_catalog ->> 'cuotas_3_habilitadas')::boolean,
        v_legacy_cuotas_sin_interes and v_legacy_cuotas_maximas = '3'
      ),
      cuotas_6_habilitadas = coalesce(
        (p_catalog ->> 'cuotas_6_habilitadas')::boolean,
        v_legacy_cuotas_sin_interes and v_legacy_cuotas_maximas = '6'
      ),
      promo_event_id = nullif(p_catalog ->> 'promo_event_id', '')::uuid,
      promo_original_precio = nullif(
        p_catalog ->> 'promo_original_precio',
        ''
      )::numeric,
      promo_original_precio_anterior = nullif(
        p_catalog ->> 'promo_original_precio_anterior',
        ''
      )::numeric,
      promo_original_descuento = nullif(
        p_catalog ->> 'promo_original_descuento',
        ''
      )::numeric,
      promo_original_cuotas_2_habilitadas = nullif(
        p_catalog ->> 'promo_original_cuotas_2_habilitadas',
        ''
      )::boolean,
      promo_original_cuotas_3_habilitadas = nullif(
        p_catalog ->> 'promo_original_cuotas_3_habilitadas',
        ''
      )::boolean,
      promo_original_cuotas_6_habilitadas = nullif(
        p_catalog ->> 'promo_original_cuotas_6_habilitadas',
        ''
      )::boolean,
      categoria_id = v_category_id,
      destacado = coalesce((p_catalog ->> 'destacado')::boolean, false),
      activo = v_active,
      peso_empaquetado_kg = nullif(p_catalog ->> 'peso_empaquetado_kg', '')::numeric,
      alto_paquete_cm = nullif(p_catalog ->> 'alto_paquete_cm', '')::numeric,
      ancho_paquete_cm = nullif(p_catalog ->> 'ancho_paquete_cm', '')::numeric,
      largo_paquete_cm = nullif(p_catalog ->> 'largo_paquete_cm', '')::numeric
  where products.id = p_product_id
  returning * into v_product;

  if v_active then
    perform public.assert_product_can_activate(p_product_id);
  end if;

  return v_product;
end;
$_$;


ALTER FUNCTION "public"."update_product_catalog_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "update_product_catalog_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_actor_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."update_product_catalog_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_actor_id" "uuid") IS 'Guarda producto y SKU principal en una única transacción, sin modificar stock.';


--
-- Name: update_product_commercial_configuration_atomic(bigint, "jsonb", "text", "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."update_product_commercial_configuration_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product public.productos%rowtype;
  v_product_active boolean := coalesce((p_catalog ->> 'activo')::boolean, false);
  v_catalog_count integer;
  v_requested_count integer;
  v_distinct_count integer;
  v_invalid_count integer;
  v_variant_id bigint;
  v_variants jsonb;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para actualizar el catálogo.';
  end if;
  if p_product_id is null
     or jsonb_typeof(coalesce(p_catalog, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_variant_states, 'null'::jsonb)) <> 'array' then
    raise exception 'La configuración comercial no es válida.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);

  select * into v_product
  from public.productos products
  where products.id = p_product_id
  for update;
  if not found then
    raise exception 'El producto ya no existe.';
  end if;

  perform 1
  from public.producto_variantes variants
  where variants.producto_id = p_product_id
  order by variants.orden, variants.id
  for update;

  select count(*) into v_catalog_count
  from public.producto_variantes variants
  where variants.producto_id = p_product_id;

  select
    count(*),
    count(distinct requested.id),
    count(*) filter (
      where requested.id is null or requested.active is null
    )
  into v_requested_count, v_distinct_count, v_invalid_count
  from jsonb_to_recordset(p_variant_states)
    as requested(id bigint, active boolean);

  if v_requested_count <> v_catalog_count
     or v_distinct_count <> v_requested_count
     or v_invalid_count > 0
     or exists (
       select 1
       from jsonb_to_recordset(p_variant_states)
         as requested(id bigint, active boolean)
       left join public.producto_variantes variants
         on variants.id = requested.id
        and variants.producto_id = p_product_id
       where variants.id is null
     ) then
    raise exception 'Los estados deben incluir exactamente todas las variantes del producto.';
  end if;

  if not v_product_active and exists (
    select 1
    from jsonb_to_recordset(p_variant_states)
      as requested(id bigint, active boolean)
    where requested.active
  ) then
    raise exception 'No podés activar una variante mientras el producto esté configurado como inactivo.';
  end if;

  if v_product_active and not exists (
    select 1
    from jsonb_to_recordset(p_variant_states)
      as requested(id bigint, active boolean)
    where requested.active
  ) then
    raise exception 'Activá al menos una variante.';
  end if;

  v_product := public.update_product_catalog_atomic(
    p_product_id,
    p_catalog,
    p_primary_sku,
    p_actor_id
  );

  if v_product_active then
    for v_variant_id in
      select requested.id
      from jsonb_to_recordset(p_variant_states)
        as requested(id bigint, active boolean)
      where requested.active
      order by requested.id
    loop
      perform public.assert_product_variant_can_activate(
        p_product_id,
        v_variant_id,
        false
      );
    end loop;
  end if;

  update public.producto_variantes variants
  set activo = requested.active
  from jsonb_to_recordset(p_variant_states)
    as requested(id bigint, active boolean)
  where variants.id = requested.id
    and variants.producto_id = p_product_id;

  if v_product_active then
    perform public.assert_product_can_activate(p_product_id);
    if not exists (
      select 1
      from public.producto_variantes variants
      where variants.producto_id = p_product_id
        and variants.activo
    ) then
      raise exception 'Activá al menos una variante.';
    end if;
  end if;

  select * into v_product
  from public.productos products
  where products.id = p_product_id;

  select coalesce(
    jsonb_agg(to_jsonb(variants) order by variants.orden, variants.id),
    '[]'::jsonb
  )
  into v_variants
  from public.producto_variantes variants
  where variants.producto_id = p_product_id;

  return jsonb_build_object(
    'product', to_jsonb(v_product),
    'variants', v_variants
  );
end;
$$;


ALTER FUNCTION "public"."update_product_commercial_configuration_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: FUNCTION "update_product_commercial_configuration_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid"); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."update_product_commercial_configuration_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid") IS 'Valida y guarda catálogo, estado del producto y estados de todas sus variantes en una única transacción.';


--
-- Name: update_product_commercial_configuration_with_pricing_atomic(bigint, "jsonb", "text", "jsonb", "uuid", "text", numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."update_product_commercial_configuration_with_pricing_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid", "p_pricing_mode" "text", "p_target_margin_percent" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
  v_mode text := coalesce(nullif(btrim(p_pricing_mode), ''), 'manual');
  v_margin numeric := p_target_margin_percent;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para actualizar la configuración comercial.';
  end if;

  if v_mode not in ('manual', 'target_margin') then
    raise exception 'El método de precio no es válido.';
  end if;

  -- En manual el margen objetivo no aplica: se limpia en vez de conservar un
  -- porcentaje viejo que después parecería vigente.
  if v_mode = 'manual' then
    v_margin := null;
  elsif v_margin is null or v_margin < 0 or v_margin >= 100 then
    raise exception 'El margen objetivo no es válido.';
  end if;

  v_result := public.update_product_commercial_configuration_atomic(
    p_product_id,
    p_catalog,
    p_primary_sku,
    p_variant_states,
    p_actor_id
  );

  insert into public.product_pricing (
    product_id, pricing_mode, target_margin_percent, updated_at, updated_by
  ) values (
    p_product_id, v_mode, v_margin, now(), p_actor_id
  )
  on conflict (product_id) do update
  set pricing_mode = excluded.pricing_mode,
      target_margin_percent = excluded.target_margin_percent,
      updated_at = excluded.updated_at,
      updated_by = excluded.updated_by;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."update_product_commercial_configuration_with_pricing_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid", "p_pricing_mode" "text", "p_target_margin_percent" numeric) OWNER TO "postgres";

--
-- Name: FUNCTION "update_product_commercial_configuration_with_pricing_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid", "p_pricing_mode" "text", "p_target_margin_percent" numeric); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."update_product_commercial_configuration_with_pricing_atomic"("p_product_id" bigint, "p_catalog" "jsonb", "p_primary_sku" "text", "p_variant_states" "jsonb", "p_actor_id" "uuid", "p_pricing_mode" "text", "p_target_margin_percent" numeric) IS 'Guarda catálogo/variantes y método de precio en una sola transacción: productos.precio y product_pricing no pueden quedar desincronizados.';


--
-- Name: update_product_variant_metadata_atomic(bigint, bigint, "jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."update_product_variant_metadata_atomic"("p_product_id" bigint, "p_variant_id" bigint, "p_metadata" "jsonb", "p_actor_id" "uuid") RETURNS "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_variant public.producto_variantes%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para actualizar la variante.';
  end if;
  if jsonb_typeof(coalesce(p_metadata, 'null'::jsonb)) <> 'object' then
    raise exception 'Los datos de la variante no son válidos.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);
  perform set_config('beyonix.actor_id', p_actor_id::text, true);

  update public.producto_variantes variants
  set nombre = case when p_metadata ? 'nombre'
        then left(btrim(p_metadata ->> 'nombre'), 160) else variants.nombre end,
      sku = case when p_metadata ? 'sku'
        then nullif(left(btrim(coalesce(p_metadata ->> 'sku', '')), 120), '')
        else variants.sku end,
      color_hex = case when p_metadata ? 'color_hex'
        then upper(p_metadata ->> 'color_hex') else variants.color_hex end,
      codigo_barra = case when p_metadata ? 'codigo_barra'
        then nullif(left(btrim(coalesce(p_metadata ->> 'codigo_barra', '')), 64), '')
        else variants.codigo_barra end,
      imagenes = case when p_metadata ? 'imagenes'
        then p_metadata -> 'imagenes' else variants.imagenes end,
      orden = case when p_metadata ? 'orden'
        then (p_metadata ->> 'orden')::integer else variants.orden end,
      peso_empaquetado_kg = case when p_metadata ? 'peso_empaquetado_kg'
        then nullif(p_metadata ->> 'peso_empaquetado_kg', '')::numeric
        else variants.peso_empaquetado_kg end,
      alto_paquete_cm = case when p_metadata ? 'alto_paquete_cm'
        then nullif(p_metadata ->> 'alto_paquete_cm', '')::numeric
        else variants.alto_paquete_cm end,
      ancho_paquete_cm = case when p_metadata ? 'ancho_paquete_cm'
        then nullif(p_metadata ->> 'ancho_paquete_cm', '')::numeric
        else variants.ancho_paquete_cm end,
      largo_paquete_cm = case when p_metadata ? 'largo_paquete_cm'
        then nullif(p_metadata ->> 'largo_paquete_cm', '')::numeric
        else variants.largo_paquete_cm end
  where variants.id = p_variant_id
    and variants.producto_id = p_product_id
  returning * into v_variant;

  if not found then
    raise exception 'La variante ya no existe.';
  end if;
  perform public.sync_product_primary_variant_image(p_product_id);
  return v_variant;
end;
$$;


ALTER FUNCTION "public"."update_product_variant_metadata_atomic"("p_product_id" bigint, "p_variant_id" bigint, "p_metadata" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: update_product_variant_with_allocation(bigint, bigint, "text", "text", "text", "jsonb", integer, "uuid"); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."update_product_variant_with_allocation"("p_product_id" bigint, "p_variant_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid") RETURNS "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_updated public.producto_variantes%rowtype;
  v_allocations jsonb;
begin
  if p_product_id is null
     or p_variant_id is null
     or nullif(btrim(p_name), '') is null
     or p_color_hex !~ '^#[0-9A-Fa-f]{6}$'
     or p_quantity is null
     or p_quantity < 0 then
    raise exception 'Los datos de la variante no son válidos.';
  end if;

  perform pg_advisory_xact_lock(93000, p_product_id::integer);

  update public.producto_variantes
  set nombre = left(btrim(p_name), 160),
      sku = nullif(left(btrim(coalesce(p_sku, '')), 120), ''),
      color_hex = upper(p_color_hex),
      imagenes = coalesce(p_images, '[]'::jsonb)
  where id = p_variant_id
    and producto_id = p_product_id
  returning * into v_updated;

  if not found then
    raise exception 'La variante ya no existe.';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'variant_id', allocations.variant_id,
        'quantity', allocations.quantity
      )
      order by allocations.variant_id
    ),
    '[]'::jsonb
  )
  into v_allocations
  from public.inventory_variant_allocations allocations
  where allocations.product_id = p_product_id
    and allocations.variant_id <> p_variant_id;

  v_allocations := v_allocations || jsonb_build_array(
    jsonb_build_object(
      'variant_id', p_variant_id,
      'quantity', p_quantity
    )
  );

  perform public.set_product_variant_allocations(
    p_product_id,
    v_allocations,
    p_actor_id
  );

  select *
  into v_updated
  from public.producto_variantes
  where id = p_variant_id;

  return v_updated;
end;
$_$;


ALTER FUNCTION "public"."update_product_variant_with_allocation"("p_product_id" bigint, "p_variant_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid") OWNER TO "postgres";

--
-- Name: update_product_variant_with_allocation_v2(bigint, bigint, "text", "text", "text", "jsonb", integer, "uuid", numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."update_product_variant_with_allocation_v2"("p_product_id" bigint, "p_variant_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid", "p_peso_empaquetado_kg" numeric, "p_alto_paquete_cm" numeric, "p_ancho_paquete_cm" numeric, "p_largo_paquete_cm" numeric) RETURNS "public"."producto_variantes"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_variant public.producto_variantes%rowtype;
begin
  v_variant := public.update_product_variant_with_allocation(
    p_product_id, p_variant_id, p_name, p_sku, p_color_hex,
    p_images, p_quantity, p_actor_id
  );
  update public.producto_variantes
  set peso_empaquetado_kg = p_peso_empaquetado_kg,
      alto_paquete_cm = p_alto_paquete_cm,
      ancho_paquete_cm = p_ancho_paquete_cm,
      largo_paquete_cm = p_largo_paquete_cm
  where id = v_variant.id
  returning * into v_variant;
  perform public.sync_product_primary_variant_image(p_product_id);
  return v_variant;
end;
$$;


ALTER FUNCTION "public"."update_product_variant_with_allocation_v2"("p_product_id" bigint, "p_variant_id" bigint, "p_name" "text", "p_sku" "text", "p_color_hex" "text", "p_images" "jsonb", "p_quantity" integer, "p_actor_id" "uuid", "p_peso_empaquetado_kg" numeric, "p_alto_paquete_cm" numeric, "p_ancho_paquete_cm" numeric, "p_largo_paquete_cm" numeric) OWNER TO "postgres";

--
-- Name: validate_checkout_inventory_reservation("jsonb", "text", bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_checkout_inventory_reservation"("p_items" "jsonb", "p_session_id" "text", "p_order_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item record;
  v_product_id bigint;
  v_available integer;
  v_expiry timestamptz := now() + public.checkout_reservation_ttl();
  v_reserved integer := 0;
  v_order_user_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No tenés permisos para validar el inventario.';
  end if;

  if p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) = 0
     or jsonb_array_length(p_items) > 50
     or p_order_id is null
     or p_order_id <= 0
     or length(btrim(coalesce(p_session_id, ''))) < 8
     or length(p_session_id) > 160 then
    raise exception 'CHECKOUT_ITEMS_INVALID';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item
    where coalesce(nullif(item ->> 'quantity', '')::integer, 0) <= 0
  ) then
    raise exception 'CHECKOUT_ITEMS_INVALID';
  end if;

  select orders.usuario_id into v_order_user_id
  from public.ordenes orders
  where orders.id = p_order_id
  for update;

  if not found then
    raise exception 'CHECKOUT_ITEMS_INVALID';
  end if;

  -- Mismo secuestro de sesión que en reserve_cart_stock, pero comparado
  -- contra el dueño real de la orden (acá no hay auth.uid(): esta función la
  -- llama únicamente el service role desde el servidor).
  if exists (
    select 1 from public.stock_reservations reservations
    where reservations.session_id = p_session_id
      and reservations.expires_at > now()
      and reservations.user_id is not null
      and reservations.user_id is distinct from v_order_user_id
  ) then
    raise exception 'RESERVATION_SESSION_MISMATCH';
  end if;

  perform public.purge_expired_stock_reservations();

  for v_product_id in
    select distinct product_id from (
      select nullif(item ->> 'product_id', '')::bigint as product_id
      from jsonb_array_elements(p_items) item
      union
      select reservations.product_id
      from public.stock_reservations reservations
      where reservations.session_id = p_session_id
    ) targets
    order by 1
  loop
    if v_product_id is null then raise exception 'CHECKOUT_ITEMS_INVALID'; end if;
    perform pg_advisory_xact_lock(93000, v_product_id::integer);
  end loop;

  -- Se reemplaza íntegramente la reserva de la sesión: si cambió cantidad,
  -- producto o variante, lo viejo se libera en la misma transacción y no
  -- quedan reservas fantasma. Nunca toca reservas de otras sesiones.
  delete from public.stock_reservations reservations
  where reservations.session_id = p_session_id;

  for v_item in
    select
      nullif(item ->> 'product_id', '')::bigint as product_id,
      nullif(item ->> 'variant_id', '')::bigint as variant_id,
      nullif(item ->> 'conditioned_stock_id', '')::uuid as conditioned_stock_id,
      sum(coalesce(nullif(item ->> 'quantity', '')::integer, 0))::integer
        as quantity
    from jsonb_array_elements(p_items) item
    group by 1, 2, 3
    order by 1, 2 nulls first, 3 nulls first
  loop
    if v_item.product_id is null or v_item.quantity is null or v_item.quantity <= 0
       or (v_item.variant_id is not null and v_item.conditioned_stock_id is not null) then
      raise exception 'CHECKOUT_ITEMS_INVALID';
    end if;

    v_available := public.available_stock_for_session(
      v_item.product_id,
      v_item.variant_id,
      v_item.conditioned_stock_id,
      p_session_id
    );

    if v_available is null or v_available < v_item.quantity then
      raise exception 'CHECKOUT_STOCK_INSUFFICIENT';
    end if;

    -- Se conserva el dueño real de la orden (null para compra de invitado):
    -- insertar siempre user_id null acá debilitaría el chequeo de propiedad
    -- que ya usan release_cart_stock_reservation/complete_cart_stock_reservation
    -- (`user_id is null or user_id = auth.uid()`) para una orden que sí tiene
    -- usuario autenticado.
    insert into public.stock_reservations (
      session_id, user_id, product_id, variant_id,
      conditioned_stock_id, quantity, order_id, expires_at
    ) values (
      p_session_id, v_order_user_id, v_item.product_id, v_item.variant_id,
      v_item.conditioned_stock_id, v_item.quantity, p_order_id, v_expiry
    );
    v_reserved := v_reserved + 1;
  end loop;

  -- Revalida producto/variante activos y "hace falta elegir variante" con el
  -- mismo criterio de siempre. No decrementa (el stock es derivado); el nombre
  -- se conserva por compatibilidad con el resto del esquema.
  perform public.decrement_checkout_inventory(p_items);

  return jsonb_build_object(
    'validated', true,
    'reserved', v_reserved,
    'expires_at', v_expiry
  );
end;
$$;


ALTER FUNCTION "public"."validate_checkout_inventory_reservation"("p_items" "jsonb", "p_session_id" "text", "p_order_id" bigint) OWNER TO "postgres";

--
-- Name: FUNCTION "validate_checkout_inventory_reservation"("p_items" "jsonb", "p_session_id" "text", "p_order_id" bigint); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."validate_checkout_inventory_reservation"("p_items" "jsonb", "p_session_id" "text", "p_order_id" bigint) IS 'Valida catálogo y disponibilidad real (stock derivado menos reservas ajenas activas) y deja la reserva de la sesión atada a la orden, todo en una transacción bajo advisory lock por producto.';


--
-- Name: validate_external_sale_variant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_external_sale_variant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_variant_product_id bigint;
begin
  if new.variant_id is not null then
    select variants.producto_id
    into v_variant_product_id
    from public.producto_variantes variants
    where variants.id = new.variant_id;

    if not found
       or new.product_id is null
       or v_variant_product_id <> new.product_id then
      raise exception 'La variante de la venta no pertenece al producto.';
    end if;
  elsif new.product_id is not null and exists (
    select 1
    from public.producto_variantes variants
    where variants.producto_id = new.product_id
  ) then
    raise exception
      'Seleccioná una variante para descontar correctamente el stock.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_external_sale_variant"() OWNER TO "postgres";

--
-- Name: validate_inventory_order_confirmation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_inventory_order_confirmation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_item record;
  v_available integer;
  v_offer_product_id bigint;
begin
  if public.inventory_order_consumes_stock(old.estado, old.payment_status)
     or not public.inventory_order_consumes_stock(
       new.estado,
       new.payment_status
     ) then
    return new;
  end if;

  for v_item in
    select
      items.producto_id,
      items.variante_id,
      items.conditioned_stock_id,
      sum(items.cantidad)::integer as quantity
    from public.orden_items items
    where items.orden_id = new.id
    group by
      items.producto_id,
      items.variante_id,
      items.conditioned_stock_id
    order by
      items.producto_id,
      items.variante_id nulls first,
      items.conditioned_stock_id nulls first
  loop
    perform pg_advisory_xact_lock(93000, v_item.producto_id::integer);

    if v_item.conditioned_stock_id is not null then
      select movements.product_id
      into v_offer_product_id
      from public.inventory_return_movements movements
      where movements.id = v_item.conditioned_stock_id
        and movements.conditioned_active
      for update;

      if not found or v_offer_product_id <> v_item.producto_id then
        raise exception 'CHECKOUT_STOCK_INSUFFICIENT';
      end if;

      select offers.available_quantity
      into v_available
      from public.conditioned_inventory_offers offers
      where offers.id = v_item.conditioned_stock_id;
    elsif v_item.variante_id is not null then
      select coalesce(variants.stock, 0)
      into v_available
      from public.producto_variantes variants
      where variants.id = v_item.variante_id
        and variants.producto_id = v_item.producto_id
        and variants.activo;
    else
      select coalesce(products.stock, 0)
      into v_available
      from public.productos products
      where products.id = v_item.producto_id
        and products.activo;
    end if;

    if not found or v_available < v_item.quantity then
      raise exception 'CHECKOUT_STOCK_INSUFFICIENT';
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_inventory_order_confirmation"() OWNER TO "postgres";

--
-- Name: validate_inventory_order_item(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_inventory_order_item"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_order public.ordenes;
  v_available integer;
  v_previous_quantity integer := 0;
begin
  select *
  into v_order
  from public.ordenes
  where id = new.orden_id;

  if not found
     or not public.inventory_order_consumes_stock(
       v_order.estado,
       v_order.payment_status
     ) then
    return new;
  end if;

  perform pg_advisory_xact_lock(93000, new.producto_id::integer);

  if tg_op = 'UPDATE'
     and old.producto_id = new.producto_id
     and old.variante_id is not distinct from new.variante_id then
    v_previous_quantity := old.cantidad;
  end if;

  if new.variante_id is not null then
    select coalesce(variants.stock, 0)
    into v_available
    from public.producto_variantes variants
    where variants.id = new.variante_id
      and variants.producto_id = new.producto_id;
  else
    select coalesce(products.stock, 0)
    into v_available
    from public.productos products
    where products.id = new.producto_id;
  end if;

  if not found or v_available + v_previous_quantity < new.cantidad then
    raise exception 'CHECKOUT_STOCK_INSUFFICIENT';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_inventory_order_item"() OWNER TO "postgres";

--
-- Name: validate_inventory_return_condition(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_inventory_return_condition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sale public.mercadolibre_sales%rowtype;
  v_item public.orden_items%rowtype;
  v_variant_product_id bigint;
  v_max_quantity integer;
begin
  if new.mercadolibre_sale_id is null then
    select * into v_item
    from public.orden_items items
    where items.id = new.order_item_id
      and items.orden_id = new.order_id;
    if not found then
      raise exception 'La devolución no pertenece al pedido indicado.';
    end if;

    new.product_id := v_item.producto_id;
    if new.variant_id is null and v_item.variante_id is not null then
      new.variant_id := v_item.variante_id;
    end if;
    v_max_quantity := v_item.cantidad;

    -- Compatibilidad con movimientos históricos que sólo informaban quantity.
    if new.received_quantity = 0
       and new.sellable_quantity = 0
       and new.discounted_quantity = 0
       and new.non_sellable_quantity = 0
       and new.quantity > 0 then
      new.received_quantity := new.quantity;
      new.sellable_quantity := new.quantity;
    end if;
  else
    select * into v_sale
    from public.mercadolibre_sales sales
    where sales.id = new.mercadolibre_sale_id;
    if not found or v_sale.product_id is null then
      raise exception 'La venta de Mercado Libre debe estar vinculada a un producto.';
    end if;

    new.product_id := v_sale.product_id;
    if tg_op = 'INSERT' and new.variant_id is null then
      new.variant_id := public.inventory_ml_variant_id(v_sale.raw_data);
    end if;
    new.order_id := null;
    new.order_item_id := null;
    v_max_quantity := v_sale.quantity;
  end if;

  -- Sólo el estado vendible normal alimenta el stock normal. Las unidades con
  -- descuento se publican y descuentan desde conditioned_inventory_offers.
  new.quantity := new.sellable_quantity;

  if new.received_quantity > v_max_quantity then
    raise exception 'No podés recibir más unidades que las vendidas.';
  end if;
  if new.received_quantity < 0
     or new.sellable_quantity < 0
     or new.discounted_quantity < 0
     or new.non_sellable_quantity < 0
     or new.sellable_quantity
          + new.discounted_quantity
          + new.non_sellable_quantity
        > new.received_quantity then
    raise exception 'La clasificación de la devolución no es válida.';
  end if;

  if new.discounted_quantity > 0 and (
    new.discount_percent is null
    or new.discount_percent <= 0
    or new.discount_percent >= 100
    or nullif(btrim(new.discount_reason), '') is null
  ) then
    raise exception 'Indicá el porcentaje y el motivo del descuento.';
  end if;
  if new.non_sellable_quantity > 0
     and nullif(btrim(new.non_sellable_reason), '') is null then
    raise exception 'Indicá por qué las unidades no son vendibles.';
  end if;

  if new.discounted_quantity = 0 then
    new.discount_percent := null;
    new.discount_reason := null;
    new.conditioned_active := false;
    new.conditioned_name := null;
    new.conditioned_sku := null;
    new.conditioned_color_hex := null;
    new.conditioned_images := '[]'::jsonb;
  end if;
  if new.non_sellable_quantity = 0 then
    new.non_sellable_reason := null;
  end if;

  if new.variant_id is not null then
    select variants.producto_id into v_variant_product_id
    from public.producto_variantes variants
    where variants.id = new.variant_id;
    if not found or v_variant_product_id is distinct from new.product_id then
      raise exception 'La variante vinculada no pertenece al producto.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_inventory_return_condition"() OWNER TO "postgres";

--
-- Name: FUNCTION "validate_inventory_return_condition"(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION "public"."validate_inventory_return_condition"() IS 'Valida devoluciones web y ML sin sumar las unidades condicionadas al stock normal.';


--
-- Name: validate_ml_sale_variant(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_ml_sale_variant"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_variant_id bigint;
  v_variant_product_id bigint;
  v_old_variant_id bigint;
begin
  if new.product_id is null
     or public.inventory_ml_stock_units(new.quantity, new.raw_data) = 0 then
    return new;
  end if;

  v_variant_id := public.inventory_ml_variant_id(new.raw_data);

  if v_variant_id is not null then
    select variants.producto_id
    into v_variant_product_id
    from public.producto_variantes variants
    where variants.id = v_variant_id;

    if not found or v_variant_product_id <> new.product_id then
      raise exception
        'La variante de la venta de Mercado Libre no pertenece al producto.';
    end if;
  elsif exists (
    select 1
    from public.producto_variantes variants
    where variants.producto_id = new.product_id
  ) then
    -- Una reimportación debe ser idempotente: no se reclasifican ventas que
    -- ocurrieron antes de convertir el producto en variantes.
    if tg_op = 'UPDATE' then
      v_old_variant_id := public.inventory_ml_variant_id(old.raw_data);
      if old.product_id = new.product_id
         and v_old_variant_id is null then
        return new;
      end if;
    end if;

    raise exception
      'La venta de Mercado Libre requiere una variante de catálogo.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_ml_sale_variant"() OWNER TO "postgres";

