--
-- Name: validate_product_commercial_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_product_commercial_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_active boolean;
begin
  select products.activo into v_product_active
  from public.productos products
  where products.id = new.id;

  if coalesce(v_product_active, false) then
    perform public.assert_product_can_activate(new.id);
    if not exists (
      select 1
      from public.producto_variantes variants
      where variants.producto_id = new.id
        and variants.activo
    ) then
      raise exception 'El producto necesita al menos una variante activa.';
    end if;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."validate_product_commercial_state"() OWNER TO "postgres";

--
-- Name: validate_product_sku_ownership(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_product_sku_ownership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.sku := nullif(btrim(new.sku), '');

  if new.sku is not null and exists (
    select 1
    from public.producto_variantes variants
    where variants.producto_id = new.id
       or public.normalized_catalog_sku(variants.sku)
          = public.normalized_catalog_sku(new.sku)
  ) then
    raise exception
      'Los productos con variantes no pueden conservar un SKU principal.';
  end if;

  return new;
end;
$$;


