-- Name: validate_product_specification_commercial_state(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION "public"."validate_product_specification_commercial_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_product_id bigint := case
    when tg_op = 'DELETE' then old.producto_id
    else new.producto_id
  end;
begin
  if exists (
    select 1 from public.productos products
    where products.id = v_product_id and products.activo
  ) then
    perform public.assert_product_can_activate(v_product_id);
  end if;
  return null;
end;
$$;


