--
-- Name: inventory_conditioned_stock; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_conditioned_stock" WITH ("security_invoker"='true') AS
 SELECT "product_id",
    "variant_id",
    "sum"("sellable_quantity") AS "normal_returned_quantity",
    "sum"("discounted_quantity") AS "discounted_quantity",
    "sum"("non_sellable_quantity") AS "non_sellable_quantity",
    "sum"(((("received_quantity" - "sellable_quantity") - "discounted_quantity") - "non_sellable_quantity")) AS "pending_review_quantity"
   FROM "public"."inventory_return_movements" "movements"
  WHERE ("mercadolibre_sale_id" IS NOT NULL)
  GROUP BY "product_id", "variant_id";


ALTER VIEW "public"."inventory_conditioned_stock" OWNER TO "postgres";

