--
-- Name: inventory_stock_breakdown; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_stock_breakdown" WITH ("security_invoker"='true') AS
 SELECT "products"."id" AS "product_id",
    "variants"."id" AS "variant_id",
    (0)::bigint AS "opening_quantity",
    COALESCE("purchases"."quantity", (0)::bigint) AS "received_quantity",
    ((COALESCE("store_sales"."quantity", (0)::bigint) + COALESCE("external_sales"."quantity", (0)::bigint)) + COALESCE("ml_sales"."quantity", (0)::bigint)) AS "sold_quantity",
    COALESCE("returns"."quantity", (0)::bigint) AS "restocked_quantity",
    COALESCE("expenses"."quantity", (0)::bigint) AS "outgoing_quantity",
    (
        CASE
            WHEN ("variants"."id" IS NOT NULL) THEN COALESCE("variants"."stock", 0)
            ELSE COALESCE("products"."stock", 0)
        END)::bigint AS "available_quantity",
    COALESCE("store_sales"."quantity", (0)::bigint) AS "store_sold_quantity",
    COALESCE("external_sales"."quantity", (0)::bigint) AS "external_sold_quantity",
    COALESCE("ml_sales"."quantity", (0)::bigint) AS "mercadolibre_sold_quantity"
   FROM ((((((("public"."productos" "products"
     LEFT JOIN "public"."producto_variantes" "variants" ON (("variants"."producto_id" = "products"."id")))
     LEFT JOIN LATERAL ( SELECT "sum"("entries"."received_quantity") AS "quantity"
           FROM "public"."product_cost_entries" "entries"
          WHERE (("entries"."product_id" = "products"."id") AND (NOT ("entries"."variant_id" IS DISTINCT FROM "variants"."id")) AND ("entries"."purchase_date" <= CURRENT_DATE))) "purchases" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("items"."cantidad") AS "quantity"
           FROM ("public"."orden_items" "items"
             JOIN "public"."ordenes" "orders" ON (("orders"."id" = "items"."orden_id")))
          WHERE (("items"."producto_id" = "products"."id") AND (NOT ("items"."variante_id" IS DISTINCT FROM "variants"."id")) AND "public"."inventory_order_consumes_stock"("orders"."estado", "orders"."payment_status") AND (("orders"."created_at")::"date" <= CURRENT_DATE))) "store_sales" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("sales"."quantity") AS "quantity"
           FROM "public"."external_sales" "sales"
          WHERE (("sales"."product_id" = "products"."id") AND ("variants"."id" IS NULL) AND ("sales"."sale_date" <= CURRENT_DATE))) "external_sales" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("public"."inventory_ml_stock_units"("sales"."quantity", "sales"."raw_data")) AS "quantity"
           FROM "public"."mercadolibre_sales" "sales"
          WHERE (("sales"."product_id" = "products"."id") AND (NOT ("public"."inventory_ml_variant_id"("sales"."raw_data") IS DISTINCT FROM "variants"."id")) AND (COALESCE((("sales"."sale_date" AT TIME ZONE 'America/Argentina/Buenos_Aires'::"text"))::"date", CURRENT_DATE) <= CURRENT_DATE))) "ml_sales" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("movements"."quantity") AS "quantity"
           FROM "public"."inventory_return_movements" "movements"
          WHERE (("movements"."product_id" = "products"."id") AND (NOT ("movements"."variant_id" IS DISTINCT FROM "variants"."id")) AND (("movements"."created_at")::"date" <= CURRENT_DATE))) "returns" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("costs"."quantity") AS "quantity"
           FROM "public"."business_expenses" "costs"
          WHERE (("costs"."expense_type" = 'product'::"text") AND ("costs"."product_id" = "products"."id") AND (NOT ("costs"."variant_id" IS DISTINCT FROM "variants"."id")) AND ("costs"."expense_date" <= CURRENT_DATE))) "expenses" ON (true));


ALTER VIEW "public"."inventory_stock_breakdown" OWNER TO "postgres";

--
-- Name: VIEW "inventory_stock_breakdown"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW "public"."inventory_stock_breakdown" IS 'Explica el stock por producto y variante usando compras, ventas, devoluciones y salidas.';


--
-- Name: inventory_stock_timeline; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."inventory_stock_timeline" WITH ("security_invoker"='true') AS
 SELECT "product_id",
    "variant_id",
    "movement_date",
    "recorded_at",
    "source",
    "source_id",
    "quantity_delta",
    ("sum"("quantity_delta") OVER (PARTITION BY "product_id", "variant_id" ORDER BY "movement_date", "recorded_at", "source", "source_id" ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW))::bigint AS "running_stock"
   FROM "public"."inventory_movements" "movements";


ALTER VIEW "public"."inventory_stock_timeline" OWNER TO "postgres";

--
-- Name: VIEW "inventory_stock_timeline"; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW "public"."inventory_stock_timeline" IS 'Saldo cronológico de inventario por producto y variante.';


