--
-- Name: ordenes_detalle; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW "public"."ordenes_detalle" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "orden_id",
    "o"."usuario_id",
    COALESCE("o"."cliente_nombre", "p"."nombre") AS "cliente_nombre",
    COALESCE("o"."cliente_email", "p"."email") AS "cliente_email",
    "o"."cliente_telefono",
    "o"."cliente_direccion",
    "o"."estado",
    "o"."total",
    "o"."created_at",
    "timezone"('America/Argentina/Buenos_Aires'::"text", "o"."created_at") AS "fecha_argentina",
    "oi"."id" AS "item_id",
    "oi"."producto_id",
    "pr"."nombre" AS "producto_nombre",
    "oi"."variante_id",
    "pv"."nombre" AS "variante_nombre",
    "pv"."color_hex" AS "variante_color_hex",
    "oi"."cantidad",
    "oi"."precio"
   FROM (((("public"."ordenes" "o"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "o"."usuario_id")))
     LEFT JOIN "public"."orden_items" "oi" ON (("oi"."orden_id" = "o"."id")))
     LEFT JOIN "public"."productos" "pr" ON (("pr"."id" = "oi"."producto_id")))
     LEFT JOIN "public"."producto_variantes" "pv" ON (("pv"."id" = "oi"."variante_id")));


ALTER VIEW "public"."ordenes_detalle" OWNER TO "postgres";

