    CONSTRAINT "reviews_comment_check" CHECK ((("char_length"(TRIM(BOTH FROM "comment")) >= 0) AND ("char_length"(TRIM(BOTH FROM "comment")) <= 150))),
    CONSTRAINT "reviews_nickname_check" CHECK ((("char_length"(TRIM(BOTH FROM "nickname")) >= 1) AND ("char_length"(TRIM(BOTH FROM "nickname")) <= 24))),
    CONSTRAINT "reviews_province_check" CHECK ((("char_length"(TRIM(BOTH FROM "province")) >= 1) AND ("char_length"(TRIM(BOTH FROM "province")) <= 45))),
    CONSTRAINT "reviews_rating_check" CHECK ((("rating" >= 1) AND ("rating" <= 5)))
);


